//! Running the pipeline against the real overworld.
//!
//! Everything above this is a loader; this is the wiring that turns them into
//! a world. It is deliberately the *only* place the stages are ordered, so
//! there is one answer to "what does rustmc generate for seed N" rather than
//! one per tool.
//!
//! # What it does not do yet, said out loud
//!
//! Most structure sets. They run between carvers and decoration in vanilla and
//! write into the same canvas. All seventeen of the overworld's twenty sets
//! are built here (see [`Generated::caveats`] for what each still lacks); the
//! other three are the nether's and the End's, generated by their own
//! dimensions' entry points.
//!
//! *(This paragraph said "three … missing strongholds, ruined portals,
//! shipwrecks, trial chambers and the rest" until 2026-08-09, by which time
//! three of the four it named as missing were being placed. A coverage claim
//! that lags the code reads as authority: the trial chambers it called absent
//! are the largest single bearding contributor in the measured window.)*
//!
//! # The bearding starts are gated on `Through::Decoration`, and that is a
//! # correctness gap, not just a coverage one
//!
//! `village_starts` and `trial_chamber_starts` are both computed only when
//! `through >= Through::Decoration`, and they are the overworld's bearding
//! starts. So `RUSTMC_THROUGH=noise`, `=surface` and `=carvers` all produce
//! terrain with **no beard at all** — not merely undecorated terrain, but
//! terrain the noise stage itself would not have produced. The cut-off is
//! documented as the way to separate a terrain difference from a feature
//! placing differently on identical terrain, and near a bearding structure it
//! does not do that. Measured: seed 20260722 chunk (78,53), 217 blocks.
//!
//! It is left standing here because moving it puts structure-start work
//! inside every noise-only dump, and noise-only dumps are what
//! `ci/stage-scale.sh` and the benches time.

// Read once, not per chunk. `crate::trace_switch` is in `rustmc-worldgen`;
// these three are read inside the per-chunk carve and decorate loops, which
// is the same shape of cost the worldgen crate's own switches had.
rustmc_worldgen::trace_switch_value!(trace_carver, "RUSTMC_TRACE_CARVER");
rustmc_worldgen::trace_switch_value!(dump_chunk, "RUSTMC_DUMP_CHUNK");
// `RUSTMC_VILLAGE_FEATURE_SKIP=minecraft:acacia,minecraft:pile_hay` declines
// the named `feature_pool_element` features and refuses them exactly as an
// unported one is refused — **including consuming none of their draws**,
// which is what an unported feature does and is the whole point of the knob.
//
// It is an attribution instrument, not a feature flag. A village plants two
// kinds of feature element and one of them can sit in the same chunk as the
// other, so the second one's stream position depends on the first: without
// this, the only way to take a per-element before/after is to build the tree
// once per element, and a delta taken across two binaries is a delta with a
// rebuild in it. With it, one binary answers every intermediate state.
rustmc_worldgen::trace_switch_value!(village_feature_skip, "RUSTMC_VILLAGE_FEATURE_SKIP");
rustmc_worldgen::trace_switch!(trace_mineshaft, "RUSTMC_TRACE_MINESHAFT");
// `RUSTMC_TRACE_BEARD=1` reports how many starts the beard was given and how
// many chunks it actually fired in.
//
// It exists because "the world did not move" is the beard's gate on every
// window measured so far, and that sentence is true both when the beard
// correctly declines and when it is silently wired to nothing. Those are the
// same observation and opposite facts, and this project has already lost a
// week to three instruments agreeing while all three were blind. A gate that
// cannot fire is not a gate.
rustmc_worldgen::trace_switch!(trace_beard, "RUSTMC_TRACE_BEARD");

