use rustmc_worldgen::biome::multi_noise::{ChunkClimate, ClimateSampler};
use rustmc_worldgen::canvas::{Canvas, PostProcessingMarks};
use rustmc_worldgen::chunk_gen::FillSettings;
use rustmc_worldgen::density::flat_cache::FlatCaches;
use rustmc_worldgen::density::router::OverworldRouter;
use rustmc_worldgen::density::surface_level::SurfaceLevels;
use rustmc_worldgen::noise::NoiseSeeding;
use rustmc_worldgen::pipeline::{Area, Pipeline, Through};
use rustmc_worldgen::stage;
use rustmc_worldgen::surface::conditions::{min_surface_cell_corners, min_surface_level};
use rustmc_worldgen::surface::context::SurfaceContext;
use rustmc_worldgen::surface::world::{ChunkSurfaceState, WorldSurfaceOracle};

use crate::{biome_table, noise_parameters, surface_rule, BiomeEntry, SEA_LEVEL};

/// Which dimension a [`Generated`] world is.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Default)]
pub enum Dim {
    #[default]
    Overworld,
    Nether,
    End,
}

/// A generated world, and what is missing from it.
pub struct Generated {
    pub canvas: Canvas,
    pub area: Area,
    pub through: Through,
    /// Which dimension produced it.
    ///
    /// On the struct rather than inferred from the canvas height, because
    /// [`Generated::caveats`] must not print the overworld's structure
    /// caveats over a nether world — a caveat list that is wrong is worse
    /// than none, since its whole job is to travel with the number.
    pub dimension: Dim,
    /// What the port declined to place, and how often. Empty is the goal;
    /// non-empty is a measurement rather than a failure.
    pub refused: BTreeMap<String, usize>,
}

impl Generated {
    /// What a number taken from this world has to be reported alongside.
    ///
    /// Not a log line — a value, so a caller cannot print the number without
    /// having had the caveats in hand.
    #[must_use]
    pub fn caveats(&self) -> Vec<&'static str> {
        if self.dimension == Dim::End {
            // Four of the End's five features are ported — `end_spike`,
            // `end_platform`, `end_island_decorated` and `chorus_plant` — plus
            // the dimension's one structure set, `end_city`.
            //
            // CORRECTED 2026-08-18, and the correction is why this comment is
            // long. It read `end_island` for `end_island_decorated`, and it
            // claimed "both reference windows are 100.000000% (seed 20260722,
            // r=7, y 0..127, centres (0,0) and (64,64))". Three things were
            // wrong with that sentence and each of them mattered:
            //
            //   * there was no r=7 reference at centre (64,64) for the End and
            //     never had been — that window is r=16 — and there was no
            //     reference at (0,0) at any radius, so one of the two windows
            //     it named did not exist;
            //   * `y 0..127` is the nether's mandatory ybox, not the End's.
            //     Every published End denominator is 71,368,704 = 1,089 x
            //     65,536, which is y 0..255, and a comment that halves it
            //     invites a caller to halve the measurement;
            //   * all six references it was measured against were destroyed on
            //     2026-08-07 and never re-harvested, so between then and
            //     2026-08-18 the sentence could not be checked at all.
            //
            // Re-taken on fourteen order-stamped replacements, per biome, at
            // `--ybox 0 255`: all five End biomes read 100.000000% — the_end
            // over 14,745,600 blocks (its first measurement ever),
            // end_midlands 25,821,184, small_end_islands 19,464,192,
            // end_highlands 18,415,616, end_barrens 7,667,712. See
            // `ci/end-biome-window.sh` and docs/DETERMINISM.md §§51-50.
            //
            // WHAT IS LEFT IS A COVERAGE GAP AND IT IS ARITHMETIC RATHER THAN
            // BAD LUCK, which is the only reason it is worth stating twice.
            // `end_gateway_return` is placed by `rarity_filter chance=700`
            // then a biome filter to `end_highlands`. Over all three measured
            // windows — 1,539 chunks, ~398 end_highlands chunk-equivalents —
            // the expected number of return gateways is 0.57 and the observed
            // number is 0: no `end_gateway` block anywhere, and no bedrock
            // outside the ten spike tops. So this port could place them
            // perfectly or not at all and every End figure would read the
            // same. A caveat naming an unmeasured gap is the only honest form
            // this list can take, and naming the *size* of the gap is the
            // difference between a caveat and an alibi.
            let mut out = vec![
                "no return gateways: `end_gateway_return` is the one unported \
                 End feature, and no measured window contains one either — \
                 rarity 1/700 filtered to end_highlands puts the expected \
                 count over all 1,539 measured chunks at 0.57 against an \
                 observed 0, so no End figure is evidence about it",
                "an end city's shulkers and its ship's elytra frame are \
                 spawned with its banners, ender chest and chests (table and \
                 seed); a shulker's yaw is written 0, where vanilla's comes \
                 from the entity's own unseeded random",
            ];
            if self.through < Through::Decoration {
                out.push("decoration did not run: no end spikes either");
            }
            if self.through < Through::Surface {
                out.push("the surface rules did not run");
            }
            if self.through < Through::Biomes {
                out.push("the biome stage did not run");
            }
            return out;
        }
        if self.dimension == Dim::Nether {
            // Deliberately short and deliberately not the overworld's list.
            // Everything the nether path does not run is named, because a
            // terrain-only world is a *useful* measurement and a misleading
            // headline.
            // The nether has three structure sets and one of them is ported,
            // so this cannot say "no structures" any more. It said exactly
            // that until 2026-08-18, months after `nether_fossil` began
            // placing and beardifying — and a caveat list that lags the code
            // reads as authoritative, which is worse than none.
            //
            //   nether_complexes  fortress                    ported
            //                     bastion_remnant             ported
            //   nether_fossils    nether_fossil               ported
            //   ruined_portals    ruined_portal_nether        ported
            //
            // `ruined_portal_nether` was the odd one until 2026-10-02:
            // `structure/ruined_portal.rs` was ported and the overworld placed
            // its six variants, but the nether never called
            // `ruined_portal_starts`, so the seventh member of the set was
            // absent from this dimension specifically.
            //
            // The forest caveat that stood here from 2026-08-18 is gone with
            // the four features it named: `nether_forest_vegetation`,
            // `huge_fungus`, `weeping_vines` and `twisting_vines` place, and
            // `tests/golden_nether_features.rs` holds them inside vanilla's own
            // spread on the one window that has both forests.
            let mut out = vec![
                "structures: `nether_fossil`, `bastion_remnant`, `fortress` \
                 and `ruined_portal_nether` are placed",
            ];
            if self.through < Through::Decoration {
                out.push(
                    "decoration did not run: no fungi, no glowstone, no quartz \
                     or gold or ancient debris, no gravel, basalt or blackstone \
                     blobs",
                );
            }
            if self.through < Through::Carvers {
                out.push("no carvers, so no cave_air and no lava cut into the terrain");
            }
            if self.through < Through::Surface {
                out.push(
                    "the surface rules did not run: no bedrock roof or floor, \
                     no soul sand, soul soil, gravel, blackstone or basalt",
                );
            }
            if self.through < Through::Biomes {
                out.push("the biome stage did not run");
            }
            return out;
        }
        let mut out = vec![
            // SEVENTEEN of the twenty sets — every overworld one — and this
            // line said sixteen until ocean monuments landed (branch
            // `structures-monument-city`), fifteen until ancient cities did,
            // fourteen until woodland mansions did, seven until 2026-10-01,
            // five until 2026-09-05. A caveat list that lags the code reads as
            // authoritative. The other three of the twenty are the nether's
            // and the End's.
            "all seventeen overworld structure sets are generated: \
             mineshafts, villages, trial chambers, ocean ruins (warm and \
             cold), shipwrecks (submerged and beached), ruined portals, buried \
             treasures, igloos, swamp huts, jungle temples, desert pyramids, \
             pillager outposts, trail ruins, strongholds, woodland mansions \
             (with their evokers, vindicators and allays), ancient cities \
             and ocean monuments (with their elder guardians)",
            // The ancient city is the one jigsaw structure whose feature
            // elements run: it had no shipped output, so its piece stream is
            // `Faithful` unconditionally rather than behind the knob.
            "an ancient city runs its `sculk_patch_ancient_city` feature \
             elements on its own piece stream, which is threaded for ancient \
             cities regardless of `RUSTMC_JIGSAW_STREAM`; sculk spreads across \
             chunk borders in both games, so its sculk is order-dependent and \
             is measured against a vanilla-against-vanilla floor",
            // Named here as well as at the refusal site, because a caveat
            // that lives only in the file it corrects does not travel —
            // AGENT-BRIEF says so, having discovered the same gamerule id
            // twice.
            // **THIS ENTRY HAS BEEN TRUE, THEN FALSE, AND IS NOW TRUE AGAIN.
            // Read the state, not the history.** `village-pool-elements`
            // rewrote it on 2026-08-10 to say the elements ARE placed, which
            // was true of that branch. Landing it on top of the jigsaw stream
            // work (2026-08-18, branch `worldgen-land`) made it false again:
            // running a feature element means spending its draws on the
            // structure's piece stream, and that stream is `None` at this
            // server's default. So the elements are PORTED — `block_pile` and
            // `rotated_block_provider` are in `rustmc-worldgen` with their own
            // tests — and NOT RUN from here.
            "a village's `feature_pool_element`s are NOT placed: `block_pile` \
             and `rotated_block_provider` are ported and tested, but running \
             one spends its draws on the structure's piece stream, which is \
             opt-in behind `RUSTMC_JIGSAW_STREAM` and off by default, so this \
             path refuses the element and records the refusal. What that \
             costs is measured: 99 order-stable blocks across five elements \
             of the (81,77) village on the r=16 seed 20260722 window, and a \
             desync of every later container in the same start. The (46,77) \
             village's 14 elements are outside every measured window",
            // The walk is gated piece for piece against vanilla's own saved
            // `Children[]` — `worldgen-dump trial-chamber-oracle` — but the
            // BLOCKS a chamber writes have no such oracle, and a chamber
            // carries block entities this port does not write at all: no
            // trial spawner contents, no vault contents, no chest loot, no
            // decorated pot sherds.
            "a trial chamber's placement is gated against vanilla's saved \
             piece list, but its trial spawners, vaults, chests and decorated \
             pots are placed as bare blocks with no block entity",
            "a shipwreck's rotation pivot (4, 0, 15) is ported but UNVERIFIED: \
             the reference wreck is `rot=NONE`, under which the pivot cancels",
            // Vanilla's outcome when every entry of a set refuses is "no
            // structure here". Ours cannot express that yet for the mineshaft.
            "a chunk where BOTH mineshaft variants refuse their biome tag \
             still gets a plain mineshaft, where vanilla gets none",
            "template entities (an igloo basement's villager and zombie \
             villager, an outpost cage's allays and iron golem, a village's \
             villagers and cats) are not placed, and a drowned or zombie that \
             rolls a chicken or zombie-nautilus jockey refuses it",
            "a mineshaft's seed index is now DERIVED from the datapack \
             (structure::step_index) and agrees with the two independent \
             measurements that preceded it: a region diff, and \
             `worldgen-dump mineshaft-ceiling` reading the stream offset out \
             of vanilla's blocks, which finds index 1 the only one that lets \
             a chunk's first corridor enter at draw 0",
            // Corrected 2026-08-17, in the commit that made the old line
            // untrue. It said "no spawner contents" flatly. A caveat list that
            // lags the code reads as authoritative and is worse than none.
            "entities are not written: no chest minecarts. Block entities are \
             written for the classes docs/DETERMINISM.md \u{a7}42 lists and for no \
             others, and the placer-written ones only under \
             RUSTMC_RECORD_BLOCK_ENTITIES=1 \u{2014} so a dump taken without it \
             carries a dungeon spawner with no mob and a chest with no loot \
             table, exactly as before",
            // Kept, but it is not what the r7 bubble_column rows are: those
            // are magma blocks landing in different places, and the columns
            // simply follow them. See BENCH.md.
            "bubble columns are formed by a sweep, not by scheduled ticks",
        ];
        if self.through >= Through::Decoration {
            out.push("precipitation ignores `has_precipitation`: snow in dry cold biomes");
        }
        if self.through < Through::Decoration {
            out.push("decoration did not run");
        }
        if self.through < Through::Carvers {
            out.push("carvers did not run");
        }
        if self.through < Through::Surface {
            out.push("surface rules did not run");
        }
        out
    }
}

/// The overworld's vertical extent.
const MIN_Y: i32 = -64;
const HEIGHT: i32 = 384;
const DEFAULT_BLOCK: &str = "minecraft:stone";

/// One chunk's biome container: the palette, and one id per 4x4x4 cell.
type BiomeContainer = (Vec<String>, Vec<u16>);

/// Everything the surface stage's per-chunk walk needs that is the same for
/// every chunk.
///
/// Bundled so the interior worker pool and the sequential perimeter run the
/// *same* body rather than two copies that can drift apart — which is the
/// only way a byte-identical claim about the split survives the next edit.
/// The surface stage's biome inputs, resolved to integers once before the
/// stage runs.
///
/// # What moved, and what did not
///
/// Nothing here changes a value. The quart fuzz, the vertical clamp and the
/// `Canvas::biome_index` cell arithmetic are the same expressions they were;
/// what changed is that the answer comes back as a [`BiomeId`] instead of a
/// freshly allocated `String`, and that the two lookups behind it — the
/// `BTreeMap<(i32,i32)>` walk to find the container and the
/// `BTreeMap<String, BiomeEntry>` walk to find its climate — became array
/// indexing.
///
/// [`BiomeId`]: rustmc_worldgen::surface::BiomeId
struct SurfaceBiomes {
    palette: rustmc_worldgen::surface::BiomePalette,
    /// `BiomeEntry::climate`, indexed by id.
    climate: Vec<rustmc_worldgen::biome::temperature::BiomeClimate>,
    /// Every generated chunk's biome container with its **per-chunk** palette
    /// already resolved to global ids. Cell order is `Canvas::biome_index`'s,
    /// y-major then z then x in 4x4x4 cells, exactly as before.
    snapshot: BTreeMap<(i32, i32), Vec<rustmc_worldgen::surface::BiomeId>>,
    canvas_min_y: i32,
    /// `BiomeManager.obfuscateSeed(seed)`.
    zoom: i64,
    /// [`PaletteOrder::Forward`] on every real run. Kept so the resample path
    /// answers the same way the snapshot does under `poison`.
    order: PaletteOrder,
}

/// How [`SurfaceBiomes::new`] issues biome ids. **A falsification instrument,
/// off unless asked for by name** — `RUSTMC_BIOME_PALETTE_ORDER`.
///
/// A sweep on 2026-08-06 found that rebuilding this palette in reverse changed
/// 4 of 4 region files, and named no consumer. `reverse` alone cannot name one
/// either, because it changes two things at once: every id's **numeric value**
/// and every pair's **relative order**. `shift` changes only the first — it
/// interns *k* unreachable names ahead of the directory, so biome *i* gets
/// `i + k` and every `<` between two real biomes still answers what it did.
///
/// So the pair is a discriminator, and this is the only reason both exist:
///
/// * `shift` moves output → some consumer reads the id's **value** (a hash, an
///   arithmetic mix, or an index into a table built somewhere other than the
///   loop below).
/// * `shift` identical and `reverse` moves output → some consumer reads the
///   **order** (a comparison, a sort, a lowest-id tie-break).
/// * neither moves output → the 2026-08-06 result does not reproduce.
///
/// # `poison` is the arm that makes the other two mean anything
///
/// A null from `reverse` and `shift` is worth exactly as much as the proof
/// that this knob reaches the generating path at all. Rule 7: when a
/// measurement clears every candidate, suspect the measurement. So there is a
/// fourth mode that **must** move output — it answers every biome query with
/// the first palette id, which is `id-of-always-zero` from the 2026-08-06
/// sweep re-expressed as a runtime knob. If `poison` comes back clean the
/// instrument is dead and no other row in the table may be read.
///
/// `ci/biome-palette-order.sh` runs exactly that and is the gate.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum PaletteOrder {
    Forward,
    Reverse,
    Shift(usize),
    Poison,
}

impl PaletteOrder {
    fn from_env() -> Self {
        match std::env::var("RUSTMC_BIOME_PALETTE_ORDER")
            .ok()
            .as_deref()
            .map(str::trim)
        {
            None | Some("") | Some("forward") => Self::Forward,
            Some("reverse") => Self::Reverse,
            Some("poison") => Self::Poison,
            Some(other) => match other.strip_prefix("shift").map(str::trim) {
                // `shift` on its own is `shift 1`; a count can be given so a
                // single-slot shift that happens to land on a symmetry cannot
                // be mistaken for a null.
                Some("") => Self::Shift(1),
                Some(n) => Self::Shift(n.parse().unwrap_or_else(|_| {
                    panic!("RUSTMC_BIOME_PALETTE_ORDER=`{other}`: `shift` takes a count")
                })),
                // Refuse rather than defaulting. A typo that silently ran the
                // control would report "no difference" and close the question
                // with a measurement of nothing.
                None => panic!(
                    "RUSTMC_BIOME_PALETTE_ORDER=`{other}`: \
                     expected forward|reverse|shift[ N]|poison"
                ),
            },
        }
    }
}

impl SurfaceBiomes {
    fn new(
        biome_data: &BTreeMap<String, BiomeEntry>,
        raw: &BTreeMap<(i32, i32), BiomeContainer>,
        canvas_min_y: i32,
        zoom: i64,
    ) -> Self {
        // The datapack's whole biome directory, in `BTreeMap` order. The
        // order keeps a seed's ids reproducible run to run and nothing more:
        // rebuilding this palette in reverse is measured **undetectable** in
        // the generated world — 0 of 4 region files at r=16 against a poison
        // arm that moves 4 of 4. `surface::ORDER_IS_NOT_OBSERVABLE` has the
        // table; `ci/biome-palette-order.sh` is the gate. (This comment
        // asserted the opposite until 2026-08-09.) Built from the registry
        // rather than from the chunks actually generated, so the palette is
        // complete before the stage starts and never has to grow under a
        // worker pool.
        //
        // The palette and the climate table are built in ONE loop, keyed on
        // the id the palette just issued, rather than by iterating the same
        // map twice and trusting the two orders to agree. They would agree
        // today. The point is that a later edit to one loop and not the other
        // would misalign every biome's climate against its id, and that is a
        // defect no value test would catch quickly: the world would still
        // generate, `cold_enough_to_snow` would just be answering about the
        // wrong biome. Two things that must agree, built in two places, is
        // the shape this project has paid for repeatedly.
        let mut palette = rustmc_worldgen::surface::BiomePalette::new();
        let mut climate = Vec::with_capacity(biome_data.len());
        let order = PaletteOrder::from_env();
        // The two injections differ in exactly one respect and that is the
        // whole point of having both — see [`PaletteOrder`].
        let mut ordered: Vec<(&String, &BiomeEntry)> = biome_data.iter().collect();
        let mut pad = 0usize;
        match order {
            PaletteOrder::Forward | PaletteOrder::Poison => {}
            PaletteOrder::Reverse => ordered.reverse(),
            PaletteOrder::Shift(k) => pad = k,
        }
        for i in 0..pad {
            // A name no chunk holds and no surface rule names, so it can only
            // ever move the ids the real biomes get. Its climate slot is
            // filled so the id-to-climate invariant below still holds; nothing
            // can read it, because nothing can obtain its id.
            let id = palette.intern(&format!("rustmc:palette_shift_{i}"));
            assert_eq!(id as usize, climate.len(), "shift padding lost lockstep");
            climate.push(
                ordered
                    .first()
                    .expect("the biome directory is not empty")
                    .1
                    .climate,
            );
        }
        for (name, entry) in ordered {
            let id = palette.intern(name);
            assert_eq!(
                id as usize,
                climate.len(),
                "the palette issued id {id} for `{name}` but the climate table is {} long — \
                 the two are built in lockstep and this can only mean the palette deduplicated \
                 a key a BTreeMap should have made unique",
                climate.len()
            );
            climate.push(entry.climate);
        }
        let snapshot = raw
            .iter()
            .map(|(&(cx, cz), (chunk_palette, ids))| {
                // One remap per chunk palette — a handful of entries — in
                // place of a name lookup per query.
                let remap: Vec<rustmc_worldgen::surface::BiomeId> = chunk_palette
                    .iter()
                    .map(|name| {
                        palette.id_of(name).unwrap_or_else(|| {
                            panic!(
                                "chunk ({cx},{cz}) holds biome `{name}`, which is not in the \
                                 datapack's biome directory — the palette is built from that \
                                 directory and a miss here means the two disagree"
                            )
                        })
                    })
                    .collect();
                let global: Vec<rustmc_worldgen::surface::BiomeId> = ids
                    .iter()
                    .map(|&local| {
                        if order == PaletteOrder::Poison {
                            0
                        } else {
                            remap[local as usize]
                        }
                    })
                    .collect();
                ((cx, cz), global)
            })
            .collect();
        // The digest is what lets `ci/biome-palette-order.sh` assert that the
        // arms genuinely built different palettes. Without it a knob that
        // silently did nothing — an env var read in the wrong process, a
        // second palette built somewhere else — would report every injection
        // as undetectable, which is the shape of "you measured the
        // instrument". Printed on every run, because a diagnostic that has to
        // be switched on is one nobody switches on.
        let mut fnv: u64 = 0xcbf2_9ce4_8422_2325;
        for id in 0..palette.len() {
            let id = u16::try_from(id).expect("palette shorter than u16::MAX");
            for b in palette.name(id).bytes().chain(std::iter::once(b'|')) {
                fnv ^= u64::from(b);
                fnv = fnv.wrapping_mul(0x0000_0100_0000_01b3);
            }
        }
        eprintln!(
            "BIOME_PALETTE order={order:?} len={} digest={fnv:016x}",
            palette.len()
        );
        Self {
            palette,
            climate,
            snapshot,
            canvas_min_y,
            zoom,
            order,
        }
    }

    /// Resolve every `biome` condition in the rule against this palette,
    /// once, before the stage runs.
    ///
    /// The assertion is the point. A name that failed to resolve would leave
    /// a condition that can never be true: the rule would still evaluate, the
    /// world would still generate, and one biome's entire surface treatment
    /// would quietly vanish. That is the same shape as the gamerule whose
    /// rejection nobody read, and it is why this refuses instead of warning.
    fn intern_rule(
        &self,
        mut rule: rustmc_worldgen::surface::rule::Rule,
    ) -> rustmc_worldgen::surface::rule::Rule {
        let mut missing = Vec::new();
        rule.intern_biomes(&|name| self.palette.id_of(name), &mut missing);
        assert!(
            missing.is_empty(),
            "the surface rule names biomes absent from the datapack's biome directory: {missing:?}"
        );
        rule
    }

    /// The id for a name the snapshot could not answer — the perimeter's
    /// resample path.
    fn id_of_name(&self, name: &str) -> rustmc_worldgen::surface::BiomeId {
        if self.order == PaletteOrder::Poison {
            return 0;
        }
        self.palette.id_of(name).unwrap_or_else(|| {
            panic!("resampled biome `{name}` is not in the datapack's biome directory")
        })
    }

    /// `BiomeManager#getBiome` read out of the stored containers, by id: the
    /// fuzzed quart, then that cell.
    ///
    /// # The vertical clamp
    ///
    /// `LevelReader#getNoiseBiome` asks the region for the chunk at
    /// `(toSection(qx), toSection(qz))` and **only if that is null** falls
    /// through to `getUncachedNoiseBiome` and resamples the climate. When the
    /// chunk is there it calls `ChunkAccess#getNoiseBiome`, which clamps:
    ///
    /// ```java
    ///   int i = QuartPos.fromBlock(this.getMinY());
    ///   int j = i + QuartPos.fromBlock(this.getHeight()) - 1;
    ///   int k = Mth.clamp(y, i, j);
    /// ```
    ///
    /// and never resamples. So `None` here means exactly one thing — the
    /// snapshot has no such chunk — and it is the one case vanilla also
    /// answers by resampling. That is what makes a chunk with all nine
    /// neighbours on the canvas *unable* to reach the shared
    /// `ParameterList`: the biome fuzz reaches at most one chunk out.
    fn id_at(&self, x: i32, y: i32, z: i32) -> Option<rustmc_worldgen::surface::BiomeId> {
        // The container has to be found before `cells_y` is known, so the
        // quart is computed once with a placeholder and the clamp redone.
        let (qx, qy, qz) = rustmc_worldgen::biome::manager::quart_for_block(self.zoom, x, y, z);
        let (bx, by, bz) = (qx << 2, qy << 2, qz << 2);
        let ids = self.snapshot.get(&(bx >> 4, bz >> 4))?;
        Some(Self::read(ids, self.canvas_min_y, by, bz, bx))
    }

    fn read(
        ids: &[rustmc_worldgen::surface::BiomeId],
        canvas_min_y: i32,
        by: i32,
        bz: i32,
        bx: i32,
    ) -> rustmc_worldgen::surface::BiomeId {
        let cells_y = i32::try_from(ids.len() / 16).unwrap_or(1);
        let cell_y = ((by - canvas_min_y) >> 2).clamp(0, cells_y - 1);
        let cell_z = (bz & 15) >> 2;
        let cell_x = (bx & 15) >> 2;
        let index = usize::try_from(cell_y * 16 + cell_z * 4 + cell_x).unwrap_or(0);
        ids[index]
    }

    /// The 3x3 of containers one chunk's surface pass can reach.
    ///
    /// The biome fuzz reaches at most one chunk out — that is the standing
    /// guard behind `RUSTMC_SURFACE_TIES=1`, whose interior fallback count
    /// must stay ZERO — so 3x3 covers every query an interior chunk makes,
    /// and anything outside it falls back to the map rather than being
    /// wrong.
    fn neighbourhood(&self, cx: i32, cz: i32) -> Neighbourhood<'_> {
        let mut cells: [Option<&[rustmc_worldgen::surface::BiomeId]>; 9] = [None; 9];
        for dz in -1i32..=1 {
            for dx in -1i32..=1 {
                let slot = usize::try_from((dz + 1) * 3 + (dx + 1)).expect("0..9");
                cells[slot] = self
                    .snapshot
                    .get(&(cx + dx, cz + dz))
                    .map(std::vec::Vec::as_slice);
            }
        }
        Neighbourhood {
            owner: self,
            centre: (cx, cz),
            cells,
        }
    }
}

/// A chunk's 3x3 container neighbourhood, resolved once per chunk.
///
/// Replaces a `BTreeMap<(i32,i32)>` walk over up to 4,761 entries — about
/// twelve pointer chases — on every one of the ~28,864 biome answers a chunk
/// needs, with a bounds check and an array index.
struct Neighbourhood<'a> {
    owner: &'a SurfaceBiomes,
    centre: (i32, i32),
    cells: [Option<&'a [rustmc_worldgen::surface::BiomeId]>; 9],
}

impl Neighbourhood<'_> {
    fn id_at(&self, x: i32, y: i32, z: i32) -> Option<rustmc_worldgen::surface::BiomeId> {
        let (qx, qy, qz) =
            rustmc_worldgen::biome::manager::quart_for_block(self.owner.zoom, x, y, z);
        let (bx, by, bz) = (qx << 2, qy << 2, qz << 2);
        let (dx, dz) = ((bx >> 4) - self.centre.0, (bz >> 4) - self.centre.1);
        if (-1..=1).contains(&dx) && (-1..=1).contains(&dz) {
            let slot = usize::try_from((dz + 1) * 3 + (dx + 1)).expect("0..9");
            let ids = self.cells[slot]?;
            return Some(SurfaceBiomes::read(
                ids,
                self.owner.canvas_min_y,
                by,
                bz,
                bx,
            ));
        }
        // Outside the 3x3. The fuzz cannot reach here, so this is the
        // perimeter's business and correctness beats speed: ask the map.
        self.owner.id_at(x, y, z)
    }
}

struct SurfaceShared<'a> {
    rule: &'a rustmc_worldgen::surface::rule::Rule,
    noises: &'a std::sync::Arc<rustmc_worldgen::surface::world::SurfaceNoises>,
    temperature_noises: &'a rustmc_worldgen::biome::temperature::TemperatureNoises,
    /// `SurfaceLevels`' density function, so each worker can build a memo of
    /// its own. The memo is of a pure function of position, so a per-worker
    /// copy costs recomputation and cannot change a value.
    preliminary: &'a rustmc_worldgen::density::DensityFunction,
    /// The palette, the id-indexed climate table and every generated chunk's
    /// biome container, taken once before the stage starts. The stage writes
    /// blocks and nothing else, so these are frozen inputs and sharing one
    /// copy with a worker pool is sound.
    biomes: &'a SurfaceBiomes,
    /// The dimension's `sea_level` and `default_block`. Both are
    /// `NoiseGeneratorSettings` fields and both reach the rule walk: the
    /// `temperature` condition and the surface context take the sea level,
    /// and the walk needs to know which block counts as "stone" for
    /// `stone_depth`. 63/stone for the overworld, 32/netherrack for the
    /// nether.
    sea_level: i32,
    default_block: &'a str,
    /// The **generator's** vertical extent, not the canvas's. See
    /// [`stage::surface::GenExtent`] — in the nether they differ and the
    /// difference decides where `below_top` resolves.
    generator: stage::surface::GenExtent,
}

// `stored_biome_at` lived here and is now `SurfaceBiomes::id_at` above, which
// answers with an id instead of a `String`. The vertical clamp it documented
// is unchanged and is documented there.

/// One chunk of the surface stage, against anything that can be written into
/// chunk-locally — the whole canvas, or one [`ChunkWriter`].
///
/// [`ChunkWriter`]: rustmc_worldgen::canvas::ChunkWriter
#[allow(
    clippy::too_many_arguments,
    reason = "\
    the surface system's own inputs plus the two per-worker memos. Bundling
    the memos into `SurfaceShared` would make them shared, which is the one
    thing they must not be."
)]
fn surface_one_chunk<T: stage::surface::SurfaceTarget>(
    target: &mut T,
    chunk_x: i32,
    chunk_z: i32,
    heights: &[i32; 256],
    shared: &SurfaceShared<'_>,
    levels: &RefCell<SurfaceLevels>,
    flat: &FlatCaches,
    biome_at: &dyn Fn(i32, i32, i32) -> rustmc_worldgen::surface::BiomeId,
) {
    // The climate comes out of a `Vec` indexed by id. It was a
    // `BTreeMap<String, BiomeEntry>` lookup keyed on the name these closures
    // had just allocated — and every key shares the `minecraft:` prefix, so
    // each comparison on the way down the tree read ten equal bytes first.
    let climate = |id: rustmc_worldgen::surface::BiomeId| {
        *shared
            .biomes
            .climate
            .get(id as usize)
            .expect("every biome in the palette has a climate")
    };
    let cold = |x: i32, y: i32, z: i32| {
        shared.temperature_noises.cold_enough_to_snow(
            climate(biome_at(x, y, z)),
            x,
            y,
            z,
            shared.sea_level,
        )
    };
    // `shouldMeltFrozenOceanIcebergSlightly` — a different threshold on the
    // same height-adjusted temperature, not a reuse of `cold`.
    let melt = |x: i32, y: i32, z: i32| {
        shared.temperature_noises.height_adjusted_temperature(
            climate(biome_at(x, y, z)),
            x,
            y,
            z,
            shared.sea_level,
        ) > 0.1
    };
    let biome_name =
        |id: rustmc_worldgen::surface::BiomeId| shared.biomes.palette.name(id).to_string();
    let mut oracle = WorldSurfaceOracle::with_noises(
        std::sync::Arc::clone(shared.noises),
        ChunkSurfaceState {
            heights,
            biome: biome_at,
            biome_name: &biome_name,
            min_surface_level: &|_, _| 0,
            temperature: &cold,
            melt_iceberg_slightly: &melt,
        },
    );
    // The blended preliminary surface, from the four cell corners.
    let blended = |x: i32, z: i32, depth: i32| {
        let corners = min_surface_cell_corners(x, z);
        let sampled = corners.map(|(cx, cz)| levels.borrow_mut().at(flat, cx, cz));
        min_surface_level(sampled, x, z, depth)
    };
    stage::surface::build_chunk(
        target,
        shared.rule,
        &mut oracle,
        shared.sea_level,
        shared.default_block,
        shared.generator,
        &blended,
        chunk_x,
        chunk_z,
    );
}

/// `SurfaceSystem#topMaterial` — the surface rule tree evaluated at exactly
/// one block, which is what `CarvingContext#topMaterial` asks for when a
/// carver breaks through to the surface and leaves bare dirt behind.
///
/// This is **not** the surface stage in miniature and the difference is the
/// whole reason it is cheap. `SurfaceSystem.topMaterial` builds a one-shot
/// `SurfaceRules$Context`, compiles the `RuleSource` and calls
/// `tryApply(x, y, z)` once. There is no column walk: `stoneDepthAbove` and
/// `stoneDepthBelow` are both **hardcoded to 1** in the bytecode, and the
/// biome `Set` argument is `null` because no rule a carver can reach
/// consults it.
///
/// The fluid flag has exactly one use, and it is the water height:
/// `under_fluid` means the block just written *above* this one holds a
/// fluid, so the water surface sits at `y + 1`; otherwise the column counts
/// as having no water at all and `waterBlockCheck` passes unconditionally.
/// That single bit is what decides `grass_block` against `dirt`, so getting
/// it from the carved state rather than from the block below is not a
/// detail.
///
/// `None` — the rule tree having no opinion — leaves the dirt alone, which
/// is also what this whole path did before it was implemented.
#[allow(clippy::too_many_arguments, reason = "the one-shot context's inputs")]
fn carver_top_material(
    shared: &SurfaceShared<'_>,
    oracle: &mut WorldSurfaceOracle<'_>,
    levels: &RefCell<SurfaceLevels>,
    flat: &FlatCaches,
    x: i32,
    y: i32,
    z: i32,
    under_fluid: bool,
) -> Option<String> {
    let depth = oracle.surface_depth_at(x, z);
    let mut ctx = SurfaceContext::new(MIN_Y, HEIGHT, shared.sea_level);
    ctx.update_xz(x, z, depth);
    // `Context#getMinSurfaceLevel` is lazy in vanilla and blended from the
    // four cell corners here exactly as the surface stage blends it.
    let corners = min_surface_cell_corners(x, z);
    let sampled = corners.map(|(cx, cz)| levels.borrow_mut().at(flat, cx, cz));
    let blended = min_surface_level(sampled, x, z, depth);
    let _ = ctx.min_surface_level(|_, _| blended);
    let water = if under_fluid {
        y + 1
    } else {
        rustmc_worldgen::surface::context::NO_WATER
    };
    ctx.update_y(1, 1, water, y);
    rustmc_worldgen::surface::eval::apply(shared.rule, &mut ctx, oracle).map(|state| state.0)
}

/// Process CPU seconds so far — every thread, including ones that have
/// already exited.
///
/// `/proc/self/stat`'s `utime`/`stime` are the **thread group's** totals, so
/// a worker pool that is created and joined inside a stage still shows up
/// after its threads are gone. That is the whole reason this is not
/// `Instant`: wall time hides a parallelism tax by construction, and the
/// +28.2% CPU-second tax measured in BENCH.md is invisible to every clock in
/// this file. No `libc` dependency: the two fields come out of `/proc`.
///
/// Units are `USER_HZ`, which is 100 on every Linux this project runs on —
/// a 10 ms tick against stages measured in seconds. Returns `None` off Linux
/// or if the file cannot be read, and the report then falls back to wall
/// time alone rather than printing a wrong number.
pub(crate) fn process_cpu_seconds() -> Option<f64> {
    let stat = std::fs::read_to_string("/proc/self/stat").ok()?;
    // `comm` can itself contain spaces and brackets, so fields are counted
    // from the LAST ')', not from the start.
    let rest = &stat[stat.rfind(')')? + 1..];
    let fields: Vec<&str> = rest.split_whitespace().collect();
    // After the ')' the first token is field 3 (`state`), so `utime` (14) is
    // index 11 and `stime` (15) is index 12.
    let utime: f64 = fields.get(11)?.parse().ok()?;
    let stime: f64 = fields.get(12)?.parse().ok()?;
    Some((utime + stime) / 100.0)
}

/// Per-stage wall **and CPU** time, printed when `RUSTMC_STAGE_TIMES` or
/// `RUSTMC_STAGE_CPU` is set.
///
/// The whole pipeline costs ~0.47 s a chunk against the noise stage's few
/// milliseconds, so better than 95% of it is spent after the fill and a
/// per-stage split is the difference between optimising the right thing and
/// the convenient thing. Five `Instant`s a world is not worth gating behind
/// a feature flag; the printing is, so a gate's output stays clean.
///
/// **The two switches are not the same instrument, and that is the point.**
/// `RUSTMC_STAGE_TIMES` also turns on the surface stage's `Cell` probes,
/// which force that whole stage down the sequential path — so a table read
/// from it is not the parallel pipeline's shape, and it can never answer how
/// a stage *scales*. `RUSTMC_STAGE_CPU` prints this table and nothing else,
/// so the run it measures is the run the benchmark ships.
struct StageTimes {
    started: std::time::Instant,
    cpu_started: Option<f64>,
    /// `(stage, wall seconds, cpu seconds)`.
    marks: Vec<(&'static str, f64, f64)>,
}

impl StageTimes {
    fn new() -> Self {
        Self {
            started: std::time::Instant::now(),
            cpu_started: process_cpu_seconds(),
            marks: Vec::new(),
        }
    }

    fn mark(&mut self, stage: &'static str) {
        let now = std::time::Instant::now();
        let cpu_now = process_cpu_seconds();
        let cpu = match (self.cpu_started, cpu_now) {
            (Some(before), Some(after)) => after - before,
            _ => 0.0,
        };
        self.marks
            .push((stage, (now - self.started).as_secs_f64(), cpu));
        self.started = now;
        self.cpu_started = cpu_now;
    }

    fn report(&self, chunks: usize) {
        if std::env::var_os("RUSTMC_STAGE_TIMES").is_none()
            && std::env::var_os("RUSTMC_STAGE_CPU").is_none()
        {
            return;
        }
        let total: f64 = self.marks.iter().map(|(_, t, _)| t).sum();
        let cpu_total: f64 = self.marks.iter().map(|(_, _, c)| c).sum();
        eprintln!(
            "stage {:<11} {:>8}  {:>6}  {:>9}  {:>7}  {:>8}",
            "NAME", "wall s", "share", "ms/chunk", "cpu s", "cores"
        );
        for (stage, t, cpu) in &self.marks {
            eprintln!(
                "stage {stage:<11} {t:8.2}  {:5.1}%  {:9.1}  {cpu:7.2}  {:8.2}",
                t / total * 100.0,
                t * 1000.0 / chunks as f64,
                // Mean cores busy through the stage. 1.00 on a sequential
                // stage; a parallel stage that reads below its worker count
                // is where the tax lives.
                if *t > 0.0 { cpu / t } else { 0.0 },
            );
        }
        eprintln!(
            "stage {:<11} {total:8.2}  100.0%  {:9.1}  {cpu_total:7.2}  {:8.2}  over {chunks} chunks",
            "TOTAL",
            total * 1000.0 / chunks as f64,
            if total > 0.0 { cpu_total / total } else { 0.0 },
        );
        let (serial_wall, serial_cpu) = Self::serial_share(&self.marks);
        let workers = rustmc_worldgen::pipeline::worker_threads() as f64;
        // Amdahl, stated as a **prediction** rather than a diagnosis, because
        // a diagnosis cannot be wrong and this can: if every stage that is
        // currently running at under 1.5 cores were left exactly as it is and
        // every other stage were run at the full worker count, this is the
        // wall time and the average occupancy that would result. Re-run the
        // same square after a change and the two numbers are checkable.
        //
        // It is a bound and not a forecast — no stage reaches its worker
        // count exactly — so a measured `after` that beats it is a signal
        // that the marks are lying, not a triumph.
        let parallel_cpu = cpu_total - serial_cpu;
        let ceiling_wall = serial_wall + parallel_cpu / workers.max(1.0);
        eprintln!(
            "stage SERIAL      {serial_wall:8.2}  {:5.1}%  {:9.1}  {serial_cpu:7.2}  \
             {:8.2}  stages under 1.50 cores",
            if total > 0.0 {
                serial_wall / total * 100.0
            } else {
                0.0
            },
            serial_wall * 1000.0 / chunks as f64,
            if serial_wall > 0.0 {
                serial_cpu / serial_wall
            } else {
                0.0
            },
        );
        eprintln!(
            "stage CEILING     {ceiling_wall:8.2}                            {:8.2}  \
             if the rest ran at {workers:.0} workers",
            if ceiling_wall > 0.0 {
                cpu_total / ceiling_wall
            } else {
                0.0
            },
        );
        crate::jigsaw_library::loads::report();
    }

    /// Wall and CPU seconds spent in stages that are sequential in all but
    /// name.
    ///
    /// A free-standing function over the marks rather than a loop inside
    /// `report`, so the threshold is testable without running a generator.
    /// 1.50 rather than 1.00 because a stage that spawns a pool and then
    /// waits in it still bills a fraction of a second of somebody else's
    /// work; nothing in this pipeline sits between 1.1 and 2.4 cores, so the
    /// classification is not sensitive to where in that gap the line goes.
    fn serial_share(marks: &[(&'static str, f64, f64)]) -> (f64, f64) {
        marks
            .iter()
            .filter(|(_, wall, cpu)| *wall > 0.0 && cpu / wall < 1.5)
            .fold((0.0, 0.0), |(w, c), (_, wall, cpu)| (w + wall, c + cpu))
    }
}

/// One chunk's decoration, run against a world no other chunk has decorated.
///
/// # What this is for
///
/// `docs/DETERMINISM.md` §31 measured that **no** value of
/// `DECORATION_MARGIN` makes a delivered chunk independent of how big the
/// area around it was: a tile of radius `r` with margin `m` decorates out to
/// `r + m` and delivers out to `r`, so its rim is at depth `m` below the
/// outermost decorated ring whatever `m` is, and that outermost ring
/// decorates against a world that stops. 5,753 / 2,201 / 1,130 blocks at
/// margins 1 / 2 / 4 — decreasing, never zero.
///
/// The pyramid in [`rustmc_worldgen::status`] removes the first half of
/// that: a chunk may decorate once its neighbours are **carved**, which is
/// what `ChunkStep`'s `addRequirement(CARVERS, 1)` says, so decoration now
/// stops one isolation reach inside the generated area and no decorating
/// chunk has a void beside it.
///
/// This removes the second half, and it is the half vanilla does not decide
/// for us. `WorldGenRegion.getChunk` caps the status a neighbour may be
/// *asked* for at `directDependencies.get(chessboardDistance)` — `CARVERS`
/// at distance 1 for the `FEATURES` step — and then hands back the live
/// `ProtoChunk`, so what a feature actually observes is whatever the
/// scheduler happened to have finished. Vanilla is measurably not a function
/// of the seed there: two unmodified vanilla runs of one seed and window
/// differ by 32,127 blocks in one chunk order and 146,169 across orders. We
/// take the cap as the contract: a decorating chunk reads the **carved**
/// world, its own writes included and no other chunk's, and the composed
/// world is every chunk's write list replayed onto the one canvas in the
/// canonical chunk order.
///
/// That makes a chunk's feature writes a pure function of the seed and its
/// position, which is what closes
/// `tiled_world::a_chunk_does_not_depend_on_how_big_the_area_around_it_was`.
/// It also makes the pass embarrassingly parallel and retires the level
/// barriers the shared-canvas pass needed.
///
/// `RUSTMC_DECORATE_ISOLATED=0` restores the shared-canvas model in the same
/// binary — see [`rustmc_worldgen::pipeline::isolated_decoration`].
/// What one isolated chunk produced: where it sits in the decoration order,
/// every block it wrote in the order it wrote them, and the post-processing
/// marks it made.
// A fourth member since the block-entity side channel landed: a decorated
// chunk hands back its writes, its post-processing marks and its
// `block_entity::Records`. Carrying them in the same tuple is what keeps them
// replayed in the same order, which matters — the last record at a position is
// the one saved. `docs/DETERMINISM.md` §42.
type ComposedChunk = (
    usize,
    Vec<(i32, i32, i32, String)>,
    PostProcessingMarks,
    rustmc_worldgen::block_entity::Records,
    rustmc_worldgen::canvas::EntityRecords,
);

struct IsolatedDecoration {
    on: bool,
    reach: i32,
    /// One entry per decorated chunk, ranked.
    ///
    /// Ranked rather than pushed, because the parallel form finishes chunks
    /// out of order and the replay order **is** the world: two chunks whose
    /// features overlap resolve by who wrote last.
    composed: Vec<ComposedChunk>,
}

impl IsolatedDecoration {
    fn new() -> Self {
        Self {
            on: rustmc_worldgen::pipeline::isolated_decoration(),
            reach: rustmc_worldgen::pipeline::isolation_reach(),
            composed: Vec::new(),
        }
    }

    /// The chunks an isolated decoration of `(x, z)` is given.
    fn footprint(reach: i32, x: i32, z: i32) -> Vec<(i32, i32)> {
        (-reach..=reach)
            .flat_map(|dz| (-reach..=reach).map(move |dx| (x + dx, z + dz)))
            .collect()
    }

    /// Decorate one chunk, sequentially.
    fn run<R>(
        &mut self,
        pipeline: &mut Pipeline,
        rank: usize,
        x: i32,
        z: i32,
        f: impl FnOnce(&mut Canvas) -> R,
    ) -> R {
        if !self.on {
            let canvas = pipeline.canvas_mut();
            canvas.set_home(x, z);
            return f(canvas);
        }
        let mut group = pipeline
            .canvas()
            .clone_region(Self::footprint(self.reach, x, z));
        group.set_home(x, z);
        group.record_writes();
        let out = f(&mut group);
        let writes = group.take_write_log().expect("recording was switched on");
        let records = group.take_block_entities();
        let entities = group.take_entities();
        self.composed.push((
            rank,
            writes,
            group.take_post_processing(),
            records,
            entities,
        ));
        out
    }

    /// Replay every chunk's writes onto the one canvas, in decoration order.
    ///
    /// A no-op under the shared-canvas model, where the writes went straight
    /// into the canvas as they were made.
    fn compose(mut self, pipeline: &mut Pipeline) {
        if !self.on {
            return;
        }
        self.composed.sort_by_key(|(rank, _, _, _, _)| *rank);
        for (_, writes, marks, records, entities) in self.composed {
            pipeline.canvas_mut().replay_writes(&writes);
            pipeline.canvas_mut().absorb_post_processing(marks);
            // In decoration order, beside the writes, because a position two
            // chunks both recorded must end up with the payload of whichever
            // wrote its block last.
            pipeline.canvas_mut().absorb_block_entities(records);
            pipeline.canvas_mut().absorb_entities(entities);
        }
    }
}

/// Generate `area` for `seed`, through the named stage.
///
/// # Errors
/// If the extract is missing or a stage's inputs cannot be built.
pub fn generate(seed: i64, area: Area, through: Through) -> Result<Generated, String> {
    generate_decorating(seed, area, through, None)
}

/// The nether's vertical extent.
///
/// **Two different numbers, and conflating them is a 50% parity error.**
/// `DimensionType.NETHER` stores 256 blocks (measured: every chunk in a
/// vanilla nether region has sixteen sections, y 0..255), while
/// `worldgen/noise_settings/nether.json` generates only `min_y 0, height
/// 128`. The canvas is the storage range so the region file has the same
/// sections vanilla's does; the fill is clamped to the noise range by
/// `FillSettings::nether`, exactly as `NoiseSettings.clampToHeightAccessor`
/// clamps it in vanilla.
const NETHER_MIN_Y: i32 = 0;
const NETHER_STORAGE_HEIGHT: i32 = 256;
/// `nether.json`'s `noise.height` — what the **generator** makes, against the
/// 256 the dimension **stores**. `below_top(5)` is y 122 off this number and
/// y 250 off the other one.
const NETHER_NOISE_HEIGHT: i32 = 128;
const NETHER_DEFAULT_BLOCK: &str = "minecraft:netherrack";
/// `nether.json`'s `sea_level`. It is the lava sea, and the surface context
/// and the `temperature` condition must both see it — vanilla passes one
/// value to both.
const NETHER_SEA_LEVEL: i32 = 32;

/// The End's vertical extent — the same two-number trap the nether has.
///
/// `DimensionType.END` stores 256 blocks (measured: a vanilla End chunk on
/// disk has sixteen sections, y 0..255, and a whole-column census of the r=7
/// reference is 14,745,600 blocks over 225 chunks), while
/// `worldgen/noise_settings/end.json` generates `min_y 0, height 128`. The
/// canvas is the storage range; the fill is clamped to the noise range by
/// `FillSettings::end`.
const END_MIN_Y: i32 = 0;
const END_STORAGE_HEIGHT: i32 = 256;
/// `end.json`'s `noise.height`. Every `below_top` anchor in an End placement
/// chain resolves against **this**, not the 256 above — the mistake that cost
/// the nether 53,865 blocks.
const END_NOISE_HEIGHT: i32 = 128;
const END_DEFAULT_BLOCK: &str = "minecraft:end_stone";
/// `end.json`'s `sea_level`. Zero, and there is no fluid to put at it — the
/// End's `default_fluid` is air.
const END_SEA_LEVEL: i32 = 0;

/// Generate the **End** for `seed`, through the named stage.
///
/// # What this does and does not run
///
/// Noise, biomes and the surface rule. **There are no carvers in the End at
/// all** — that is not a gap, it is the dimension: `end.json` names no
/// carvers and no End biome carries a `carvers` entry, so an entire stage of
/// divergence does not exist here. Features and the one structure set (end
/// cities) do not run yet, and the caveats say so.
///
/// # Errors
/// If the extract is missing or a stage's inputs cannot be built.
/// The order the decoration stage walks `area`'s chunks in, as selected by
/// `RUSTMC_DECORATE_ORDER`. Every dimension's decoration stage takes its
/// traversal from here, so the order sweep reaches all of them.
///
/// **Nine names, eight orders.** `diag` walks a sequence no other name walks
/// — its digest is unique — and still writes a region tree byte-identical to
/// `default`, checked with `diff -rq` by `ci/decorate-order-intersect.sh`.
/// Two traversals that never separate two chunks whose features can touch the
/// same block produce one world. Quote the sweep as eight.
///
/// A feature writes one chunk out, so wherever two chunks' features touch the
/// same block the order decides the answer — measured, not assumed: two
/// vanilla worlds of one seed generated at different centres differ by 637
/// blocks, all of it ore veins. This knob exists to find out whether the same
/// mechanism explains the cave features, where our output matches
/// `DecorateGolden` and both differ from a server-generated world.
///
/// When the variable is set, one line goes to stderr naming the order and a
/// digest of the sequence it produced. That line is the answer to "did the
/// sweep actually vary the order?" — a sweep that silently ran the default
/// nine times is indistinguishable from a pass without it, and a
/// same-digest-nine-times run is the failure it hides. Unset stays silent, so
/// the default path's output is byte-for-byte what it was.
fn decorate_order_for(area: Area) -> Vec<(i32, i32)> {
    let mut v: Vec<(i32, i32)> = area.chunks().collect();
    let (cx, cz) = (
        (area.min_chunk_x + area.max_chunk_x) / 2,
        (area.min_chunk_z + area.max_chunk_z) / 2,
    );
    let requested = std::env::var("RUSTMC_DECORATE_ORDER").unwrap_or_default();
    let mut unrecognised = false;
    match requested.as_str() {
        // `reverse` walks the raster the other way.
        "reverse" => v.reverse(),
        // z outer, x inner — the raster transposed.
        "zx" => v.sort_by_key(|&(x, z)| (z, x)),
        // Chebyshev rings out from the centre, which is the shape a
        // ticket-driven chunk system loads in.
        "spiral" => v.sort_by_key(|&(x, z)| ((x - cx).abs().max((z - cz).abs()), z, x)),
        // The same rings, worked inwards.
        "spiral_in" => {
            v.sort_by_key(|&(x, z)| (-(x - cx).abs().max((z - cz).abs()), z, x));
        }
        // Two more, added to test whether the *order-invariant* residual
        // is really invariant. A mismatch that survives every order is
        // taken as port error rather than order noise; that inference is
        // only as good as the set of orders, so the set has to be
        // widened until the intersection stops shrinking.
        "zx_rev" => v.sort_by_key(|&(x, z)| (z, std::cmp::Reverse(x))),
        // Anti-diagonal sweep — neighbours are visited in a different
        // relative order from any raster or ring.
        "diag" => v.sort_by_key(|&(x, z)| (x + z, x)),
        // z outer **descending**, x inner ascending.
        //
        // Not symmetry-hunting: this is the only simple order that
        // satisfies both of the pairwise constraints the main window
        // actually measures. Every one of its 13 ore-vs-lake mismatches
        // needs chunk (63,65) to decorate **before** (63,64) — the
        // server's lake shell beats our ore blob on exactly the 11
        // gravel and 2 diorite where the two overlap — while the one
        // overlap that *agrees*, an `ore_lapis` from (63,63) under a
        // lake from (64,63), needs x ascending.
        "zx_zrev" => v.sort_by_key(|&(x, z)| (std::cmp::Reverse(z), x)),
        // Chebyshev rings out from **spawn**, not from the window centre.
        //
        // A server forceloads outward from the spawn chunk, so the order a
        // chunk's neighbours decorate in depends on their distance from
        // (0,0) rather than from whatever square is being measured. The
        // six orders sampled here are all window-relative and none of them
        // is that — which matters, because every mismatch this project
        // calls "genuine" survives all six, and surviving six synthetic
        // orders is not the same as surviving a server's.
        "spawn" => v.sort_by_key(|&(x, z)| (x.abs().max(z.abs()), z, x)),
        // `default` is the raster `Area::chunks()` already produces. It is
        // named so a caller can state the condition instead of leaving it
        // unset, which is the whole of ORACLE rule 29: a chunk order that is
        // implicit is a chunk order nobody set.
        //
        // The empty string is the var being unset, which is every caller that
        // has not opted in. It stays silent and unchanged: this guard is about
        // a name that was *given* and not understood, not about the absence of
        // one. Getting that wrong would have made every existing dump exit 2.
        "default" | "" => {}
        _ => unrecognised = true,
    }
    // AN UNRECOGNISED NAME MUST NOT LOOK LIKE A CONFIRMATION. The arm above
    // used to be a bare `_ => {}`, so `RUSTMC_DECORATE_ORDER=zx_zev` silently
    // produced the default raster **and still printed a `decorate-order:` line
    // naming the order it had not used** — a digest that reads as proof the
    // knob turned, emitted by the path where it did not. Two of this project's
    // orders differ by one character (`zx_rev`, `zx_zrev`) and the charge for
    // getting the order wrong is 117,628 blocks on an innocent vanilla run
    // (ORACLE rule 29), so this is loud rather than tolerant.
    if unrecognised {
        eprintln!(
            "decorate-order: UNRECOGNISED '{requested}' — refusing to run the \
             default raster under another order's name"
        );
        std::process::exit(2);
    }
    if !requested.is_empty() {
        // FNV-1a over the whole sequence: cheap, order-sensitive, and it
        // cannot collide with a permutation of itself by accident.
        let mut h: u64 = 0xcbf2_9ce4_8422_2325;
        for &(x, z) in &v {
            for b in x.to_le_bytes().iter().chain(z.to_le_bytes().iter()) {
                h ^= u64::from(*b);
                h = h.wrapping_mul(0x0000_0100_0000_01b3);
            }
        }
        eprintln!(
            "decorate-order: {requested} chunks={} first={:?} last={:?} digest={h:016x}",
            v.len(),
            v.first(),
            v.last(),
        );
    }
    v
}

pub fn generate_end(seed: i64, area: Area, through: Through) -> Result<Generated, String> {
    let router = rustmc_worldgen::density::router::OverworldRouter::end(seed);
    let seeding = NoiseSeeding::new(seed);
    let settings = FillSettings::end();

    let mut pipeline = Pipeline::new(area, END_MIN_Y, END_STORAGE_HEIGHT, "minecraft:air");
    let mut times = StageTimes::new();
    let generated_chunks = pipeline.generated().chunk_count();
    times.mark("setup");

    // ---- noise ----
    //
    // Sequential, for the same reason the nether's is: the overworld's pool
    // is proved byte-identical against `RUSTMC_WORKERS=1` and this path has
    // no such proof, and a first measurement is not the place to take one on
    // trust.
    {
        let mut writers = pipeline.canvas_mut().chunk_writers();
        for writer in &mut writers {
            let _kept = stage::noise::fill_chunk_into(
                writer,
                &router,
                &seeding,
                settings,
                END_DEFAULT_BLOCK,
                // No beard in the End, and this is a fact about the data
                // rather than a gap in the port: `end_city` is the only
                // structure the dimension places and its
                // `terrain_adaptation` is absent, which the codec reads as
                // `NONE`. `forStructuresInChunk` filters `NONE` out at
                // offset 2, so vanilla builds `Beardifier.EMPTY` here too.
                None,
            );
        }
    }
    times.mark("noise");
    if through == Through::Noise {
        times.report(generated_chunks);
        return Ok(Generated {
            canvas: pipeline.into_canvas(),
            area,
            through,
            dimension: Dim::End,
            refused: BTreeMap::new(),
        });
    }

    // ---- biomes ----
    //
    // No `ParameterList`, no `ClimateSampler`, no six-axis search: the End's
    // biome source is a four-branch classifier over the router's erosion
    // slot. See `biome::end`.
    {
        for (chunk_x, chunk_z) in pipeline.generated().chunks().collect::<Vec<_>>() {
            let mut at = |qx: i32, qy: i32, qz: i32| {
                rustmc_worldgen::biome::end::biome_at_quart(&router.erosion, qx, qy, qz).to_string()
            };
            stage::biome::fill_chunk(pipeline.canvas_mut(), &mut at, chunk_x, chunk_z);
        }
    }
    times.mark("biomes");
    if through == Through::Biomes {
        times.report(generated_chunks);
        return Ok(Generated {
            canvas: pipeline.into_canvas(),
            area,
            through,
            dimension: Dim::End,
            refused: BTreeMap::new(),
        });
    }

    // The two `_WG` heightmaps go live here, as in the other two dimensions.
    {
        let props = crate::block_props()?;
        pipeline
            .canvas_mut()
            .set_wg_live(rustmc_worldgen::canvas::WgPredicates::new(
                move |state: &str| {
                    props.get(state).map_or(
                        rustmc_worldgen::canvas::WgFacts {
                            air: true,
                            blocks_motion: false,
                        },
                        |p| rustmc_worldgen::canvas::WgFacts {
                            air: p.air,
                            blocks_motion: p.blocks_motion,
                        },
                    )
                },
            ));
    }

    // ---- surface ----
    //
    // `end.json`'s whole surface rule is one unconditional
    // `block(end_stone)`. It is run rather than skipped because *whether* an
    // unconditional state rule is a no-op over terrain that is already
    // end_stone is a question about `SurfaceSystem.buildSurface`, and this
    // port answers questions like that by measuring, not by reasoning: the
    // `RUSTMC_THROUGH=biomes` and `RUSTMC_THROUGH=surface` diffs of the same
    // window say what it is worth.
    let rule = crate::end_surface_rule()?;
    let biome_data = crate::biome_data();
    let temperature_noises = rustmc_worldgen::biome::temperature::TemperatureNoises::new();
    let params = noise_parameters();
    // **`legacy_random_source: true`**, as in the nether.
    let surface_noises = std::sync::Arc::new(
        rustmc_worldgen::surface::world::SurfaceNoises::for_dimension(seed, &params, true),
    );
    let zoom = rustmc_worldgen::biome::manager::obfuscate_seed(seed);
    let canvas_min_y = pipeline.canvas().min_y();
    let (biome_snapshot, heights_by_chunk) = {
        let canvas = pipeline.canvas();
        let mut biomes_out: BTreeMap<(i32, i32), BiomeContainer> = BTreeMap::new();
        let mut heights_out: BTreeMap<(i32, i32), [i32; 256]> = BTreeMap::new();
        for (cx, cz) in pipeline.generated().chunks() {
            if let Some((palette, ids)) = canvas.chunk_biomes(cx, cz) {
                biomes_out.insert((cx, cz), (palette.to_vec(), ids.to_vec()));
            }
            heights_out.insert(
                (cx, cz),
                canvas
                    .world_surface_wg_chunk(cx, cz)
                    .ok_or("a generated chunk has no heightmap")?,
            );
        }
        (biomes_out, heights_out)
    };
    let surface_biomes = SurfaceBiomes::new(&biome_data, &biome_snapshot, canvas_min_y, zoom);
    let rule = surface_biomes.intern_rule(rule);
    let shared = SurfaceShared {
        rule: &rule,
        noises: &surface_noises,
        temperature_noises: &temperature_noises,
        preliminary: &router.preliminary_surface_level,
        biomes: &surface_biomes,
        sea_level: END_SEA_LEVEL,
        default_block: END_DEFAULT_BLOCK,
        generator: stage::surface::GenExtent {
            min_y: END_MIN_Y,
            height: END_NOISE_HEIGHT,
        },
    };
    {
        let levels = RefCell::new(SurfaceLevels::new(router.preliminary_surface_level.clone()));
        let flat = FlatCaches::none();
        for (chunk_x, chunk_z) in pipeline.generated().chunks().collect::<Vec<_>>() {
            let heights = heights_by_chunk[&(chunk_x, chunk_z)];
            let near = shared.biomes.neighbourhood(chunk_x, chunk_z);
            let biome_at = |x: i32, y: i32, z: i32| {
                near.id_at(x, y, z).unwrap_or_else(|| {
                    let (qx, qy, qz) =
                        rustmc_worldgen::biome::manager::quart_for_block(zoom, x, y, z);
                    shared
                        .biomes
                        .id_of_name(rustmc_worldgen::biome::end::biome_at_quart(
                            &router.erosion,
                            qx,
                            qy,
                            qz,
                        ))
                })
            };
            surface_one_chunk(
                pipeline.canvas_mut(),
                chunk_x,
                chunk_z,
                &heights,
                &shared,
                &levels,
                &flat,
                &biome_at,
            );
        }
    }
    times.mark("surface");
    if through == Through::Surface {
        times.report(generated_chunks);
        return Ok(Generated {
            canvas: pipeline.into_canvas(),
            area,
            through,
            dimension: Dim::End,
            refused: BTreeMap::new(),
        });
    }

    // ---- carvers: THERE ARE NONE ----
    //
    // Not skipped, absent. `end.json` names no carvers and every one of the
    // five End biomes has `"carvers": []`, so there is no stage here to be
    // wrong about — which is also why `cave_air` never appears in an End
    // region and a `Through::Carvers` request lands on this comment.

    // ---- decoration ----
    //
    // Five placed features across the five biomes, and that is the whole
    // dimension: `end_island_decorated` (step 0, small_end_islands),
    // `end_spike` and `end_gateway_return` (step 4, the_end and end_highlands
    // respectively), `chorus_plant` (step 9, end_highlands) and `end_platform`
    // (step 10, the_end).
    //
    // The one structure set — end cities — is built, at `surface_structures`
    // like the overworld's villages. It is not a jigsaw: see
    // `structure::end_city`.
    let tags = crate::block_tags()?;
    let props = crate::block_props()?;
    let facts = crate::facts::TableFacts(props);
    let survival = crate::facts::Survival {
        tags: crate::block_tags()?,
    };
    let per_step = crate::features_per_step_end()?;
    let features = crate::biome_features()?;
    let placed = crate::placed_features()?;
    let configured = crate::configured_features()?;
    let info_noise = rustmc_worldgen::biome::temperature::TemperatureNoises::new();

    pipeline.prime_heightmaps(&HeightmapsFrom(&facts));

    // End cities. Laid out for the whole area before decoration, like the
    // overworld's villages and for the same reason — a city spans chunks and
    // every one of them must write the same 70 pieces.
    //
    // `getCornerHeights` reads `getFirstOccupiedHeight(WORLD_SURFACE_WG)`,
    // which is `getBaseHeight - 1`. `base_height` returns the base height, so
    // the `-1` is here and not in the port: putting it inside `generation_point`
    // would make the gate a block generous and let a city stand on a column
    // vanilla rejects.
    let end_cities = if through >= Through::Decoration {
        // `EndCityStructure.getCornerHeights` asks the GENERATOR
        // (`ChunkGenerator.getFirstOccupiedHeight`, a noise column), never a
        // chunk. Reading the canvas instead made every start whose corner
        // columns fall outside the generated margin undecidable, and it was
        // skipped: at seed 12345 the ship of the city started at chunk
        // (-3136, 6243) went missing from the r=7 window at (-3125, 6250),
        // 950 blocks against a vanilla floor of 0.
        end_city_starts(
            seed,
            area,
            &mut |qx, qy, qz| {
                rustmc_worldgen::biome::end::biome_at_quart(&router.erosion, qx, qy, qz).to_string()
            },
            |x, z| {
                Some(
                    rustmc_worldgen::stage::noise::base_height(
                        &router,
                        &seeding,
                        settings,
                        x,
                        z,
                        rustmc_worldgen::chunk_gen::Wg::WorldSurface,
                    ) - 1,
                )
            },
        )?
    } else {
        Vec::new()
    };
    let end_city_templates: std::sync::Mutex<
        BTreeMap<String, Option<std::sync::Arc<rustmc_worldgen::structure::template::Template>>>,
    > = std::sync::Mutex::new(BTreeMap::new());
    let end_city_dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../data/vanilla/structure/end_city");

    let unplaceable: RefCell<Vec<String>> = RefCell::new(Vec::new());
    let mut refused: BTreeMap<String, usize> = BTreeMap::new();

    let biome_cells: BiomeCells = {
        let canvas = pipeline.canvas();
        pipeline
            .generated()
            .chunks()
            .filter_map(|(x, z)| {
                canvas
                    .chunk_biomes(x, z)
                    .map(|(palette, ids)| ((x, z), (palette.to_vec(), ids.to_vec())))
            })
            .collect()
    };
    let canvas_height = pipeline.canvas().height();
    // The End's `getUncachedNoiseBiome`: the same classifier the biome stage
    // ran, with no state to be scheduling-dependent about. Nothing to say
    // about tie-breaks here — there are no ties, because there is no search.
    let resample = |qx: i32, qy: i32, qz: i32| {
        rustmc_worldgen::biome::end::biome_at_quart(&router.erosion, qx, qy, qz).to_string()
    };

    // The same knob the overworld's decoration stage takes its traversal from
    // — see `decorate_order_for`. Until this call existed the End's stage was
    // a plain raster `for` and the nine-order sweep could not reach it, so the
    // dimension's 100% was proved for exactly one traversal. `chorus_plant` is
    // why that mattered: it reads the world back on every block it writes and
    // spreads up to 8 blocks horizontally, so a plant whose neighbour chunk
    // decorated first could in principle see a different world from one whose
    // neighbour came later.
    let end_city_index = i32::try_from(
        crate::structure_step_indices()
            .0
            .get("minecraft:end_city")
            .map_or(0, |s| s.index),
    )
    .unwrap_or(0);
    let mut isolation = IsolatedDecoration::new();
    for (rank, (chunk_x, chunk_z)) in decorate_order_for(pipeline.decorated())
        .into_iter()
        .enumerate()
    {
        let outcome = isolation.run(&mut pipeline, rank, chunk_x, chunk_z, |canvas| {
            let biomes_present = canvas.biomes_in(chunk_x, chunk_z, 1);
            let mut biome_facts = Biomes {
                zoom,
                resample: &resample,
                data: &biome_data,
                features: &features,
                noises: &info_noise,
                stored: &biome_cells,
                min_y: canvas_min_y,
                height: canvas_height,
                resampled: 0,
            };
            let mut world = rustmc_worldgen::stage::decorate::Decoration::new(
                canvas,
                &facts,
                &survival,
                &mut biome_facts,
                &tags,
                END_SEA_LEVEL,
                // The generator's genDepth, 128 — NOT the canvas's 256.
                END_NOISE_HEIGHT,
                seed,
            )
            // `WorldGenRegion.getRandom()`. The End's noise settings set
            // `legacy_random_source`, so its factory is the legacy one.
            .with_level_random(seed, true);
            world.begin_chunk(chunk_x, chunk_z);
            let outcome = rustmc_worldgen::feature::decorate::run_chunk(
                &mut world,
                &per_step,
                &features,
                &biomes_present,
                &|name| placed.get(name).cloned(),
                seed,
                rustmc_worldgen::feature::decorate::ChunkOrigin {
                    chunk_x,
                    chunk_z,
                    min_section_y: END_MIN_Y >> 4,
                },
                // End cities are `surface_structures`, step 4 of the eleven —
                // the same step the overworld writes a village at, and the End's
                // only structure set.
                |world: &mut rustmc_worldgen::stage::decorate::Decoration<'_>,
                 step: usize,
                 population: i64| {
                    if step != 4 {
                        return;
                    }
                    // `applyBiomeDecoration`'s one stream for every start of
                    // this structure in this chunk, seeded with the
                    // structure's index in step 4 — the same derivation the
                    // overworld's mansion uses. It is what every chest's
                    // `LootTableSeed` is drawn from.
                    let mut random = rustmc_worldgen::rng::worldgen_random::WorldgenRandom::new(
                        rustmc_worldgen::rng::xoroshiro::XoroshiroRandomSource::from_seed(0),
                    );
                    random.set_feature_seed(population, end_city_index, 4);
                    // `ChunkGenerator.getWritableArea`, whose low corner is
                    // `getMinY() + 1`. Everything a piece asks the world goes
                    // through this box.
                    let clip = rustmc_worldgen::structure::pieces::BoundingBox::new(
                        chunk_x * 16,
                        END_MIN_Y + 1,
                        chunk_z * 16,
                        chunk_x * 16 + 15,
                        END_MIN_Y + END_STORAGE_HEIGHT - 1,
                        chunk_z * 16 + 15,
                    );
                    for city in &end_cities {
                        if !city.union_box.intersects(clip) {
                            continue;
                        }
                        place_end_city_in_chunk(
                            world,
                            city,
                            &end_city_templates,
                            &end_city_dir,
                            clip,
                            &mut random,
                        );
                    }
                },
                |world, feature, _name, pos, random| {
                    let Some(config) = configured.get(&feature.feature) else {
                        return;
                    };
                    if let Err(e) = config.place(world, &tags, random, (pos.x, pos.y, pos.z)) {
                        unplaceable.borrow_mut().push(e.0);
                    }
                },
            );
            outcome
        });
        match outcome {
            Ok(o) => {
                for e in o.refusals {
                    *refused.entry(e.0).or_insert(0) += 1;
                }
            }
            Err(e) => *refused.entry(e.0).or_insert(0) += 1,
        }
    }
    isolation.compose(&mut pipeline);
    // `LevelChunk#postProcessGeneration` over the marked positions — the
    // pass the End never ran, as the nether never did before nether-parity.
    // An end city marks its stairs and pillars; without the pass each keeps
    // the shape its template stored. Measured: seed 20260722 c(107,-37) r=7,
    // one `purpur_stairs` at (1713,72,-581) saved `outer_right` from the
    // template where all three vanilla worlds hold `straight`.
    let post = run_post_process(pipeline.canvas_mut(), &tags, &facts.0);
    if std::env::var_os("RUSTMC_POST_PROCESS_STATS").is_some() {
        eprintln!(
            "POST-PROCESS  shapes={} fluid_ticked={}",
            post.shapes, post.fluid.ticked
        );
    }
    for reason in unplaceable.into_inner() {
        *refused.entry(reason).or_insert(0) += 1;
    }

    times.mark("decoration");
    times.report(generated_chunks);
    Ok(Generated {
        canvas: pipeline.into_canvas(),
        area,
        through: Through::Decoration,
        dimension: Dim::End,
        refused,
    })
}

/// Generate the **nether** for `seed`, through the named stage.
///
/// # What this does and does not run
///
/// Noise, biomes and the surface rules. Carvers and decoration do not run
/// yet, and the caveats say so. Measured on the reference (WORKLIST), the
/// nether's block budget is ~99.2% terrain and surface material and under 1%
/// decoration, so the stages that are here are the ones worth being exact
/// first.
///
/// # Errors
/// If the extract is missing, a stage's inputs cannot be built, or `through`
/// names a stage the nether path does not run yet.
pub fn generate_nether(seed: i64, area: Area, through: Through) -> Result<Generated, String> {
    let noises = crate::nether_noises()?;
    let router = rustmc_worldgen::density::router::OverworldRouter::nether(seed, &noises);
    let seeding = NoiseSeeding::new(seed);
    let settings = FillSettings::nether();

    let mut pipeline = Pipeline::new(area, NETHER_MIN_Y, NETHER_STORAGE_HEIGHT, "minecraft:air");
    let mut times = StageTimes::new();
    let generated_chunks = pipeline.generated().chunk_count();
    times.mark("setup");

    // ---- structures ----
    //
    // Above the noise stage, where `ChunkPyramid` puts `STRUCTURE_STARTS`,
    // and for the reason that ordering exists: a structure raises the terrain
    // around itself through `Beardifier`, so its pieces must exist before the
    // fill reads the density.
    //
    // The climate sampler and the biome list are hoisted with it. Both are
    // pure constructions from the router and registry data — neither touches
    // the canvas or the pipeline — which is what makes the hoist safe; the
    // overworld's equivalent move was proved byte-identical the same way.
    //
    // **Not gated on `through`.** Every other structure in this port sits
    // behind `Through::Decoration` because it only writes blocks during
    // decoration. This one changes the *noise stage's own output*, so a run
    // stopped at `RUSTMC_THROUGH=noise` must still see it or it is not
    // measuring the terrain this generator makes.
    let sampler = ClimateSampler::from_router(&router);
    let biomes = std::sync::Mutex::new(ParameterList::new(crate::nether_biome_table()?));
    let fossils = {
        let mut biome_at = |qx: i32, qy: i32, qz: i32| {
            biomes
                .lock()
                .expect("the climate list lock")
                .find_value(sampler.sample(qx, qy, qz))
                .clone()
        };
        let column_at = |x: i32, z: i32| {
            rustmc_worldgen::stage::noise::base_column(&router, &seeding, settings, x, z)
        };
        nether_fossil_starts(
            seed,
            area,
            &mut biome_at,
            column_at,
            settings.min_y,
            settings.height,
            settings.sea_level,
        )?
    };

    // Bastions, laid out here for the same reason the fossils are: vanilla
    // runs `STRUCTURE_STARTS` above `NOISE` and a start that is a function of
    // the terrain it will later stand on is not the same start.
    //
    // **They add nothing to `beard_starts`, and that is a property of the
    // data rather than an omission.** `bastion_remnant.json` declares no
    // `terrain_adaptation`, so it is `TerrainAdjustment.NONE`,
    // `Structure.adjustBoundingBox` returns the box uninflated and
    // `Beardifier` never sees it. The noise stage below is therefore
    // byte-identical with and without this call, which is what makes it safe
    // to say the bastion port cannot have moved a block of terrain.
    //
    // Gated on `through` where the fossils are not, for exactly that reason:
    // a fossil changes the noise stage's own output and a bastion does not.
    //
    // The same attempt reports the chunks the fortress wins. A fortress is
    // `terrain_adaptation` NONE as well, so it too leaves the noise stage
    // alone. Its walk reaches 112 blocks from the start's corner plus a
    // nineteen-block piece, so the attempt is searched nine chunks out
    // rather than the bastion's six; a bastion found in the wider ring
    // reaches nothing and costs only its layout.
    let mut fortress_chunks: Vec<(i32, i32)> = Vec::new();
    let bastions = if through >= Through::Decoration {
        let mut biome_at = |qx: i32, qy: i32, qz: i32| {
            biomes
                .lock()
                .expect("the climate list lock")
                .find_value(sampler.sample(qx, qy, qz))
                .clone()
        };
        nether_complex_starts(
            seed,
            area,
            &mut biome_at,
            |x, z| {
                // Every bastion element is `rigid` — all 176 of them, across all
                // 60 pools — so no element in the tree ever asks the library for
                // a height. A total function is still passed rather than a
                // panicking stub, because "nothing reads it" is a fact about
                // today's datapack and a stub would turn a data change into a
                // crash instead of a measurement.
                rustmc_worldgen::stage::noise::base_height(
                    &router,
                    &seeding,
                    settings,
                    x,
                    z,
                    rustmc_worldgen::chunk_gen::Wg::WorldSurface,
                )
            },
            9,
            &mut fortress_chunks,
        )?
    } else {
        Vec::new()
    };
    // `ruined_portal_nether`, the seventh member of `ruined_portals`. The same
    // attempt the overworld makes: every variant in the set's shuffled order,
    // each filtered on its own biome tag, so in this dimension only the
    // nether variant can win. Its placement is `in_nether` — a random height
    // and the base column's corners, no heightmap — and its setup can never
    // be cold, so `cold_at` is never asked.
    let ruined_portals = if through >= Through::Decoration {
        ruined_portal_starts(
            seed,
            area,
            &mut |qx, qy, qz| {
                biomes
                    .lock()
                    .expect("the climate list lock")
                    .find_value(sampler.sample(qx, qy, qz))
                    .clone()
            },
            |x, z, ocean_floor| {
                rustmc_worldgen::stage::noise::base_height(
                    &router,
                    &seeding,
                    settings,
                    x,
                    z,
                    if ocean_floor {
                        rustmc_worldgen::chunk_gen::Wg::OceanFloor
                    } else {
                        rustmc_worldgen::chunk_gen::Wg::WorldSurface
                    },
                )
            },
            |x, z| rustmc_worldgen::stage::noise::base_column(&router, &seeding, settings, x, z),
            &mut |_: &str, _: i32, _: i32, _: i32| false,
            NETHER_MIN_Y,
        )?
    } else {
        Vec::new()
    };
    // Each fortress laid out once for the whole area, behind a lock because
    // `postProcess` flips two of its pieces' fields (`isNeedingChest`,
    // `hasPlacedSpawner`) and decoration runs chunks on a pool.
    let fortresses: Vec<
        std::sync::Mutex<Vec<rustmc_worldgen::structure::fortress::FortressPiece>>,
    > = fortress_chunks
        .iter()
        .map(|&chunk| {
            std::sync::Mutex::new(rustmc_worldgen::structure::fortress::generate(seed, chunk))
        })
        .collect();
    if trace_beard() {
        eprintln!(
            "STARTS bastion_remnant={} fortress={} (terrain_adaptation NONE, so 0 beard starts)",
            bastions.len(),
            fortresses.len()
        );
        // The chunk and the union box of each, because the count alone
        // cannot distinguish "one too many" from "one outside the window".
        // `bastion_starts` searches 6 chunks beyond `area` — a 105-piece
        // start spans seven chunks and its own placement chunk is not the
        // one it is widest in — so a start in that border ring is expected
        // and is NOT comparable against vanilla's saved starts, which exist
        // only for chunks vanilla generated.
        for bastion in &bastions {
            let b = bastion.union_box;
            eprintln!(
                "  bastion_remnant chunk ({}, {}) pieces={} BB=[{} {} {} .. {} {} {}]",
                bastion.start_chunk.0,
                bastion.start_chunk.1,
                bastion.pieces.len(),
                b.min_x,
                b.min_y,
                b.min_z,
                b.max_x,
                b.max_y,
                b.max_z
            );
        }
    }

    // The bearding starts. A fossil is a plain `TemplateStructurePiece`, not
    // a pool piece, so it takes `PieceShape::Plain`: a `Rigid` with a
    // `groundLevelDelta` of **0** and no junctions. `GD=0` is asserted
    // against all thirty of vanilla's own saved starts in
    // `tests/golden_nether_fossil.rs`, so this is measured rather than
    // assumed.
    let beard_starts: Vec<rustmc_worldgen::density::beard::Start> = fossils
        .iter()
        .map(|fossil| rustmc_worldgen::density::beard::Start {
            adjustment: fossil.terrain_adaptation,
            union_box: fossil.bbox,
            pieces: vec![rustmc_worldgen::density::beard::StartPiece {
                bounds: fossil.bbox,
                shape: rustmc_worldgen::density::beard::PieceShape::Plain,
            }],
        })
        .collect();
    if trace_beard() {
        eprintln!(
            "BEARD starts={} pieces={} (nether fossils)",
            beard_starts.len(),
            beard_starts.len()
        );
    }
    let beard_chunks = std::sync::atomic::AtomicUsize::new(0);
    times.mark("structures");

    // ---- noise ----
    //
    // Sequential rather than pooled. The overworld's pool is proved
    // byte-identical against `RUSTMC_WORKERS=1`; this path has no such proof
    // yet and a first measurement is not the place to take a new one on
    // trust. The nether is cheap — no aquifer, no ore veins, a third of the
    // column — so the cost is small and the claim is simple.
    {
        let mut writers = pipeline.canvas_mut().chunk_writers();
        for writer in &mut writers {
            let _kept = stage::noise::fill_chunk_into(
                writer,
                &router,
                &seeding,
                settings,
                NETHER_DEFAULT_BLOCK,
                // The beard. `nether_fossil` is `beard_thin` and is the one
                // bearding structure with starts in the measured window;
                // measured on chunk (58,67) against a real `Beardifier` built
                // from the reference's own piece box, it is worth 624 blocks
                // in that chunk alone.
                {
                    let position = writer.position();
                    let beardifier =
                        rustmc_worldgen::density::beard::Beardifier::for_structures_in_chunk(
                            &beard_starts,
                            position.0,
                            position.1,
                        );
                    if !beardifier.is_empty() {
                        beard_chunks.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                    }
                    (!beardifier.is_empty()).then(|| std::sync::Arc::new(beardifier))
                },
            );
        }
    }
    if trace_beard() {
        eprintln!(
            "BEARD chunks_with_a_beard={}",
            beard_chunks.load(std::sync::atomic::Ordering::Relaxed)
        );
    }
    times.mark("noise");
    if through == Through::Noise {
        times.report(generated_chunks);
        return Ok(Generated {
            canvas: pipeline.into_canvas(),
            area,
            through,
            dimension: Dim::Nether,
            refused: BTreeMap::new(),
        });
    }

    // ---- biomes ----
    //
    // The same two-pass shape as the overworld would be pointless here: the
    // nether's climate is two noises and its parameter list is five single
    // points, so the search is trivial and the sampling is not the cost.
    // One pass, in `stage::biome::cells` order, which is the order the
    // shared list must see.
    {
        let min_y = pipeline.canvas().min_y();
        let height = pipeline.canvas().height();
        for (chunk_x, chunk_z) in pipeline.generated().chunks().collect::<Vec<_>>() {
            let mut at = |qx: i32, qy: i32, qz: i32| {
                let point = sampler.sample(qx, qy, qz);
                biomes
                    .lock()
                    .expect("the climate list lock")
                    .find_value(point)
                    .clone()
            };
            let _ = (min_y, height);
            stage::biome::fill_chunk(pipeline.canvas_mut(), &mut at, chunk_x, chunk_z);
        }
    }
    times.mark("biomes");
    if through == Through::Biomes {
        times.report(generated_chunks);
        return Ok(Generated {
            canvas: pipeline.into_canvas(),
            area,
            through,
            dimension: Dim::Nether,
            refused: BTreeMap::new(),
        });
    }

    // The two `_WG` heightmaps stay live from here, exactly as the overworld
    // does — the nether surface rule's `stone_depth` conditions read
    // `WORLD_SURFACE_WG`.
    {
        let props = crate::block_props()?;
        pipeline
            .canvas_mut()
            .set_wg_live(rustmc_worldgen::canvas::WgPredicates::new(
                move |state: &str| {
                    props.get(state).map_or(
                        rustmc_worldgen::canvas::WgFacts {
                            air: true,
                            blocks_motion: false,
                        },
                        |p| rustmc_worldgen::canvas::WgFacts {
                            air: p.air,
                            blocks_motion: p.blocks_motion,
                        },
                    )
                },
            ));
    }

    // ---- surface ----
    //
    // Sequential over every generated chunk, in `generated().chunks()` order.
    // The overworld splits an interior off onto a worker pool; that split
    // rests on a measured guard (`RUSTMC_SURFACE_TIES`, "interior must stay
    // zero") which has never been run for the nether, so it is not taken here.
    let rule = crate::nether_surface_rule()?;
    let biome_data = crate::biome_data();
    let temperature_noises = rustmc_worldgen::biome::temperature::TemperatureNoises::new();
    let params = noise_parameters();
    // **`legacy_random_source: true`.** Every named surface noise, the clay
    // bands, the `vertical_gradient` streams and `getSurfaceDepth`'s jitter
    // come off `new LegacyRandomSource(seed).forkPositional()` here, not off
    // Xoroshiro. One boolean, and it moves every surface block in the
    // dimension.
    let surface_noises = std::sync::Arc::new(
        rustmc_worldgen::surface::world::SurfaceNoises::for_dimension(seed, &params, true),
    );
    let zoom = rustmc_worldgen::biome::manager::obfuscate_seed(seed);
    let canvas_min_y = pipeline.canvas().min_y();
    let (biome_snapshot, heights_by_chunk) = {
        let canvas = pipeline.canvas();
        let mut biomes_out: BTreeMap<(i32, i32), BiomeContainer> = BTreeMap::new();
        let mut heights_out: BTreeMap<(i32, i32), [i32; 256]> = BTreeMap::new();
        for (cx, cz) in pipeline.generated().chunks() {
            if let Some((palette, ids)) = canvas.chunk_biomes(cx, cz) {
                biomes_out.insert((cx, cz), (palette.to_vec(), ids.to_vec()));
            }
            heights_out.insert(
                (cx, cz),
                canvas
                    .world_surface_wg_chunk(cx, cz)
                    .ok_or("a generated chunk has no heightmap")?,
            );
        }
        (biomes_out, heights_out)
    };
    let surface_biomes = SurfaceBiomes::new(&biome_data, &biome_snapshot, canvas_min_y, zoom);
    let rule = surface_biomes.intern_rule(rule);
    let shared = SurfaceShared {
        rule: &rule,
        noises: &surface_noises,
        temperature_noises: &temperature_noises,
        preliminary: &router.preliminary_surface_level,
        biomes: &surface_biomes,
        sea_level: NETHER_SEA_LEVEL,
        default_block: NETHER_DEFAULT_BLOCK,
        generator: stage::surface::GenExtent {
            min_y: NETHER_MIN_Y,
            height: NETHER_NOISE_HEIGHT,
        },
    };
    {
        let levels = RefCell::new(SurfaceLevels::new(router.preliminary_surface_level.clone()));
        let flat = FlatCaches::none();
        for (chunk_x, chunk_z) in pipeline.generated().chunks().collect::<Vec<_>>() {
            let heights = heights_by_chunk[&(chunk_x, chunk_z)];
            let near = shared.biomes.neighbourhood(chunk_x, chunk_z);
            let biome_at = |x: i32, y: i32, z: i32| {
                near.id_at(x, y, z).unwrap_or_else(|| {
                    let (qx, qy, qz) =
                        rustmc_worldgen::biome::manager::quart_for_block(zoom, x, y, z);
                    let name = biomes
                        .lock()
                        .expect("the climate list lock")
                        .find_value(sampler.sample(qx, qy, qz))
                        .clone();
                    shared.biomes.id_of_name(&name)
                })
            };
            surface_one_chunk(
                pipeline.canvas_mut(),
                chunk_x,
                chunk_z,
                &heights,
                &shared,
                &levels,
                &flat,
                &biome_at,
            );
        }
    }
    times.mark("surface");
    if through == Through::Surface {
        times.report(generated_chunks);
        return Ok(Generated {
            canvas: pipeline.into_canvas(),
            area,
            through,
            dimension: Dim::Nether,
            refused: BTreeMap::new(),
        });
    }

    // ---- carvers ----
    //
    // `NetherWorldCarver.carveBlock` never consults the aquifer and never
    // asks for a top material, so both closures below are unreachable rather
    // than stubbed — the overworld's two named parity gaps do not exist here.
    // `CarveBounds` carries the **generator's** extent, which is where the
    // override's `getMinGenY() + 31` lava line comes from.
    let tags = crate::block_tags()?;
    let configured = crate::configured_carvers();
    for (chunk_x, chunk_z) in pipeline.generated().chunks().collect::<Vec<_>>() {
        let mut mask =
            rustmc_worldgen::carver::mask::CarvingMask::new(NETHER_NOISE_HEIGHT, NETHER_MIN_Y);
        let mut aquifer = |_: i32, _: i32, _: i32| (None, false);
        let mut top = |_: i32, _: i32, _: i32, _: bool| None;
        let mut target =
            stage::carver::CanvasTarget::new(pipeline.canvas_mut(), &mut aquifer, false, &mut top);
        rustmc_worldgen::carver::driver::apply_carvers(
            &mut target,
            &tags,
            &|source_x, source_z| {
                let id = biomes
                    .lock()
                    .expect("the climate list lock")
                    .find_value(sampler.sample(source_x * 4, 0, source_z * 4))
                    .clone();
                biome_data.get(&id).map_or_else(Vec::new, |entry| {
                    entry
                        .carvers
                        .iter()
                        .filter_map(|name| configured.get(name).cloned())
                        .collect()
                })
            },
            seed,
            rustmc_worldgen::carver::carve::CarveBounds {
                min_gen_y: NETHER_MIN_Y,
                gen_depth: NETHER_NOISE_HEIGHT,
                chunk_x,
                chunk_z,
            },
            &mut mask,
        );
    }
    times.mark("carvers");
    if through == Through::Carvers {
        times.report(generated_chunks);
        return Ok(Generated {
            canvas: pipeline.into_canvas(),
            area,
            through,
            dimension: Dim::Nether,
            refused: BTreeMap::new(),
        });
    }

    // ---- decoration ----
    //
    // The feature loop, plus the `nether_fossil` hook further down. The
    // overworld's block additionally lays out villages, mineshafts and ocean
    // ruins behind the structure hook, and **none of those structure sets
    // exists in the nether**.
    //
    // The nether's own three sets are `nether_complexes` (fortress,
    // bastion_remnant), `nether_fossils` and `ruined_portals`. This comment
    // said "not one is ported" until 2026-08-18; `nether_fossil` has been
    // placed here since 2026-08-02 and is what took the r=7 window from
    // 22,014 mismatches to 8,472 (docs/PARITY.md §5). Still absent:
    // `fortress`, `bastion_remnant`, and `ruined_portal_nether` — the last
    // being a structure this tree can already place, in a dimension where it
    // is never asked to.
    //
    // The ordering comes from `features_per_step_nether()`, which is a
    // *different* ordering over a disjoint biome set: the nether's five
    // biomes are not among the overworld's 55, so numbering a nether feature
    // against `feature_order_vectors.json` would seed it from a list it is
    // not in.
    let props = crate::block_props()?;
    // A second copy for the fossil hook: `TableFacts` takes the table by
    // value and the decoration closure outlives this binding, so the two
    // consumers cannot share one without a lifetime that buys nothing.
    let fossil_props = crate::block_props()?;
    let facts = crate::facts::TableFacts(props);
    let survival = crate::facts::Survival {
        tags: crate::block_tags()?,
    };
    let per_step = crate::features_per_step_nether()?;
    let features = crate::biome_features()?;
    let placed = crate::placed_features()?;
    let configured = crate::configured_features()?;
    let info_noise = rustmc_worldgen::biome::temperature::TemperatureNoises::new();

    // `generateFeatures` primes the four live heightmaps on the line before
    // the first feature, for every chunk, and *then* decorates.
    pipeline.prime_heightmaps(&HeightmapsFrom(&facts));

    let unplaceable: RefCell<Vec<String>> = RefCell::new(Vec::new());
    let mut refused: BTreeMap<String, usize> = BTreeMap::new();
    // A second refusal sink, and a `Mutex` rather than the `RefCell` above,
    // because `place_jigsaw_starts` is shared with the overworld's pooled
    // decoration and takes one. Drained into `refused` beside the feature refusals at
    // the end of the stage, so a bastion that cannot place a piece is counted
    // in exactly the place a feature that cannot place is.
    let bastion_unplaceable: std::sync::Mutex<Vec<String>> = std::sync::Mutex::new(Vec::new());
    let bastion_lists: std::sync::Mutex<ProcessorLists> =
        std::sync::Mutex::new(ProcessorLists::new());
    // `bastion_remnant` sorts **first** of the 26 `surface_structures` in the
    // registry, so its index is 0 — the earliest stream position any
    // structure in that step is given. Derived rather than written down:
    // `structure_step_indices()` reads the datapack in the order
    // `ResourceManagerRegistryLoadTask` imposes, and the same table already
    // supplies the ruined portals' 10 and 16 and the villages' 21..25.
    let (step_index_table, _) = crate::structure_step_indices();

    let biome_cells: BiomeCells = {
        let canvas = pipeline.canvas();
        pipeline
            .generated()
            .chunks()
            .filter_map(|(x, z)| {
                canvas
                    .chunk_biomes(x, z)
                    .map(|(palette, ids)| ((x, z), (palette.to_vec(), ids.to_vec())))
            })
            .collect()
    };
    let canvas_height = pipeline.canvas().height();

    // `find_value_stateless`, **not** `find_value`, and the difference is
    // determinism rather than speed. The hinted search carries a `lastResult`
    // from call to call and resolves exact ties by the sequence of calls
    // before it; decoration now runs on a pool, so that sequence is a
    // function of thread scheduling. Vanilla has the same property — the hint
    // is a `ThreadLocal` and its worldgen runs on a pool too — but this
    // project's claim is that a seed gives one world, so a
    // scheduling-dependent answer is not acceptable here.
    //
    // It is not a behaviour change on the measured square: this path runs
    // **4,188 times** at r=16 (`RUSTMC_STAGE_TIMES` reports it), and the
    // regions are byte-identical to a sequential control either way, so the
    // hint decided none of them. Should a tie ever ride on it, the stateless
    // answer is the one that is the same every run.
    let resample = |qx: i32, qy: i32, qz: i32| {
        biomes
            .lock()
            .expect("the climate list lock")
            .find_value_stateless(sampler.sample(qx, qy, qz))
            .clone()
    };

    // Same knob, same reason as the End's — see `decorate_order_for`. This
    // stage was also a plain raster `for`, so the nether has never been swept
    // either (`ci/decorate-order-sweep.sh` drives `worldgen-dump full`, which
    // is the overworld). Wiring it changes nothing with the variable unset;
    // measuring the nether's nine orders is a separate item — and it has now
    // been done: the nether's residual is almost entirely order-INVARIANT,
    // 24,220 falling only to 24,207 across the eight distinct orders, which is
    // the mirror of the overworld's 95.5%.
    let mut isolation = IsolatedDecoration::new();
    for (rank, (chunk_x, chunk_z)) in decorate_order_for(pipeline.decorated())
        .into_iter()
        .enumerate()
    {
        let outcome = isolation.run(&mut pipeline, rank, chunk_x, chunk_z, |canvas| {
            let biomes_present = canvas.biomes_in(chunk_x, chunk_z, 1);
            let mut biome_facts = Biomes {
                zoom,
                resample: &resample,
                data: &biome_data,
                features: &features,
                noises: &info_noise,
                stored: &biome_cells,
                min_y: canvas_min_y,
                height: canvas_height,
                resampled: 0,
            };
            let mut world = rustmc_worldgen::stage::decorate::Decoration::new(
                canvas,
                &facts,
                &survival,
                &mut biome_facts,
                &tags,
                NETHER_SEA_LEVEL,
                // The generator's genDepth, 128 — NOT the canvas's 256. Every
                // `below_top` anchor in a nether placement chain resolves against
                // this.
                NETHER_NOISE_HEIGHT,
                seed,
            )
            // `WorldGenRegion.getRandom()`. The nether's noise settings set
            // `legacy_random_source`, the same boolean
            // `SurfaceNoises::for_dimension` is given above.
            .with_level_random(seed, true)
            // `has_skylight: false` in `dimension_type/the_nether.json`.
            .without_sky_light();
            world.begin_chunk(chunk_x, chunk_z);
            let outcome = rustmc_worldgen::feature::decorate::run_chunk(
                &mut world,
                &per_step,
                &features,
                &biomes_present,
                &|name| placed.get(name).cloned(),
                seed,
                rustmc_worldgen::feature::decorate::ChunkOrigin {
                    chunk_x,
                    chunk_z,
                    min_section_y: NETHER_MIN_Y >> 4,
                },
                // `nether_fossil` is `step: underground_decoration`, which is
                // index 7 of `GenerationStep.Decoration` — RAW_GENERATION, LAKES,
                // LOCAL_MODIFICATIONS, UNDERGROUND_STRUCTURES, SURFACE_STRUCTURES,
                // STRONGHOLDS, UNDERGROUND_ORES, UNDERGROUND_DECORATION.
                |world: &mut rustmc_worldgen::stage::decorate::Decoration<'_>,
                 step: usize,
                 population: i64| {
                    // `surface_structures`, step 4 — the bastions, then the
                    // ruined portals.
                    if step == 4 {
                        if bastions.is_empty() && ruined_portals.is_empty() {
                            return;
                        }
                        // `ChunkGenerator.getWritableArea`, whose low corner
                        // is `getMinY() + 1`. The nether's `getMinY()` is 0,
                        // so the bottom writable row is y=1 and y=0 is outside
                        // the box a piece is handed — the same off-by-one the
                        // overworld's villages document at -63, and it matters
                        // for the same reason: `getBlock` answers air outside
                        // this box and `placeBlock` writes nothing outside it.
                        //
                        // The top is the DIMENSION's 255, not the noise
                        // settings' 127. A bastion tops out near y 56 so
                        // neither bound is reached on this seed, but those two
                        // numbers are the pair this file warns is a 50% error
                        // when conflated, and the writable area is the
                        // dimension's.
                        let clip = rustmc_worldgen::structure::pieces::BoundingBox::new(
                            chunk_x * 16,
                            NETHER_MIN_Y + 1,
                            chunk_z * 16,
                            chunk_x * 16 + 15,
                            NETHER_MIN_Y + NETHER_STORAGE_HEIGHT - 1,
                            chunk_z * 16 + 15,
                        );
                        // **One random per STRUCTURE, not per start**, the
                        // same rule the overworld's villages follow:
                        // `applyBiomeDecoration` seeds once for the structure
                        // registered to the step and then runs every start of
                        // it on that one stream, so two bastions reaching one
                        // chunk share a stream and the second begins where the
                        // first left off. `place_jigsaw_starts` is that rule,
                        // and it is the same function the overworld's villages
                        // and the trial chambers go through — so the piece
                        // stream stays opt-in here exactly as it is there
                        // rather than being threaded unconditionally in the
                        // nether and behind a knob everywhere else.
                        place_jigsaw_starts(
                            world,
                            &bastions,
                            &bastion_lists,
                            clip,
                            &bastion_unplaceable,
                            population,
                            &step_index_table,
                            4,
                        );
                        // `ruined_portal_nether` sorts after `bastion_remnant`
                        // in `surface_structures`, on its own index's stream.
                        for portal in &ruined_portals {
                            let index = step_index_table
                                .get(&format!("minecraft:{}", portal.structure))
                                .map_or(0, |s| s.index);
                            let mut random =
                                rustmc_worldgen::rng::worldgen_random::WorldgenRandom::new(
                                    rustmc_worldgen::rng::xoroshiro::XoroshiroRandomSource::from_seed(0),
                                );
                            random.set_feature_seed(population, i32::try_from(index).unwrap_or(0), 4);
                            place_ruined_portal_in_chunk(
                                world,
                                portal,
                                &mut random,
                                chunk_x,
                                chunk_z,
                                &facts.0,
                                NETHER_MIN_Y,
                                NETHER_STORAGE_HEIGHT,
                            );
                        }
                        return;
                    }
                    // `nether_fossil` is `step: underground_decoration`, index
                    // 7 of `GenerationStep.Decoration`.
                    if step != 7 {
                        return;
                    }
                    // `fortress` is the other structure of that step and sorts
                    // before `nether_fossil` in `step_index`. One stream for
                    // the structure, shared by every start that reaches this
                    // chunk, as `applyBiomeDecoration` seeds it.
                    if !fortresses.is_empty() {
                        let index = step_index_table
                            .get("minecraft:fortress")
                            .map_or(0, |s| s.index);
                        let mut random = rustmc_worldgen::rng::worldgen_random::WorldgenRandom::new(
                            rustmc_worldgen::rng::xoroshiro::XoroshiroRandomSource::from_seed(0),
                        );
                        random.set_feature_seed(population, i32::try_from(index).unwrap_or(0), 7);
                        let clip = rustmc_worldgen::structure::pieces::BoundingBox::new(
                            chunk_x * 16,
                            NETHER_MIN_Y + 1,
                            chunk_z * 16,
                            chunk_x * 16 + 15,
                            NETHER_MIN_Y + NETHER_STORAGE_HEIGHT - 1,
                            chunk_z * 16 + 15,
                        );
                        for fortress in &fortresses {
                            let mut pieces = fortress.lock().expect("the fortress lock");
                            for p in pieces.iter_mut() {
                                if p.piece.bounding_box.intersects(clip) {
                                    rustmc_worldgen::structure::fortress::post_process(
                                        world,
                                        p,
                                        clip,
                                        &mut random,
                                    );
                                }
                            }
                        }
                    }
                    for fossil in &fossils {
                        place_nether_fossil_in_chunk(
                            world,
                            fossil,
                            chunk_x,
                            chunk_z,
                            &fossil_props,
                            seed,
                        );
                    }
                },
                |world, feature, _name, pos, random| {
                    let Some(config) = configured.get(&feature.feature) else {
                        return;
                    };
                    // The overworld's label, so `RUSTMC_TRACE_WRITE` names a
                    // nether feature too rather than `? (no feature running)`.
                    if rustmc_worldgen::canvas::tracing_writes() {
                        rustmc_worldgen::canvas::set_writer(&format!(
                            "{} from chunk ({chunk_x}, {chunk_z}) at ({}, {}, {})",
                            feature.feature, pos.x, pos.y, pos.z
                        ));
                    }
                    if let Err(e) = config.place(world, &tags, random, (pos.x, pos.y, pos.z)) {
                        unplaceable.borrow_mut().push(e.0);
                    }
                    if rustmc_worldgen::canvas::tracing_writes() {
                        rustmc_worldgen::canvas::set_writer("");
                    }
                },
            );
            outcome
        });
        match outcome {
            Ok(o) => {
                for e in o.refusals {
                    *refused.entry(e.0).or_insert(0) += 1;
                }
            }
            Err(e) => *refused.entry(e.0).or_insert(0) += 1,
        }
    }
    isolation.compose(&mut pipeline);
    // The marked positions, replayed as `ChunkStatusTasks` does once the
    // structures and features are in. The nether never ran this pass: every
    // fence, wall and chain a bastion or a fortress wrote kept the
    // connections its piece gave it rather than the ones its neighbours
    // decide. There is no aquifer in this dimension and no structure marks a
    // fluid, so the pass's fluid half finds nothing to tick here.
    let post = run_post_process(pipeline.canvas_mut(), &tags, &facts.0);
    if std::env::var_os("RUSTMC_POST_PROCESS_STATS").is_some() {
        eprintln!(
            "POST-PROCESS  shapes={} fluid_ticked={}",
            post.shapes, post.fluid.ticked
        );
    }
    for reason in unplaceable.into_inner() {
        *refused.entry(reason).or_insert(0) += 1;
    }

    for reason in bastion_unplaceable
        .into_inner()
        .expect("the bastion refusal lock")
    {
        *refused.entry(reason).or_insert(0) += 1;
    }
    times.mark("decoration");
    times.report(generated_chunks);
    Ok(Generated {
        canvas: pipeline.into_canvas(),
        area,
        through,
        dimension: Dim::Nether,
        refused,
    })
}

/// `LevelChunk#postProcessGeneration` over every position a stage marked —
/// the shape half (`updateFromNeighbourShapes`) and the fluid half — with the
/// block-property table answering the shape questions. Shared by the
/// overworld and the nether, which both place structures that mark fences.
fn run_post_process(
    canvas: &mut rustmc_worldgen::canvas::Canvas,
    tags: &rustmc_worldgen::tags::BlockTags,
    props: &rustmc_behavior::block_props::BlockPropsTable,
) -> rustmc_worldgen::stage::post_process::Outcome {
    struct Shapes<'a>(&'a rustmc_behavior::block_props::BlockPropsTable);
    impl rustmc_worldgen::stage::post_process::ShapeFacts for Shapes<'_> {
        fn face_is_sturdy(&self, state: &str, direction: usize) -> Option<bool> {
            self.0
                .get(state)
                .and_then(|p| p.sturdy_faces.get(direction).copied())
        }
        fn face_is_collision_full(&self, state: &str, direction: usize) -> Option<bool> {
            self.0
                .get(state)
                .and_then(|p| p.collision_full_faces.get(direction).copied())
        }
        fn is_solid(&self, state: &str) -> Option<bool> {
            self.0.get(state).map(|p| p.solid)
        }
    }
    // The flow rules ask three questions a block name cannot answer. A
    // state the table has never heard of answers as a full cube that
    // blocks motion — the *refusing* answer everywhere it is used, so an
    // unknown block stops a spread rather than silently letting water
    // through it.
    impl rustmc_worldgen::stage::fluid::FluidFacts for Shapes<'_> {
        fn blocks_motion(&self, state: &str) -> bool {
            self.0.get(state).is_none_or(|p| p.blocks_motion)
        }
        fn is_solid(&self, state: &str) -> bool {
            self.0.get(state).is_none_or(|p| p.solid)
        }
        fn collision_full_faces(&self, state: &str) -> [bool; 6] {
            self.0
                .get(state)
                .map_or([true; 6], |p| p.collision_full_faces)
        }
    }
    let shapes = Shapes(props);
    rustmc_worldgen::stage::post_process::run(
        canvas,
        tags,
        &shapes,
        &shapes,
        rustmc_worldgen::stage::fluid::FluidRules::REFERENCE_HARNESS,
    )
}

/// As [`generate`], but decorating only one chunk.
///
/// `decorate_only` restricts the **decoration** stage to a single chunk while
/// every earlier stage still runs over the whole generated area. That is the
/// shape `DecorateGolden` measures: it decorates one chunk against
/// neighbours which are generated but have **not** themselves decorated.
///
/// Without this the two cannot be compared. A full pipeline decorates in
/// x-then-z order, so the west neighbour finishes all eleven of its steps
/// before the chunk under test begins, and a feature that reads a block a
/// later step can write sees a different world than vanilla's isolated run
/// did. Comparing those two and calling the difference a port fault is a
/// mistake this project has made, and this parameter is what makes the
/// question answerable instead.
///
/// # Errors
/// If the extract is missing or a stage's inputs cannot be built.
pub fn generate_decorating(
    seed: i64,
    area: Area,
    through: Through,
    decorate_only: Option<(i32, i32)>,
) -> Result<Generated, String> {
    generate_resuming(seed, area, through, decorate_only, None)
}

/// As [`generate_decorating`], but generating **onto a canvas that already
/// exists**.
///
/// This is the generate-once half of `docs/DETERMINISM.md` §32.6. With
/// `resume` set, the square is generated over the canvas the previous pass
/// handed back: every chunk it already carved keeps its terrain and its
/// features, every chunk it already decorated is skipped by the decoration
/// stage, and the only work done is the chunks this square adds. Passing
/// `None` is the from-scratch pass every other caller wants and is
/// byte-for-byte what it always was — the skips are all of the form "this set
/// is empty".
///
/// # Errors
/// If the extract is missing or a stage's inputs cannot be built.
pub fn generate_resuming(
    seed: i64,
    area: Area,
    through: Through,
    decorate_only: Option<(i32, i32)>,
    resume: Option<rustmc_worldgen::pipeline::Resumed>,
) -> Result<Generated, String> {
    let params = noise_parameters();
    let noises = crate::overworld_noises(&params);
    let router = OverworldRouter::new(seed, &noises, false);
    let seeding = NoiseSeeding::new(seed);
    let settings = FillSettings::overworld();

    let mut pipeline = match resume {
        Some(resume) => Pipeline::resuming(area, MIN_Y, HEIGHT, "minecraft:air", resume),
        None => Pipeline::new(area, MIN_Y, HEIGHT, "minecraft:air"),
    };
    // Taken once, here, because every terrain stage below holds the canvas
    // mutably for the whole of its loop and cannot ask the pipeline anything
    // while it runs. Both sets are empty for a from-scratch pass, so every
    // `fresh`/`undecorated` test below is a constant `true` there.
    let settled_terrain = pipeline.settled_terrain();
    let settled_decoration = pipeline.settled_decoration();
    let fresh = |chunk_x: i32, chunk_z: i32| !settled_terrain.contains(&(chunk_x, chunk_z));
    let generated_chunks = pipeline.generated().chunk_count();
    let mut times = StageTimes::new();
    times.mark("setup");

    let sampler = ClimateSampler::from_router(&router);
    let biomes = std::sync::Mutex::new(ParameterList::new(biome_table()));

    // ---- structures ----
    //
    // **Before the noise stage, which is where vanilla runs it.**
    // `ChunkPyramid` orders `STRUCTURE_STARTS` ahead of `NOISE`, and the
    // reason it matters here is `Beardifier`: a structure raises terrain
    // around itself through a density term, so its pieces have to exist
    // before the fill runs. This stage read `WORLD_SURFACE_WG` and
    // `OCEAN_FLOOR_WG` off the canvas until those five reads were swapped
    // for `stage::noise::base_height`, which walks a noise column against
    // the router and needs no filled chunk — that swap is what unblocked
    // this move, and it landed byte-neutral on its own commit.
    //
    // `pipeline.canvas_mut().freeze_wg()` deliberately did NOT come with it.
    // It is the "the `_WG` maps are frozen after CARVERS" mechanism, and
    // hoisting it here would freeze the maps before anything had written
    // them. It stays where the carvers end.
    //
    // Laid out for the whole generated area before decoration starts,
    // because a mineshaft reaches several chunks and every chunk it touches
    // has to write the same pieces.
    //
    // The index a structure is seeded with is **derived** from the datapack
    // now — see `structure_step_indices` and
    // `rustmc_worldgen::structure::step_index`.
    //
    // This block used to open "cannot be read from
    // `VanillaRegistries.createLookup()` — its iteration order is not stable
    // between JVM runs (ORACLE.md fault 9)". That was wrong, and it was
    // expensive: it is why `shipwreck_beached` and the village hay pile were
    // both parked. A *dump* of that lookup is indeed unordered, but the
    // server never iterates the lookup — `ResourceManagerRegistryLoadTask`
    // sorts by resource identifier before registering anything, so the
    // registry the generator walks is in a total, run-independent order.
    //
    // The measurement below is kept, because it is now the thing that
    // *checks* the derivation rather than the thing that substitutes for it.
    // It was taken by generating under every candidate and diffing against a
    // real vanilla region.
    //
    //     index   exactness
    //     none    99.392587%
    //     0       99.715282%
    //     1       99.758798%   <-- and it is not close
    //     2       99.698102%
    //     3       99.697763%
    //     4       99.720256%
    //
    // Corroborated independently: `mineshaft` was at position 1 in *both*
    // of the unstable registry dumps, differing as they did about
    // everything else. Two lines of evidence, neither derived from the
    // other.
    //
    // And a third, which is the one that settles it, because it does not
    // look at the diff at all. `worldgen-dump mineshaft-ceiling` reads the
    // stream offset each corridor entered on out of vanilla's own blocks;
    // the **first** corridor of a chunk's pass must enter at offset 0,
    // because nothing before it draws. Only one index makes that true:
    //
    //     index   first corridors pinned   at offset 0   unexplainable
    //     0       3                        0             118
    //     1       27                       25            8
    //     2       3                        0             122
    //     3       6                        0             115
    //     4       2                        0             120
    //
    // `RUSTMC_STRUCTURE_INDEX` overrides it, because the experiment has to
    // stay runnable — and that override is how this number was re-checked
    // once the registry order became readable.
    const MEASURED_MINESHAFT_INDEX: i32 = 1;
    let (step_index_table, _step_structure_counts) = crate::structure_step_indices();
    let derived_mineshaft = step_index_table
        .get("minecraft:mineshaft")
        .copied()
        .expect("the extract has no mineshaft structure");
    // The derivation reads a registry and never looks at a block; the
    // measurement read blocks and never looked at a registry. Their agreeing
    // is the evidence, so a disagreement is fatal rather than a warning —
    // whichever is wrong, every mineshaft in the world is on the wrong
    // stream and the diff that follows would be measuring nothing.
    assert_eq!(
        derived_mineshaft.step, 3,
        "mineshaft is underground_structures"
    );
    assert_eq!(
        i32::try_from(derived_mineshaft.index).expect("index fits i32"),
        MEASURED_MINESHAFT_INDEX,
        "the derived mineshaft index and the one measured out of vanilla's \
         corridors have parted company"
    );
    let structure_index: i32 = std::env::var("RUSTMC_STRUCTURE_INDEX")
        .ok()
        .and_then(|v| v.parse().ok())
        .unwrap_or(MEASURED_MINESHAFT_INDEX);
    let mineshafts = if through >= Through::Decoration {
        mineshaft_starts(
            seed,
            area,
            &mut |qx, qy, qz| {
                biomes
                    .lock()
                    .expect("the climate list lock")
                    .find_value(sampler.sample(qx, qy, qz))
                    .clone()
            },
            // `WORLD_SURFACE_WG` off the canvas, but only inside the generated
            // area: outside it the fossil has never been written, and reading
            // it would hand a mesa mine a height from empty terrain rather
            // than refusing.
            |x, z| {
                let (cx, cz) = (x >> 4, z >> 4);
                if cx < area.min_chunk_x
                    || cx > area.max_chunk_x
                    || cz < area.min_chunk_z
                    || cz > area.max_chunk_z
                {
                    None
                } else {
                    Some(rustmc_worldgen::stage::noise::base_height(
                        &router,
                        &seeding,
                        settings,
                        x,
                        z,
                        rustmc_worldgen::chunk_gen::Wg::WorldSurface,
                    ))
                }
            },
        )?
    } else {
        Vec::new()
    };
    times.mark("str:mineshaft");
    // Buried treasure. `underground_structures`, like the mineshaft, and it
    // needs no measured structure index for the same reason the ocean ruin
    // does not: the only `nextLong` in its path is the chest's loot table,
    // inside an `instanceof ChestBlockEntity` guard and on the structure's own
    // random rather than the feature stream. Placing one moves nothing else.
    let buried_treasures = if through >= Through::Decoration {
        buried_treasure_starts(
            seed,
            area,
            &mut |qx, qy, qz| {
                biomes
                    .lock()
                    .expect("the climate list lock")
                    .find_value(sampler.sample(qx, qy, qz))
                    .clone()
            },
            // `ChunkGenerator.getFirstOccupiedHeight` = `getBaseHeight - 1`,
            // beardless and needing no filled chunk, which is what lets this
            // run before the noise stage. Outside the generated area it
            // answers `None` rather than handing back a height from terrain
            // that was never written.
            |x, z| {
                let (cx, cz) = (x >> 4, z >> 4);
                let g = pipeline.generated();
                if cx < g.min_chunk_x
                    || cx > g.max_chunk_x
                    || cz < g.min_chunk_z
                    || cz > g.max_chunk_z
                {
                    None
                } else {
                    Some(
                        rustmc_worldgen::stage::noise::base_height(
                            &router,
                            &seeding,
                            settings,
                            x,
                            z,
                            rustmc_worldgen::chunk_gen::Wg::OceanFloor,
                        ) - 1,
                    )
                }
            },
        )?
    } else {
        Vec::new()
    };
    // Ocean ruins. Unlike the mineshaft this needs no measured structure
    // index, because the ruin spends nothing from the decoration stream: its
    // processors are all positional or world-seed derived, and the one
    // `nextLong` behind the chest's loot table sits inside a
    // `getBlockEntity(pos) instanceof ChestBlockEntity` guard that a worldgen
    // ProtoChunk does not satisfy. So placing it moves no other feature.
    let ocean_ruins = if through >= Through::Decoration {
        ocean_ruin_starts(
            seed,
            area,
            &mut |qx, qy, qz| {
                biomes
                    .lock()
                    .expect("the climate list lock")
                    .find_value(sampler.sample(qx, qy, qz))
                    .clone()
            },
            // `ChunkGenerator.getFirstOccupiedHeight` = `getBaseHeight - 1`,
            // the pure noise column, so it answers everywhere. It used to
            // answer `None` outside the generated area and the ruin then
            // skipped its biome gate; with two temperatures in the set the
            // biome decides *which* ruin as well as whether, so an unchecked
            // start is no longer expressible — and vanilla never skips it.
            |x, z| {
                Some(
                    rustmc_worldgen::stage::noise::base_height(
                        &router,
                        &seeding,
                        settings,
                        x,
                        z,
                        rustmc_worldgen::chunk_gen::Wg::OceanFloor,
                    ) - 1,
                )
            },
        )?
    } else {
        Vec::new()
    };
    times.mark("str:oceanruin");

    // Shipwrecks, both branches. An ocean wreck spends nothing from the
    // decoration stream — its two draws are on its own `setLargeFeatureSeed`
    // random and its palette is a pure function of the final position. A
    // beached one spends one `nextInt(3)` on the `shipwreck_beached` stream,
    // in `place_shipwreck_in_chunk`.
    let shipwrecks = if through >= Through::Decoration {
        shipwreck_starts(
            seed,
            area,
            &mut |qx, qy, qz| {
                biomes
                    .lock()
                    .expect("the climate list lock")
                    .find_value(sampler.sample(qx, qy, qz))
                    .clone()
            },
            |x, z| {
                let (cx, cz) = (x >> 4, z >> 4);
                let g = pipeline.generated();
                if cx < g.min_chunk_x
                    || cx > g.max_chunk_x
                    || cz < g.min_chunk_z
                    || cz > g.max_chunk_z
                {
                    None
                } else {
                    Some(
                        rustmc_worldgen::stage::noise::base_height(
                            &router,
                            &seeding,
                            settings,
                            x,
                            z,
                            rustmc_worldgen::chunk_gen::Wg::OceanFloor,
                        ) - 1,
                    )
                }
            },
            |x, z| {
                let (cx, cz) = (x >> 4, z >> 4);
                let g = pipeline.generated();
                if cx < g.min_chunk_x
                    || cx > g.max_chunk_x
                    || cz < g.min_chunk_z
                    || cz > g.max_chunk_z
                {
                    None
                } else {
                    Some(
                        rustmc_worldgen::stage::noise::base_height(
                            &router,
                            &seeding,
                            settings,
                            x,
                            z,
                            rustmc_worldgen::chunk_gen::Wg::WorldSurface,
                        ) - 1,
                    )
                }
            },
        )?
    } else {
        Vec::new()
    };
    times.mark("str:shipwreck");

    // Villages. Laid out for the whole area before decoration, like the
    // mineshaft and for the same reason: a village reaches 80 blocks and every
    // chunk it touches must write the same pieces.
    //
    // The height it reads is `getFirstFreeHeight` — `getBaseHeight`, a pure
    // beardless noise column — and **not** the canvas's `WORLD_SURFACE_WG`
    // fossil and not anything clamped to this window. Vanilla lays structures
    // out at the STRUCTURE_STARTS step, before any neighbour chunk exists, so
    // its height source cannot be a generated heightmap and neither may ours.
    // Clamping it to `area` used to make the village *set* depend on the size
    // of the square being generated; see [`overworld_first_free_height`].
    let villages = if through >= Through::Decoration {
        village_starts(
            seed,
            area,
            &mut |qx, qy, qz| {
                biomes
                    .lock()
                    .expect("the climate list lock")
                    .find_value(sampler.sample(qx, qy, qz))
                    .clone()
            },
            |x, z| overworld_first_free_height(&router, &seeding, settings, x, z),
        )?
    } else {
        Vec::new()
    };
    times.mark("str:village");
    let ancient_cities = if through >= Through::Decoration {
        ancient_city_starts(
            seed,
            area,
            &mut |qx, qy, qz| {
                biomes
                    .lock()
                    .expect("the climate list lock")
                    .find_value(sampler.sample(qx, qy, qz))
                    .clone()
            },
            |x, z| overworld_first_free_height(&router, &seeding, settings, x, z),
        )?
    } else {
        Vec::new()
    };
    let trail_ruins = if through >= Through::Decoration {
        trail_ruin_starts(
            seed,
            area,
            &mut |qx, qy, qz| {
                biomes
                    .lock()
                    .expect("the climate list lock")
                    .find_value(sampler.sample(qx, qy, qz))
                    .clone()
            },
            |x, z| overworld_first_free_height(&router, &seeding, settings, x, z),
        )?
    } else {
        Vec::new()
    };
    // Pillager outposts: a jigsaw like the villages, and `beard_thin` like them.
    let outposts = if through >= Through::Decoration {
        outpost_starts(
            seed,
            area,
            &mut |qx, qy, qz| {
                biomes
                    .lock()
                    .expect("the climate list lock")
                    .find_value(sampler.sample(qx, qy, qz))
                    .clone()
            },
            |x, z| overworld_first_free_height(&router, &seeding, settings, x, z),
        )?
    } else {
        Vec::new()
    };
    // Strongholds: concentric-ring placement and a `bury` beard.
    let strongholds: Vec<std::sync::Mutex<rustmc_worldgen::structure::stronghold::Stronghold>> =
        if through >= Through::Decoration {
            stronghold_starts(seed, area, &mut |qx, qy, qz| {
                biomes
                    .lock()
                    .expect("the climate list lock")
                    .find_value(sampler.sample(qx, qy, qz))
                    .clone()
            })?
            .into_iter()
            .map(std::sync::Mutex::new)
            .collect()
        } else {
            Vec::new()
        };
    let igloos = if through >= Through::Decoration {
        igloo_starts(
            seed,
            area,
            &mut |qx, qy, qz| {
                biomes
                    .lock()
                    .expect("the climate list lock")
                    .find_value(sampler.sample(qx, qy, qz))
                    .clone()
            },
            |x, z| overworld_first_free_height(&router, &seeding, settings, x, z) - 1,
        )?
    } else {
        Vec::new()
    };
    // Woodland mansions. No terrain adaptation: `afterPlace` lays its own
    // cobblestone foundation instead of a beard.
    let mansions = if through >= Through::Decoration {
        mansion_starts(
            seed,
            area,
            &mut |qx, qy, qz| {
                biomes
                    .lock()
                    .expect("the climate list lock")
                    .find_value(sampler.sample(qx, qy, qz))
                    .clone()
            },
            |x, z| overworld_first_free_height(&router, &seeding, settings, x, z) - 1,
        )?
    } else {
        Vec::new()
    };
    // Ocean monuments. No terrain adaptation; the building writes its own
    // water and its pillars fill down to the floor.
    let monuments = if through >= Through::Decoration {
        monument_starts(
            seed,
            area,
            &mut |qx, qy, qz| {
                biomes
                    .lock()
                    .expect("the climate list lock")
                    .find_value(sampler.sample(qx, qy, qz))
                    .clone()
            },
            |x, z| {
                rustmc_worldgen::stage::noise::base_height(
                    &router,
                    &seeding,
                    settings,
                    x,
                    z,
                    rustmc_worldgen::chunk_gen::Wg::OceanFloor,
                ) - 1
            },
        )?
    } else {
        Vec::new()
    };
    // The three `ScatteredFeaturePiece` sets. No terrain adaptation, so they
    // are not bearding starts; their height is seated at write time.
    let scattered = if through >= Through::Decoration {
        scattered_starts(
            seed,
            area,
            &mut |qx, qy, qz| {
                biomes
                    .lock()
                    .expect("the climate list lock")
                    .find_value(sampler.sample(qx, qy, qz))
                    .clone()
            },
            |x, z| overworld_first_free_height(&router, &seeding, settings, x, z) - 1,
        )?
    } else {
        Vec::new()
    };
    // Trial chambers. `underground_structures`, so they are written at step 3
    // with the mineshaft rather than at step 4 with the villages — but their
    // pieces are assembled here, beside the villages, because the beard needs
    // every bearding start before the noise stage runs.
    //
    // `trial_chambers` is `encapsulate`, which is a different `TerrainAdjustment`
    // from the villages' `beard_thin`; both are gated bit-for-bit against
    // vanilla's own `Beardifier` by `ci/beard-golden.sh`.
    let trial_chambers = if through >= Through::Decoration {
        trial_chamber_starts(
            seed,
            area,
            &mut |qx, qy, qz| {
                biomes
                    .lock()
                    .expect("the climate list lock")
                    .find_value(sampler.sample(qx, qy, qz))
                    .clone()
            },
            |x, z| {
                let (cx, cz) = (x >> 4, z >> 4);
                if cx < area.min_chunk_x
                    || cx > area.max_chunk_x
                    || cz < area.min_chunk_z
                    || cz > area.max_chunk_z
                {
                    None
                } else {
                    Some(rustmc_worldgen::stage::noise::base_height(
                        &router,
                        &seeding,
                        settings,
                        x,
                        z,
                        rustmc_worldgen::chunk_gen::Wg::WorldSurface,
                    ))
                }
            },
        )?
    } else {
        Vec::new()
    };
    times.mark("str:trial");
    // A `Mutex` rather than a `RefCell` because decoration runs on a worker
    // pool. It is a **pure cache** — `resolve` reads a named list off disk and
    // remembers it — so which chunk populates an entry cannot change what any
    // chunk gets back, and sharing one across the pool is order-independent
    // by construction rather than by argument.
    let village_lists: std::sync::Mutex<ProcessorLists> =
        std::sync::Mutex::new(ProcessorLists::new());

    // `MineShaftCorridor.hasPlacedSpider`, one flag per corridor piece,
    // living as long as the piece list does. Which is what it is in vanilla:
    // the start is held by the chunk that owns it and handed to every chunk
    // it reaches, so the field survives across chunk passes.
    //
    // A `Mutex` for the pool. Unlike the processor-list cache this one really
    // is order-dependent — whichever chunk post-processes a spider corridor
    // first spends the spawner's draw — so it is only safe because the two
    // chunks that could race for one entry cannot run at the same time: a
    // corridor piece is at most 19 blocks long, so it spans at most three
    // chunks in an axis, i.e. two apart, and the parallel driver below orders
    // any two chunks within `2 * DECORATE_REACH` (>= 2) of each other.
    //
    // **That argument names the level barriers, and the isolated arm has
    // none.** `docs/DETERMINISM.md` §33: under
    // `RUSTMC_DECORATE_ISOLATED=1` the driver is a flat work queue over every
    // chunk at once, two chunks two apart do run at the same time, and one
    // binary produced three different worlds from one seed and one window.
    // So the memory is chosen by the model rather than assumed — see
    // [`SpiderMemory`].
    let spider_placed: std::sync::Mutex<std::collections::BTreeSet<(i32, i32, usize)>> =
        std::sync::Mutex::new(std::collections::BTreeSet::new());
    let spider_is_chunk_local = rustmc_worldgen::pipeline::isolated_decoration();
    // One block set per variant. A mesa mineshaft is the same layout with
    // different woods, so the set is chosen per start rather than per world.
    let default_states = rustmc_worldgen::feature::state_spec::extract_or_skip()
        .ok_or("no block-props extract, so no scattered-piece block states")?;
    let props = rustmc_worldgen::feature::state_spec::extract_or_skip()
        .ok_or("no block-props extract, so no structure block states")?;
    let mineshaft_blocks = rustmc_worldgen::structure::mineshaft::MineshaftBlocks::vanilla(
        rustmc_worldgen::structure::mineshaft::MineshaftType::Normal,
        &props,
    )
    .ok_or("the extract does not carry the mineshaft's blocks")?;
    let mesa_blocks = rustmc_worldgen::structure::mineshaft::MineshaftBlocks::vanilla(
        rustmc_worldgen::structure::mineshaft::MineshaftType::Mesa,
        &props,
    )
    .ok_or("the extract does not carry the mesa mineshaft's blocks")?;

    // The bearding starts, as `Beardifier.forStructuresInChunk` reads them.
    //
    // Villages and trial chambers, and that is a fact about what is ported
    // rather than a filter: of the eleven structures in 26.2 whose
    // `terrain_adaptation` is not `none` — five villages, `pillager_outpost`,
    // `nether_fossil`, `ancient_city`, `stronghold`, `trail_ruins`,
    // `trial_chambers` — those six are the ones this pipeline places. The
    // mineshaft, the warm ocean ruin and the shipwreck all declare no
    // adaptation at all, so vanilla's own predicate at `forStructuresInChunk`
    // offset 2 would drop them here anyway.
    //
    // The villages are `beard_thin` and the chambers `encapsulate`, so this is
    // also the first time two different adjustments are live at once.
    //
    // Built once for the whole area. The per-chunk work is the two filters
    // inside `for_structures_in_chunk`, not this.
    let beard_starts: Vec<rustmc_worldgen::density::beard::Start> = villages
        .iter()
        .chain(outposts.iter())
        .chain(trail_ruins.iter())
        .chain(ancient_cities.iter())
        .chain(trial_chambers.iter())
        .map(|village| rustmc_worldgen::density::beard::Start {
            adjustment: village.terrain_adaptation,
            union_box: village.union_box,
            pieces: village
                .pieces
                .iter()
                .map(|piece| rustmc_worldgen::density::beard::StartPiece {
                    bounds: piece.bbox,
                    // Every village piece is a `PoolElementStructurePiece`.
                    shape: rustmc_worldgen::density::beard::PieceShape::Pool {
                        rigid: piece.element.projection
                            == rustmc_worldgen::structure::template_pool::Projection::Rigid,
                        ground_level_delta: piece.ground_level_delta,
                        junctions: piece
                            .junctions
                            .iter()
                            .map(|junction| rustmc_worldgen::density::beard::Junction {
                                source_x: junction.source_x,
                                source_ground_y: junction.source_ground_y,
                                source_z: junction.source_z,
                            })
                            .collect(),
                    },
                })
                .collect(),
        })
        .collect();
    // The strongholds' pieces are plain `StructurePiece`s: each a `Rigid`
    // with a ground-level delta of 0, under `bury`.
    let mut beard_starts = beard_starts;
    for sh in &strongholds {
        let sh = sh.lock().expect("the stronghold lock");
        let boxes: Vec<_> = sh.pieces.iter().map(|p| p.piece.bounding_box).collect();
        let Some(union_box) =
            rustmc_worldgen::structure::pieces::BoundingBox::encapsulating(&boxes)
        else {
            continue;
        };
        beard_starts.push(rustmc_worldgen::density::beard::Start {
            adjustment: rustmc_worldgen::structure::template_pool::TerrainAdaptation::Bury,
            union_box,
            pieces: boxes
                .iter()
                .map(|b| rustmc_worldgen::density::beard::StartPiece {
                    bounds: *b,
                    shape: rustmc_worldgen::density::beard::PieceShape::Plain,
                })
                .collect(),
        });
    }
    if trace_beard() {
        let pieces: usize = beard_starts.iter().map(|start| start.pieces.len()).sum();
        eprintln!(
            "BEARD starts={} pieces={} adaptations={:?}",
            beard_starts.len(),
            pieces,
            beard_starts
                .iter()
                .map(|start| format!("{:?}", start.adjustment))
                .collect::<std::collections::BTreeSet<_>>()
        );
        for start in &beard_starts {
            let b = start.union_box;
            eprintln!(
                "BEARD start union_box=[{} {} {} .. {} {} {}] pieces={}",
                b.min_x,
                b.min_y,
                b.min_z,
                b.max_x,
                b.max_y,
                b.max_z,
                start.pieces.len()
            );
            // One line per piece, in the same shape `worldgen-dump
            // jigsaw-starts` prints vanilla's own saved pieces in. That
            // command reads the reference's `Children[].BB`, `GD` and
            // projection straight out of vanilla's chunk NBT — so diffing
            // these two listings is a **vanilla-side oracle for the piece
            // collection**, which is otherwise the one half of the beard
            // with nothing behind it but a reading of the bytecode.
            for (index, piece) in start.pieces.iter().enumerate() {
                let bb = piece.bounds;
                let (rigid, gld, junctions) = match &piece.shape {
                    rustmc_worldgen::density::beard::PieceShape::Pool {
                        rigid,
                        ground_level_delta,
                        junctions,
                    } => (*rigid, *ground_level_delta, junctions.len()),
                    rustmc_worldgen::density::beard::PieceShape::Plain => (false, 0, 0),
                };
                eprintln!(
                    "BEARDPIECE {index} gld={gld} proj={} BB=[{} {} {} .. {} {} {}] junctions={junctions}",
                    if rigid { "rigid" } else { "terrain_matching" },
                    bb.min_x,
                    bb.min_y,
                    bb.min_z,
                    bb.max_x,
                    bb.max_y,
                    bb.max_z
                );
            }
        }
    }
    let beard_chunks = std::sync::atomic::AtomicUsize::new(0);
    // The residual of the structure stage: the block-property extract, the
    // two mineshaft palettes and the bearding starts. The six `str:*` marks
    // above are the structure layouts themselves, split out because a single
    // 39.8%-of-wall row at 1.00 cores says where to look and not what to fix.
    times.mark("str:rest");

    // ---- noise ----
    //
    // The aquifer each chunk built is kept, because the carvers ask the
    // *same* one what belongs in the holes they cut. Dropping it and asking a
    // constant instead was 41% of the first whole-world diff's mismatches.
    //
    // **This stage runs on every core.** It is the one stage that is
    // chunk-local: every write lands inside its own chunk, and it runs before
    // `set_wg_live`, so no write triggers `update_wg`'s read-modify-write of
    // a neighbour's column. `Canvas::chunk_writers` turns that into disjoint
    // `&mut` borrows the compiler checks, and the work is pulled one chunk at
    // a time off a shared queue rather than sliced up front, because chunk
    // cost varies by terrain and a static split finishes on its slowest
    // slice.
    //
    // It cannot change a block. Each chunk's palette is interned in its own
    // write order, which does not depend on what any other chunk did, and the
    // per-chunk `Retained` is a pure function of position — so the result is
    // reassembled into the same `BTreeMap` whatever order the workers
    // finished in. `RUSTMC_WORKERS=1` forces the sequential path; the two are
    // compared byte for byte in BENCH.md.
    let mut retained: BTreeMap<(i32, i32), stage::noise::Retained> = BTreeMap::new();
    {
        // A resumed pass fills only the chunks it added. Re-filling a chunk
        // that has already decorated would replace its features with stone,
        // which is the loudest possible way to break "delivered once, never
        // written again" — and the quietest, because every stage after it
        // would then agree with every other stage about a world nobody asked
        // for.
        let writers: Vec<rustmc_worldgen::canvas::ChunkWriter<'_>> = pipeline
            .canvas_mut()
            .chunk_writers()
            .into_iter()
            .filter(|w| {
                let (cx, cz) = w.position();
                fresh(cx, cz)
            })
            .collect();
        let threads = rustmc_worldgen::pipeline::worker_threads().min(writers.len().max(1));
        let queue = std::sync::Mutex::new(writers.into_iter());
        let fill = |queue: &std::sync::Mutex<
            std::vec::IntoIter<rustmc_worldgen::canvas::ChunkWriter<'_>>,
        >| {
            let mut out: Vec<((i32, i32), stage::noise::Retained)> = Vec::new();
            loop {
                let next = queue.lock().expect("the noise queue lock").next();
                let Some(mut writer) = next else { break };
                let position = writer.position();
                let kept = stage::noise::fill_chunk_into(
                    &mut writer,
                    &router,
                    &seeding,
                    settings,
                    DEFAULT_BLOCK,
                    // The beard. Villages are the only bearding structure
                    // this port places — all five are `beard_thin` — so this
                    // is the only one of the three dimensions' noise loops
                    // that can pass anything but `None`.
                    //
                    // Built per chunk from the whole area's starts, because
                    // `forStructuresInChunk` applies both of vanilla's
                    // filters itself: the reference test against each start's
                    // union box, and `isCloseToChunk` per piece.
                    {
                        let beardifier =
                            rustmc_worldgen::density::beard::Beardifier::for_structures_in_chunk(
                                &beard_starts,
                                position.0,
                                position.1,
                            );
                        // `None` rather than an empty beardifier, so a chunk
                        // no structure reaches takes the same code path it
                        // took before the beard existed and is byte-identical
                        // by construction rather than by an argument about
                        // adding 0.0.
                        if !beardifier.is_empty() {
                            beard_chunks.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                        }
                        (!beardifier.is_empty()).then(|| std::sync::Arc::new(beardifier))
                    },
                );
                out.push((position, kept));
            }
            out
        };
        if threads <= 1 {
            retained.extend(fill(&queue));
        } else {
            let batches: Vec<Vec<((i32, i32), stage::noise::Retained)>> =
                std::thread::scope(|scope| {
                    let handles: Vec<_> =
                        (0..threads).map(|_| scope.spawn(|| fill(&queue))).collect();
                    handles
                        .into_iter()
                        .map(|h| h.join().expect("a noise worker"))
                        .collect()
                });
            for batch in batches {
                retained.extend(batch);
            }
        }
    }
    // `NoiseBasedChunkGenerator#doFill` marks every aquifer fluid position
    // whose `shouldScheduleFluidUpdate` was set. The stage returns them per
    // chunk because a `ChunkWriter` cannot reach the canvas's mark set; the
    // union happens here, once, after the pool has joined. `retained` is a
    // `BTreeMap` and the destination is a set, so worker order cannot reach
    // the result. This is the transfer that used to be missing: the marks
    // were produced by the aquifer and read by nothing.
    {
        let canvas = pipeline.canvas_mut();
        for kept in retained.values() {
            for &(x, y, z) in &kept.post_processing {
                canvas.mark_post_processing(x, y, z);
            }
        }
    }
    if trace_beard() {
        eprintln!(
            "BEARD chunks_with_a_beard={}",
            beard_chunks.load(std::sync::atomic::Ordering::Relaxed)
        );
    }
    times.mark("noise");
    if through == Through::Noise {
        times.report(generated_chunks);
        return Ok(Generated {
            canvas: pipeline.into_canvas(),
            area,
            through,
            dimension: Dim::Overworld,
            refused: BTreeMap::new(),
        });
    }

    // ---- biomes ----
    //
    // `find_value` needs `&mut` because the search is order-dependent on
    // exact ties — vanilla hides that in a ThreadLocal, this port makes it
    // visible — so the list lives in a cell the stage closure can borrow.
    // `BiomeManager`'s obfuscated seed. Everything that asks for the biome at
    // a **block** — the surface rules, the decoration filter — goes through
    // its fuzzed quantisation, *not* a plain `>> 2`. The fuzz nudges the
    // border a block or two either way, which is invisible in open terrain
    // and decides which side of a sulfur-cave boundary a column lands on.
    let zoom = rustmc_worldgen::biome::manager::obfuscate_seed(seed);
    {
        // **Two passes, and the split is exact rather than speculative.**
        //
        // A cell is two halves. `ClimateSampler::sample` is six density
        // functions and is a **pure function of `(qx, qy, qz)`**;
        // `find_value` mutates a search hint and resolves exact ties by the
        // sequence of calls before it, so the order of *those* calls is
        // behaviour (0.195% of cells are ties — `golden_climate_ties.rs`).
        // BENCH.md measures the pair inside the surface stage at 4.84 s of
        // sampling against 0.19 s of searching, so the order-dependent half
        // is under 4% of the work.
        //
        // Pass 1 computes every cell's `TargetPoint` on a worker pool. Pass 2
        // walks the chunks — and each chunk's cells — in exactly the order
        // they are walked today, calling `find_value` on the stored points.
        // The list therefore sees literally the same calls, with the same
        // inputs, in the same order. There is nothing to speculate and
        // nothing to validate, and no owner ruling is needed.
        //
        // Batched so the points in flight do not scale with the radius: 256
        // chunks x 1,536 cells x 48 bytes is ~19 MB whatever the square. The
        // whole square at r=32 would be 351 MB on top of a 1.4 GB process.
        const BATCH: usize = 256;
        let min_y = pipeline.canvas().min_y();
        let height = pipeline.canvas().height();
        // A resumed pass fills the biome containers of the chunks it added
        // and leaves the rest alone; a chunk that is already carved has its
        // containers, and the snapshot below reads all of them off the canvas
        // rather than out of this pass.
        let all: Vec<(i32, i32)> = pipeline
            .generated()
            .chunks()
            .filter(|&(cx, cz)| fresh(cx, cz))
            .collect();
        let threads = rustmc_worldgen::pipeline::worker_threads();
        for batch in all.chunks(BATCH) {
            // Each sampler carries its own copy of the six climate functions
            // and its own flat-cache tables, because filling a table numbers
            // the markers and writes into them. One per worker, not one per
            // chunk: the numbering deep-clones the terrain spline behind
            // `offset`, and that clone is a function of the graph, not of the
            // chunk.
            let sample_one =
                |climate: &mut ChunkClimate, chunk_x: i32, chunk_z: i32| -> Vec<TargetPoint> {
                    climate.move_to(chunk_x, chunk_z);
                    stage::biome::cells(min_y, height, chunk_x, chunk_z)
                        .map(|(qx, qy, qz)| climate.sample(qx, qy, qz))
                        .collect()
                };
            let sampled: Vec<Vec<TargetPoint>> = if threads <= 1 {
                let mut climate = ChunkClimate::new(&sampler);
                batch
                    .iter()
                    .map(|&(cx, cz)| sample_one(&mut climate, cx, cz))
                    .collect()
            } else {
                let next = std::sync::atomic::AtomicUsize::new(0);
                let slots: Vec<std::sync::Mutex<Vec<TargetPoint>>> = batch
                    .iter()
                    .map(|_| std::sync::Mutex::new(Vec::new()))
                    .collect();
                std::thread::scope(|scope| {
                    for _ in 0..threads {
                        scope.spawn(|| {
                            let mut climate = ChunkClimate::new(&sampler);
                            loop {
                                let i = next.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                                let Some(&(cx, cz)) = batch.get(i) else { break };
                                let points = sample_one(&mut climate, cx, cz);
                                *slots[i].lock().expect("a biome sample slot") = points;
                            }
                        });
                    }
                });
                slots
                    .into_iter()
                    .map(|slot| slot.into_inner().expect("a biome sample slot"))
                    .collect()
            };

            for (&(chunk_x, chunk_z), points) in batch.iter().zip(sampled) {
                let mut points = points.into_iter();
                // The coordinates are ignored deliberately: both passes walk
                // `stage::biome::cells`, so cell *n* of pass 2 is cell *n* of
                // pass 1 by construction. The debug assertion says so out
                // loud, and the count check below is the release-build guard.
                let mut expected = stage::biome::cells(min_y, height, chunk_x, chunk_z);
                let mut at = |qx: i32, qy: i32, qz: i32| {
                    debug_assert_eq!(
                        expected.next(),
                        Some((qx, qy, qz)),
                        "the two biome passes walk the cells in different orders"
                    );
                    let point = points.next().expect("one sampled point per cell");
                    biomes
                        .lock()
                        .expect("the climate list lock")
                        .find_value(point)
                        .clone()
                };
                stage::biome::fill_chunk(pipeline.canvas_mut(), &mut at, chunk_x, chunk_z);
                assert!(
                    points.next().is_none(),
                    "pass 1 sampled more cells than pass 2 consumed"
                );
            }
        }
    }
    times.mark("biomes");
    if through == Through::Biomes {
        times.report(generated_chunks);
        return Ok(Generated {
            canvas: pipeline.into_canvas(),
            area,
            through,
            dimension: Dim::Overworld,
            refused: BTreeMap::new(),
        });
    }

    // The two `_WG` heightmaps stay live from here until decoration starts.
    // Vanilla updates whatever the chunk's *persisted* status names, and the
    // persisted status lags the running step by one, so surface and carver
    // writes both land while `{OCEAN_FLOOR_WG, WORLD_SURFACE_WG}` is the
    // active set. Freezing them after the noise stage — which is what this
    // did — leaves every heightmap-anchored placement above a carved sea
    // floor hanging in the water.
    {
        let props = crate::block_props()?;
        pipeline
            .canvas_mut()
            .set_wg_live(rustmc_worldgen::canvas::WgPredicates::new(
                move |state: &str| {
                    props.get(state).map_or(
                        // A state the table does not know matches nothing, which
                        // lowers a heightmap rather than raising it. A raised one
                        // silently moves features; a lowered one is visible.
                        rustmc_worldgen::canvas::WgFacts {
                            air: true,
                            blocks_motion: false,
                        },
                        |p| rustmc_worldgen::canvas::WgFacts {
                            air: p.air,
                            blocks_motion: p.blocks_motion,
                        },
                    )
                },
            ));
    }

    // ---- surface ----
    let rule = surface_rule()?;
    let biome_data = crate::biome_data();
    let temperature_noises = rustmc_worldgen::biome::temperature::TemperatureNoises::new();
    // Once for the world, not once per chunk. Building it per chunk
    // instantiated every surface noise and redrew the 192 clay bands for
    // each chunk that only reads them, and was 79% of the whole pipeline.
    // Counts and times every biome query the surface rules make, when
    // `RUSTMC_STAGE_TIMES` asks. The rule walk is 78% of a chunk and this
    // closure is the one thing in it that re-derives rather than reads —
    // `ClimateSampler::sample` is six density functions and `find_value` a
    // linear search over the biome table, per call — so knowing the call
    // count is the difference between a hypothesis and a target.
    //
    // The fourth cell counts the **fallback** — a query the 3x3 biome
    // snapshot could not answer, which is the only path in this stage that
    // reaches `ParameterList::find_value`. That call mutates a search hint
    // and resolves exact ties by the order of the calls before it, so it is
    // the one thing standing between this stage and a worker pool. Whether
    // it is a real obstacle is a *count*, not an argument: at zero the
    // shared list is never touched here and per-worker copies are free.
    type Probe = (
        std::cell::Cell<u64>,
        std::cell::Cell<std::time::Duration>,
        std::cell::Cell<std::time::Duration>,
        std::cell::Cell<u64>,
    );
    let surface_probe: Option<Probe> = std::env::var_os("RUSTMC_STAGE_TIMES").map(|_| {
        (
            std::cell::Cell::new(0),
            std::cell::Cell::new(std::time::Duration::ZERO),
            std::cell::Cell::new(std::time::Duration::ZERO),
            std::cell::Cell::new(0),
        )
    });
    // What the surface stage does to the shared `ParameterList`, and **why**.
    // Separate from `Probe` because it runs a *second* search per fallback,
    // so it is off unless asked for by name: `RUSTMC_SURFACE_TIES=1`.
    //
    // `interior` is the counter that decides the parallel split. A chunk with
    // all nine neighbours on the canvas is claimed never to reach
    // `find_value` at all; if that holds, those chunks can run on a worker
    // pool that never touches the shared list, and the perimeter runs
    // sequentially in its original order, which is exactly the order the
    // list sees today.
    //
    // **`interior` is the standing guard on the parallel split**, not a
    // diagnostic. A chunk with all nine neighbours on the canvas must never
    // reach the shared list; if it ever does again, this counter is how the
    // next run finds out, and the split has to come back out.
    struct TieProbe {
        asked: std::cell::Cell<u64>,
        changed: std::cell::Cell<u64>,
        interior: std::cell::Cell<u64>,
        chunks: std::cell::Cell<u64>,
        touched: std::cell::Cell<u64>,
    }
    let surface_tie_probe: Option<TieProbe> =
        std::env::var_os("RUSTMC_SURFACE_TIES").map(|_| TieProbe {
            asked: std::cell::Cell::new(0),
            changed: std::cell::Cell::new(0),
            interior: std::cell::Cell::new(0),
            chunks: std::cell::Cell::new(0),
            touched: std::cell::Cell::new(0),
        });

    // Memoises the climate sample, and **only** the climate sample.
    //
    // The rule walk asks for a biome 31,719 times a chunk and the answer is
    // built in two halves: `ClimateSampler::sample`, six density functions
    // over a quart-quantised position, and `find_value`, a search of the
    // biome parameter list. Measured at radius 1: 7.11s of a 12.60s pipeline
    // is the sample and 1.95s is the search — the sample alone is 56% of
    // everything.
    //
    // Only the first half is cached, and the distinction is not a
    // convenience. `sample` is a pure function of `(qx, qy, qz)`, so
    // returning a stored answer is returning the same answer. `find_value`
    // mutates a search hint and its result on an *exact tie* depends on the
    // sequence of calls that came before it — vanilla hides the same
    // behaviour in a ThreadLocal — so skipping a call to it would change
    // which biome a tie resolves to. That is a live mechanism here, not a
    // theoretical one: the repo's standing 3-block red is a climate tie.
    //
    // So every `find_value` call still happens, in the same order, with the
    // same input. Only the six density functions behind it stop being re-run
    // for a position already asked about.
    //
    // A `BTreeMap` because CLAUDE.md forbids hash iteration at
    // behaviour-visible sites; this one is never iterated, but the cost of
    // an ordered lookup against six noise evaluations is not worth the
    // exception.
    //
    // Proved transparent the only way worth proving it — generate the world
    // both ways and compare the bytes, not the blocks. Two seeds, two
    // centres, `cmp` on every region file: identical. 20260722 at (64,64)
    // 28.4s -> 18.0s, 31415926 at (-53,-33) 22.5s -> 11.1s. The second
    // window is land and so asks more biome questions, which is where the
    // 2x comes from.
    let climate_cache: RefCell<
        BTreeMap<(i32, i32, i32), rustmc_worldgen::biome::climate::TargetPoint>,
    > = RefCell::new(BTreeMap::new());

    let surface_noises = std::sync::Arc::new(rustmc_worldgen::surface::world::SurfaceNoises::new(
        seed, &params,
    ));

    // Everything the walk reads that is not its own chunk's blocks, taken
    // once for the whole stage rather than nine `Vec` clones per chunk.
    //
    // The surface rules must read the **stored** biome, not recompute it. A
    // server's `BiomeManager` resolves quart cells out of the container that
    // `fillBiomesFromNoise` filled from `noiseChunk.cachedClimateSampler(..)`,
    // and sampling the climate function again at the same cell is a
    // *different computation* that disagrees at some of them. Measured at
    // seed 20260722 chunk (63,68): the container holds `savanna` at
    // (1013,45,1098) where resampling says `lukewarm_ocean`, and since
    // `savanna` is not in the rule's `[warm_ocean, lukewarm_ocean,
    // deep_lukewarm_ocean]` list the server falls through to gravel where
    // this port took the ocean branch to sand — 51 blocks on the 121-chunk
    // window.
    //
    // This stage writes **blocks** and nothing else, so the biome containers
    // and the `_WG` fossils are frozen inputs to it and one snapshot serves
    // every chunk. That is also what makes the snapshot safe to share with a
    // worker pool: nothing writes it while the stage runs.
    let canvas_min_y = pipeline.canvas().min_y();
    let (biome_snapshot, heights_by_chunk) = {
        let canvas = pipeline.canvas();
        let mut biomes_out: BTreeMap<(i32, i32), BiomeContainer> = BTreeMap::new();
        let mut heights_out: BTreeMap<(i32, i32), [i32; 256]> = BTreeMap::new();
        for (cx, cz) in pipeline.generated().chunks() {
            if let Some((palette, ids)) = canvas.chunk_biomes(cx, cz) {
                biomes_out.insert((cx, cz), (palette.to_vec(), ids.to_vec()));
            }
            heights_out.insert(
                (cx, cz),
                canvas
                    .world_surface_wg_chunk(cx, cz)
                    .ok_or("a generated chunk has no heightmap")?,
            );
        }
        (biomes_out, heights_out)
    };

    // A chunk with all nine neighbours on the canvas cannot reach the shared
    // `ParameterList` — see `SurfaceShared::stored_biome_at` and BENCH.md.
    // The canvas holds exactly `generated()`, so that set is `generated()`
    // minus its outer ring, and the ring is the only part that has to stay
    // sequential.
    let generated = pipeline.generated();
    let interior = |cx: i32, cz: i32| {
        cx > generated.min_chunk_x
            && cx < generated.max_chunk_x
            && cz > generated.min_chunk_z
            && cz < generated.max_chunk_z
    };
    let surface_biomes = SurfaceBiomes::new(&biome_data, &biome_snapshot, canvas_min_y, zoom);
    let rule = surface_biomes.intern_rule(rule);
    let shared = SurfaceShared {
        rule: &rule,
        noises: &surface_noises,
        temperature_noises: &temperature_noises,
        preliminary: &router.preliminary_surface_level,
        biomes: &surface_biomes,
        sea_level: SEA_LEVEL,
        default_block: DEFAULT_BLOCK,
        generator: stage::surface::GenExtent {
            min_y: MIN_Y,
            height: HEIGHT,
        },
    };

    // ---- the interior, on every core ----
    //
    // Each worker holds its own `SurfaceLevels`, which is a memo of a pure
    // function of position, so a per-worker copy costs recomputation and
    // cannot change a value. Nothing else is per-worker: an interior chunk's
    // `biome_at` only ever reads the snapshot.
    //
    // The instruments are **sequential-only**. `Probe` and `TieProbe` are
    // `Cell`s, and a probe that a worker pool could increment would be a
    // different measurement anyway — so a run with either switch on takes the
    // sequential path for the whole stage, and says so.
    let instrumented = surface_probe.is_some() || surface_tie_probe.is_some();
    if !instrumented {
        let writers: Vec<rustmc_worldgen::canvas::ChunkWriter<'_>> = pipeline
            .canvas_mut()
            .chunk_writers()
            .into_iter()
            .filter(|w| {
                let (cx, cz) = w.position();
                interior(cx, cz) && fresh(cx, cz)
            })
            .collect();
        let threads = rustmc_worldgen::pipeline::worker_threads().min(writers.len().max(1));
        let queue = std::sync::Mutex::new(writers.into_iter());
        let surface_marks: std::sync::Mutex<Vec<Vec<(i32, i32, i32)>>> =
            std::sync::Mutex::new(Vec::new());
        let run = |queue: &std::sync::Mutex<
            std::vec::IntoIter<rustmc_worldgen::canvas::ChunkWriter<'_>>,
        >| {
            let levels = RefCell::new(SurfaceLevels::new(shared.preliminary.clone()));
            let flat = FlatCaches::none();
            loop {
                let next = queue.lock().expect("the surface queue lock").next();
                let Some(mut writer) = next else { break };
                let (cx, cz) = writer.position();
                let heights = &heights_by_chunk[&(cx, cz)];
                // The 3x3 that this chunk's fuzz can reach, resolved once per
                // chunk. This is the hot path: an interior chunk asks ~28,864
                // times and every one of them used to walk a `BTreeMap` of up
                // to 4,761 entries to find the same nine containers.
                let near = shared.biomes.neighbourhood(cx, cz);
                let biome_at = |x: i32, y: i32, z: i32| {
                    near.id_at(x, y, z).expect(
                        "an interior chunk's biome fuzz reaches at most one chunk out, and the \
                         vertical clamp keeps every quart y on the container — so the snapshot \
                         always answers. RUSTMC_SURFACE_TIES=1 reports the guard.",
                    )
                };
                surface_one_chunk(
                    &mut writer,
                    cx,
                    cz,
                    heights,
                    &shared,
                    &levels,
                    &flat,
                    &biome_at,
                );
                // `SurfaceSystem`'s column writer marks every fluid it writes.
                // The writer is dropped at the end of this iteration, so its
                // marks are taken here and unioned once the workers have
                // joined; within-chunk order is what matters and one chunk is
                // one writer, so nothing is reordered by the collection.
                let taken = writer.take_post_processing();
                if !taken.is_empty() {
                    surface_marks
                        .lock()
                        .expect("the surface mark lock")
                        .push(taken);
                }
            }
        };
        if threads <= 1 {
            run(&queue);
        } else {
            std::thread::scope(|scope| {
                let handles: Vec<_> = (0..threads).map(|_| scope.spawn(|| run(&queue))).collect();
                for handle in handles {
                    handle.join().expect("a surface worker");
                }
            });
        }
        // Sorted before the union so a run at twelve workers marks in the
        // same order as a run at one: the outer order is across chunks and
        // cannot matter, but a set that differs run to run would make the
        // mark dump unreadable as a diff.
        let mut collected = surface_marks
            .into_inner()
            .expect("the surface mark lock at join");
        collected.sort();
        let canvas = pipeline.canvas_mut();
        for chunk_marks in collected {
            for (x, y, z) in chunk_marks {
                canvas.mark_post_processing(x, y, z);
            }
        }
    }

    // ---- the perimeter, and the whole stage when instrumented ----
    //
    // In `generated().chunks()` order, which is the order the shared list saw
    // before this split existed. Because the interior makes **no** calls to
    // it, dropping the interior out of that sequence leaves the sequence of
    // calls the list actually sees byte for byte identical — the split is
    // order-preserving rather than order-invariant, so it needs no ruling and
    // no validation pass.
    let levels = RefCell::new(SurfaceLevels::new(router.preliminary_surface_level.clone()));
    let flat = FlatCaches::none();
    for (chunk_x, chunk_z) in pipeline.generated().chunks() {
        if !instrumented && interior(chunk_x, chunk_z) {
            continue;
        }
        // A chunk this pass inherited already has its surface.
        //
        // **This one is not free and is written down rather than waved past.**
        // `ParameterList::find_value` takes `&mut self` because the previous
        // result seeds the next search *and breaks its ties*, so dropping the
        // inherited perimeter chunks out of the query sequence can hand a
        // fresh chunk a different biome on an exact tie than a from-scratch
        // pass would have. That is a difference between growing a world and
        // regenerating it, and it is the same class of difference
        // `docs/DETERMINISM.md` §32.4 says is unavoidable once features read
        // neighbours' features — it is emphatically **not** a write into
        // anything already delivered, which is the property being bought here.
        if !fresh(chunk_x, chunk_z) {
            continue;
        }
        let heights = heights_by_chunk[&(chunk_x, chunk_z)];
        // Whether *this* chunk reached the shared parameter list at all —
        // the standing guard on the split above.
        let chunk_fell_back = std::cell::Cell::new(false);
        let biome_at = |x: i32, y: i32, z: i32| {
            let started = surface_probe.as_ref().map(|_| std::time::Instant::now());
            // The stored cell if we have it. Falling back to a resample keeps
            // the very edge of the generated area working, where the fuzz can
            // reach a chunk that was never started; inside the area — which is
            // everything a dump reports — the snapshot always hits.
            if let Some(stored) = shared.biomes.id_at(x, y, z) {
                if let (Some(probe), Some(t)) = (surface_probe.as_ref(), started) {
                    probe.0.set(probe.0.get() + 1);
                    probe.1.set(probe.1.get() + t.elapsed());
                }
                return stored;
            }
            let (qx, qy, qz) = rustmc_worldgen::biome::manager::quart_for_block(zoom, x, y, z);
            let point = {
                let hit = climate_cache.borrow().get(&(qx, qy, qz)).copied();
                match hit {
                    Some(p) => p,
                    None => {
                        let p = sampler.sample(qx, qy, qz);
                        climate_cache.borrow_mut().insert((qx, qy, qz), p);
                        p
                    }
                }
            };
            let sampled = surface_probe.as_ref().map(|_| std::time::Instant::now());
            let out = {
                let mut list = biomes.lock().expect("the climate list lock");
                // Whether the search **hint** ever changed an answer, which
                // is a stronger question than whether it was consulted.
                // `find_value_stateless` is the same search with no hint, so
                // a disagreement is a tie that the call order decided.
                let unhinted = surface_tie_probe
                    .as_ref()
                    .map(|_| list.find_value_stateless(point).clone());
                let hinted = list.find_value(point).clone();
                if let (Some(counts), Some(unhinted)) = (surface_tie_probe.as_ref(), unhinted) {
                    counts.asked.set(counts.asked.get() + 1);
                    if unhinted != hinted {
                        counts.changed.set(counts.changed.get() + 1);
                    }
                    // A fallback from a chunk with all nine neighbours would
                    // break the split above. It must stay zero.
                    if interior(chunk_x, chunk_z) {
                        counts.interior.set(counts.interior.get() + 1);
                    }
                    chunk_fell_back.set(true);
                }
                shared.biomes.id_of_name(&hinted)
            };
            if let (Some(probe), Some(t), Some(s)) = (surface_probe.as_ref(), started, sampled) {
                probe.0.set(probe.0.get() + 1);
                probe.3.set(probe.3.get() + 1);
                probe.1.set(probe.1.get() + t.elapsed());
                // The half that is a pure function of the position, and so
                // the only half that is safe to memoise: `find_value` mutates
                // a search hint and its result on an exact tie depends on the
                // sequence of calls before it.
                probe.2.set(probe.2.get() + s.elapsed());
            }
            out
        };
        surface_one_chunk(
            pipeline.canvas_mut(),
            chunk_x,
            chunk_z,
            &heights,
            &shared,
            &levels,
            &flat,
            &biome_at,
        );
        if let Some(counts) = surface_tie_probe.as_ref() {
            counts.chunks.set(counts.chunks.get() + 1);
            if chunk_fell_back.get() {
                counts.touched.set(counts.touched.get() + 1);
            }
        }
    }

    if let Some((calls, spent, find, fallbacks)) = &surface_probe {
        let total = spent.get().as_secs_f64();
        let search = find.get().as_secs_f64();
        eprintln!(
            "surface biome queries: {} over {generated_chunks} chunks ({:.0}/chunk), \
             {total:.2}s = {:.2}s climate sample + {search:.2}s parameter search",
            calls.get(),
            calls.get() as f64 / generated_chunks as f64,
            total - search,
        );
        // The number that decides whether this stage can be parallelised.
        eprintln!(
            "surface find_value fallbacks: {} of {} queries ({:.4}%)",
            fallbacks.get(),
            calls.get(),
            100.0 * fallbacks.get() as f64 / calls.get().max(1) as f64,
        );
    }
    // How many named-noise samples the rule walk asked for against how many
    // were computed — the count vanilla shares one memoised sampler for.
    // Zero when `RUSTMC_SURFACE_NOISE` is unset, which is when the counters
    // are not incremented at all.
    {
        let (asked, computed, depth_asked, depth_computed) =
            rustmc_worldgen::surface::world::noise_counts::read();
        if asked > 0 || depth_asked > 0 {
            let per = |n: u64| n as f64 / generated_chunks as f64;
            eprintln!(
                "surface named noise: asked {asked} ({:.0}/chunk), computed {computed} \
                 ({:.0}/chunk), ratio {:.2}x",
                per(asked),
                per(computed),
                asked as f64 / computed.max(1) as f64,
            );
            eprintln!(
                "surface getSurfaceDepth: asked {depth_asked} ({:.0}/chunk), computed \
                 {depth_computed} ({:.0}/chunk), ratio {:.2}x",
                per(depth_asked),
                per(depth_computed),
                depth_asked as f64 / depth_computed.max(1) as f64,
            );
        }
    }
    if let Some(counts) = &surface_tie_probe {
        eprintln!(
            "surface find_value ties: the hint changed {} of {} answers; \
             {} came from a chunk with all nine neighbours",
            counts.changed.get(),
            counts.asked.get(),
            counts.interior.get(),
        );
        eprintln!(
            "surface find_value chunks: {} of {} chunks reached the shared list ({:.1}%)",
            counts.touched.get(),
            counts.chunks.get(),
            100.0 * counts.touched.get() as f64 / counts.chunks.get().max(1) as f64,
        );
    }
    times.mark("surface");
    if through == Through::Surface {
        times.report(generated_chunks);
        return Ok(Generated {
            canvas: pipeline.into_canvas(),
            area,
            through,
            dimension: Dim::Overworld,
            refused: BTreeMap::new(),
        });
    }

    // ---- carvers ----
    //
    // The aquifer and `topMaterial` closures are the two things a carver asks
    // the rest of the generator. Both are now real. `topMaterial` was
    // stubbed to `None` until 2026-08-09 — a cave mouth kept bare dirt where
    // vanilla re-runs the surface rule on the exposed block — and it was
    // worth 646 blocks of the r=16 window's order-stable residual, 88% of
    // it. Note that the stub was only half of that defect: the `hasGrass`
    // arm in `carve_block` compared a *state* string against a *block*
    // name, so this closure was never called at all.
    let tags = crate::block_tags()?;
    let configured = crate::configured_carvers();
    // The carver stage's own hot lookup, counted.
    //
    // `apply_carvers` calls `carvers_at` **unconditionally** for every one of
    // the 289 source chunks of every target chunk, so this is 289 climate
    // samples and 289 `ParameterList::find_value` queries per chunk however
    // few carvers a biome lists. Nothing counted them, and the count is what
    // says whether the stage is carving or looking up. `RUSTMC_CARVER_BIOME=1`.
    let carver_biome_calls = std::sync::atomic::AtomicU64::new(0);
    let carver_biome_nanos = std::sync::atomic::AtomicU64::new(0);
    let carver_biome_hint_moved = std::sync::atomic::AtomicU64::new(0);
    let carver_point_moved = std::sync::atomic::AtomicU64::new(0);
    let verify_carver_biome = std::env::var_os("RUSTMC_CARVER_BIOME_VERIFY").is_some();
    // One climate sample per **source chunk**, not one per (target chunk,
    // source chunk) pair.
    //
    // `apply_carvers` asks `carvers_at` for all 289 source chunks of every
    // target chunk, so a source chunk in the middle of the square is sampled
    // 289 times with identical arguments: 1,375,929 samples for 7,225 distinct
    // positions on the r=32 square, measured 2026-08-16. `ClimateSampler` is a
    // pure function of the quart position — nothing about it depends on what
    // was asked before — so collapsing them cannot move a block.
    //
    // **What is emphatically not collapsed is the `find_value` below it.**
    // `ParameterList` starts each search from the previous query's leaf, so
    // its answer *can* depend on the order queries arrive in, and on this
    // square it does: 545 of those 1,375,929 lookups come back with a
    // different biome when the hint is taken away. The memo therefore sits
    // above the sampler and below the list, and the query sequence into the
    // list is the sequence it always was.
    //
    // `RUSTMC_CARVER_BIOME_VERIFY=1` checks both halves of that: it compares
    // the memoised point against a fresh sample at every call, and the
    // hinted search against the stateless one. The first must be 0 and the
    // second is 545 — the same instrument, one arm green and one arm red,
    // which is what says the green arm means something.
    let carver_points: RefCell<BTreeMap<(i32, i32), rustmc_worldgen::biome::climate::TargetPoint>> =
        RefCell::new(BTreeMap::new());
    let top_material_asks = std::sync::atomic::AtomicU64::new(0);
    let top_material_asks_fluid = std::sync::atomic::AtomicU64::new(0);
    let top_material_unresolved = std::sync::atomic::AtomicU64::new(0);

    // ---- pass 1: the biome lookups, sequentially and in the sweep's order ----
    //
    // `apply_carvers` asks `carvers_at` for all 289 source chunks of every
    // target chunk, unconditionally and in `dx`-then-`dz` order, so the whole
    // query sequence is structural and can be replayed. It is recorded here,
    // on one thread, in exactly the order the single-threaded stage produced
    // it — which is the condition `ParameterList`'s search hint needs, and it
    // is not a formality: 545 of the 1,375,929 lookups on this square come
    // back with a different biome when the hint is taken away.
    //
    // What is recorded is an index into the handful of distinct carver lists,
    // not the lists themselves: `u16` per query, 2.8 MB for the r=32 square
    // against the ~330 MB the cloned `Vec<ConfiguredCarver>`s would be.
    const SWEEP: i32 = rustmc_worldgen::carver::driver::SWEEP_RADIUS;
    let per_chunk = ((2 * SWEEP + 1) * (2 * SWEEP + 1)) as usize;
    let carve_targets: Vec<(i32, i32)> = pipeline
        .generated()
        .chunks()
        .filter(|&(x, z)| fresh(x, z))
        .collect();
    let mut carver_lists: Vec<Vec<rustmc_worldgen::carver::config::ConfiguredCarver>> = Vec::new();
    let mut list_of_biome: BTreeMap<String, u16> = BTreeMap::new();
    let mut carver_log: Vec<u16> = Vec::with_capacity(carve_targets.len() * per_chunk);
    for &(cx, cz) in &carve_targets {
        for dx in -SWEEP..=SWEEP {
            for dz in -SWEEP..=SWEEP {
                let (source_x, source_z) = (cx + dx, cz + dz);
                let clock = std::time::Instant::now();
                let point = {
                    let hit = carver_points.borrow().get(&(source_x, source_z)).copied();
                    match hit {
                        Some(point) => {
                            if verify_carver_biome
                                && point != sampler.sample(source_x * 4, 0, source_z * 4)
                            {
                                carver_point_moved
                                    .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                            }
                            point
                        }
                        None => {
                            let point = sampler.sample(source_x * 4, 0, source_z * 4);
                            carver_points
                                .borrow_mut()
                                .insert((source_x, source_z), point);
                            point
                        }
                    }
                };
                let id = {
                    let mut list = biomes.lock().expect("the climate list lock");
                    // `RUSTMC_CARVER_BIOME_VERIFY=1` asks the same query both
                    // ways: `find_value`, which starts its search from the
                    // *previous* query's leaf and so can depend on the order
                    // queries arrive in, and `find_value_stateless`, which
                    // cannot. A disagreement is the only thing that makes this
                    // stage's lookups order-sensitive, and it is the only
                    // thing that could make memoising or parallelising them
                    // move a block. Counted rather than argued.
                    if verify_carver_biome {
                        let stateless = list.find_value_stateless(point).clone();
                        let stateful = list.find_value(point).clone();
                        if stateless != stateful {
                            carver_biome_hint_moved
                                .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                        }
                        stateful
                    } else {
                        list.find_value(point).clone()
                    }
                };
                let next = u16::try_from(carver_lists.len())
                    .map_err(|_| "more distinct carver lists than a u16 can index")?;
                let slot = *list_of_biome.entry(id.clone()).or_insert_with(|| {
                    carver_lists.push(biome_data.get(&id).map_or_else(Vec::new, |entry| {
                        entry
                            .carvers
                            .iter()
                            .filter_map(|name| configured.get(name).cloned())
                            .collect()
                    }));
                    next
                });
                carver_log.push(slot);
                carver_biome_calls.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                carver_biome_nanos.fetch_add(
                    clock.elapsed().as_nanos() as u64,
                    std::sync::atomic::Ordering::Relaxed,
                );
            }
        }
    }

    // ---- pass 2: the carving, on the pool ----
    //
    // A carver writes only into the chunk it was called for — the carve loop
    // clamps its `x` and `z` indices to that chunk's `0..=15` — and the only
    // read outside the loop is one block below, in the same column. So each
    // chunk gets a `ChunkWriter`, which is a disjoint `&mut` the compiler
    // checks, and its own `Retained` aquifer state, which was already
    // per-chunk. Nothing else is shared but read-only tables and the replayed
    // log above.
    let carve_one = |writer: &mut rustmc_worldgen::canvas::ChunkWriter<'_>,
                     kept: &mut stage::noise::Retained,
                     chunk_x: i32,
                     chunk_z: i32,
                     log: &[u16]| {
        let mut mask = rustmc_worldgen::carver::mask::CarvingMask::new(HEIGHT, MIN_Y);
        // `Aquifer#computeSubstance(pos, 0.0)` — the real one, from this
        // chunk's own fill. `None` means the aquifer declined and the block
        // stays as it was, which is how caves stop below the water table.
        let flat = &kept.flat;
        let surface = &mut kept.surface;
        let aquifer_state = &mut kept.aquifer;
        // `RUSTMC_TRACE_CARVER=<cx>,<cz>` also reports what the aquifer told
        // the carvers here. `None` means "leave the block alone", so an
        // aquifer that answers `None` everywhere silently turns every carve
        // in the chunk into a no-op — which looks exactly like a chunk with
        // no caves in it.
        let watch = trace_carver()
            .and_then(|v| {
                let (a, b) = v.split_once(',')?;
                Some((a.trim().parse::<i32>().ok()?, b.trim().parse::<i32>().ok()?))
            })
            .is_some_and(|(a, b)| a == chunk_x && b == chunk_z);
        if watch {
            eprintln!(
                "CARVE ({chunk_x},{chunk_z}) aquifer present: {}",
                aquifer_state.is_some()
            );
        }
        let asked = std::cell::Cell::new(0u64);
        let declined = std::cell::Cell::new(0u64);
        let answers: RefCell<BTreeMap<String, u64>> = RefCell::new(BTreeMap::new());
        // The flag as the *fill* stage left it on this same aquifer object.
        // `getCarveState`'s lava branch reads it without refreshing it, so
        // the first carve in a chunk can legitimately see the fill's answer.
        let initial_should_schedule = aquifer_state.as_ref().is_some_and(
            rustmc_worldgen::density::aquifer::NoiseBasedAquifer::should_schedule_fluid_update,
        );
        let mut aquifer = |x: i32, y: i32, z: i32| {
            let mut should_schedule = false;
            let out = aquifer_state.as_mut().and_then(|a| {
                let substance = a.compute_substance(flat, surface, (x, y, z), 0.0);
                should_schedule = a.should_schedule_fluid_update();
                substance.map(|substance| {
                    rustmc_worldgen::anvil_bridge::block_name(substance, DEFAULT_BLOCK).to_string()
                })
            });
            if watch {
                asked.set(asked.get() + 1);
                match &out {
                    None => declined.set(declined.get() + 1),
                    Some(name) => {
                        *answers.borrow_mut().entry(name.clone()).or_insert(0) += 1;
                    }
                }
            }
            (out, should_schedule)
        };
        // `CarvingContext#topMaterial`. The oracle is the surface stage's
        // own, rebuilt per chunk from the same frozen inputs: the
        // `WORLD_SURFACE_WG` fossil this canvas took at the noise stage, the
        // stored biome containers, and the shared per-seed noises. Nothing
        // it reads is written by carving, which is why it can be built
        // outside the borrow the carve target holds on the canvas.
        //
        // A MISS ON THE STORED BIOME DECLINES; IT DOES NOT GUESS. The biome
        // fuzz reaches one chunk out, so on the outer ring of the generated
        // area `id_at` can land on a container that was never filled. The
        // alternative to declining is resampling the climate function, and
        // `SurfaceShared` above records what that costs: it is a *different
        // computation* from the container and disagreed with it at real
        // positions on this seed. Answering `None` leaves the dirt exactly as
        // the stub used to, so a miss can only fail to improve a block and can
        // never move one the wrong way — and the count is printed rather than
        // swallowed. It is NOT zero and the guess was not harmless by luck
        // alone: measured 29 over the r=16 window, 2026-08-09, and the dump
        // taken while this closure still answered `BiomeId::default()` at
        // those 29 is byte-identical to the one taken while it declines. So
        // the two behaviours agree on this window and only one of them says
        // so out loud.
        let top_heights = &heights_by_chunk[&(chunk_x, chunk_z)];
        let top_climate = |id: rustmc_worldgen::surface::BiomeId| {
            *shared
                .biomes
                .climate
                .get(id as usize)
                .expect("every biome in the palette has a climate")
        };
        // The rule tree asks at positions the fuzz can move off the exposed
        // block; those inner misses fall back to the id resolved for the block
        // itself, which is the only way this closure is reached at all.
        let top_base_biome = std::cell::Cell::new(rustmc_worldgen::surface::BiomeId::default());
        let top_biome_at = |x: i32, y: i32, z: i32| {
            shared
                .biomes
                .id_at(x, y, z)
                .unwrap_or_else(|| top_base_biome.get())
        };
        let top_cold = |x: i32, y: i32, z: i32| {
            shared.temperature_noises.cold_enough_to_snow(
                top_climate(top_biome_at(x, y, z)),
                x,
                y,
                z,
                shared.sea_level,
            )
        };
        let top_melt = |x: i32, y: i32, z: i32| {
            shared.temperature_noises.height_adjusted_temperature(
                top_climate(top_biome_at(x, y, z)),
                x,
                y,
                z,
                shared.sea_level,
            ) > 0.1
        };
        let top_biome_name =
            |id: rustmc_worldgen::surface::BiomeId| shared.biomes.palette.name(id).to_string();
        let mut top_oracle = WorldSurfaceOracle::with_noises(
            std::sync::Arc::clone(shared.noises),
            ChunkSurfaceState {
                heights: top_heights,
                biome: &top_biome_at,
                biome_name: &top_biome_name,
                min_surface_level: &|_, _| 0,
                temperature: &top_cold,
                melt_iceberg_slightly: &top_melt,
            },
        );
        let top_levels = RefCell::new(SurfaceLevels::new(shared.preliminary.clone()));
        let top_flat = FlatCaches::none();
        let top_asked = std::cell::Cell::new(0u64);
        let top_asked_fluid = std::cell::Cell::new(0u64);
        let top_unresolved = std::cell::Cell::new(0u64);
        let mut top = |x: i32, y: i32, z: i32, under_fluid: bool| {
            top_asked.set(top_asked.get() + 1);
            if under_fluid {
                top_asked_fluid.set(top_asked_fluid.get() + 1);
            }
            let Some(base) = shared.biomes.id_at(x, y, z) else {
                top_unresolved.set(top_unresolved.get() + 1);
                return None;
            };
            top_base_biome.set(base);
            carver_top_material(
                &shared,
                &mut top_oracle,
                &top_levels,
                &top_flat,
                x,
                y,
                z,
                under_fluid,
            )
        };
        let mut target = stage::carver::CanvasTarget::new(
            writer,
            &mut aquifer,
            initial_should_schedule,
            &mut top,
        );
        // The recorded answers, handed back in the order the sweep asks for
        // them. A cursor rather than a map lookup because the *sequence* is
        // what pass 1 preserved; a map keyed on the source chunk would answer
        // the same question the shared list answers differently 545 times.
        let cursor = std::cell::Cell::new(0usize);
        rustmc_worldgen::carver::driver::apply_carvers(
            &mut target,
            &tags,
            &|source_x, source_z| {
                let k = cursor.get();
                cursor.set(k + 1);
                debug_assert_eq!(
                    (source_x - chunk_x, source_z - chunk_z),
                    (
                        (k as i32) / (2 * SWEEP + 1) - SWEEP,
                        (k as i32) % (2 * SWEEP + 1) - SWEEP
                    ),
                    "the sweep asked for a source the replay did not record"
                );
                carver_lists[log[k] as usize].clone()
            },
            seed,
            rustmc_worldgen::carver::carve::CarveBounds {
                min_gen_y: MIN_Y,
                gen_depth: HEIGHT,
                chunk_x,
                chunk_z,
            },
            &mut mask,
        );
        if watch {
            eprintln!(
                "CARVE ({chunk_x},{chunk_z}) aquifer asked {} times, declined {}, answers {:?}",
                asked.get(),
                declined.get(),
                answers.borrow()
            );
        }
        // Counted whether or not anyone is watching, because a zero here is
        // the signature of the dead `hasGrass` arm this stage carried until
        // 2026-08-09 and it must stay falsifiable. Reported per chunk only
        // under the trace; the total is what `RUSTMC_CARVER_TOPMAT` prints.
        top_material_asks.fetch_add(top_asked.get(), std::sync::atomic::Ordering::Relaxed);
        top_material_asks_fluid
            .fetch_add(top_asked_fluid.get(), std::sync::atomic::Ordering::Relaxed);
        top_material_unresolved
            .fetch_add(top_unresolved.get(), std::sync::atomic::Ordering::Relaxed);
    };

    // One unit per fresh chunk: its writer, its retained aquifer state and
    // its slice of the replay log. `chunk_writers` yields chunks in the
    // canvas's `BTreeMap` key order, which is `(x, z)` ascending — the same
    // order `Area::chunks` walks — and `retained` is keyed the same way, so
    // the three line up by construction and the assertion below says so.
    {
        let mut kept_iter = retained.iter_mut().peekable();
        let mut units: Vec<(
            rustmc_worldgen::canvas::ChunkWriter<'_>,
            &mut stage::noise::Retained,
            usize,
        )> = Vec::with_capacity(carve_targets.len());
        let writers: Vec<rustmc_worldgen::canvas::ChunkWriter<'_>> = pipeline
            .canvas_mut()
            .chunk_writers()
            .into_iter()
            .filter(|w| {
                let (cx, cz) = w.position();
                fresh(cx, cz)
            })
            .collect();
        for (i, writer) in writers.into_iter().enumerate() {
            let position = writer.position();
            if carve_targets.get(i) != Some(&position) {
                return Err(format!(
                    "the carver stage's writers and its replay log disagree at {i}: \
                     writer {position:?} against target {:?}",
                    carve_targets.get(i)
                ));
            }
            let kept = loop {
                match kept_iter.next() {
                    Some((key, value)) if *key == position => break value,
                    Some(_) => continue,
                    None => return Err("a generated chunk kept no aquifer".to_string()),
                }
            };
            units.push((writer, kept, i));
        }
        let threads = rustmc_worldgen::pipeline::worker_threads().min(units.len().max(1));
        let queue = std::sync::Mutex::new(units.into_iter());
        type Unit<'a> = (
            rustmc_worldgen::canvas::ChunkWriter<'a>,
            &'a mut stage::noise::Retained,
            usize,
        );
        // One chunk's post-processing marks, keyed by the chunk that made
        // them. Named because it is written three times below — the worker's
        // accumulator, the union, and the sequential arm — and `clippy::
        // type_complexity` is right that three copies of a nested tuple is
        // where a reader stops checking they are the same type.
        type ChunkMarks = ((i32, i32), Vec<(i32, i32, i32)>);
        let run = |queue: &std::sync::Mutex<std::vec::IntoIter<Unit<'_>>>| {
            let mut marks: Vec<ChunkMarks> = Vec::new();
            loop {
                let next = queue.lock().expect("the carver queue lock").next();
                let Some((mut writer, kept, i)) = next else {
                    break;
                };
                let (chunk_x, chunk_z) = writer.position();
                carve_one(
                    &mut writer,
                    kept,
                    chunk_x,
                    chunk_z,
                    &carver_log[i * per_chunk..(i + 1) * per_chunk],
                );
                let made = writer.take_post_processing();
                if !made.is_empty() {
                    marks.push(((chunk_x, chunk_z), made));
                }
            }
            marks
        };
        // A `ChunkWriter` cannot reach the canvas's mark set, so the marks come
        // back per chunk and are unioned here. Sorted by chunk first: the
        // destination is a `BTreeMap<(i32, i32), Vec<..>>` keyed by chunk, so
        // a chunk's own marks keep their within-chunk order however the
        // workers interleaved, and sorting makes the *arrival* order the
        // sequential run's too rather than relying on it not mattering.
        let mut all: Vec<ChunkMarks> = if threads <= 1 {
            run(&queue)
        } else {
            std::thread::scope(|scope| {
                let handles: Vec<_> = (0..threads).map(|_| scope.spawn(|| run(&queue))).collect();
                handles
                    .into_iter()
                    .flat_map(|h| h.join().expect("a carver worker"))
                    .collect()
            })
        };
        all.sort_by_key(|(position, _)| *position);
        let canvas = pipeline.canvas_mut();
        for (_, made) in all {
            for (x, y, z) in made {
                canvas.mark_post_processing(x, y, z);
            }
        }
    }
    let top_material_asks = top_material_asks.load(std::sync::atomic::Ordering::Relaxed);
    let top_material_asks_fluid =
        top_material_asks_fluid.load(std::sync::atomic::Ordering::Relaxed);
    let top_material_unresolved =
        top_material_unresolved.load(std::sync::atomic::Ordering::Relaxed);
    if std::env::var_os("RUSTMC_CARVER_TOPMAT").is_some() {
        // The fluid split is printed beside the total because the flag is the
        // only thing `topMaterial` does with its fourth argument, and a window
        // that never carves into water has not exercised that branch at all.
        eprintln!(
            "CARVE topMaterial asked {top_material_asks} times over the generated area \
             ({top_material_asks_fluid} of them under a fluid, \
             {top_material_unresolved} declined for an unfilled biome container)"
        );
    }

    if std::env::var_os("RUSTMC_CARVER_BIOME").is_some() {
        eprintln!(
            "CARVE biome lookups {} over {} sampled source chunks in {:.2} s, \
             {} moved by the search hint, {} moved by the sample memo{}",
            carver_biome_calls.load(std::sync::atomic::Ordering::Relaxed),
            carver_points.borrow().len(),
            carver_biome_nanos.load(std::sync::atomic::Ordering::Relaxed) as f64 / 1e9,
            carver_biome_hint_moved.load(std::sync::atomic::Ordering::Relaxed),
            carver_point_moved.load(std::sync::atomic::Ordering::Relaxed),
            if verify_carver_biome {
                ""
            } else {
                " (not checked — set RUSTMC_CARVER_BIOME_VERIFY=1)"
            },
        );
    }
    times.mark("carvers");
    if through == Through::Carvers {
        return Ok(Generated {
            canvas: pipeline.into_canvas(),
            area,
            through,
            dimension: Dim::Overworld,
            refused: BTreeMap::new(),
        });
    }

    // Decoration begins: the `_WG` maps become the fossils the placement
    // chains read.
    pipeline.canvas_mut().freeze_wg();

    // The outside-access count *before* decoration, so the decoration pass's
    // own contribution can be read off rather than inferred from a total that
    // includes every stage before it.
    let outside_before_decoration = pipeline.canvas().outside_accesses();

    // ---- decoration ----
    let props = crate::block_props()?;
    let facts = crate::facts::TableFacts(props);
    let survival = crate::facts::Survival {
        tags: crate::block_tags()?,
    };
    let per_step = crate::features_per_step()?;
    let features = crate::biome_features()?;
    let placed = crate::placed_features()?;
    let configured = crate::configured_features()?;
    let info_noise = rustmc_worldgen::biome::temperature::TemperatureNoises::new();

    // `generateFeatures` primes the four live heightmaps on the line before
    // the first feature, for every chunk, and *then* decorates.
    times.mark("dec:tables");
    pipeline.prime_heightmaps(&HeightmapsFrom(&facts));

    // Every refusal, so the caller can report what did not run rather than
    // quietly generating a thinner world.
    // A tally, not a log: every entry is folded into `refused` as a count, so
    // the order entries arrive in is not observable and a `Mutex` shared
    // across the decoration pool is order-independent.
    let unplaceable: std::sync::Mutex<Vec<String>> = std::sync::Mutex::new(Vec::new());
    let mut refused: BTreeMap<String, usize> = BTreeMap::new();
    let decorate_order: Vec<(i32, i32)> = decorate_order_for(pipeline.decorated());
    // `RUSTMC_DECORATE_PREFIX=cx,cz,r` decorates exactly what
    // `-Ddecorate.region=r` decorates: the raster prefix of the (2r+1)^2
    // square around (cx,cz), up to and including the centre.
    //
    // The decorate gate replays into the *oracle's* snapshot of the world, so
    // it proves our features right given that world and never that the
    // pipeline's world is that world. Comparing the two needs the pipeline to
    // stop where the snapshot was taken, and neither `decorate_only` (one
    // chunk) nor a full run (everything) is that point.
    let prefix: Option<std::collections::HashSet<(i32, i32)>> =
        std::env::var("RUSTMC_DECORATE_PREFIX").ok().and_then(|v| {
            let mut parts = v.split(',').map(|p| p.trim().parse::<i32>());
            let (cx, cz, r) = (
                parts.next()?.ok()?,
                parts.next()?.ok()?,
                parts.next()?.ok()?,
            );
            let mut set = std::collections::HashSet::new();
            'outer: for dz in -r..=r {
                for dx in -r..=r {
                    // Exclusive of the centre: the oracle's snapshot is taken
                    // *before* the centre chunk decorates, so a pipeline world
                    // comparable with it must stop there too.
                    if dx == 0 && dz == 0 {
                        break 'outer;
                    }
                    set.insert((cx + dx, cz + dz));
                }
            }
            Some(set)
        });

    // Every generated chunk's biome container, taken once.
    //
    // `Biomes::biome_at` resolves the fuzzed quart cell out of this rather
    // than resampling the climate function, because that is what a server's
    // `BiomeManager` does — see the comment there for the measurement. One
    // snapshot for the whole area rather than a 3x3 per chunk: decoration
    // writes blocks and never biomes, so nothing here goes stale, and the
    // canvas is held mutably by `Decoration` for the whole pass.
    times.mark("dec:heightmaps");
    let biome_cells: BiomeCells = {
        let canvas = pipeline.canvas();
        pipeline
            .generated()
            .chunks()
            .filter_map(|(x, z)| {
                canvas
                    .chunk_biomes(x, z)
                    .map(|(palette, ids)| ((x, z), (palette.to_vec(), ids.to_vec())))
            })
            .collect()
    };
    let canvas_min_y = pipeline.canvas().min_y();
    let canvas_height = pipeline.canvas().height();
    let mut biome_resamples = 0u64;

    // ---- one chunk's decoration, over whatever canvas it is handed ----
    //
    // Lifted out of the loop below so the *same* code runs sequentially over
    // the whole canvas and in parallel over a detached group. There is one
    // body, so "the parallel path does what the sequential path does" is not
    // an argument, it is the same function.
    //
    // It returns its refusals and its biome resamples rather than folding
    // them into the outer tallies: a count merged afterwards is
    // order-independent, a shared counter is not.
    // `find_value_stateless`, **not** `find_value`, and the difference is
    // determinism rather than speed. The hinted search carries a `lastResult`
    // from call to call and resolves exact ties by the sequence of calls
    // before it; decoration now runs on a pool, so that sequence is a
    // function of thread scheduling. Vanilla has the same property — the hint
    // is a `ThreadLocal` and its worldgen runs on a pool too — but this
    // project's claim is that a seed gives one world, so a
    // scheduling-dependent answer is not acceptable here.
    //
    // It is not a behaviour change on the measured square: this path runs
    // **4,188 times** at r=16 (`RUSTMC_STAGE_TIMES` reports it), and the
    // regions are byte-identical to a sequential control either way, so the
    // hint decided none of them. Should a tie ever ride on it, the stateless
    // answer is the one that is the same every run.
    let resample = |qx: i32, qy: i32, qz: i32| {
        biomes
            .lock()
            .expect("the climate list lock")
            .find_value_stateless(sampler.sample(qx, qy, qz))
            .clone()
    };

    // Ruined portals. Laid out here rather than beside the shipwrecks because
    // this is the first point where both the temperature noises and the biome
    // climate table are in scope, and `cold` needs them: it is
    // `setup.canBeCold() && Biome.coldEnoughToSnow(stub, seaLevel)`, and it
    // gates three separate things — which lava rule is used, whether the
    // netherrack-to-magma rule exists at all, and whether
    // `placeNetherrackOrMagma` spends a draw.
    //
    // The heights are the **unclamped** pure noise columns, for the reason
    // [`overworld_first_free_height`] spells out: vanilla lays structure
    // starts out before any neighbour chunk exists, so a height source
    // clamped to this window would make the set of portals a function of the
    // window size.
    times.mark("dec:biomecells");
    let ruined_portals = if through >= Through::Decoration {
        ruined_portal_starts(
            seed,
            area,
            &mut |qx, qy, qz| {
                biomes
                    .lock()
                    .expect("the climate list lock")
                    .find_value(sampler.sample(qx, qy, qz))
                    .clone()
            },
            |x, z, ocean_floor| {
                rustmc_worldgen::stage::noise::base_height(
                    &router,
                    &seeding,
                    settings,
                    x,
                    z,
                    if ocean_floor {
                        rustmc_worldgen::chunk_gen::Wg::OceanFloor
                    } else {
                        rustmc_worldgen::chunk_gen::Wg::WorldSurface
                    },
                )
            },
            |x, z| rustmc_worldgen::stage::noise::base_column(&router, &seeding, settings, x, z),
            &mut |biome: &str, x: i32, y: i32, z: i32| {
                biome_data.get(biome).is_some_and(|entry| {
                    info_noise.cold_enough_to_snow(entry.climate, x, y, z, crate::SEA_LEVEL)
                })
            },
            settings.min_y,
        )?
    } else {
        Vec::new()
    };

    // `Block.defaultBlockState().setValue(..)` for the scattered pieces, which
    // spell every state they place as a block name and the properties they set.
    let scattered_state = |spec: &str| -> String {
        rustmc_worldgen::feature::state_spec::parse_for_block(spec, &default_states)
            .unwrap_or_else(|e| panic!("a scattered piece names a state the extract refuses: {e}"))
    };
    let decorate_chunk = |canvas: &mut rustmc_worldgen::canvas::Canvas,
                          chunk_x: i32,
                          chunk_z: i32|
     -> (BTreeMap<String, usize>, u64) {
        let mut refused_here: BTreeMap<String, usize> = BTreeMap::new();
        canvas.set_home(chunk_x, chunk_z);
        let biomes_present = canvas.biomes_in(chunk_x, chunk_z, 1);
        let mut biome_facts = Biomes {
            zoom,
            resample: &resample,
            data: &biome_data,
            features: &features,
            noises: &info_noise,
            stored: &biome_cells,
            min_y: canvas_min_y,
            height: canvas_height,
            resampled: 0,
        };
        let mut world = rustmc_worldgen::stage::decorate::Decoration::new(
            canvas,
            &facts,
            &survival,
            &mut biome_facts,
            &tags,
            SEA_LEVEL,
            // The overworld generates every block it stores, so genDepth and
            // the canvas height are the same number here. Passed explicitly
            // anyway: the two being equal is a fact about this dimension, not
            // an invariant.
            canvas_height,
            seed,
        )
        // `WorldGenRegion.getRandom()`, taken per generating chunk in
        // `begin_chunk`. The overworld is Xoroshiro — `SurfaceNoises::new`
        // passes `false` for the same boolean a few hundred lines up.
        .with_level_random(seed, false);
        world.begin_chunk(chunk_x, chunk_z);
        // `RUSTMC_DUMP_CHUNK=x,z` prints every decoration attempt in that
        // chunk: the feature, how many positions its chain produced, and
        // where the first one landed. Added while chasing a chunk where all
        // the aquatic features placed nothing while its neighbours were
        // exact — "which features ran and with how many positions" is the
        // question a whole-world diff cannot answer.
        let dump_here = dump_chunk()
            .and_then(|v| {
                let (a, b) = v.split_once(',')?;
                Some((a.trim().parse::<i32>().ok()?, b.trim().parse::<i32>().ok()?))
            })
            .is_some_and(|(x, z)| x == chunk_x && z == chunk_z);

        let outcome = rustmc_worldgen::feature::decorate::run_chunk(
            &mut world,
            &per_step,
            &features,
            &biomes_present,
            &|name| placed.get(name).cloned(),
            seed,
            rustmc_worldgen::feature::decorate::ChunkOrigin {
                chunk_x,
                chunk_z,
                min_section_y: MIN_Y >> 4,
            },
            // Structures. The hook exists and the port behind it is written
            // and gated as far as the *layout*.
            //
            // The index a structure is seeded with is no longer the blocker
            // it was: `structure_step_indices()` derives it from the
            // datapack, in the order `ResourceManagerRegistryLoadTask`
            // imposes, and the mineshaft assertion above pins that
            // derivation to a figure measured out of vanilla's own blocks.
            // What is still missing is the *placement* code for the
            // structures nobody has ported yet — a different and much more
            // honest kind of gap, and one `caveats()` names individually.
            |world: &mut rustmc_worldgen::stage::decorate::Decoration<'_>,
             step: usize,
             population: i64| {
                let index = structure_index;
                // `surface_structures` is step 4 of the eleven, and is where
                // an ocean ruin is written. Handled before the mineshaft's
                // guard because both live behind this one hook.
                if step == 4 {
                    // Within the step, structures run in registry order:
                    // `desert_pyramid` (1) and `jungle_pyramid` (4) before the
                    // ocean ruins (7, 8); `swamp_hut` after the shipwrecks.
                    for (kind, id) in [
                        (
                            Some(rustmc_worldgen::structure::scattered::Kind::DesertPyramid),
                            "minecraft:desert_pyramid",
                        ),
                        (None, "minecraft:igloo"),
                        (
                            Some(rustmc_worldgen::structure::scattered::Kind::JungleTemple),
                            "minecraft:jungle_pyramid",
                        ),
                    ] {
                        // The igloo spends nothing on its stream that a block
                        // reads, but its basement chest's `LootTableSeed` is
                        // two draws on it: `placeInWorld`'s for the template
                        // chest, then the `chest` marker's.
                        let Some(kind) = kind else {
                            place_igloos_in_chunk(
                                world,
                                &igloos,
                                population,
                                i32::try_from(step_index_table.get(id).map_or(0, |s| s.index))
                                    .unwrap_or(0),
                                chunk_x,
                                chunk_z,
                                &facts.0,
                                &scattered_state,
                            );
                            continue;
                        };
                        let index = step_index_table.get(id).map_or(0, |s| s.index);
                        place_scattered_in_chunk(
                            world,
                            &scattered,
                            kind,
                            population,
                            i32::try_from(index).unwrap_or(0),
                            seed,
                            chunk_x,
                            chunk_z,
                            &scattered_state,
                        );
                    }
                    // `mansion` sorts after `jungle_pyramid` and before the
                    // ocean ruins, on its own index.
                    place_mansions_in_chunk(
                        world,
                        &mansions,
                        population,
                        i32::try_from(
                            step_index_table
                                .get("minecraft:mansion")
                                .map_or(0, |s| s.index),
                        )
                        .unwrap_or(0),
                        chunk_x,
                        chunk_z,
                        &facts.0,
                        &scattered_state,
                    );
                    // `monument` sorts after `mansion` and before the ocean
                    // ruins, on its own index.
                    place_monuments_in_chunk(
                        world,
                        &monuments,
                        population,
                        i32::try_from(
                            step_index_table
                                .get("minecraft:monument")
                                .map_or(0, |s| s.index),
                        )
                        .unwrap_or(0),
                        chunk_x,
                        chunk_z,
                        &scattered_state,
                    );
                    // `ocean_ruin_cold` (7) before `ocean_ruin_warm` (8), each on
                    // its own `applyBiomeDecoration` stream — the one a chest
                    // marker's `LootTableSeed` is drawn from.
                    for cold in [true, false] {
                        let id = if cold {
                            "minecraft:ocean_ruin_cold"
                        } else {
                            "minecraft:ocean_ruin_warm"
                        };
                        let mut random = rustmc_worldgen::rng::worldgen_random::WorldgenRandom::new(
                            rustmc_worldgen::rng::xoroshiro::XoroshiroRandomSource::from_seed(0),
                        );
                        random.set_feature_seed(
                            population,
                            i32::try_from(step_index_table.get(id).map_or(0, |s| s.index))
                                .unwrap_or(0),
                            4,
                        );
                        for ruin in ocean_ruins.iter().filter(|r| r.main.cold == cold) {
                            place_ocean_ruin_in_chunk(
                                world,
                                &ruin.main,
                                seed,
                                chunk_x,
                                chunk_z,
                                &mut random,
                            );
                            for satellite in &ruin.satellites {
                                place_ocean_ruin_in_chunk(
                                    world,
                                    satellite,
                                    seed,
                                    chunk_x,
                                    chunk_z,
                                    &mut random,
                                );
                            }
                        }
                    }
                    // `pillager_outpost` (9) after the ruins, before the
                    // portals (10).
                    place_jigsaw_starts(
                        world,
                        &outposts,
                        &village_lists,
                        rustmc_worldgen::structure::pieces::BoundingBox::new(
                            chunk_x * 16,
                            MIN_Y + 1,
                            chunk_z * 16,
                            chunk_x * 16 + 15,
                            MIN_Y + HEIGHT - 1,
                            chunk_z * 16 + 15,
                        ),
                        &unplaceable,
                        population,
                        &step_index_table,
                        4,
                    );
                    // Ruined portals sit between the two: their identifiers
                    // sort after `ocean_ruin_*` (indices 7 and 8) and before
                    // `shipwreck` (17), so `ruined_portal` is index 10 and
                    // `ruined_portal_swamp` 16. The starts are already in
                    // that order.
                    //
                    // Each variant is seeded on **its own** index, which is
                    // why this loop reseeds per portal rather than hoisting
                    // one random: a desert portal and a standard one in the
                    // same chunk would otherwise share a stream vanilla gives
                    // them separately.
                    for portal in &ruined_portals {
                        let index = step_index_table
                            .get(&format!("minecraft:{}", portal.structure))
                            .map_or(10, |s| s.index);
                        let mut random = rustmc_worldgen::rng::worldgen_random::WorldgenRandom::new(
                            rustmc_worldgen::rng::xoroshiro::XoroshiroRandomSource::from_seed(0),
                        );
                        random.set_feature_seed(population, i32::try_from(index).unwrap_or(10), 4);
                        place_ruined_portal_in_chunk(
                            world,
                            portal,
                            &mut random,
                            chunk_x,
                            chunk_z,
                            &facts.0,
                            MIN_Y,
                            HEIGHT,
                        );
                    }
                    // Shipwrecks are `surface_structures` too. Written after
                    // the ruins because `shipwrecks.json` sorts after
                    // `ocean_ruins.json`, which is the order
                    // `possibleStructureSets` yields them in — and the wreck
                    // reads the world's fluid before each write, so which of
                    // the two goes first is observable.
                    // `shipwreck` (17) then `shipwreck_beached` (18), each on
                    // its own `setFeatureSeed` stream; only the beached one
                    // draws from it.
                    for beached in [false, true] {
                        let id = if beached {
                            "minecraft:shipwreck_beached"
                        } else {
                            "minecraft:shipwreck"
                        };
                        let index = step_index_table.get(id).map_or(17, |s| s.index);
                        let mut random = rustmc_worldgen::rng::worldgen_random::WorldgenRandom::new(
                            rustmc_worldgen::rng::xoroshiro::XoroshiroRandomSource::from_seed(0),
                        );
                        random.set_feature_seed(population, i32::try_from(index).unwrap_or(17), 4);
                        for wreck in shipwrecks.iter().filter(|w| w.plan.beached == beached) {
                            place_shipwreck_in_chunk(
                                world,
                                wreck,
                                chunk_x,
                                chunk_z,
                                &facts.0,
                                &mut random,
                            );
                        }
                    }
                    // `stronghold` sorts between `shipwreck_beached` and
                    // `swamp_hut`.
                    {
                        let index = step_index_table
                            .get("minecraft:stronghold")
                            .map_or(0, |s| s.index);
                        let mut random = rustmc_worldgen::rng::worldgen_random::WorldgenRandom::new(
                            rustmc_worldgen::rng::xoroshiro::XoroshiroRandomSource::from_seed(0),
                        );
                        random.set_feature_seed(population, i32::try_from(index).unwrap_or(0), 4);
                        let clip = rustmc_worldgen::structure::pieces::BoundingBox::new(
                            chunk_x * 16,
                            MIN_Y + 1,
                            chunk_z * 16,
                            chunk_x * 16 + 15,
                            MIN_Y + HEIGHT - 1,
                            chunk_z * 16 + 15,
                        );
                        for sh in &strongholds {
                            let mut sh = sh.lock().expect("the stronghold lock");
                            for p in &mut sh.pieces {
                                if !p.piece.bounding_box.intersects(clip) {
                                    continue;
                                }
                                rustmc_worldgen::structure::stronghold::post_process(
                                    world,
                                    p,
                                    clip,
                                    &mut random,
                                    &scattered_state,
                                );
                            }
                        }
                    }
                    let index = step_index_table
                        .get("minecraft:swamp_hut")
                        .map_or(0, |s| s.index);
                    place_scattered_in_chunk(
                        world,
                        &scattered,
                        rustmc_worldgen::structure::scattered::Kind::SwampHut,
                        population,
                        i32::try_from(index).unwrap_or(0),
                        seed,
                        chunk_x,
                        chunk_z,
                        &scattered_state,
                    );
                    // Villages are `surface_structures` too. The clip is
                    // `ChunkGenerator.getWritableArea`, whose low corner is
                    // `getMinY() + 1` — the same off-by-one row the mineshaft
                    // path documents below, and it matters for the same
                    // reason: everything a piece asks the world goes through
                    // this box.
                    let clip = rustmc_worldgen::structure::pieces::BoundingBox::new(
                        chunk_x * 16,
                        MIN_Y + 1,
                        chunk_z * 16,
                        chunk_x * 16 + 15,
                        MIN_Y + HEIGHT - 1,
                        chunk_z * 16 + 15,
                    );
                    place_jigsaw_starts(
                        world,
                        &villages,
                        &village_lists,
                        clip,
                        &unplaceable,
                        population,
                        &step_index_table,
                        4,
                    );
                    return;
                }
                // `underground_decoration` is step 7: the ancient cities.
                if step == 7 {
                    place_jigsaw_starts_with(
                        world,
                        &ancient_cities,
                        &village_lists,
                        rustmc_worldgen::structure::pieces::BoundingBox::new(
                            chunk_x * 16,
                            MIN_Y + 1,
                            chunk_z * 16,
                            chunk_x * 16 + 15,
                            MIN_Y + HEIGHT - 1,
                            chunk_z * 16 + 15,
                        ),
                        &unplaceable,
                        population,
                        &step_index_table,
                        7,
                        Some(FeatureElements {
                            configured: &configured,
                            tags: &survival.tags,
                        }),
                    );
                    return;
                }
                // `underground_structures` is step 3 of the eleven.
                if step != 3 {
                    return;
                }
                // Buried treasure is `underground_structures` too, and it
                // goes FIRST: within one step the structure sets run in the
                // registry's order, which for the data-driven registry is
                // alphabetical by resource id, and `buried_treasures.json`
                // sorts before `mineshafts.json` and `trial_chambers.json`.
                //
                // It takes nothing from the mineshaft's stream and gives it
                // nothing, so the order is observable only where a treasure
                // and a mine overlap — which is exactly why it is stated
                // rather than left to whichever loop happened to be written
                // first.
                for treasure in &buried_treasures {
                    place_buried_treasure_in_chunk(
                        world,
                        treasure,
                        chunk_x,
                        chunk_z,
                        &facts.0,
                        population,
                        i32::try_from(
                            step_index_table
                                .get("minecraft:buried_treasure")
                                .map_or(0, |s| s.index),
                        )
                        .unwrap_or(0),
                    );
                }
                let mut random = rustmc_worldgen::rng::worldgen_random::WorldgenRandom::new(
                    rustmc_worldgen::rng::xoroshiro::XoroshiroRandomSource::from_seed(0),
                );
                random.set_feature_seed(population, index, 3);
                // `ChunkGenerator.getWritableArea` — and the low corner is
                // `getMinY() + 1`, not `getMinY()`. Vanilla's bottom
                // buildable y for a structure is -63; -64 is outside the box
                // it hands `placeInChunk`.
                //
                // The extra row is not cosmetic. Everything a piece asks the
                // world goes through the box: `getBlock` answers **air**
                // outside it, `isInterior` returns false outside it, and
                // `placeBlock` writes nothing outside it. So a clip one row
                // too tall changes what `isSupportingBox`, the rail pass and
                // `fillPillarDownOrChainUp` read at the bottom of the world,
                // and `isInterior` gates a cobweb draw.
                let clip = rustmc_worldgen::structure::pieces::BoundingBox::new(
                    chunk_x * 16,
                    MIN_Y + 1,
                    chunk_z * 16,
                    chunk_x * 16 + 15,
                    MIN_Y + HEIGHT - 1,
                    chunk_z * 16 + 15,
                );
                if rustmc_worldgen::canvas::tracing_writes() {
                    rustmc_worldgen::canvas::set_writer(&format!(
                        "mineshaft into chunk ({chunk_x}, {chunk_z})"
                    ));
                }
                // `RUSTMC_MINESHAFT_ORDER=reverse` walks the starts the
                // other way. Two mineshafts reach one chunk often enough for
                // their relative order to decide the shared random stream,
                // and nothing gates that order against vanilla's.
                // `StructureManager#startsForStructure` walks the chunk's
                // reference set and hands each start to `placeInChunk` in
                // **iteration order**, and they share one random. The set is
                // a fastutil `LongOpenHashSet`, so its order is neither
                // insertion nor sorted — see [`fastutil_long_set`].
                //
                // Membership is by the start's **union** box, which is what
                // `createReferences` intersects, not by any single piece. A
                // start whose union reaches this chunk but whose pieces do
                // not draws nothing, yet it still occupies a slot in the set
                // and so moves everyone else.
                let mut refs = rustmc_worldgen::fastutil_long_set::LongOpenHashSet::new();
                for mine in &mineshafts {
                    if mine.union_box.intersects(clip) {
                        let (sx, sz) = mine.start_chunk;
                        if let Err(e) = refs.add(
                            rustmc_worldgen::fastutil_long_set::chunk_pos_as_long(sx, sz),
                        ) {
                            unplaceable.lock().expect("the refusal lock").push(e);
                        }
                    }
                }
                let ordered: Vec<&Mineshaft> = refs
                    .iter_order()
                    .into_iter()
                    .filter_map(|packed| {
                        mineshafts.iter().find(|m| {
                            rustmc_worldgen::fastutil_long_set::chunk_pos_as_long(
                                m.start_chunk.0,
                                m.start_chunk.1,
                            ) == packed
                        })
                    })
                    .collect();
                // One counter across the whole pass, because one stream runs
                // across the whole pass. `RUSTMC_TRACE_MINESHAFT=1` prints
                // the position each corridor enters its ceiling pass at,
                // which is the same number `worldgen-dump mineshaft-ceiling`
                // recovers from vanilla's blocks — so the two are directly
                // comparable and a disagreement names the piece that spent
                // the wrong number of values.
                let mut counted = DrawCounter {
                    inner: &mut random,
                    draws: 0,
                    // The mineshaft path has no jigsaw pool and so no feature
                    // pool element to refuse; there is nothing for the audit
                    // to relate draws to.
                    tally: None,
                };
                // Which memory the corridor's `hasPlacedSpider` lives in is
                // decided by the decoration model, not by this call site —
                // see [`SpiderMemory`] and `docs/DETERMINISM.md` §33.
                let spider_memory = if spider_is_chunk_local {
                    SpiderMemory::for_chunk()
                } else {
                    SpiderMemory::Pass(&spider_placed)
                };
                for mine in ordered {
                    place_mineshaft_in_chunk(
                        world,
                        mine,
                        match mine.kind {
                            rustmc_worldgen::structure::mineshaft::MineshaftType::Mesa => {
                                &mesa_blocks
                            }
                            _ => &mineshaft_blocks,
                        },
                        clip,
                        chunk_x,
                        chunk_z,
                        &spider_memory,
                        &mut counted,
                    );
                }
                if rustmc_worldgen::canvas::tracing_writes() {
                    rustmc_worldgen::canvas::set_writer("");
                }
                // Trial chambers are `underground_structures` too, and they
                // are written **after** the mineshaft.
                //
                // The order of two structure sets inside one step is the order
                // the registry yields them in, and for this pair it does not
                // matter which of the two readings of that you take: the
                // built-in bootstrap order in `BuiltinStructureSets` has
                // MINESHAFTS eleventh and TRIAL_CHAMBERS twentieth, and the
                // data-driven registry's alphabetical resource order has
                // `mineshafts.json` before `trial_chambers.json`. Both put the
                // mineshaft first, so this is one of the rare ordering
                // decisions that does not rest on which rule applies.
                //
                // A chamber takes nothing from the mineshaft's stream, and the
                // reason is the reseed rather than any property of template
                // placement. **This comment used to say `place_piece` "draws
                // only inside its own processors", and that is false**:
                // `StructureTemplate.placeInWorld` spends one `nextLong` per
                // placed `RandomizableContainer` on the piece's own stream
                // (offsets 476..499, guarded on `instanceof
                // RandomizableContainer` and on `!DEBUG_STRUCTURE_EDIT_MODE`),
                // and a chamber is nothing but containers. What keeps the two
                // apart is that `applyBiomeDecoration` calls
                // `setFeatureSeed(populationSeed, index, step)` once per
                // *structure* — offset 293 in `ChunkGenerator` — so the
                // chamber enters on a freshly seeded stream whatever the
                // mineshaft spent.
                // Trail ruins sort between the mineshafts and the chambers.
                place_jigsaw_starts(
                    world,
                    &trail_ruins,
                    &village_lists,
                    clip,
                    &unplaceable,
                    population,
                    &step_index_table,
                    3,
                );
                place_jigsaw_starts(
                    world,
                    &trial_chambers,
                    &village_lists,
                    clip,
                    &unplaceable,
                    population,
                    &step_index_table,
                    3,
                );
            },
            |world, feature, _name, pos, random| {
                // The actual placement. A configured feature this port cannot
                // place refuses, and the refusal is counted rather than
                // swallowed: its draws are missing and every feature after it
                // in the step lands somewhere else, so a silent skip would be
                // a wrong world reported as a right one.
                let Some(config) = configured.get(&feature.feature) else {
                    return;
                };
                // So `RUSTMC_TRACE_WRITE` can name whoever wrote a block.
                // The *decorating chunk* is part of the answer, not decoration
                // on it: a feature reaches one chunk out, so "which feature"
                // and "run from where" are different questions and the second
                // is usually the one that matters.
                if rustmc_worldgen::canvas::tracing_writes() {
                    rustmc_worldgen::canvas::set_writer(&format!(
                        "{} from chunk ({chunk_x}, {chunk_z})",
                        feature.feature
                    ));
                }
                if let Err(e) = config.place(world, &tags, random, (pos.x, pos.y, pos.z)) {
                    unplaceable.lock().expect("the refusal lock").push(e.0);
                }
                // Clear it again. A label that outlives its feature is worse
                // than no label: the next writer that does not set one — a
                // structure, a stage — inherits it, and the trace then names
                // a feature that had nothing to do with the block. That
                // happened once and cost a wrong attribution.
                if rustmc_worldgen::canvas::tracing_writes() {
                    rustmc_worldgen::canvas::set_writer("");
                }
            },
        );
        if dump_here {
            match &outcome {
                Ok(outcome) => {
                    println!(
                        "CHUNK ({chunk_x}, {chunk_z}) — {} attempts, {} refused",
                        outcome.attempts.len(),
                        outcome.refusals.len()
                    );
                    // Every position, not just the first. "Which features
                    // ran" answers one question; "and at exactly which
                    // positions" answers the next one, and a feature whose
                    // *first* position agrees while a later one does not is
                    // precisely the case a first-only dump cannot see —
                    // which is how a missing disk_sand hid behind a correct
                    // one in the same chunk.
                    //
                    // `RUSTMC_DUMP_FEATURE=<substring>` narrows the list,
                    // because a chunk runs a few hundred features and only
                    // one is ever under suspicion.
                    let only = std::env::var("RUSTMC_DUMP_FEATURE").ok();
                    for a in &outcome.attempts {
                        if let Some(only) = &only {
                            if !a.feature.contains(only.as_str()) {
                                continue;
                            }
                        }
                        let where_ = a
                            .positions
                            .iter()
                            .map(|p| format!("({}, {}, {})", p.x, p.y, p.z))
                            .collect::<Vec<_>>()
                            .join(" ");
                        // `after` is the stream state once the feature has
                        // run, and it is the sharpest single number here:
                        // `DecorateGolden` records the same value, so a
                        // feature whose positions match but whose `after`
                        // does not has spent a different number of draws —
                        // and one whose `after` matches cannot have.
                        println!(
                            "  index {:3}  {:46} {:4} positions  after={:<21} {where_}",
                            a.index,
                            a.feature,
                            a.positions.len(),
                            a.after
                        );
                    }
                }
                Err(e) => println!("CHUNK ({chunk_x}, {chunk_z}) refused: {}", e.0),
            }
        }
        match outcome {
            Ok(o) => {
                for e in o.refusals {
                    *refused_here.entry(e.0).or_insert(0) += 1;
                }
            }
            Err(e) => *refused_here.entry(e.0).or_insert(0) += 1,
        }
        (refused_here, biome_facts.resampled)
    };

    // Which chunks decorate at all, in the order they would decorate in.
    times.mark("dec:portals");
    let targets: Vec<(i32, i32)> = decorate_order
        .iter()
        .copied()
        .filter(|c| prefix.as_ref().is_none_or(|only| only.contains(c)))
        .filter(|c| decorate_only.is_none_or(|only| only == *c))
        // **The generate-once rule.** `ChunkGenerationTask.scheduleChunkInLayer`
        // skips a chunk that has already reached the status, and this is that
        // line. A chunk decorates exactly once in the life of a world, so a
        // chunk whose own 3x3 has decorated can never be written again —
        // `FEATURES` has `blockStateWriteRadius(1)` and nothing in the pyramid
        // writes further. That is the whole of `docs/DETERMINISM.md` §32.6.
        .filter(|c| !settled_decoration.contains(c))
        .collect();

    // **Decoration, isolated per chunk and composed afterwards.**
    //
    // Every chunk here is independent: it decorates against a copy of the
    // carved canvas that no other chunk has written into, so there is no
    // order between any two of them and no barrier to place. The
    // shared-canvas pass this replaces had to group chunks into levels so
    // that a chunk only ran once every *earlier* chunk within
    // `2 * DECORATE_REACH` had finished — see `IsolatedDecoration` for why
    // that is no longer a constraint, and `docs/DETERMINISM.md` §32 for the
    // measurement.
    //
    // The order still decides the world, but it decides it in `compose`
    // rather than here: the write lists are replayed in the decoration
    // order, so two chunks whose features overlap resolve by who wrote
    // last, exactly as the sequential pass resolved them.
    let mut isolation = IsolatedDecoration::new();
    let threads = rustmc_worldgen::pipeline::worker_threads();
    // Any of the tracing instruments forces the sequential path: they print
    // from the writing thread and their order is the answer they give.
    let traced = rustmc_worldgen::canvas::tracing_writes()
        || dump_chunk().is_some()
        || std::env::var_os("RUSTMC_TRACE_FEATURE").is_some()
        || std::env::var_os("RUSTMC_TRACE_ATTEMPT").is_some();
    if threads <= 1 || traced {
        for (rank, (chunk_x, chunk_z)) in targets.iter().copied().enumerate() {
            let (r, n) = isolation.run(&mut pipeline, rank, chunk_x, chunk_z, |canvas| {
                decorate_chunk(canvas, chunk_x, chunk_z)
            });
            for (reason, count) in r {
                *refused.entry(reason).or_insert(0) += count;
            }
            biome_resamples += n;
        }
    } else if !isolation.on {
        // **The shared-canvas parallel pass, unchanged.** Chunks decorating
        // into one canvas *do* have an order between them wherever their
        // footprints overlap, so this keeps the sequential order's answer
        // exactly rather than approximating it: two chunks more than
        // `2 * DECORATE_REACH` apart cannot see or overwrite each other's
        // work, a chunk runs once every *earlier* chunk within that distance
        // has finished, and grouping the ready chunks into levels makes that
        // a barrier per level with disjoint `(2R+1)^2` footprints.
        // `Canvas::merge` panics if two groups ever claim one chunk, so the
        // disjointness is checked rather than asserted.
        //
        // Given that, the result is byte-identical to the sequential run for
        // every decoration order — which is what makes the nine-order sweep
        // (`ci/decorate-order-sweep.sh`) a reproduction rather than a
        // re-measurement: it compares bytes, not parity percentages.
        //
        // The isolated arm below needs none of this. Its chunks are
        // independent by construction, so it has no levels and no barriers —
        // which is a real saving and the one thing that model buys that
        // §32.3 does not charge it for.
        let reach: i32 = std::env::var("RUSTMC_DECORATE_REACH")
            .ok()
            .and_then(|v| v.parse().ok())
            .unwrap_or(rustmc_worldgen::pipeline::DECORATE_REACH);
        let span = 2 * reach;
        let mut level_of: std::collections::HashMap<(i32, i32), usize> =
            std::collections::HashMap::new();
        let mut levels: Vec<Vec<(i32, i32)>> = Vec::new();
        for &(x, z) in &targets {
            let mut level = 0usize;
            for dz in -span..=span {
                for dx in -span..=span {
                    if let Some(&earlier) = level_of.get(&(x + dx, z + dz)) {
                        level = level.max(earlier + 1);
                    }
                }
            }
            level_of.insert((x, z), level);
            if levels.len() <= level {
                levels.resize(level + 1, Vec::new());
            }
            levels[level].push((x, z));
        }
        if std::env::var("RUSTMC_OUTSIDE_READS").is_ok() {
            println!(
                "DECORATION LEVELS {} over {} chunks at reach {reach} (mean {:.1} per level)",
                levels.len(),
                targets.len(),
                targets.len() as f64 / levels.len() as f64
            );
        }
        struct SharedGroup {
            canvas: rustmc_worldgen::canvas::Canvas,
            target: (i32, i32),
            refused: BTreeMap<String, usize>,
            resamples: u64,
        }
        // Where the level pass actually spends its wall time. The stage's
        // mean `cores` column cannot separate the three, and they have
        // opposite fixes: `detach` and `merge` are serial canvas copies on
        // the calling thread, the middle is the only part on the pool, and
        // the number of levels is how many times the pool is drained and
        // refilled.
        let mut detach_secs = 0.0f64;
        let mut work_secs = 0.0f64;
        let mut merge_secs = 0.0f64;
        for level in &levels {
            let clock = std::time::Instant::now();
            let mut slots: Vec<std::sync::Mutex<SharedGroup>> = Vec::with_capacity(level.len());
            for &(x, z) in level {
                let footprint = (-reach..=reach)
                    .flat_map(|dz| (-reach..=reach).map(move |dx| (x + dx, z + dz)))
                    .collect::<Vec<_>>();
                slots.push(std::sync::Mutex::new(SharedGroup {
                    canvas: pipeline.canvas_mut().detach(footprint),
                    target: (x, z),
                    refused: BTreeMap::new(),
                    resamples: 0,
                }));
            }
            detach_secs += clock.elapsed().as_secs_f64();
            let clock = std::time::Instant::now();
            let next = std::sync::atomic::AtomicUsize::new(0);
            std::thread::scope(|scope| {
                for _ in 0..threads.min(slots.len().max(1)) {
                    scope.spawn(|| loop {
                        let i = next.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                        let Some(slot) = slots.get(i) else { break };
                        let mut group = slot.lock().expect("a decoration group");
                        let (x, z) = group.target;
                        let (r, n) = decorate_chunk(&mut group.canvas, x, z);
                        group.refused = r;
                        group.resamples = n;
                    });
                }
            });
            work_secs += clock.elapsed().as_secs_f64();
            let clock = std::time::Instant::now();
            for slot in slots {
                let group = slot.into_inner().expect("a decoration group");
                pipeline.canvas_mut().merge(group.canvas);
                for (reason, count) in group.refused {
                    *refused.entry(reason).or_insert(0) += count;
                }
                biome_resamples += group.resamples;
            }
            merge_secs += clock.elapsed().as_secs_f64();
        }
        if std::env::var_os("RUSTMC_STAGE_CPU").is_some()
            || std::env::var_os("RUSTMC_STAGE_TIMES").is_some()
        {
            let widest = levels.iter().map(Vec::len).max().unwrap_or(0);
            eprintln!(
                "stage dec:levels  {} levels over {} chunks (widest {widest}, mean {:.1}) \
                 detach {detach_secs:.2} s  pool {work_secs:.2} s  merge {merge_secs:.2} s",
                levels.len(),
                targets.len(),
                targets.len() as f64 / levels.len().max(1) as f64,
            );
        }
    } else {
        // One group per chunk, cloned up front rather than inside the
        // worker: `clone_region` reads the pipeline's canvas, and handing
        // the threads a `&Canvas` for the whole pass would be the same read
        // with a lifetime argument attached. Cloning here keeps the
        // pipeline's borrow inside this statement.
        let reach = isolation.reach;
        struct Group {
            canvas: rustmc_worldgen::canvas::Canvas,
            target: (i32, i32),
            rank: usize,
            refused: BTreeMap<String, usize>,
            resamples: u64,
        }
        let mut slots: Vec<std::sync::Mutex<Group>> = Vec::with_capacity(targets.len());
        for (rank, &(x, z)) in targets.iter().enumerate() {
            let mut canvas = pipeline
                .canvas()
                .clone_region(IsolatedDecoration::footprint(reach, x, z));
            canvas.set_home(x, z);
            canvas.record_writes();
            slots.push(std::sync::Mutex::new(Group {
                canvas,
                target: (x, z),
                rank,
                refused: BTreeMap::new(),
                resamples: 0,
            }));
        }
        let next = std::sync::atomic::AtomicUsize::new(0);
        std::thread::scope(|scope| {
            for _ in 0..threads.min(slots.len().max(1)) {
                scope.spawn(|| loop {
                    let i = next.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                    let Some(slot) = slots.get(i) else { break };
                    let mut group = slot.lock().expect("a decoration group");
                    let (x, z) = group.target;
                    let (r, n) = decorate_chunk(&mut group.canvas, x, z);
                    group.refused = r;
                    group.resamples = n;
                });
            }
        });
        for slot in slots {
            let mut group = slot.into_inner().expect("a decoration group");
            let writes = group
                .canvas
                .take_write_log()
                .expect("recording was switched on");
            let records = group.canvas.take_block_entities();
            let entities = group.canvas.take_entities();
            isolation.composed.push((
                group.rank,
                writes,
                group.canvas.take_post_processing(),
                records,
                entities,
            ));
            for (reason, count) in group.refused {
                *refused.entry(reason).or_insert(0) += count;
            }
            biome_resamples += group.resamples;
        }
    }
    isolation.compose(&mut pipeline);

    // Counted rather than silent, the way the harness counts its own: a
    // fuzzed cell outside the generated area is one a server reads from a
    // chunk it has, and resampling is `getUncachedNoiseBiome`'s answer. If
    // this is ever large the generated area is too small for the question.
    if biome_resamples > 0 && std::env::var("RUSTMC_STAGE_TIMES").is_ok() {
        println!("BIOME RESAMPLES (fuzzed cell outside the generated area) {biome_resamples}");
    }
    // Every read or write that named a chunk the canvas did not hold.
    //
    // This is the parallel decoration pass's own gate, and it is reported
    // rather than asserted because the *right* number is not zero: the outer
    // ring of the generated area really does read past the edge, and a
    // sequential run counts those too. What must hold is that the parallel
    // run's total equals the sequential run's — a group too small to hold
    // everything its chunk reaches shows up here as a surplus, and shows up
    // in the blocks only if the void happened to be the wrong answer.
    if std::env::var("RUSTMC_READ_REACH").is_ok() {
        println!(
            "DECORATION READ REACH (max Chebyshev chunk distance from the \
             decorating chunk) {}",
            pipeline.canvas().max_reach()
        );
    }
    if std::env::var("RUSTMC_OUTSIDE_READS").is_ok() {
        println!(
            "OUTSIDE ACCESSES (a read or write naming a chunk the canvas lacks) {} \
             (before decoration {outside_before_decoration}, decoration {})",
            pipeline.canvas().outside_accesses(),
            pipeline.canvas().outside_accesses() - outside_before_decoration
        );
    }

    times.mark("dec:pass");
    // Bubble columns, which vanilla forms during chunk post-processing.
    let generated = pipeline.generated();
    // `ChunkStatusTasks` replays the marked positions after the structures
    // and features are done, which is when a fence finally has neighbours to
    // decide against.
    {
        let outcome = run_post_process(pipeline.canvas_mut(), &tags, &facts.0);
        if std::env::var_os("RUSTMC_POST_PROCESS_STATS").is_some() {
            eprintln!(
                "POST-PROCESS  shapes={} fluid_ticked={} fluid_writes={} \
                 ticked_lava={} merged_face_branch={} lava_conversions={}",
                outcome.shapes,
                outcome.fluid.ticked,
                outcome.fluid.writes,
                outcome.fluid.ticked_lava,
                outcome.fluid.merged_face_branch,
                outcome.fluid.lava_conversions,
            );
        }
    }

    times.mark("dec:postprocess");
    rustmc_worldgen::stage::decorate::form_bubble_columns(pipeline.canvas_mut(), generated);
    times.mark("dec:bubbles");

    // Fold the two refusal channels into one tally.
    for reason in unplaceable.into_inner().expect("the refusal lock") {
        *refused.entry(reason).or_insert(0) += 1;
    }

    times.mark("decoration");
    times.report(generated_chunks);

    Ok(Generated {
        canvas: pipeline.into_canvas(),
        area,
        through,
        dimension: Dim::Overworld,
        refused,
    })
}

/// Adapts [`BlockFacts`] to the canvas's heightmap predicate.
struct HeightmapsFrom<'a>(&'a crate::facts::TableFacts);

impl rustmc_worldgen::canvas::HeightmapPredicates for HeightmapsFrom<'_> {
    fn matches(&self, state: &str, map: rustmc_worldgen::canvas::LiveHeightmap) -> bool {
        rustmc_worldgen::stage::decorate::BlockFacts::matches_heightmap(self.0, state, map)
    }
}

/// One mineshaft: where it starts, and what it is made of.
pub struct Mineshaft {
    /// The chunk the start was generated in. Vanilla identifies a start by
    /// this — `startsForStructure` walks a `LongSet` of exactly these,
    /// packed by `ChunkPos.asLong` — so the order they are visited in is a
    /// function of this value and nothing else.
    pub start_chunk: (i32, i32),
    /// `StructureStart#getBoundingBox` — the union of every piece's box.
    /// This, not any individual piece, is what decides whether a chunk holds
    /// a reference to this start.
    pub union_box: rustmc_worldgen::structure::pieces::BoundingBox,
    pub pieces: Vec<rustmc_worldgen::structure::pieces::Piece>,
    pub kinds: Vec<rustmc_worldgen::structure::mineshaft::Kind>,
    /// Which of the set's two structures won the weighted pick at this chunk.
    ///
    /// `mineshafts.json` holds `mineshaft` and `mineshaft_mesa` at equal
    /// weight, and `ChunkGenerator.createStructures` picks between them with
    /// retry — a refusal removes the entry and rolls again. The two biome tags
    /// are disjoint (51 against 3), so the retry makes the outcome a pure
    /// function of the biome: badlands gets mesa, everything else gets normal.
    /// The draws are isolated in their own `LegacyRandomSource(0)` and cannot
    /// move anything else.
    pub kind: rustmc_worldgen::structure::mineshaft::MineshaftType,
    /// Where the room's children broke through — the room hollows these.
    pub entrances: Vec<rustmc_worldgen::structure::pieces::BoundingBox>,
}

/// Every mineshaft that starts in or near `area`.
///
/// The margin is generous on purpose: a mineshaft reaches up to 80 blocks
/// from its room, so a start five chunks outside the area still writes into
/// it. Missing one shows up as a mine that stops at a chunk border.
pub fn mineshaft_starts<B, S>(
    seed: i64,
    area: Area,
    biome_at: &mut B,
    surface_at: S,
) -> Result<Vec<Mineshaft>, String>
where
    B: FnMut(i32, i32, i32) -> String,
    // `WORLD_SURFACE_WG`, or `None` outside the generated area. A **mesa**
    // mine hangs off the surface rather than the sea level, so it needs this
    // and a normal mine does not — which is why the plain `generate_with_kinds`
    // was enough until the variant was selected for real.
    S: Fn(i32, i32) -> Option<i32> + Copy,
{
    use rustmc_worldgen::structure::placement::StructurePlacement;

    let path = format!("{}/worldgen/structure_set/mineshafts.json", crate::DATA);
    let json: serde_json::Value =
        serde_json::from_str(&std::fs::read_to_string(&path).map_err(|e| format!("{path}: {e}"))?)
            .map_err(|e| format!("{path}: {e}"))?;
    let placement = StructurePlacement::parse(&json["placement"])?;

    // Six chunks of reach. `generateAndAddPiece` refuses a piece more than
    // 80 blocks from the start in x or z, and a corridor is at most 19 long,
    // so ~100 blocks is the true extent and 96 looked marginal.
    //
    // It is not marginal in practice: `RUSTMC_MINESHAFT_REACH` was added to
    // test exactly that, and 6, 8 and 10 all give **the same** blocks on the
    // chunk under investigation. Kept as a probe rather than raised, because
    // raising it costs generation time for no measured gain.
    let reach: i32 = std::env::var("RUSTMC_MINESHAFT_REACH")
        .ok()
        .and_then(|v| v.parse().ok())
        .unwrap_or(6);
    // Resolved once: the tags nest several levels and every placement chunk
    // would otherwise re-read the same files.
    let biomes = MineshaftBiomes::load()?;
    let mut out = Vec::new();
    for cx in (area.min_chunk_x - reach)..=(area.max_chunk_x + reach) {
        for cz in (area.min_chunk_z - reach)..=(area.max_chunk_z + reach) {
            if !placement
                .is_structure_chunk_ignoring_exclusion(seed, cx, cz)
                .map_err(|e| format!("{e:?}"))?
            {
                continue;
            }
            let mut random = rustmc_worldgen::rng::worldgen_random::WorldgenRandom::new(
                rustmc_worldgen::rng::legacy::LegacyRandomSource::new(0),
            );
            random.set_large_feature_seed(seed, cx, cz);
            // Which of the set's two structures wins here. The tags are
            // disjoint, so with pick-with-retry the outcome is decided by the
            // biome alone and the roll only changes which is *tried* first —
            // but the roll is still made, because a future set with
            // overlapping tags would need it and a shortcut here would be a
            // silent behaviour change rather than an omission.
            let kind = chosen_mineshaft_kind(seed, cx, cz, &biomes, biome_at);
            let layout = rustmc_worldgen::structure::mineshaft::generate_with_kinds_using(
                &mut random,
                cx,
                cz,
                kind,
                SEA_LEVEL,
                MIN_Y,
                surface_at,
            )
            .map_err(|e| format!("{e:?}"))?;
            let Some(union_box) = layout.pieces.iter().map(|p| p.bounding_box).reduce(|a, b| {
                rustmc_worldgen::structure::pieces::BoundingBox::new(
                    a.min_x.min(b.min_x),
                    a.min_y.min(b.min_y),
                    a.min_z.min(b.min_z),
                    a.max_x.max(b.max_x),
                    a.max_y.max(b.max_y),
                    a.max_z.max(b.max_z),
                )
            }) else {
                continue;
            };
            out.push(Mineshaft {
                start_chunk: (cx, cz),
                union_box,
                pieces: layout.pieces,
                kinds: layout.kinds,
                entrances: layout.entrances,
                kind,
            });
        }
    }
    Ok(out)
}

/// The two mineshaft variants' biome tags, resolved once.
///
/// Loading these per placement chunk would re-read eight nested tag files a
/// hundred times over for no gain.
pub struct MineshaftBiomes {
    plain: std::collections::BTreeSet<String>,
    mesa: std::collections::BTreeSet<String>,
}

impl MineshaftBiomes {
    /// Resolve both tags.
    ///
    /// # Errors
    /// If a tag file is missing or malformed.
    pub fn load() -> Result<Self, String> {
        Ok(Self {
            plain: crate::facts::resolve_biome_tag("has_structure/mineshaft")?,
            mesa: crate::facts::resolve_biome_tag("has_structure/mineshaft_mesa")?,
        })
    }
}

/// Which mineshaft variant vanilla would build at this chunk.
///
/// `ChunkGenerator.createStructures` rolls `nextInt(total)` over the set's
/// entries, tries the winner, and on refusal removes it and rolls again over
/// the reduced total — `weighted_attempt_order` reproduces that sequence. A
/// structure refuses when the biome at its generation stub is outside its own
/// tag, which `Structure.isValidBiome` samples once, in quart coordinates.
///
/// For mineshafts the two tags are disjoint (51 biomes against 3), so the
/// retry makes the *outcome* a function of the biome alone. The roll is still
/// performed rather than short-circuited: it decides which is attempted first,
/// and a set with overlapping tags would depend on it.
///
/// # Errors
/// If the biome tags cannot be resolved.
fn chosen_mineshaft_kind<B: FnMut(i32, i32, i32) -> String>(
    seed: i64,
    chunk_x: i32,
    chunk_z: i32,
    biomes: &MineshaftBiomes,
    biome_at: &mut B,
) -> rustmc_worldgen::structure::mineshaft::MineshaftType {
    use rustmc_worldgen::structure::mineshaft::MineshaftType;
    use rustmc_worldgen::structure::processor::weighted_attempt_order;

    // `mineshafts.json`: two entries, weight 1 each, in file order —
    // mineshaft then mineshaft_mesa.
    let order = weighted_attempt_order(seed, chunk_x, chunk_z, &[1, 1]);

    // `Structure.isValidBiome` samples once, at the stub position, in quart
    // coordinates. A mineshaft's stub comes from
    // `BlockPos(chunkPos.getMiddleBlockX(), 50, chunkPos.getMinBlockZ())`.
    let (bx, by, bz) = (chunk_x * 16 + 8, 50, chunk_z * 16);
    let biome = biome_at(bx >> 2, by >> 2, bz >> 2);

    for entry in order {
        let (kind, tag) = match entry {
            0 => (MineshaftType::Normal, &biomes.plain),
            _ => (MineshaftType::Mesa, &biomes.mesa),
        };
        if tag.contains(&biome) {
            return kind;
        }
    }
    // Every entry refused. Vanilla generates no mineshaft here at all; this
    // port has no way to express that yet, so it keeps the old behaviour and
    // the divergence is named in `caveats()` rather than hidden by a guess.
    MineshaftType::Normal
}

/// A `RandomSource` that counts what it hands out.
///
/// The whole mineshaft question is "how many values did this corridor enter
/// on", and the port could not answer it about itself. Vanilla's answer is
/// recoverable from a saved region — `worldgen-dump mineshaft-ceiling` reads
/// a corridor's ceiling row back as a thresholded run of `nextFloat`s — so
/// having ours in the same units turns a guess into a subtraction.
///
/// A wrapper rather than a field on the sources: the generator is the P1
/// performance target and a counter in `next_i32` would be paid per noise
/// sample, forever, for a diagnostic.
/// Where a start's piece stream went wrong, counted rather than described.
///
/// `docs/DETERMINISM.md` §44.7 reserves the villages from the affordability
/// verdict on a mechanism: a refused `feature_pool_element` leaves every LATER
/// container in that stream reading a position vanilla has already moved past,
/// so its `LootTableSeed` is wrong rather than merely absent. §44.9 counts the
/// refusals (six on seed 20260722) and the draws (three) but never relates
/// them, and the two orderings have opposite consequences:
///
/// * every draw BEFORE the first refusal is on the vanilla position and is
///   as correct as a trial chamber's;
/// * every draw AFTER it is on a desynced position and is silently wrong —
///   wrong in a payload, which no block-state instrument in this repo can see.
///
/// So the audit records the running draw count at the moment of the first
/// refusal in a stream. Downstream draws are `total - first_refusal_at`.
/// This changes no draw and is only assembled under `RUSTMC_JIGSAW_TRACE=1`.
struct StreamAudit<'a> {
    tally: &'a std::cell::Cell<u64>,
    refusals: u64,
    first_refusal_at: Option<u64>,
}

impl StreamAudit<'_> {
    fn note_refusal(&mut self) {
        self.refusals += 1;
        if self.first_refusal_at.is_none() {
            self.first_refusal_at = Some(self.tally.get());
        }
    }
    /// Draws spent on a stream vanilla has already moved past.
    fn downstream_draws(&self) -> u64 {
        match self.first_refusal_at {
            Some(at) => self.tally.get().saturating_sub(at),
            None => 0,
        }
    }
}

struct DrawCounter<'a, R: rustmc_worldgen::rng::RandomSource + ?Sized> {
    inner: &'a mut R,
    draws: u64,
    /// The same count, shared, so `place_village_in_chunk` can read it at the
    /// instant a feature pool element is refused — while this counter is
    /// mutably borrowed by the placer and `draws` is therefore unreachable.
    ///
    /// A `Cell` and not an atomic: it never leaves the stack frame of one
    /// `place_jigsaw_starts` call, which owns one chunk.
    tally: Option<&'a std::cell::Cell<u64>>,
}

impl<R: rustmc_worldgen::rng::RandomSource + ?Sized> rustmc_worldgen::rng::RandomSource
    for DrawCounter<'_, R>
{
    fn set_seed(&mut self, seed: i64) {
        self.inner.set_seed(seed);
    }
    fn next_i32(&mut self) -> i32 {
        self.draws += 1;
        if let Some(t) = self.tally {
            t.set(t.get() + 1);
        }
        self.inner.next_i32()
    }
    fn next_i32_bound(&mut self, bound: i32) -> i32 {
        self.draws += 1;
        if let Some(t) = self.tally {
            t.set(t.get() + 1);
        }
        self.inner.next_i32_bound(bound)
    }
    fn next_i64(&mut self) -> i64 {
        self.draws += 1;
        if let Some(t) = self.tally {
            t.set(t.get() + 1);
        }
        self.inner.next_i64()
    }
    fn next_bool(&mut self) -> bool {
        self.draws += 1;
        if let Some(t) = self.tally {
            t.set(t.get() + 1);
        }
        self.inner.next_bool()
    }
    fn next_f32(&mut self) -> f32 {
        self.draws += 1;
        if let Some(t) = self.tally {
            t.set(t.get() + 1);
        }
        self.inner.next_f32()
    }
    fn next_f64(&mut self) -> f64 {
        self.draws += 1;
        if let Some(t) = self.tally {
            t.set(t.get() + 1);
        }
        self.inner.next_f64()
    }
    fn next_gaussian(&mut self) -> f64 {
        self.draws += 1;
        if let Some(t) = self.tally {
            t.set(t.get() + 1);
        }
        self.inner.next_gaussian()
    }
}

/// One corridor piece, identified the way the pass identifies it:
/// the start's chunk and the piece's index in that start's list.
type SpiderKey = (i32, i32, usize);

/// Who remembers `MineShaftCorridor.hasPlacedSpider`, and for how long.
///
/// The flag is a **field on the piece** in vanilla — saved as `hps` in the
/// piece NBT, which is what settles that it is meant to persist rather than
/// being an accident of object reuse — and one corridor is post-processed
/// once per chunk it overlaps. So under any model where a chunk decorates
/// into a world the other chunks have written into, the flag has to carry
/// between those chunks: `spider && !placed_spider` gates a `nextInt(3)`,
/// and a redraw lands every later value in that chunk's mineshaft pass one
/// place late.
///
/// **Under `RUSTMC_DECORATE_ISOLATED=1` it must not carry, and that is the
/// model rather than a workaround.** That arm's whole claim is that a
/// chunk's feature writes are a pure function of the seed and the chunk's
/// position; a flag another chunk set is another chunk's write reaching this
/// one by a different name, and it is the *only* such reach left in the
/// pass. It was also a live data race: the isolated driver is a flat work
/// queue with no levels and no barriers, so two chunks sharing a corridor
/// run at the same time, both read the flag before either writes it, and
/// both spend the draw. One binary, one seed, one window, nine runs:
/// **three different worlds** — `docs/DETERMINISM.md` §33.
///
/// [`Self::Chunk`] needs no lock because the isolated pass builds one per
/// chunk inside the worker that owns it, and [`Self::Pass`] keeps the
/// `Mutex` the shared-canvas arms have always had.
enum SpiderMemory<'a> {
    /// One memory for the whole decoration pass — the shared-canvas models.
    Pass(&'a std::sync::Mutex<std::collections::BTreeSet<SpiderKey>>),
    /// One memory per decorating chunk — the isolated model.
    Chunk(std::cell::RefCell<std::collections::BTreeSet<SpiderKey>>),
}

impl SpiderMemory<'_> {
    /// A memory for one chunk, remembering nothing any other chunk did.
    fn for_chunk() -> Self {
        Self::Chunk(std::cell::RefCell::new(std::collections::BTreeSet::new()))
    }

    fn contains(&self, key: SpiderKey) -> bool {
        match self {
            Self::Pass(shared) => shared
                .lock()
                .expect("the spider-corridor lock")
                .contains(&key),
            Self::Chunk(own) => own.borrow().contains(&key),
        }
    }

    fn insert(&self, key: SpiderKey) {
        match self {
            Self::Pass(shared) => {
                shared.lock().expect("the spider-corridor lock").insert(key);
            }
            Self::Chunk(own) => {
                own.borrow_mut().insert(key);
            }
        }
    }
}

/// `StructureStart.placeInChunk` — every piece whose box meets this chunk.
#[allow(
    clippy::too_many_arguments,
    reason = "\
    vanilla's own inputs to this step: the world, the start, its block
    palette, the clip box, which chunk is being decorated, the cross-chunk
    spider set, and the shared random. Bundling them into a struct would
    move the list rather than shorten it, and it would hide that the clip
    box and the chunk are *different* things — a distinction this file has
    already been caught by once."
)]
fn place_mineshaft_in_chunk<R: rustmc_worldgen::rng::RandomSource + ?Sized>(
    world: &mut rustmc_worldgen::stage::decorate::Decoration<'_>,
    mine: &Mineshaft,
    blocks: &rustmc_worldgen::structure::mineshaft::MineshaftBlocks,
    clip: rustmc_worldgen::structure::pieces::BoundingBox,
    chunk_x: i32,
    chunk_z: i32,
    spider_placed: &SpiderMemory<'_>,
    random: &mut DrawCounter<'_, R>,
) {
    use rustmc_worldgen::structure::mineshaft::{
        post_process_corridor, post_process_crossing, post_process_room, post_process_stairs, Kind,
    };
    // How many *distinct mineshafts* reach one chunk decides whether their
    // relative order can matter at all. Vanilla walks the chunk's references
    // (a LongSet) via `startsForStructure`; we walk a Vec built by scanning
    // chunk coordinates, and nothing gates the two against each other.
    if trace_mineshaft() && mine.pieces.iter().any(|p| p.bounding_box.intersects(clip)) {
        let bb = mine.pieces[0].bounding_box;
        println!(
            "MINESHAFT start at {},{},{} reaches chunk clip {}..{} x {}..{}",
            bb.min_x, bb.min_y, bb.min_z, clip.min_x, clip.max_x, clip.min_z, clip.max_z
        );
    }
    for (index, (piece, kind)) in mine.pieces.iter().zip(&mine.kinds).enumerate() {
        if !piece.bounding_box.intersects(clip) {
            continue;
        }
        match *kind {
            Kind::Corridor { .. } => {
                if trace_mineshaft() {
                    let bb = piece.bounding_box;
                    println!(
                        "MINESHAFT chunk ({chunk_x}, {chunk_z}) corridor start \
                         ({}, {}) box {},{},{}..{},{},{} enters at draw {}",
                        mine.start_chunk.0,
                        mine.start_chunk.1,
                        bb.min_x,
                        bb.min_y,
                        bb.min_z,
                        bb.max_x,
                        bb.max_y,
                        bb.max_z,
                        random.draws,
                    );
                }
                // `hasPlacedSpider` is a field on the piece, and the same
                // piece object is post-processed once per chunk it overlaps.
                // Vanilla even saves it (`hps`). Keeping it in a call-local
                // would redraw the spawner's `nextInt(3)` in every chunk a
                // spider corridor reaches.
                let key = (mine.start_chunk.0, mine.start_chunk.1, index);
                let mut placed = spider_placed.contains(key);
                post_process_corridor(world, piece, *kind, blocks, clip, random, &mut placed);
                if placed {
                    spider_placed.insert(key);
                }
            }
            Kind::Crossing { two_floored } => {
                post_process_crossing(world, piece, two_floored, blocks, clip);
            }
            Kind::Stairs => post_process_stairs(world, piece, blocks, clip),
            Kind::Room => post_process_room(world, piece, &mine.entrances, blocks, clip),
        }
    }
}

/// One chunk's stored biome container: its palette, and a cell id per
/// 4x4x4 cell, y-major then z then x — `Canvas::chunk_biomes`'s own shape.
type BiomeCells = BTreeMap<(i32, i32), BiomeContainer>;

/// The biome and climate answers, over the loaded tables.
struct Biomes<'a> {
    zoom: i64,
    /// `getUncachedNoiseBiome` — what to answer when a fuzzed lookup lands
    /// outside the snapshot.
    ///
    /// A closure rather than the climate list and sampler it used to be two
    /// fields of, because the End has neither: its biome source is a
    /// four-branch classifier over one density function, not a search over a
    /// `ParameterList`. Two dimensions supply the stateless climate search
    /// here and the third supplies `biome::end::biome_at_quart`.
    resample: &'a (dyn Fn(i32, i32, i32) -> String + 'a),
    data: &'a BTreeMap<String, BiomeEntry>,
    features: &'a BTreeMap<String, Vec<Vec<String>>>,
    noises: &'a rustmc_worldgen::biome::temperature::TemperatureNoises,
    /// Every generated chunk's stored biome container, snapshotted before
    /// decoration starts. See [`Biomes::biome_at`] for why a resample is the
    /// wrong answer and this is the right one; snapshotted because decoration
    /// holds the canvas mutably while it reads biomes from it, and taken once
    /// for the whole area rather than per chunk because features write blocks
    /// and never biomes.
    stored: &'a BiomeCells,
    /// The canvas's `min_y`, to turn a world y into a container cell.
    min_y: i32,
    /// The canvas's height in blocks, for the same clamp
    /// `ChunkAccess.getNoiseBiome` applies.
    height: i32,
    /// Fuzzed lookups that fell outside the snapshot and were resampled. A
    /// server reads those from a chunk it has and this harness does not, so
    /// the resample is `getUncachedNoiseBiome`'s case — but if it is ever
    /// large, the generated area is too small.
    resampled: u64,
}

impl Biomes<'_> {
    /// `ChunkAccess.getNoiseBiome(qx, qy, qz)` over the snapshot: clamp qy
    /// into the chunk, then read the cell at `(qx & 3, qy & 3, qz & 3)`.
    ///
    /// `None` for a chunk the snapshot does not hold, which is the
    /// `getUncachedNoiseBiome` fallback.
    fn stored_at(&self, qx: i32, qy: i32, qz: i32) -> Option<&str> {
        let (palette, ids) = self.stored.get(&(qx >> 2, qz >> 2))?;
        let lo = self.min_y >> 2;
        let hi = lo + (self.height >> 2) - 1;
        let qy = qy.clamp(lo, hi);
        let cell_y = qy - lo;
        let index = usize::try_from(cell_y * 16 + (qz & 3) * 4 + (qx & 3)).ok()?;
        let id = *ids.get(index)?;
        palette.get(id as usize).map(String::as_str)
    }
}

impl rustmc_worldgen::stage::decorate::BiomeFacts for Biomes<'_> {
    fn biome_at(&mut self, x: i32, y: i32, z: i32) -> String {
        // Through the biome manager's fuzz, as `WorldGenLevel.getBiome` does —
        // and then out of the **stored container**, as a server does.
        //
        // `LevelReader.getBiome(pos)` is `getBiomeManager().getBiome(pos)`;
        // `WorldGenRegion` constructs that manager with *itself* as the
        // `NoiseBiomeSource`, so the fuzzed cell is resolved by
        // `LevelReader.getNoiseBiome` -> `ChunkAccess.getNoiseBiome` -> the
        // container `fillBiomesFromNoise` filled from
        // `noiseChunk.cachedClimateSampler(router, spawnTarget)`. Sampling the
        // climate function again at the same cell is a **different
        // computation** and disagrees at some of them.
        //
        // This resampled until 2026-07-28, and the surface stage's own
        // `biome_at` — thirty lines up, with the same comment — did not. The
        // divergence is measured, not argued: with `DecorateGolden` rewired to
        // a server's path, `golden_biome_lookup` against
        // `decorate_vectors.json` reported **11 wrong of 2755**, every one of
        // them `want beach, got river`, around (1285,·,2457) at seed 20260725.
        //
        // It is worth more than eleven answers because `BiomeFilter` is the
        // last modifier on every vegetal chain: a lookup wrong 0.4% of the
        // time accepts and rejects the wrong candidates.
        let (qx, qy, qz) = rustmc_worldgen::biome::manager::quart_for_block(self.zoom, x, y, z);
        if let Some(stored) = self.stored_at(qx, qy, qz) {
            return stored.to_string();
        }
        self.resampled += 1;
        // Each dimension's `resample` closure carries the reasoning for what
        // it answers; for the two climate dimensions that is
        // `find_value_stateless` rather than the hinted search, and the note
        // is at the closure.
        (self.resample)(qx, qy, qz)
    }

    fn biome_lists(&mut self, biome: &str, feature: &str) -> bool {
        self.features
            .get(biome)
            .is_some_and(|steps| steps.iter().any(|step| step.iter().any(|f| f == feature)))
    }

    fn info_noise(&mut self, x: f64, z: f64) -> f64 {
        // `Biome.BIOME_INFO_NOISE.getValue(x, z, false)` — the third
        // argument is `useNoiseStart` and vanilla passes false here.
        self.noises.biome_info_noise().get_value(x, z, false)
    }

    fn cold_enough_to_snow(&mut self, biome: &str, x: i32, y: i32, z: i32) -> bool {
        self.data.get(biome).is_some_and(|entry| {
            self.noises
                .cold_enough_to_snow(entry.climate, x, y, z, SEA_LEVEL)
        })
    }

    fn precipitation_is_snow(&mut self, biome: &str, x: i32, y: i32, z: i32) -> bool {
        // `getPrecipitationAt(pos, seaLevel) == SNOW` is
        // `hasPrecipitation() && coldEnoughToSnow(...)`. The datapack's
        // `has_precipitation` is not carried in `BiomeClimate` yet, so this
        // is the cold half only — which over-reports snow in dry cold biomes
        // and is named in `caveats` rather than left to be discovered.
        self.data.get(biome).is_some_and(|entry| {
            self.noises
                .cold_enough_to_snow(entry.climate, x, y, z, SEA_LEVEL)
        })
    }
}

/// Every biome's carver list, resolved once.
#[must_use]
pub fn carvers_by_biome(
    biome_data: &BTreeMap<String, BiomeEntry>,
) -> BTreeMap<String, Vec<String>> {
    biome_data
        .iter()
        .map(|(name, entry)| (name.clone(), entry.carvers.clone()))
        .collect()
}

/// Write one fossil's bones into a chunk.
///
/// `TemplateStructurePiece.postProcess` with `makeSettings`'s settings:
/// the drawn rotation, `Mirror.NONE`, **no pivot**, and
/// `BlockIgnoreProcessor.STRUCTURE_AND_AIR`.
///
/// No height adjustment. Unlike the shipwreck — whose constructor y never
/// survives its own `postProcess` walk — a fossil's position is final the
/// moment `findGenerationPoint` returns it, so the piece is placed exactly
/// where the start says. That is why `worldgen-dump nether-fossil-starts`
/// can be diffed against vanilla's saved `TP` at all.
fn place_nether_fossil_in_chunk(
    world: &mut rustmc_worldgen::stage::decorate::Decoration<'_>,
    fossil: &NetherFossil,
    chunk_x: i32,
    chunk_z: i32,
    props: &rustmc_behavior::block_props::BlockPropsTable,
    world_seed: i64,
) {
    use rustmc_worldgen::structure::place::{place_piece, PieceWorld, PlaceSettings};
    use rustmc_worldgen::structure::writer::StructureWorld;

    // `StructureStart.placeInChunk` tests the piece's box against the chunk
    // before it calls `postProcess` — offsets 105 and 124 — so a chunk the
    // fossil does not reach never touches it.
    let clip = rustmc_worldgen::structure::pieces::BoundingBox::new(
        chunk_x * 16,
        NETHER_MIN_Y,
        chunk_z * 16,
        chunk_x * 16 + 15,
        NETHER_MIN_Y + NETHER_STORAGE_HEIGHT - 1,
        chunk_z * 16 + 15,
    );
    if !fossil.bbox.intersects(clip) {
        return;
    }
    // `NetherFossilPiece.postProcess` opens with
    // `chunkBB.encapsulate(template.getBoundingBox(settings, pos))` — it
    // WIDENS the box it was handed to the whole fossil before placing the
    // template, so the first chunk that reaches a fossil writes all of it
    // (as far as the region's own write radius lets it), not just its slice.
    // Which chunk decorates first then decides what a neighbour's features
    // find there, so the clip is not a detail.
    let Some(clip) =
        rustmc_worldgen::structure::pieces::BoundingBox::encapsulating(&[clip, fossil.bbox])
    else {
        return;
    };

    struct Piece<'w, 'a, 'p> {
        world: &'w mut rustmc_worldgen::stage::decorate::Decoration<'a>,
        props: &'p rustmc_behavior::block_props::BlockPropsTable,
    }
    // `Decoration` already implements the recorder; this view exists only to
    // narrow what a piece may touch, so it forwards rather than deciding.
    impl rustmc_worldgen::block_entity::BlockEntityRecorder for Piece<'_, '_, '_> {
        fn record_block_entity(
            &mut self,
            x: i32,
            y: i32,
            z: i32,
            record: rustmc_worldgen::block_entity::Record,
        ) {
            self.world.record_block_entity(x, y, z, record);
        }
    }
    impl PieceWorld for Piece<'_, '_, '_> {
        fn block_at(&mut self, x: i32, y: i32, z: i32) -> String {
            self.world.block_at(x, y, z)
        }
        fn set_block(&mut self, x: i32, y: i32, z: i32, state: &str) {
            self.world.set_block(x, y, z, state);
        }
        fn world_surface_wg(&mut self, x: i32, z: i32) -> i32 {
            self.world.world_surface_wg(x, z)
        }
        fn block_in_tag(&self, tag: &str, block: &str) -> bool {
            self.world.block_tags().contains(tag, block)
        }
        // `BlockStateParser.parseForBlock` needs the block's default state.
        // Without it the jigsaw replacement writes `final_state` verbatim and
        // loses every property the string does not name.
        fn default_state(&self, block: &str) -> Option<String> {
            self.world.default_state(block)
        }
        fn face_is_sturdy(&self, state: &str, direction: usize) -> Option<bool> {
            self.props
                .get(state)
                .and_then(|p| p.sturdy_faces.get(direction).copied())
        }
    }

    if rustmc_worldgen::canvas::tracing_writes() {
        rustmc_worldgen::canvas::set_writer(&format!(
            "nether fossil into chunk ({chunk_x}, {chunk_z})"
        ));
    }
    let mut view = Piece { world, props };
    place_piece(
        &mut view,
        &fossil.template,
        // `nether_fossil.json` declares no processor list at all, so there is
        // no rule here to read a reference position.
        rustmc_worldgen::structure::place::PieceOrigin::unthreaded(fossil.start.pos),
        // No `with_pivot`: `makeSettings` never calls `setRotationPivot`, so
        // the pivot is `BlockPos.ZERO`. No `with_waterlogging`: the nether
        // has no water, and adding it would be a rule this port cannot
        // measure here.
        PlaceSettings::new(fossil.start.rotation).with_shape_update(),
        &[rustmc_worldgen::structure::place::structure_and_air()],
        clip,
        // No piece stream threaded down here yet — see `place_piece`'s note
        // on the `LootTableSeed` draw. Nothing in this structure reads the
        // stream after the placement, so the omission is invisible today.
        None,
    );
    place_dried_ghast(view.world, fossil.bbox, clip, world_seed);
    if rustmc_worldgen::canvas::tracing_writes() {
        rustmc_worldgen::canvas::set_writer("");
    }
}

/// `NetherFossilPiece.placeDriedGhast`, which `postProcess` calls after the
/// template — new in 26.x, and never ported until 2026-10-02.
///
/// Its random is its own, a function of the world seed and the fossil alone:
///
/// ```text
///   r = RandomSource.createThreadLocalInstance(level.getSeed())   // legacy LCG
///         .forkPositional()                                       // one nextLong
///         .at(templateBox.getCenter())
///   if r.nextFloat() < 0.5:
///       pos = (box.minX + r.nextInt(box.xSpan), box.minY, box.minZ + r.nextInt(box.zSpan))
///       if level.getBlockState(pos).isAir() && chunkBox.isInside(pos):
///           setBlock(pos, DRIED_GHAST.defaultBlockState().rotate(Rotation.getRandom(r)), 2)
/// ```
///
/// `chunkBox` is the box `postProcess` already widened to the whole fossil,
/// so the test passes for any chunk that reaches it; the `isAir` test is what
/// keeps a second chunk from placing it twice.
fn place_dried_ghast(
    world: &mut rustmc_worldgen::stage::decorate::Decoration<'_>,
    template_box: rustmc_worldgen::structure::pieces::BoundingBox,
    chunk_box: rustmc_worldgen::structure::pieces::BoundingBox,
    world_seed: i64,
) {
    use rustmc_worldgen::rng::legacy::LegacyRandomSource;
    use rustmc_worldgen::rng::{PositionalRandomFactory, RandomSource};
    use rustmc_worldgen::structure::writer::StructureWorld;

    let (cx, cy, cz) = template_box.center();
    let mut r = LegacyRandomSource::new(world_seed)
        .fork_positional()
        .at(cx, cy, cz);
    if r.next_f32() >= 0.5 {
        return;
    }
    let x = template_box.min_x + r.next_i32_bound(template_box.max_x - template_box.min_x + 1);
    let y = template_box.min_y;
    let z = template_box.min_z + r.next_i32_bound(template_box.max_z - template_box.min_z + 1);
    let inside = (chunk_box.min_x..=chunk_box.max_x).contains(&x)
        && (chunk_box.min_y..=chunk_box.max_y).contains(&y)
        && (chunk_box.min_z..=chunk_box.max_z).contains(&z);
    if !rustmc_worldgen::structure::writer::is_air(&world.block_at(x, y, z)) || !inside {
        return;
    }
    // `Rotation.getRandom` is `values()[nextInt(4)]` — NONE, CLOCKWISE_90,
    // CLOCKWISE_180, COUNTERCLOCKWISE_90 — applied to the default `north`.
    let facing = match r.next_i32_bound(4) {
        0 => "north",
        1 => "east",
        2 => "south",
        _ => "west",
    };
    world.set_block(
        x,
        y,
        z,
        &format!("minecraft:dried_ghast[facing={facing},hydration=0,waterlogged=false]"),
    );
}

/// One nether fossil, placed but not yet written.
#[derive(Clone, Debug)]
pub struct NetherFossil {
    pub start_chunk: (i32, i32),
    pub start: rustmc_worldgen::structure::nether_fossil::FossilStart,
    /// `Structure.terrainAdaptation`, read from
    /// `worldgen/structure/nether_fossil.json` rather than assumed. It is
    /// `beard_thin`, and that is the whole reason this structure was the one
    /// to port first — but a datapack is data, and the beard's behaviour
    /// changes completely between the five values.
    pub terrain_adaptation: rustmc_worldgen::structure::template_pool::TerrainAdaptation,
    /// The loaded template, shared rather than reloaded per chunk: a fossil
    /// spans at most a few chunks and each of them places the same bones.
    pub template: std::sync::Arc<rustmc_worldgen::structure::template::Template>,
    /// `TemplateStructurePiece`'s box — `template.getBoundingBox(settings,
    /// pos)` with the piece's rotation and no pivot, which is what vanilla
    /// saves as `BB` in the chunk's `Children[]`.
    pub bbox: rustmc_worldgen::structure::pieces::BoundingBox,
}

/// Every `nether_fossil` start whose piece can reach `area`.
///
/// # Its placement is degenerate, and vanilla's own output says so
///
/// `nether_fossils.json` is `random_spread` with `spacing 2, separation 1`,
/// so `getPotentialStructureChunk`'s offset range is `spacing - separation`
/// = **1**, and `nextInt(1)` is 0 for every seed. Every chunk with an even x
/// and an even z is a placement chunk, and no other chunk ever is. That is
/// not an inference to trust on its own — it is confirmed by the reference,
/// where all thirty saved starts sit on even/even chunks.
///
/// The draw is still made rather than skipped, because `is_placement_chunk`
/// is shared with every other structure set and this one is not special to
/// it.
///
/// # Order of the three tests
///
/// Placement, then `findGenerationPoint`, then the biome. The biome comes
/// **last** because vanilla's `findValidGenerationPoint` runs it against the
/// position `findGenerationPoint` returns — folding it in earlier would skip
/// chunks whose draws vanilla makes, and while each chunk here has its own
/// freshly seeded stream, the position it tests would be a different one.
pub fn nether_fossil_starts<B, C>(
    seed: i64,
    area: Area,
    biome_at: &mut B,
    column_at: C,
    min_y: i32,
    height: i32,
    sea_level: i32,
) -> Result<Vec<NetherFossil>, String>
where
    B: FnMut(i32, i32, i32) -> String,
    C: Fn(i32, i32) -> Vec<rustmc_worldgen::density::fill::Substance>,
{
    use rustmc_worldgen::structure::placement::StructurePlacement;
    use rustmc_worldgen::structure::template::Template;

    let set_path = format!("{}/worldgen/structure_set/nether_fossils.json", crate::DATA);
    let set: serde_json::Value = serde_json::from_str(
        &std::fs::read_to_string(&set_path).map_err(|e| format!("{set_path}: {e}"))?,
    )
    .map_err(|e| format!("{set_path}: {e}"))?;
    let placement = StructurePlacement::parse(&set["placement"])?;
    let valid_biomes = crate::facts::resolve_biome_tag("has_structure/nether_fossil")?;

    let structure_path = format!("{}/worldgen/structure/nether_fossil.json", crate::DATA);
    let structure: serde_json::Value = serde_json::from_str(
        &std::fs::read_to_string(&structure_path).map_err(|e| format!("{structure_path}: {e}"))?,
    )
    .map_err(|e| format!("{structure_path}: {e}"))?;
    // Absent means `NONE`, which is the codec's default and the one value
    // that would make this structure raise no terrain at all.
    let terrain_adaptation = match structure.get("terrain_adaptation") {
        None => rustmc_worldgen::structure::template_pool::TerrainAdaptation::None,
        Some(serde_json::Value::String(name)) => {
            rustmc_worldgen::structure::template_pool::TerrainAdaptation::parse(name)
                .map_err(|e| format!("{structure_path}: {}", e.0))?
        }
        Some(other) => return Err(format!("{structure_path}: terrain_adaptation is {other}")),
    };
    let templates = format!("{}/structure", crate::DATA);

    // The largest fossil is a handful of blocks across and the beard reaches
    // twelve, so a start more than two chunks outside the area cannot touch
    // it. Kept deliberately generous rather than tight: a start that is
    // missed is a beard that never happens, and that failure is silent.
    let reach = 2;
    let mut out = Vec::new();
    let mut cache: std::collections::BTreeMap<String, std::sync::Arc<Template>> =
        std::collections::BTreeMap::new();

    for cx in (area.min_chunk_x - reach)..=(area.max_chunk_x + reach) {
        for cz in (area.min_chunk_z - reach)..=(area.max_chunk_z + reach) {
            if !placement
                .is_placement_chunk(seed, cx, cz)
                .map_err(|e| format!("{e:?}"))?
            {
                continue;
            }
            let Some(start) = rustmc_worldgen::structure::nether_fossil::find_generation_point(
                seed, cx, cz, &column_at, min_y, height, sea_level,
            ) else {
                continue;
            };
            let (x, y, z) = start.pos;
            if !valid_biomes.contains(&biome_at(x >> 2, y >> 2, z >> 2)) {
                continue;
            }

            if !cache.contains_key(start.template) {
                let path = format!("{templates}/{}.nbt", start.template);
                let file = std::fs::File::open(&path)
                    .map_err(|e| format!("{path}: the extract has no such template: {e}"))?;
                let mut reader = flate2::read::GzDecoder::new(file);
                let (_n, root) =
                    rustmc_world::nbt::read_named_root(&mut reader).map_err(|e| e.to_string())?;
                let template = Template::from_nbt(&root).map_err(|e| format!("{path}: {}", e.0))?;
                cache.insert(start.template.to_string(), std::sync::Arc::new(template));
            }
            let template = cache[start.template].clone();
            // `makeSettings` sets a rotation and `Mirror.NONE` and no pivot,
            // so the box is the plain rotated one about the origin.
            let bbox = template.bounding_box(start.pos, start.rotation);
            out.push(NetherFossil {
                start_chunk: (cx, cz),
                terrain_adaptation,
                template,
                start,
                bbox,
            });
        }
    }
    Ok(out)
}

/// Every `nether_fossil` start for a window, set up the way
/// `generate_nether` sets its stages up.
///
/// Exists so `worldgen-dump nether-fossil-starts` can be diffed against
/// `worldgen-dump jigsaw-starts <vanilla-region-dir> nether_fossil`, which
/// reads the same four facts — chunk, template, rotation, template position
/// — out of vanilla's own saved chunk NBT. That is a complete oracle for
/// this structure's placement, and it is a much stronger one than most
/// structures get.
///
/// # Errors
/// If the nether noises, biome table or a fossil template cannot be read.
pub fn nether_fossil_report(seed: i64, area: Area) -> Result<Vec<NetherFossil>, String> {
    let noises = crate::nether_noises()?;
    let router = rustmc_worldgen::density::router::OverworldRouter::nether(seed, &noises);
    let seeding = NoiseSeeding::new(seed);
    let settings = FillSettings::nether();
    let sampler = ClimateSampler::from_router(&router);
    let biomes = std::sync::Mutex::new(ParameterList::new(crate::nether_biome_table()?));

    let mut biome_at = |qx: i32, qy: i32, qz: i32| {
        biomes
            .lock()
            .expect("the climate list lock")
            .find_value(sampler.sample(qx, qy, qz))
            .clone()
    };
    // `getBaseColumn`, beardless — see `stage::noise::base_column`.
    let column_at = |x: i32, z: i32| {
        rustmc_worldgen::stage::noise::base_column(&router, &seeding, settings, x, z)
    };

    nether_fossil_starts(
        seed,
        area,
        &mut biome_at,
        column_at,
        settings.min_y,
        settings.height,
        settings.sea_level,
    )
}

/// Every `bastion_remnant` this port lays out for `area`, assembled but not
/// written.
///
/// The same entry point `generate_nether` uses, extracted so a gate can read
/// the layout without generating 1,089 chunks of terrain to look at it. That
/// separation is the point: `tests/golden_bastion_start.rs` compares this
/// against vanilla's own saved `Children[]` piece for piece, and a plan gate
/// that had to run the whole pipeline would be too slow to keep and would
/// confound a layout fault with a placement one.
///
/// # Errors
/// If the extract is missing or malformed.
pub fn bastion_report(seed: i64, area: Area) -> Result<Vec<Village>, String> {
    let noises = crate::nether_noises()?;
    let router = rustmc_worldgen::density::router::OverworldRouter::nether(seed, &noises);
    let seeding = NoiseSeeding::new(seed);
    let settings = FillSettings::nether();
    let sampler = ClimateSampler::from_router(&router);
    let biomes = std::sync::Mutex::new(ParameterList::new(crate::nether_biome_table()?));

    let mut biome_at = |qx: i32, qy: i32, qz: i32| {
        biomes
            .lock()
            .expect("the climate list lock")
            .find_value(sampler.sample(qx, qy, qz))
            .clone()
    };
    bastion_starts(seed, area, &mut biome_at, |x, z| {
        rustmc_worldgen::stage::noise::base_height(
            &router,
            &seeding,
            settings,
            x,
            z,
            rustmc_worldgen::chunk_gen::Wg::WorldSurface,
        )
    })
}

/// The placement chunks where the `nether_complexes` set places a
/// **fortress**, over `area` widened by `reach` chunks.
///
/// # Errors
/// If the extract is missing or malformed.
pub fn fortress_report(seed: i64, area: Area, reach: i32) -> Result<Vec<(i32, i32)>, String> {
    let noises = crate::nether_noises()?;
    let router = rustmc_worldgen::density::router::OverworldRouter::nether(seed, &noises);
    let seeding = NoiseSeeding::new(seed);
    let settings = FillSettings::nether();
    let sampler = ClimateSampler::from_router(&router);
    let biomes = std::sync::Mutex::new(ParameterList::new(crate::nether_biome_table()?));
    let mut biome_at = |qx: i32, qy: i32, qz: i32| {
        biomes
            .lock()
            .expect("the climate list lock")
            .find_value(sampler.sample(qx, qy, qz))
            .clone()
    };
    let mut fortresses = Vec::new();
    nether_complex_starts(
        seed,
        area,
        &mut biome_at,
        |x, z| {
            rustmc_worldgen::stage::noise::base_height(
                &router,
                &seeding,
                settings,
                x,
                z,
                rustmc_worldgen::chunk_gen::Wg::WorldSurface,
            )
        },
        reach,
        &mut fortresses,
    )?;
    Ok(fortresses)
}

/// One village, assembled but not yet written.
///
/// The piece list is built once for the whole generated area, for the same
/// reason a mineshaft's is: a village reaches 80 blocks from its centre, so
/// every chunk it touches has to write the *same* pieces, and re-running the
/// walk per chunk would be both wasteful and — because the walk reads the
/// heightmap — not obviously identical.
pub struct Village {
    pub start_chunk: (i32, i32),
    /// Which of the five variants won the weighted attempt.
    pub structure: String,
    pub pieces: Vec<rustmc_worldgen::structure::jigsaw::Piece>,
    pub union_box: rustmc_worldgen::structure::pieces::BoundingBox,
    /// `Structure.terrainAdaptation`. All five villages are `beard_thin`,
    /// which makes them the only bearding structure this port places — the
    /// nether's `nether_fossil` is not ported and nothing in the End beards.
    /// Carried per start rather than assumed, because `forStructuresInChunk`
    /// reads it off the structure and a sixth variant would not have to agree.
    pub terrain_adaptation: rustmc_worldgen::structure::template_pool::TerrainAdaptation,
}

/// `ChunkGenerator.getFirstFreeHeight(x, z, WORLD_SURFACE_WG, ..)` for the
/// overworld, as a free function of the column.
///
/// **It needs no chunk, and that is the whole point.** `getFirstFreeHeight`
/// is, in bytecode, nothing but `getBaseHeight` (`ChunkGenerator`, offsets
/// 0..11 — `getFirstOccupiedHeight` is the same call with an `iconst_1 isub`
/// after it, which is where the mineshaft's `- 1` comes from). For a
/// `NoiseBasedChunkGenerator` that is `iterateNoiseColumn`, a pure beardless
/// evaluation of one column, so vanilla can and does ask it about columns in
/// chunks that do not exist yet — structure starts are laid out at
/// `STRUCTURE_STARTS`, before any neighbour has been generated.
///
/// This port used to clamp it to the square being generated and treat a miss
/// as "this window cannot decide", which **made the set of structures a
/// function of the window size**. At seed 20260722, centre (64,64), r=16 that
/// silently dropped both `village_savanna` starts — (46,77) and (81,77) both
/// begin outside chunks 48..80 — for 13,659 blocks of residual, the
/// second-largest item in the window and the only one visible from the
/// ground.
pub fn overworld_first_free_height(
    router: &OverworldRouter,
    seeding: &NoiseSeeding,
    settings: FillSettings,
    x: i32,
    z: i32,
) -> i32 {
    rustmc_worldgen::stage::noise::base_height(
        router,
        seeding,
        settings,
        x,
        z,
        rustmc_worldgen::chunk_gen::Wg::WorldSurface,
    )
}

/// Every village whose pieces can reach `area`.
///
/// # The five variants, and which one wins
///
/// `villages.json` is a five-entry structure set at equal weight, so
/// `ChunkGenerator.createStructures` shuffles it with
/// `weighted_attempt_order` and tries each in turn. An attempt is a full
/// `JigsawPlacement.addPieces` run — vanilla builds the stub, *then* filters it
/// by biome (`Structure.findValidGenerationPoint` -> `isValidBiome`), so a
/// variant that assembles into the wrong biome is discarded after it was
/// assembled. Each attempt reseeds its own `LegacyRandomSource(0)` from
/// `setLargeFeatureSeed(seed, cx, cz)`, so the discarded attempts cost the
/// accepted one nothing.
///
/// The stub position is not the chunk's middle column. It is
/// `((bb.maxX + bb.minX) / 2, i1, (bb.maxZ + bb.minZ) / 2)` of the **start
/// piece**, where `i1` is the height the piece was projected onto — which
/// after `move` is exactly `bb.minY + groundLevelDelta`. `probe_find_village`
/// tests the chunk's middle column at y=64 instead, and says so: it is a
/// shortlist, not a placement claim.
///
/// # Errors
/// If the extract is present but malformed.
pub fn village_starts<B, H>(
    seed: i64,
    area: Area,
    biome_at: &mut B,
    height_at: H,
) -> Result<Vec<Village>, String>
where
    B: FnMut(i32, i32, i32) -> String,
    // Not `-> Option<i32>`. The height source is a pure noise column
    // ([`overworld_first_free_height`]) and is therefore total; an `Option`
    // here invited a caller to clamp it to its own generated square and treat
    // a miss as "skip this village", and a caller did exactly that.
    //
    // `Sync` since 2026-08-16, because the jigsaw walks run on a pool. It is
    // the *height* source that crosses threads and not the biome source: a
    // column is a pure function of the seed and the position, while
    // `ParameterList::find_value` carries the previous query's leaf and so
    // stays on the calling thread. See the acceptance pass below.
    H: Fn(i32, i32) -> i32 + Sync,
{
    use rustmc_worldgen::rng::legacy::LegacyRandomSource;
    use rustmc_worldgen::rng::worldgen_random::WorldgenRandom;
    use rustmc_worldgen::structure::jigsaw;
    use rustmc_worldgen::structure::placement::StructurePlacement;
    use rustmc_worldgen::structure::processor::weighted_attempt_order;
    use rustmc_worldgen::structure::template_pool::{JigsawStructure, StartHeight};

    let set_path = format!("{}/worldgen/structure_set/villages.json", crate::DATA);
    let Ok(text) = std::fs::read_to_string(&set_path) else {
        return Ok(Vec::new());
    };
    let json: serde_json::Value =
        serde_json::from_str(&text).map_err(|e| format!("{set_path}: {e}"))?;
    let placement = StructurePlacement::parse(&json["placement"])?;

    // The five entries, in file order, with their weights.
    let entries: Vec<(String, i32)> = json["structures"]
        .as_array()
        .ok_or_else(|| format!("{set_path}: no `structures`"))?
        .iter()
        .map(|e| {
            (
                e["structure"]
                    .as_str()
                    .unwrap_or_default()
                    .strip_prefix("minecraft:")
                    .unwrap_or_default()
                    .to_string(),
                e["weight"].as_i64().unwrap_or(1) as i32,
            )
        })
        .collect();
    let weights: Vec<i32> = entries.iter().map(|(_, w)| *w).collect();

    // Every variant's definition and biome set, resolved once.
    let mut defs: Vec<(JigsawStructure, std::collections::BTreeSet<String>)> = Vec::new();
    for (name, _) in &entries {
        let path = format!("{}/worldgen/structure/{name}.json", crate::DATA);
        let value: serde_json::Value =
            serde_json::from_str(&std::fs::read_to_string(&path).map_err(|e| e.to_string())?)
                .map_err(|e| format!("{path}: {e}"))?;
        let def = JigsawStructure::parse(&value).map_err(|e| format!("{path}: {}", e.0))?;
        let tag = def
            .biomes
            .strip_prefix('#')
            .and_then(|t| t.strip_prefix("minecraft:"))
            .ok_or_else(|| format!("{path}: `biomes` is not a namespaced tag"))?;
        let biomes = crate::facts::resolve_biome_tag(tag)?;
        defs.push((def, biomes));
    }

    // `max_distance_from_center` is 80 blocks, so a start five chunks outside
    // the area can still write into it. The placement test rejects almost
    // every chunk before a pool is opened.
    let reach = 6;

    // The placement grid, walked in the visiting order the result is built
    // in. `is_placement_chunk` rejects all but about one chunk in `spacing^2`
    // and costs a few hash operations, so this sweep is not what the stage
    // spends its time on: measured 2026-08-16 at seed 20260722, r=32, it
    // accepts **6** chunks out of 5,929 and the 30 jigsaw walks on those six
    // are 33.4 s of a 99.6 s pipeline, all of it on one thread.
    let mut candidates: Vec<(i32, i32)> = Vec::new();
    for cx in (area.min_chunk_x - reach)..=(area.max_chunk_x + reach) {
        for cz in (area.min_chunk_z - reach)..=(area.max_chunk_z + reach) {
            if placement
                .is_placement_chunk(seed, cx, cz)
                .map_err(|e| format!("{e:?}"))?
            {
                candidates.push((cx, cz));
            }
        }
    }
    crate::jigsaw_library::loads::PLACEMENT_CHUNKS.fetch_add(
        candidates.len() as u64,
        std::sync::atomic::Ordering::Relaxed,
    );

    // Every attempt this stage could make, as one flat list of independent
    // units of work.
    //
    // # Why this is byte-neutral, and where the line is
    //
    // A jigsaw walk reads `seed`, its own chunk position and the datapack,
    // and nothing else: it reseeds a `LegacyRandomSource(0)` from
    // `setLargeFeatureSeed(seed, cx, cz)`, and its heights come from
    // `getFirstFreeHeight`, a pure beardless noise column. So `assemble`
    // below is a function of `(cx, cz, entry)` alone and may run in any
    // order, on any thread.
    //
    // **`biome_at` is not.** `ParameterList::find_value` keeps the previous
    // query's leaf and searches from its distance, exactly as vanilla's
    // `RTree` keeps `lastResult` — so which biome comes back can depend on
    // which query ran before it, and a parallel pass would be reordering
    // queries on a shared list. That is why acceptance is a second,
    // sequential pass below rather than part of the worker: the assembled
    // pieces are order-free, the biome test is not, and separating them is
    // what makes this change provably not move a block.
    //
    // The cost of the split is that a chunk which the sequential loop would
    // have abandoned after its first accepted variant has its remaining
    // variants assembled anyway. That is CPU spent, never a block moved, and
    // on the measured square it is zero: all six accepted chunks already ran
    // all five attempts.
    let mut units: Vec<(usize, usize, usize)> = Vec::new();
    for (slot, &(cx, cz)) in candidates.iter().enumerate() {
        for (rank, entry) in weighted_attempt_order(seed, cx, cz, &weights)
            .into_iter()
            .enumerate()
        {
            units.push((slot, rank, entry));
        }
    }
    crate::jigsaw_library::loads::ATTEMPTS
        .fetch_add(units.len() as u64, std::sync::atomic::Ordering::Relaxed);

    // One assembled attempt: the pieces and the stub position the biome test
    // will be run at.
    type Assembled = (
        usize,
        Vec<rustmc_worldgen::structure::jigsaw::Piece>,
        (i32, i32, i32),
    );
    for (_, _, entry) in &units {
        if let StartHeight::Uniform { .. } = &defs[*entry].0.start_height {
            return Err("a village with a uniform start height, which draws".to_string());
        }
    }
    let assemble = |slot: usize, entry: usize| -> Option<Assembled> {
        let (cx, cz) = candidates[slot];
        let (def, _) = &defs[entry];
        let StartHeight::Constant(anchor) = &def.start_height else {
            // Refused above, for the whole list, before any work is done.
            return None;
        };
        let start_y = anchor.resolve(MIN_Y, MIN_Y + HEIGHT);
        let mut library = crate::jigsaw_library::FileLibrary::new(|x: i32, z: i32| height_at(x, z));
        let mut random = WorldgenRandom::new(LegacyRandomSource::new(0));
        random.set_large_feature_seed(seed, cx, cz);
        let settings = jigsaw::Settings {
            start_pool: def.start_pool.clone(),
            start_jigsaw_name: def.start_jigsaw_name.clone(),
            max_depth: def.size,
            start_pos: (cx * 16, start_y, cz * 16),
            use_expansion_hack: def.use_expansion_hack,
            project_start_to_heightmap: def.project_start_to_heightmap.is_some(),
            max_distance_horizontal: def.max_distance_from_center,
            max_distance_vertical: def.max_distance_from_center,
            level_min_y: MIN_Y,
            level_max_y: MIN_Y + HEIGHT - 1,
            padding_bottom: def.dimension_padding,
            padding_top: def.dimension_padding,
        };
        let pieces = jigsaw::add_pieces(&mut random, &mut library, &settings)?;
        let start = pieces.first()?;
        let stub = (
            (start.bbox.max_x + start.bbox.min_x) / 2,
            start.bbox.min_y + start.ground_level_delta,
            (start.bbox.max_z + start.bbox.min_z) / 2,
        );
        Some((entry, pieces, stub))
    };

    let assembled = crate::parallel::map_indexed(units.len(), |i| {
        let (slot, _, entry) = units[i];
        assemble(slot, entry)
    });

    // ---- acceptance, sequentially and in the visiting order ----
    //
    // The biome test runs here, once per attempt, in exactly the order the
    // single-threaded loop ran it: candidates in grid order, variants in
    // weighted-attempt order, stopping at the first acceptance. The shared
    // `ParameterList` therefore sees the same queries with the same inputs in
    // the same order, which is the condition its `lastResult` hint needs.
    let mut out = Vec::new();
    let mut placed: Option<usize> = None;
    for (i, &(slot, _rank, entry)) in units.iter().enumerate() {
        if placed == Some(slot) {
            // This chunk has already placed a village, and the sequential
            // loop's `break` skipped the rest of its attempt order. Skipping
            // them here — rather than never assembling them — is what keeps
            // the biome query sequence identical.
            continue;
        }
        let Some((entry_back, pieces, stub)) = &assembled[i] else {
            continue;
        };
        debug_assert_eq!(*entry_back, entry, "a slot holds its own attempt");
        let (def, biomes) = &defs[entry];
        let biome = biome_at(stub.0 >> 2, stub.1 >> 2, stub.2 >> 2);
        if !biomes.contains(&biome) {
            continue;
        }
        let boxes: Vec<_> = pieces.iter().map(|p| p.bbox).collect();
        let Some(union_box) =
            rustmc_worldgen::structure::pieces::BoundingBox::encapsulating(&boxes)
        else {
            continue;
        };
        out.push(Village {
            start_chunk: candidates[slot],
            structure: entries[entry].0.clone(),
            pieces: pieces.clone(),
            union_box,
            terrain_adaptation: def.terrain_adaptation,
        });
        placed = Some(slot);
    }
    Ok(out)
}

/// Every `bastion_remnant` whose pieces can reach `area`.
///
/// # The set has two entries and only one of them is a jigsaw
///
/// `nether_complexes.json` is `{fortress, weight 2}, {bastion_remnant, weight
/// 3}`, so `ChunkGenerator.createStructures` shuffles the pair with
/// `weighted_attempt_order` and tries each in turn until one generates. A
/// port that ran only the bastion would put one on **every** placement chunk,
/// because nothing would ever be tried before it.
///
/// The fortress is the reason that matters, and it is worse than a
/// coin-flip's worth of error:
///
/// * `NetherFortressStructure.findGenerationPoint` is
///   `Optional.of(new GenerationStub(new BlockPos(chunkPos.getMinBlockX(),
///   64, chunkPos.getMinBlockZ()), ...))` — **unconditional**. It has no
///   failure path at all.
/// * `fortress.json`'s `biomes` is `#minecraft:is_nether`, which every nether
///   biome is in, so `findValidGenerationPoint`'s filter never rejects it
///   either.
///
/// So the fortress attempt **always succeeds in the nether**, and a bastion
/// exists at a placement chunk if and only if the shuffle drew the bastion
/// first. That is why this function models the fortress at all: it writes no
/// fortress block and never will from here, but leaving it out of the attempt
/// order would place bastions where vanilla places a fortress. On the r=16
/// window at seed 20260722 the difference is visible without a diff — vanilla
/// saved **two** bastion starts and **no fortress**, and a
/// bastion-only port produces four.
///
/// Nothing is consumed by a losing attempt. Each `Structure.generate` builds
/// its own `GenerationContext`, whose `makeRandom` is a fresh
/// `WorldgenRandom(new LegacyRandomSource(0))` reseeded with
/// `setLargeFeatureSeed(seed, cx, cz)`, so an attempt that runs first and
/// wins costs the one behind it nothing and vice versa.
///
/// # What a bastion needs that a village does not
///
/// Almost nothing, which was the survey's finding and is repeated here
/// because it is the reason this function is short. All 176 bastion pool
/// elements across 60 pools are `single_pool_element`; every processor list
/// they name is a `minecraft:rule` or an empty inline list; and the one thing
/// that was missing is the `axis_aligned_linear_pos` in `high_rampart.json`,
/// which is a `PosRuleTest` and not a structure feature at all.
///
/// The two differences that do exist are in the structure definition and both
/// are already parameters: `use_expansion_hack` is **false** where a village's
/// is true, and `terrain_adaptation` is absent — so a bastion is `NONE` and
/// beards nothing. The second is why residual is charged to a bastion at
/// **margin 0**: there is no beard ring around it to widen the box for.
///
/// # Errors
/// If the extract is present but malformed.
pub fn bastion_starts<B, H>(
    seed: i64,
    area: Area,
    biome_at: &mut B,
    height_at: H,
) -> Result<Vec<Village>, String>
where
    B: FnMut(i32, i32, i32) -> String,
    H: Fn(i32, i32) -> i32,
{
    nether_complex_starts(seed, area, biome_at, height_at, 6, &mut Vec::new())
}

/// The `nether_complexes` set's attempts over `area` widened by `reach`
/// chunks: the bastions it lays out, and the placement chunks the
/// **fortress** wins, pushed onto `fortresses` in the same chunk order.
///
/// One function rather than two, because the two answers are one decision:
/// a placement chunk holds a fortress exactly when the weighted shuffle tries
/// the fortress before a bastion that succeeds, and computing either alone
/// would have to repeat the other's whole attempt.
///
/// # Errors
/// If the extract is present but malformed.
pub fn nether_complex_starts<B, H>(
    seed: i64,
    area: Area,
    biome_at: &mut B,
    height_at: H,
    reach: i32,
    fortresses: &mut Vec<(i32, i32)>,
) -> Result<Vec<Village>, String>
where
    B: FnMut(i32, i32, i32) -> String,
    H: Fn(i32, i32) -> i32,
{
    use rustmc_worldgen::rng::legacy::LegacyRandomSource;
    use rustmc_worldgen::rng::worldgen_random::WorldgenRandom;
    use rustmc_worldgen::structure::jigsaw;
    use rustmc_worldgen::structure::placement::StructurePlacement;
    use rustmc_worldgen::structure::processor::weighted_attempt_order;
    use rustmc_worldgen::structure::template_pool::{JigsawStructure, StartHeight};

    let set_path = format!(
        "{}/worldgen/structure_set/nether_complexes.json",
        crate::DATA
    );
    let Ok(text) = std::fs::read_to_string(&set_path) else {
        return Ok(Vec::new());
    };
    let json: serde_json::Value =
        serde_json::from_str(&text).map_err(|e| format!("{set_path}: {e}"))?;
    let placement = StructurePlacement::parse(&json["placement"])?;

    // File order, with weights — the order `weighted_attempt_order` indexes
    // into. `fortress` sorts first in the document and its weight is 2.
    let entries: Vec<(String, i32)> = json["structures"]
        .as_array()
        .ok_or_else(|| format!("{set_path}: no `structures`"))?
        .iter()
        .map(|e| {
            (
                e["structure"]
                    .as_str()
                    .unwrap_or_default()
                    .strip_prefix("minecraft:")
                    .unwrap_or_default()
                    .to_string(),
                e["weight"].as_i64().unwrap_or(1) as i32,
            )
        })
        .collect();
    let weights: Vec<i32> = entries.iter().map(|(_, w)| *w).collect();

    // The bastion's own definition, and the fortress's biome set. The
    // fortress is deliberately NOT parsed as a `JigsawStructure`: it is a
    // `minecraft:fortress`, a hardcoded structure with no `start_pool`, and
    // `JigsawStructure::parse` would refuse it. Only its biome tag is read,
    // because only its biome tag can decide the contention above.
    let mut bastion: Option<(JigsawStructure, std::collections::BTreeSet<String>)> = None;
    let mut fortress_biomes: Option<std::collections::BTreeSet<String>> = None;
    for (name, _) in &entries {
        let path = format!("{}/worldgen/structure/{name}.json", crate::DATA);
        let value: serde_json::Value =
            serde_json::from_str(&std::fs::read_to_string(&path).map_err(|e| e.to_string())?)
                .map_err(|e| format!("{path}: {e}"))?;
        let tag = value["biomes"]
            .as_str()
            .and_then(|t| t.strip_prefix('#'))
            .and_then(|t| t.strip_prefix("minecraft:"))
            .ok_or_else(|| format!("{path}: `biomes` is not a namespaced tag"))?;
        let biomes = crate::facts::resolve_biome_tag(tag)?;
        if name == "bastion_remnant" {
            let def = JigsawStructure::parse(&value).map_err(|e| format!("{path}: {}", e.0))?;
            bastion = Some((def, biomes));
        } else {
            fortress_biomes = Some(biomes);
        }
    }
    let Some((def, bastion_biomes)) = bastion else {
        return Err(format!("{set_path} names no bastion_remnant"));
    };
    let fortress_biomes = fortress_biomes.ok_or_else(|| format!("{set_path} names no fortress"))?;

    // `max_distance_from_center` is 80 blocks — the same figure a village
    // carries — so the same 6-chunk reach applies. The 105-piece start at
    // (55,63) spans x 785..896, which is seven chunks wide, and its own
    // placement chunk is not the chunk it is widest in.
    let mut out = Vec::new();
    for cx in (area.min_chunk_x - reach)..=(area.max_chunk_x + reach) {
        for cz in (area.min_chunk_z - reach)..=(area.max_chunk_z + reach) {
            if !placement
                .is_placement_chunk(seed, cx, cz)
                .map_err(|e| format!("{e:?}"))?
            {
                continue;
            }
            for entry in weighted_attempt_order(seed, cx, cz, &weights) {
                if entries[entry].0 != "bastion_remnant" {
                    // The fortress attempt. Its stub is the chunk's minimum
                    // corner at y **64** — not the chunk centre, and not a
                    // heightmap read — and `isValidBiome` samples that
                    // position in quart coordinates.
                    let stub = (cx * 16, 64, cz * 16);
                    if fortress_biomes.contains(&biome_at(stub.0 >> 2, stub.1 >> 2, stub.2 >> 2)) {
                        // The set is satisfied: a fortress, not a bastion.
                        fortresses.push((cx, cz));
                        break;
                    }
                    continue;
                }
                let start_y = match &def.start_height {
                    // `absolute: 33`, so the accessor's bounds are not read
                    // at all here — passed anyway because a `below_top`
                    // anchor would read them, and the pair to pass is the
                    // DIMENSION's 0..255 and not the noise settings' 0..127.
                    // `VerticalAnchor` resolves against
                    // `WorldGenerationContext`, which is built from the chunk
                    // generator and the `LevelHeightAccessor` — the nether's
                    // accessor is `DimensionType.NETHER`, 256 blocks.
                    StartHeight::Constant(anchor) => {
                        anchor.resolve(NETHER_MIN_Y, NETHER_MIN_Y + NETHER_STORAGE_HEIGHT)
                    }
                    StartHeight::Uniform { .. } => {
                        return Err("a bastion with a uniform start height, which draws".to_string())
                    }
                };
                let mut library =
                    crate::jigsaw_library::FileLibrary::new(|x: i32, z: i32| height_at(x, z));
                let mut random = WorldgenRandom::new(LegacyRandomSource::new(0));
                random.set_large_feature_seed(seed, cx, cz);
                let settings = jigsaw::Settings {
                    start_pool: def.start_pool.clone(),
                    start_jigsaw_name: def.start_jigsaw_name.clone(),
                    max_depth: def.size,
                    start_pos: (cx * 16, start_y, cz * 16),
                    use_expansion_hack: def.use_expansion_hack,
                    project_start_to_heightmap: def.project_start_to_heightmap.is_some(),
                    max_distance_horizontal: def.max_distance_from_center,
                    max_distance_vertical: def.max_distance_from_center,
                    // The NETHER's height accessor, not the overworld's. A
                    // bastion assembles from y 33 and is 24 blocks tall, so
                    // the clamp never bites on this seed — but handing the
                    // walk the overworld's -64..319 would make the bound a
                    // different number for no reason anyone could later find.
                    level_min_y: NETHER_MIN_Y,
                    level_max_y: NETHER_MIN_Y + NETHER_STORAGE_HEIGHT - 1,
                    padding_bottom: def.dimension_padding,
                    padding_top: def.dimension_padding,
                };
                let Some(pieces) = jigsaw::add_pieces(&mut random, &mut library, &settings) else {
                    continue;
                };
                let Some(start) = pieces.first() else {
                    continue;
                };
                let stub = (
                    (start.bbox.max_x + start.bbox.min_x) / 2,
                    start.bbox.min_y + start.ground_level_delta,
                    (start.bbox.max_z + start.bbox.min_z) / 2,
                );
                if !bastion_biomes.contains(&biome_at(stub.0 >> 2, stub.1 >> 2, stub.2 >> 2)) {
                    continue;
                }
                let boxes: Vec<_> = pieces.iter().map(|p| p.bbox).collect();
                let Some(union_box) =
                    rustmc_worldgen::structure::pieces::BoundingBox::encapsulating(&boxes)
                else {
                    continue;
                };
                out.push(Village {
                    start_chunk: (cx, cz),
                    structure: entries[entry].0.clone(),
                    pieces,
                    union_box,
                    terrain_adaptation: def.terrain_adaptation,
                });
                break;
            }
        }
    }
    Ok(out)
}

/// Every trial chamber whose pieces can reach `area`.
///
/// `trial_chambers` is a **one-entry** structure set, so there is no weighted
/// attempt order to make: the placement grid picks a chunk and one attempt is
/// made.
///
/// # What makes it different from a village, and both differences draw
///
/// 1. **`start_height` is `uniform`, not a constant.**
///    `JigsawStructure.findGenerationPoint` opens with
///    `this.startHeight.sample(ctx.random(), ..)`, and `UniformHeight.sample`
///    is `Mth.randomBetweenInclusive(random, min, max)` —
///    `nextInt(max - min + 1) + min`. That is **one draw off the walk's own
///    stream, taken before the first piece**, so a port that skips it puts
///    every subsequent draw one position out and builds a different chamber.
///    The anchors are absolute -40 and -20, so the bound is 21.
/// 2. **`pool_aliases`**, which draw off a *different* stream — see
///    [`rustmc_worldgen::structure::pool_alias`]. Four of the spawner pool
///    names have no file on disk, so the alias table is not an optimisation:
///    without it those jigsaws resolve to nothing and the chamber generates
///    with its spawner rooms missing.
///
/// The context random is seeded exactly as a village's is —
/// `new WorldgenRandom(new LegacyRandomSource(0))` then
/// `setLargeFeatureSeed(seed, chunkX, chunkZ)`, read out of
/// `Structure$GenerationContext.makeRandom` — so nothing else about the walk
/// changes.
///
/// # Errors
/// If the extract is present but malformed.
pub fn trial_chamber_starts<B, H>(
    seed: i64,
    area: Area,
    biome_at: &mut B,
    height_at: H,
) -> Result<Vec<Village>, String>
where
    B: FnMut(i32, i32, i32) -> String,
    H: Fn(i32, i32) -> Option<i32> + Sync,
{
    use rustmc_worldgen::rng::legacy::LegacyRandomSource;
    use rustmc_worldgen::rng::worldgen_random::WorldgenRandom;
    use rustmc_worldgen::rng::RandomSource;
    use rustmc_worldgen::structure::jigsaw;
    use rustmc_worldgen::structure::placement::StructurePlacement;
    use rustmc_worldgen::structure::pool_alias;
    use rustmc_worldgen::structure::template_pool::{JigsawStructure, StartHeight};

    let set_path = format!("{}/worldgen/structure_set/trial_chambers.json", crate::DATA);
    let Ok(text) = std::fs::read_to_string(&set_path) else {
        return Ok(Vec::new());
    };
    let json: serde_json::Value =
        serde_json::from_str(&text).map_err(|e| format!("{set_path}: {e}"))?;
    let placement = StructurePlacement::parse(&json["placement"])?;

    let def_path = format!("{}/worldgen/structure/trial_chambers.json", crate::DATA);
    let value: serde_json::Value =
        serde_json::from_str(&std::fs::read_to_string(&def_path).map_err(|e| e.to_string())?)
            .map_err(|e| format!("{def_path}: {e}"))?;
    let def = JigsawStructure::parse(&value).map_err(|e| format!("{def_path}: {}", e.0))?;
    let tag = def
        .biomes
        .strip_prefix('#')
        .and_then(|t| t.strip_prefix("minecraft:"))
        .ok_or_else(|| format!("{def_path}: `biomes` is not a namespaced tag"))?;
    let biomes = crate::facts::resolve_biome_tag(tag)?;

    // `max_distance_from_center` is 116 blocks — 7.25 chunks — against a
    // village's 80. Eight chunks covers it and the ninth is the same margin the
    // village path keeps.
    let reach = 9;
    // Assembled on the pool, accepted sequentially — the same split the
    // village layout uses and for the same reason. A chamber's walk reads
    // `seed`, its own chunk position and the datapack; the biome test under
    // it goes through `ParameterList::find_value`, which starts each search
    // from the previous query's leaf and so has to keep the order it always
    // had. See `village_starts` for the measurement that says the hint is not
    // inert.
    let mut candidates: Vec<(i32, i32)> = Vec::new();
    for cx in (area.min_chunk_x - reach)..=(area.max_chunk_x + reach) {
        for cz in (area.min_chunk_z - reach)..=(area.max_chunk_z + reach) {
            if placement
                .is_placement_chunk(seed, cx, cz)
                .map_err(|e| format!("{e:?}"))?
            {
                candidates.push((cx, cz));
            }
        }
    }
    type Chamber = (
        Vec<rustmc_worldgen::structure::jigsaw::Piece>,
        (i32, i32, i32),
    );
    let assemble = |i: usize| -> Option<Chamber> {
        {
            let (cx, cz) = candidates[i];
            let mut random = WorldgenRandom::new(LegacyRandomSource::new(0));
            random.set_large_feature_seed(seed, cx, cz);
            // Draw 1, before anything else touches this stream.
            let start_y = match &def.start_height {
                StartHeight::Constant(anchor) => anchor.resolve(MIN_Y, MIN_Y + HEIGHT),
                StartHeight::Uniform {
                    min_inclusive,
                    max_inclusive,
                } => {
                    let lo = min_inclusive.resolve(MIN_Y, MIN_Y + HEIGHT);
                    let hi = max_inclusive.resolve(MIN_Y, MIN_Y + HEIGHT);
                    // `UniformHeight.sample` returns `min` WITHOUT drawing when
                    // the range is inverted. Reproduced rather than assumed
                    // away: it is a branch that changes the draw count.
                    if lo > hi {
                        lo
                    } else {
                        random.next_i32_between_inclusive(lo, hi)
                    }
                }
            };
            let start_pos = (cx * 16, start_y, cz * 16);
            let aliases = pool_alias::lookup_table(&def.pool_aliases, start_pos, seed);
            let outside = std::cell::Cell::new(false);
            let mut library = crate::jigsaw_library::FileLibrary::new(|x: i32, z: i32| {
                height_at(x, z).unwrap_or_else(|| {
                    outside.set(true);
                    MIN_Y
                })
            })
            .with_aliases(aliases);
            let settings = jigsaw::Settings {
                start_pool: def.start_pool.clone(),
                start_jigsaw_name: def.start_jigsaw_name.clone(),
                max_depth: def.size,
                start_pos,
                use_expansion_hack: def.use_expansion_hack,
                project_start_to_heightmap: def.project_start_to_heightmap.is_some(),
                max_distance_horizontal: def.max_distance_from_center,
                max_distance_vertical: def.max_distance_from_center,
                level_min_y: MIN_Y,
                level_max_y: MIN_Y + HEIGHT - 1,
                padding_bottom: def.dimension_padding,
                padding_top: def.dimension_padding,
            };
            let pieces = jigsaw::add_pieces(&mut random, &mut library, &settings)?;
            let start = pieces.first()?;
            // A chamber is underground and its walk never reads the heightmap,
            // so `outside` should not fire here — unlike a village, whose
            // terrain-matching streets do. Kept as a guard rather than dropped:
            // if it fires, the chamber was assembled against terrain that does
            // not exist, and skipping it is the honest answer.
            if outside.get() {
                return None;
            }
            let stub = (
                (start.bbox.max_x + start.bbox.min_x) / 2,
                start.bbox.min_y + start.ground_level_delta,
                (start.bbox.max_z + start.bbox.min_z) / 2,
            );
            Some((pieces, stub))
        }
    };
    let assembled = crate::parallel::map_indexed(candidates.len(), assemble);

    let mut out = Vec::new();
    for (i, &(cx, cz)) in candidates.iter().enumerate() {
        let Some((pieces, stub)) = &assembled[i] else {
            continue;
        };
        let biome = biome_at(stub.0 >> 2, stub.1 >> 2, stub.2 >> 2);
        if !biomes.contains(&biome) {
            continue;
        }
        let boxes: Vec<_> = pieces.iter().map(|p| p.bbox).collect();
        let Some(union_box) =
            rustmc_worldgen::structure::pieces::BoundingBox::encapsulating(&boxes)
        else {
            continue;
        };
        out.push(Village {
            start_chunk: (cx, cz),
            structure: "trial_chambers".to_string(),
            pieces: pieces.clone(),
            union_box,
            terrain_adaptation: def.terrain_adaptation,
        });
    }
    Ok(out)
}

/// `trial_chamber_starts` against a freshly built overworld router, for the
/// oracle command.
///
/// Mirrors [`nether_fossil_report`]: a standalone entry point that needs no
/// generated canvas, so the walk can be gated against vanilla's own saved
/// `Children[]` without generating a single block. That is the cheap gate the
/// standing rules ask for before any block diff — a block diff cannot tell a
/// wrong template from a wrong rotation from a wrong stream position, and this
/// can.
///
/// # Errors
/// If the extract is missing or malformed.
/// `pillager_outposts` over `area` and the jigsaw's reach of margin.
///
/// The set is the one overworld set with both a frequency and an exclusion
/// zone: `random_spread` spacing 32, then `legacy_type_1` at 0.2, then no
/// `villages` placement chunk within 10 chunks (`hasStructureChunkInRange`
/// asks the other set's grid and frequency only — not its biome, so a village
/// that never generates still excludes an outpost). Then the jigsaw walk from
/// `pillager_outpost/base_plates` at y 0 projected to `WORLD_SURFACE_WG`, and
/// the biome gate at the start piece's centre, exactly as a village.
pub fn outpost_starts<B, H>(
    seed: i64,
    area: Area,
    biome_at: &mut B,
    height_at: H,
) -> Result<Vec<Village>, String>
where
    B: FnMut(i32, i32, i32) -> String,
    H: Fn(i32, i32) -> i32,
{
    single_jigsaw_starts(
        seed,
        area,
        "structure_set/pillager_outposts.json",
        "pillager_outpost",
        biome_at,
        height_at,
    )
}

/// `trail_ruins` over `area`: a one-entry `random_spread` set (spacing 34,
/// separation 8, no frequency, no exclusion zone), then the jigsaw walk from
/// `trail_ruins/tower` at y -15 projected to `WORLD_SURFACE_WG` — so the start
/// sits fifteen blocks under the surface — and `bury`, which the beard
/// already models. `underground_structures`, placed between the mineshafts
/// and the trial chambers by registry index. Every pool element is
/// `single_pool_element`.
pub fn trail_ruin_starts<B, H>(
    seed: i64,
    area: Area,
    biome_at: &mut B,
    height_at: H,
) -> Result<Vec<Village>, String>
where
    B: FnMut(i32, i32, i32) -> String,
    H: Fn(i32, i32) -> i32,
{
    single_jigsaw_starts(
        seed,
        area,
        "structure_set/trail_ruins.json",
        "trail_ruins",
        biome_at,
        height_at,
    )
}

/// `ancient_cities` over `area`: `random_spread` spacing 24, separation 8,
/// then the jigsaw walk from `ancient_city/city_center` anchored on its
/// `minecraft:city_anchor` jigsaw at y -27, not projected, `beard_box`, and
/// placed in `underground_decoration` (step 7). Its one
/// `feature_pool_element` (`sculk_patch_ancient_city`) is refused and
/// counted, as a village's are.
pub fn ancient_city_starts<B, H>(
    seed: i64,
    area: Area,
    biome_at: &mut B,
    height_at: H,
) -> Result<Vec<Village>, String>
where
    B: FnMut(i32, i32, i32) -> String,
    H: Fn(i32, i32) -> i32,
{
    single_jigsaw_starts(
        seed,
        area,
        "structure_set/ancient_cities.json",
        "ancient_city",
        biome_at,
        height_at,
    )
}

/// A one-structure jigsaw set, as `outpost_starts` and `trail_ruin_starts`
/// share it: the set's full `isStructureChunk` (grid, frequency, exclusion
/// against any other set's grid), the walk from the structure's start pool at
/// its constant start height, and the biome gate at the start piece's centre.
fn single_jigsaw_starts<B, H>(
    seed: i64,
    area: Area,
    set: &str,
    structure: &str,
    biome_at: &mut B,
    height_at: H,
) -> Result<Vec<Village>, String>
where
    B: FnMut(i32, i32, i32) -> String,
    H: Fn(i32, i32) -> i32,
{
    use rustmc_worldgen::rng::legacy::LegacyRandomSource;
    use rustmc_worldgen::rng::worldgen_random::WorldgenRandom;
    use rustmc_worldgen::structure::jigsaw;
    use rustmc_worldgen::structure::placement::StructurePlacement;
    use rustmc_worldgen::structure::template_pool::{JigsawStructure, StartHeight};

    let read_set = |name: &str| -> Result<Option<StructurePlacement>, String> {
        let path = format!("{}/worldgen/{name}", crate::DATA);
        let Ok(text) = std::fs::read_to_string(&path) else {
            return Ok(None);
        };
        let json: serde_json::Value =
            serde_json::from_str(&text).map_err(|e| format!("{path}: {e}"))?;
        StructurePlacement::parse(&json["placement"]).map(Some)
    };
    let Some(placement) = read_set(set)? else {
        return Ok(Vec::new());
    };
    // The one exclusion zone any 26.2 overworld set declares is the
    // outposts' against `minecraft:villages`; a zone naming anything else
    // refuses, through `is_structure_chunk`'s own error.
    let villages = read_set("structure_set/villages.json")?.ok_or("no villages structure set")?;
    let other = |name: &str| (name == "minecraft:villages").then(|| villages.clone());

    let def_path = format!("{}/worldgen/structure/{structure}.json", crate::DATA);
    let value: serde_json::Value =
        serde_json::from_str(&std::fs::read_to_string(&def_path).map_err(|e| e.to_string())?)
            .map_err(|e| format!("{def_path}: {e}"))?;
    let def = JigsawStructure::parse(&value).map_err(|e| format!("{def_path}: {}", e.0))?;
    let biomes = crate::facts::resolve_structure_biomes(&value, &def_path)?;
    if def.project_start_to_heightmap.is_some() && def.start_jigsaw_name.is_some() {
        return Err(format!(
            "{structure} both projects its start and names a start jigsaw; the \
             stub height for that combination is not derived here"
        ));
    }

    // `max_distance_from_center` in chunks, plus the box and a chunk spare:
    // 7 for an outpost or a trail ruin (80), 9 for an ancient city (116).
    let reach = def.max_distance_from_center / 16 + 2;
    let mut out = Vec::new();
    for cx in (area.min_chunk_x - reach)..=(area.max_chunk_x + reach) {
        for cz in (area.min_chunk_z - reach)..=(area.max_chunk_z + reach) {
            if !placement
                .is_structure_chunk(seed, cx, cz, &other)
                .map_err(|e| format!("{e:?}"))?
            {
                continue;
            }
            let start_y = match &def.start_height {
                StartHeight::Constant(anchor) => anchor.resolve(MIN_Y, MIN_Y + HEIGHT),
                StartHeight::Uniform { .. } => {
                    return Err(format!(
                        "{structure} has a uniform start height, which draws"
                    ))
                }
            };
            let mut library =
                crate::jigsaw_library::FileLibrary::new(|x: i32, z: i32| height_at(x, z));
            let mut random = WorldgenRandom::new(LegacyRandomSource::new(0));
            random.set_large_feature_seed(seed, cx, cz);
            let settings = jigsaw::Settings {
                start_pool: def.start_pool.clone(),
                start_jigsaw_name: def.start_jigsaw_name.clone(),
                max_depth: def.size,
                start_pos: (cx * 16, start_y, cz * 16),
                use_expansion_hack: def.use_expansion_hack,
                project_start_to_heightmap: def.project_start_to_heightmap.is_some(),
                max_distance_horizontal: def.max_distance_from_center,
                max_distance_vertical: def.max_distance_from_center,
                level_min_y: MIN_Y,
                level_max_y: MIN_Y + HEIGHT - 1,
                padding_bottom: def.dimension_padding,
                padding_top: def.dimension_padding,
            };
            let Some(pieces) = jigsaw::add_pieces(&mut random, &mut library, &settings) else {
                continue;
            };
            let Some(start) = pieces.first() else {
                continue;
            };
            // `GenerationStub` y is the projected y plus the named anchor's
            // offset. Projected, there is no anchor (no 26.2 structure has
            // both) and it is the moved box's `minY + groundLevelDelta`;
            // unprojected, the offsets cancel and it is the start height —
            // which for an ancient city is y -27 wherever its anchor sits.
            let stub = (
                (start.bbox.max_x + start.bbox.min_x) / 2,
                if def.project_start_to_heightmap.is_some() {
                    start.bbox.min_y + start.ground_level_delta
                } else {
                    start_y
                },
                (start.bbox.max_z + start.bbox.min_z) / 2,
            );
            if !biomes.contains(&biome_at(stub.0 >> 2, stub.1 >> 2, stub.2 >> 2)) {
                continue;
            }
            let boxes: Vec<_> = pieces.iter().map(|p| p.bbox).collect();
            let Some(union_box) =
                rustmc_worldgen::structure::pieces::BoundingBox::encapsulating(&boxes)
            else {
                continue;
            };
            out.push(Village {
                start_chunk: (cx, cz),
                structure: structure.to_string(),
                pieces,
                union_box,
                terrain_adaptation: def.terrain_adaptation,
            });
        }
    }
    Ok(out)
}

/// Every outpost start for a window, wired as `generate_resuming` wires it.
///
/// # Errors
/// If the extract is missing or malformed.
pub fn outpost_report(seed: i64, area: Area) -> Result<Vec<Village>, String> {
    let params = noise_parameters();
    let noises = crate::overworld_noises(&params);
    let router = OverworldRouter::new(seed, &noises, false);
    let seeding = NoiseSeeding::new(seed);
    let settings = FillSettings::overworld();
    let sampler = ClimateSampler::from_router(&router);
    let biomes = std::sync::Mutex::new(ParameterList::new(biome_table()));
    let mut biome_at = |qx: i32, qy: i32, qz: i32| {
        biomes
            .lock()
            .expect("the climate list lock")
            .find_value(sampler.sample(qx, qy, qz))
            .clone()
    };
    outpost_starts(seed, area, &mut biome_at, |x, z| {
        overworld_first_free_height(&router, &seeding, settings, x, z)
    })
}

