pub fn trial_chamber_report(seed: i64, area: Area) -> Result<Vec<Village>, String> {
    let params = noise_parameters();
    let noises = crate::overworld_noises(&params);
    let router = OverworldRouter::new(seed, &noises, false);
    let seeding = NoiseSeeding::new(seed);
    let settings = FillSettings::overworld();
    let sampler = ClimateSampler::from_router(&router);
    let biomes = std::sync::Mutex::new(ParameterList::new(biome_table()));

    let mut biome_at = |qx: i32, qy: i32, qz: i32| {
        biomes
            .lock()
            .expect("the climate list lock")
            .find_value(sampler.sample(qx, qy, qz))
            .clone()
    };
    // A chamber is rigid and underground, so this is never read — but it is
    // wired to the same `base_height` a village uses rather than to a
    // constant, so that a chamber which *did* read it would get the same
    // answer the pipeline would give, instead of a plausible-looking wrong one.
    let height_at = |x: i32, z: i32| {
        Some(rustmc_worldgen::stage::noise::base_height(
            &router,
            &seeding,
            settings,
            x,
            z,
            rustmc_worldgen::chunk_gen::Wg::WorldSurface,
        ))
    };

    trial_chamber_starts(seed, area, &mut biome_at, height_at)
}

/// `strongholds` over `area`: the 128 concentric-ring positions (distance 32,
/// spread 3), each moved by its own `findBiomeHorizontal` toward a
/// `#stronghold_biased_to` biome within 112 blocks — run only for positions
/// that can reach `area` — then the biome gate at the chunk's world position
/// `(minX, 0, minZ)` and the piece walk.
///
/// # Errors
/// If the extract is missing or malformed.
pub fn stronghold_starts<B>(
    seed: i64,
    area: Area,
    biome_at: &mut B,
) -> Result<Vec<rustmc_worldgen::structure::stronghold::Stronghold>, String>
where
    B: FnMut(i32, i32, i32) -> String,
{
    use rustmc_worldgen::structure::stronghold::{
        find_biome_horizontal, generate, ring_candidates,
    };
    let set_path = format!("{}/worldgen/structure_set/strongholds.json", crate::DATA);
    let Ok(text) = std::fs::read_to_string(&set_path) else {
        return Ok(Vec::new());
    };
    let json: serde_json::Value =
        serde_json::from_str(&text).map_err(|e| format!("{set_path}: {e}"))?;
    let placement = &json["placement"];
    let int = |key: &str| -> Result<i32, String> {
        placement[key]
            .as_i64()
            .and_then(|v| i32::try_from(v).ok())
            .ok_or_else(|| format!("{set_path}: no `{key}`"))
    };
    let (distance, spread, count) = (int("distance")?, int("spread")?, int("count")?);
    let preferred_tag = placement["preferred_biomes"]
        .as_str()
        .and_then(|t| t.strip_prefix("#minecraft:"))
        .ok_or_else(|| format!("{set_path}: `preferred_biomes` is not a tag"))?;
    let preferred = crate::facts::resolve_biome_tag(preferred_tag)?;
    let def_path = format!("{}/worldgen/structure/stronghold.json", crate::DATA);
    let def: serde_json::Value = serde_json::from_str(
        &std::fs::read_to_string(&def_path).map_err(|e| format!("{def_path}: {e}"))?,
    )
    .map_err(|e| format!("{def_path}: {e}"))?;
    let biomes = crate::facts::resolve_structure_biomes(&def, &def_path)?;
    // The search moves a position at most 112 blocks (7 chunks); a
    // stronghold's pieces stay within 112 blocks of its start piece plus a
    // piece. 16 chunks either way is safely past both.
    let reach = 16;
    let mut out = Vec::new();
    for ((cx, cz), fork_seed) in ring_candidates(seed, distance, spread, count) {
        if cx < area.min_chunk_x - reach
            || cx > area.max_chunk_x + reach
            || cz < area.min_chunk_z - reach
            || cz > area.max_chunk_z + reach
        {
            continue;
        }
        let found = find_biome_horizontal(
            cx * 16 + 8,
            0,
            cz * 16 + 8,
            112,
            fork_seed,
            &mut |qx, qy, qz| preferred.contains(&biome_at(qx, qy, qz)),
        );
        let (sx, sz) = found.map_or((cx, cz), |(x, _, z)| (x >> 4, z >> 4));
        if !biomes.contains(&biome_at((sx * 16) >> 2, 0, (sz * 16) >> 2)) {
            continue;
        }
        out.push(generate(seed, (sx, sz), SEA_LEVEL, MIN_Y));
    }
    Ok(out)
}

/// Every stronghold start for a window, wired as `generate_resuming` wires it.
///
/// # Errors
/// If the extract is missing or malformed.
pub fn stronghold_report(
    seed: i64,
    area: Area,
) -> Result<Vec<rustmc_worldgen::structure::stronghold::Stronghold>, String> {
    let params = noise_parameters();
    let noises = crate::overworld_noises(&params);
    let router = OverworldRouter::new(seed, &noises, false);
    let sampler = ClimateSampler::from_router(&router);
    let biomes = std::sync::Mutex::new(ParameterList::new(biome_table()));
    let mut biome_at = |qx: i32, qy: i32, qz: i32| {
        biomes
            .lock()
            .expect("the climate list lock")
            .find_value(sampler.sample(qx, qy, qz))
            .clone()
    };
    stronghold_starts(seed, area, &mut biome_at)
}

/// Every scattered start (pyramid, jungle temple, swamp hut) and every igloo
/// for a window, wired exactly as `generate_resuming` wires them.
///
/// Exists to find windows: `worldgen-dump scattered-starts` prints these, and
/// a vanilla harvest centred on one is what then measures it. The harvest's
/// own `structures.starts` NBT is the check on this listing — a start this
/// prints that vanilla does not save is a placement defect, read before a
/// single block is compared.
///
/// # Errors
/// If the extract is missing or malformed.
pub fn scattered_report(
    seed: i64,
    area: Area,
) -> Result<
    (
        Vec<rustmc_worldgen::structure::scattered::ScatteredStart>,
        Vec<Igloo>,
    ),
    String,
> {
    let params = noise_parameters();
    let noises = crate::overworld_noises(&params);
    let router = OverworldRouter::new(seed, &noises, false);
    let seeding = NoiseSeeding::new(seed);
    let settings = FillSettings::overworld();
    let sampler = ClimateSampler::from_router(&router);
    let biomes = std::sync::Mutex::new(ParameterList::new(biome_table()));
    let mut biome_at = |qx: i32, qy: i32, qz: i32| {
        biomes
            .lock()
            .expect("the climate list lock")
            .find_value(sampler.sample(qx, qy, qz))
            .clone()
    };
    let height =
        |x: i32, z: i32| overworld_first_free_height(&router, &seeding, settings, x, z) - 1;
    let scattered = scattered_starts(seed, area, &mut biome_at, height)?;
    let igloos = igloo_starts(seed, area, &mut biome_at, height)?;
    Ok((scattered, igloos))
}

