/// Every village start for a window, wired exactly as `generate_decorating`
/// wires it.
///
/// Exists so the assembled piece list can be diffed against
/// `worldgen-dump jigsaw-starts <vanilla-region-dir> village_savanna`, which
/// reads element, rotation, position, bounding box, ground level delta and
/// junction count out of vanilla's own saved chunk NBT. That is the cheap
/// gate the standing rules ask for before any block diff: a block diff cannot
/// tell a wrong template from a wrong rotation from a wrong stream position,
/// and this can.
///
/// **It shares the height source with the pipeline rather than reproducing
/// it.** `worldgen-dump village-pieces` does not — it reads the *canvas*
/// `WORLD_SURFACE_WG` instead of `getFirstFreeHeight`, and at seed 20260722
/// chunk (46,77) those two disagree enough to build a 103-piece village where
/// vanilla builds 98. A gate wired to the wrong source is a gate that passes
/// while the world is wrong.
///
/// # Errors
/// If the extract is missing or malformed.
pub fn village_report(seed: i64, area: Area) -> Result<Vec<Village>, String> {
    let params = noise_parameters();
    let noises = crate::overworld_noises(&params);
    let router = OverworldRouter::new(seed, &noises, false);
    let seeding = NoiseSeeding::new(seed);
    let settings = FillSettings::overworld();
    let sampler = ClimateSampler::from_router(&router);
    let biomes = std::sync::Mutex::new(ParameterList::new(biome_table()));

    let mut biome_at = |qx: i32, qy: i32, qz: i32| {
        biomes
            .lock()
            .expect("the climate list lock")
            .find_value(sampler.sample(qx, qy, qz))
            .clone()
    };
    village_starts(seed, area, &mut biome_at, |x, z| {
        overworld_first_free_height(&router, &seeding, settings, x, z)
    })
}

/// Every End city start for a window, wired as `generate_end` wires it, with
/// no canvas: the biome is the router's End classifier and the height is
/// `getFirstOccupiedHeight(WORLD_SURFACE_WG)`, i.e. the noise fill's base
/// height minus one, which is the value `generate_end` reads off its canvas.
///
/// Exists so a city's piece list — including whether its tower bridge grew a
/// ship — can be read before anything is placed, and checked box for box
/// against vanilla's saved `Children` with `region-differ starts`.
///
/// # Errors
/// If the extract is missing or malformed.
pub fn end_city_report(seed: i64, area: Area) -> Result<Vec<EndCity>, String> {
    let router = rustmc_worldgen::density::router::OverworldRouter::end(seed);
    let seeding = NoiseSeeding::new(seed);
    let settings = FillSettings::end();
    end_city_starts(
        seed,
        area,
        &mut |qx, qy, qz| {
            rustmc_worldgen::biome::end::biome_at_quart(&router.erosion, qx, qy, qz).to_string()
        },
        |x, z| {
            Some(
                rustmc_worldgen::stage::noise::base_height(
                    &router,
                    &seeding,
                    settings,
                    x,
                    z,
                    rustmc_worldgen::chunk_gen::Wg::WorldSurface,
                ) - 1,
            )
        },
    )
}

/// One entity a structure's `postProcess` adds, where it adds it.
///
/// `block` is the `BlockPos` the spawn is keyed to: a mob is `snapTo`'d to
/// its centre (`x + 0.5, y, z + 0.5`), an item frame hangs on it facing
/// `facing`. `count` is how many spawn there: 1, or `None` for a mansion's
/// "Group of Allays", which draws `nextInt(3) + 1` on the level random this
/// port does not run for structures.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct StructureSpawn {
    pub structure: &'static str,
    pub id: &'static str,
    pub block: (i32, i32, i32),
    pub facing: Option<&'static str>,
    pub count: Option<u8>,
}

/// Every entity the woodland mansions, ocean monuments (overworld) or end
/// cities (`end = true`) of `area` spawn while they are placed, inside
/// `area`'s chunks.
///
/// No placer records these: nothing in worldgen carries an entity. This is
/// the list, derived from the same starts the placers build, so it can be
/// read against a vanilla world's `entities/` region files.
///
/// * `WoodlandMansionPieces.handleDataMarker`: `Mage` an evoker, `Warrior` a
///   vindicator, `Group of Allays` one to three allays, at the marker.
/// * `OceanMonumentPieces`: `spawnElder` at the penthouse's `(6, 1, 6)` and at
///   each wing room's `(11, 2, 16)` (design 0) or `(11, 5, 13)` (design 1).
/// * `EndCityPieces.handleDataMarker`: `Sentry` a shulker at the marker,
///   `Elytra` an item frame holding an elytra, hung facing
///   `rotation.rotate(SOUTH)`.
///
/// # Errors
/// If the extract is missing or malformed.
pub fn structure_spawns(seed: i64, area: Area, end: bool) -> Result<Vec<StructureSpawn>, String> {
    use rustmc_worldgen::structure::ocean_monument::RoomKind;
    use rustmc_worldgen::structure::template::{transform, Mirror, Rotation};
    let in_area = |(x, _, z): (i32, i32, i32)| {
        let (cx, cz) = (x >> 4, z >> 4);
        area.chunks().any(|c| c == (cx, cz))
    };
    let mut out = Vec::new();
    let mut push = |structure, id, block: (i32, i32, i32), facing, count| {
        if in_area(block) {
            out.push(StructureSpawn {
                structure,
                id,
                block,
                facing,
                count,
            });
        }
    };
    if end {
        let dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("../../data/vanilla/structure/end_city");
        let mut cache: BTreeMap<
            String,
            std::sync::Arc<rustmc_worldgen::structure::template::Template>,
        > = BTreeMap::new();
        for city in end_city_report(seed, area)? {
            for piece in &city.pieces {
                let template = if let Some(t) = cache.get(&piece.template) {
                    t.clone()
                } else {
                    let path = dir.join(format!("{}.nbt", piece.template));
                    let file = std::fs::File::open(&path)
                        .map_err(|e| format!("{}: {e}", path.display()))?;
                    let mut reader = flate2::read::GzDecoder::new(file);
                    let (_n, root) = rustmc_world::nbt::read_named_root(&mut reader)
                        .map_err(|e| format!("{}: {e}", path.display()))?;
                    let t = std::sync::Arc::new(
                        rustmc_worldgen::structure::template::Template::from_nbt(&root)
                            .map_err(|e| format!("{}: {}", path.display(), e.0))?,
                    );
                    cache.insert(piece.template.clone(), t.clone());
                    t
                };
                for block in &template.blocks {
                    let Some(marker) = block.marker.as_deref() else {
                        continue;
                    };
                    let r = transform(block.pos, Mirror::None, piece.rotation, (0, 0));
                    let at = (piece.pos.0 + r.0, piece.pos.1 + r.1, piece.pos.2 + r.2);
                    if marker.starts_with("Sentry") {
                        push("end_city", "minecraft:shulker", at, None, Some(1));
                    } else if marker.starts_with("Elytra") {
                        // `rotation.rotate(Direction.SOUTH)`.
                        let facing = match piece.rotation {
                            Rotation::None => "south",
                            Rotation::Clockwise90 => "west",
                            Rotation::Clockwise180 => "north",
                            Rotation::Counterclockwise90 => "east",
                        };
                        push(
                            "end_city",
                            "minecraft:item_frame",
                            at,
                            Some(facing),
                            Some(1),
                        );
                    }
                }
            }
        }
        return Ok(out);
    }
    for mansion in mansion_report(seed, area)? {
        for placed in &mansion.pieces {
            for block in &placed.template.blocks {
                let id = match block.marker.as_deref() {
                    Some("Mage") => "minecraft:evoker",
                    Some("Warrior") => "minecraft:vindicator",
                    Some("Group of Allays") => "minecraft:allay",
                    _ => continue,
                };
                let p = &placed.piece;
                let r = transform(block.pos, p.mirror, p.rotation, (0, 0));
                let at = (p.pos.0 + r.0, p.pos.1 + r.1, p.pos.2 + r.2);
                let count = if id == "minecraft:allay" {
                    None
                } else {
                    Some(1)
                };
                push("mansion", id, at, None, count);
            }
        }
    }
    for monument in monument_report(seed, area)? {
        for room in &monument.rooms {
            let local = match room.kind {
                RoomKind::Penthouse => (6, 1, 6),
                RoomKind::Wing { main_design: 0 } => (11, 2, 16),
                RoomKind::Wing { main_design: 1 } => (11, 5, 13),
                _ => continue,
            };
            let at = room.piece.world_pos(local.0, local.1, local.2);
            push("monument", "minecraft:elder_guardian", at, None, Some(1));
        }
    }
    Ok(out)
}

/// One End city, assembled but not yet written.
///
/// Built once for the whole generated area, like a village and for the same
/// reason: a city reaches well past its own chunk, so every chunk it touches
/// has to write the *same* pieces, and re-running the walk per chunk would
/// re-draw a 70-piece random sequence 200 times for one answer.
pub struct EndCity {
    pub start_chunk: (i32, i32),
    pub pieces: Vec<rustmc_worldgen::structure::end_city::Piece>,
    pub union_box: rustmc_worldgen::structure::pieces::BoundingBox,
}

/// Every End city whose pieces can reach `area`.
///
/// `end_cities.json` is a one-entry structure set, so there is no weighted
/// attempt order to make: the placement grid picks a chunk, one
/// `LegacyRandomSource(0)` is seeded with `setLargeFeatureSeed(seed, cx, cz)`,
/// and `EndCityStructure.findGenerationPoint` draws the rotation **first** —
/// before it takes a height — and then refuses anything under y=60.
///
/// # The two gates, in vanilla's order
///
/// `Structure.findValidGenerationPoint` is
/// `findGenerationPoint(ctx).filter(isValidBiome)`, so the height gate runs
/// first and the biome gate second, at the stub position in quart
/// coordinates. The order is free here — neither gate draws — but it is
/// written in vanilla's order anyway, because the day one of them gains a
/// draw the other way round becomes a silent divergence.
///
/// # Errors
/// If the extract is present but malformed.
pub fn end_city_starts<B, H>(
    seed: i64,
    area: Area,
    biome_at: &mut B,
    height_at: H,
) -> Result<Vec<EndCity>, String>
where
    B: FnMut(i32, i32, i32) -> String,
    H: Fn(i32, i32) -> Option<i32>,
{
    use rustmc_worldgen::rng::legacy::LegacyRandomSource;
    use rustmc_worldgen::rng::worldgen_random::WorldgenRandom;
    use rustmc_worldgen::structure::end_city;
    use rustmc_worldgen::structure::placement::StructurePlacement;

    let set_path = format!("{}/worldgen/structure_set/end_cities.json", crate::DATA);
    let Ok(text) = std::fs::read_to_string(&set_path) else {
        return Ok(Vec::new());
    };
    let json: serde_json::Value =
        serde_json::from_str(&text).map_err(|e| format!("{set_path}: {e}"))?;
    let placement = StructurePlacement::parse(&json["placement"])?;

    let def_path = format!("{}/worldgen/structure/end_city.json", crate::DATA);
    let def: serde_json::Value =
        serde_json::from_str(&std::fs::read_to_string(&def_path).map_err(|e| e.to_string())?)
            .map_err(|e| format!("{def_path}: {e}"))?;
    let tag = def["biomes"]
        .as_str()
        .and_then(|b| b.strip_prefix('#'))
        .and_then(|b| b.strip_prefix("minecraft:"))
        .ok_or_else(|| format!("{def_path}: `biomes` is not a namespaced tag"))?;
    let biomes = crate::facts::resolve_biome_tag(tag)?;

    let template_dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../data/vanilla/structure/end_city");
    if !template_dir.is_dir() {
        return Ok(Vec::new());
    }
    let mut cache: BTreeMap<
        String,
        Option<std::sync::Arc<rustmc_worldgen::structure::template::Template>>,
    > = BTreeMap::new();

    // The widest reach measured on a real city is ~7 chunks from the start,
    // and a bridge that catches a ship adds 70 blocks on one axis. 12 is
    // generous rather than derived — the placement test rejects 399 of every
    // 400 chunks before a template is opened, so the cost of being generous
    // is nothing and the cost of being tight is a city sliced off at the
    // window edge.
    let reach = 12;
    let mut out = Vec::new();
    for cx in (area.min_chunk_x - reach)..=(area.max_chunk_x + reach) {
        for cz in (area.min_chunk_z - reach)..=(area.max_chunk_z + reach) {
            if !placement
                .is_placement_chunk(seed, cx, cz)
                .map_err(|e| format!("{e:?}"))?
            {
                continue;
            }
            let mut random = WorldgenRandom::new(LegacyRandomSource::new(0));
            random.set_large_feature_seed(seed, cx, cz);
            let rotation = rustmc_worldgen::structure::jigsaw::random_rotation(&mut random);
            // A city whose height gate asked for a column this canvas does
            // not have is a city this window cannot decide. Skipping it is
            // the honest answer — the alternative is a city built against a
            // height that was never generated.
            let Some(stub) = end_city::generation_point(cx, cz, rotation, &height_at) else {
                continue;
            };
            let biome = biome_at(stub.0 >> 2, stub.1 >> 2, stub.2 >> 2);
            if !biomes.contains(&biome) {
                continue;
            }
            let mut load = |name: &str| -> Option<std::sync::Arc<_>> {
                if let Some(hit) = cache.get(name) {
                    return hit.clone();
                }
                let path = template_dir.join(format!("{name}.nbt"));
                let loaded = std::fs::File::open(&path).ok().and_then(|file| {
                    let mut reader = flate2::read::GzDecoder::new(file);
                    let (_n, root) = rustmc_world::nbt::read_named_root(&mut reader).ok()?;
                    rustmc_worldgen::structure::template::Template::from_nbt(&root)
                        .ok()
                        .map(std::sync::Arc::new)
                });
                cache.insert(name.to_string(), loaded.clone());
                loaded
            };
            let pieces = end_city::start_house_tower(&mut load, stub, rotation, &mut random)
                .map_err(|missing| format!("end_city: no template `{missing}` in the extract"))?;
            let boxes: Vec<_> = pieces.iter().map(|p| p.bbox).collect();
            let Some(union_box) =
                rustmc_worldgen::structure::pieces::BoundingBox::encapsulating(&boxes)
            else {
                continue;
            };
            out.push(EndCity {
                start_chunk: (cx, cz),
                pieces,
                union_box,
            });
        }
    }
    Ok(out)
}

/// Write the pieces of one End city that fall inside this chunk.
///
/// `StructureStart.placeInChunk` walks the piece list **in order**, so a later
/// piece overwrites an earlier one where they touch — and an End city relies
/// on that: a `tower_piece` is stacked straight onto the one below it.
///
/// The processor chain is `EndCityPiece.makeSettings` exactly: one
/// `BlockIgnoreProcessor`, chosen by the `overwrite` flag the walk recorded,
/// and nothing else. Not `settings_processors`, which is a pool element's
/// chain and would add a jigsaw replacement no End city template has a use
/// for.
fn place_end_city_in_chunk(
    world: &mut rustmc_worldgen::stage::decorate::Decoration<'_>,
    city: &EndCity,
    templates: &std::sync::Mutex<
        BTreeMap<String, Option<std::sync::Arc<rustmc_worldgen::structure::template::Template>>>,
    >,
    dir: &std::path::Path,
    clip: rustmc_worldgen::structure::pieces::BoundingBox,
    random: &mut dyn rustmc_worldgen::rng::RandomSource,
) {
    use rustmc_worldgen::block_entity::BlockEntityRecorder;
    use rustmc_worldgen::structure::place::{
        place_piece, structure_and_air, structure_block, PieceWorld,
    };
    use rustmc_worldgen::structure::writer::StructureWorld;

    struct View<'w, 'a> {
        world: &'w mut rustmc_worldgen::stage::decorate::Decoration<'a>,
    }
    // `Decoration` already implements the recorder; this view exists only to
    // narrow what a piece may touch, so it forwards rather than deciding.
    impl rustmc_worldgen::block_entity::BlockEntityRecorder for View<'_, '_> {
        fn record_block_entity(
            &mut self,
            x: i32,
            y: i32,
            z: i32,
            record: rustmc_worldgen::block_entity::Record,
        ) {
            self.world.record_block_entity(x, y, z, record);
        }
    }
    impl PieceWorld for View<'_, '_> {
        fn block_at(&mut self, x: i32, y: i32, z: i32) -> String {
            use rustmc_worldgen::structure::writer::StructureWorld;
            self.world.block_at(x, y, z)
        }
        fn set_block(&mut self, x: i32, y: i32, z: i32, state: &str) {
            use rustmc_worldgen::structure::writer::StructureWorld;
            self.world.set_block(x, y, z, state);
        }
        fn world_surface_wg(&mut self, x: i32, z: i32) -> i32 {
            self.world.world_surface_wg(x, z)
        }
        fn block_in_tag(&self, tag: &str, block: &str) -> bool {
            self.world.block_tags().contains(tag, block)
        }
        // `BlockStateParser.parseForBlock` needs the block's default state.
        // Without it the jigsaw replacement writes `final_state` verbatim and
        // loses every property the string does not name.
        fn default_state(&self, block: &str) -> Option<String> {
            self.world.default_state(block)
        }
        // The two block-shape questions the shape update asks of an end city:
        // a ladder's wall, and the block a wall banner hangs on.
        fn face_is_sturdy(&self, state: &str, direction: usize) -> Option<bool> {
            self.world.block_face_is_sturdy(state, direction)
        }
        fn is_solid(&self, state: &str) -> Option<bool> {
            self.world.block_is_solid(state)
        }
    }

    for piece in &city.pieces {
        if !piece.bbox.intersects(clip) {
            continue;
        }
        let template = {
            let mut lock = templates.lock().expect("the end city template lock");
            if let Some(hit) = lock.get(&piece.template) {
                hit.clone()
            } else {
                let path = dir.join(format!("{}.nbt", piece.template));
                let loaded = std::fs::File::open(&path).ok().and_then(|file| {
                    let mut reader = flate2::read::GzDecoder::new(file);
                    let (_n, root) = rustmc_world::nbt::read_named_root(&mut reader).ok()?;
                    rustmc_worldgen::structure::template::Template::from_nbt(&root)
                        .ok()
                        .map(std::sync::Arc::new)
                });
                lock.insert(piece.template.clone(), loaded.clone());
                loaded
            }
        };
        let Some(template) = template else { continue };
        let chain = if piece.overwrite {
            vec![structure_block()]
        } else {
            vec![structure_and_air()]
        };
        if rustmc_worldgen::canvas::tracing_writes() {
            rustmc_worldgen::canvas::set_writer(&format!(
                "end_city into chunk ({}, {})",
                clip.min_x >> 4,
                clip.min_z >> 4
            ));
        }
        let mut view = View { world };
        place_piece(
            &mut view,
            &template,
            rustmc_worldgen::structure::place::PieceOrigin::unthreaded(piece.pos),
            // `EndCityPiece.makeSettings` is `setIgnoreEntities`, `addProcessor`
            // and `setRotation` — never `setKnownShape(true)` — so vanilla's
            // `placeInWorld` runs `updateFromNeighbourShapes` over every block
            // it wrote. Without it a stair kept its template shape: seed
            // 20260722 c(107,-37), (1713,72,-581) `outer_right` against
            // `straight` in all three vanilla worlds.
            rustmc_worldgen::structure::place::PlaceSettings::new(piece.rotation)
                .with_shape_update(),
            &chain,
            clip,
            // `placeInWorld` spends one `nextLong` on each template chest
            // (their tags are `{Items:[]}`) on the postProcess stream.
            Some(&mut *random),
        );
        // `filterBlocks(templatePosition, placeSettings, STRUCTURE_BLOCK)`,
        // then `EndCityPiece.handleDataMarker` for each DATA marker, in
        // template order. Only `Chest` touches a block entity: `Sentry` (a
        // shulker) and `Elytra` (an item frame) are entities and draw nothing
        // from this stream.
        for block in &template.blocks {
            let Some(marker) = block.marker.as_deref() else {
                continue;
            };
            if marker.starts_with("Sentry") || marker.starts_with("Elytra") {
                // `chunkBB.isInside(pos) && Level.isInSpawnableBounds(pos)`,
                // then a shulker at the block's centre (no `finalizeSpawn`,
                // no draw), or the ship's elytra frame facing
                // `rotation.rotate(SOUTH)`.
                use rustmc_worldgen::structure::spawned::{elytra_frame, mob_compound, uuid, Mob};
                let r = rustmc_worldgen::structure::template::transform(
                    block.pos,
                    rustmc_worldgen::structure::template::Mirror::None,
                    piece.rotation,
                    (0, 0),
                );
                let at = (piece.pos.0 + r.0, piece.pos.1 + r.1, piece.pos.2 + r.2);
                if !clip.is_inside(at.0, at.1, at.2)
                    || at.1 < END_MIN_Y
                    || at.1 >= END_MIN_Y + END_STORAGE_HEIGHT
                {
                    continue;
                }
                let entity = if marker.starts_with("Sentry") {
                    mob_compound(Mob::Shulker, at, None, uuid(Mob::Shulker.id(), at, 0))
                } else {
                    use rustmc_worldgen::structure::template::Rotation;
                    let facing = match piece.rotation {
                        Rotation::None => 3,
                        Rotation::Clockwise90 => 4,
                        Rotation::Clockwise180 => 2,
                        Rotation::Counterclockwise90 => 5,
                    };
                    elytra_frame(at, facing, uuid("minecraft:item_frame", at, 0))
                };
                view.world.record_entity(entity);
                continue;
            }
            if !marker.starts_with("Chest") {
                continue;
            }
            let r = rustmc_worldgen::structure::template::transform(
                block.pos,
                rustmc_worldgen::structure::template::Mirror::None,
                piece.rotation,
                (0, 0),
            );
            // `pos.below()`, and the chunk box is asked about THAT position.
            let (x, y, z) = (piece.pos.0 + r.0, piece.pos.1 + r.1 - 1, piece.pos.2 + r.2);
            if !clip.is_inside(x, y, z) {
                continue;
            }
            // `RandomizableContainer.setBlockEntityLootTable`: the draw is
            // spent only if a container's block entity is there.
            let here = view.world.block_at(x, y, z);
            if !matches!(
                here.split('[').next().unwrap_or(""),
                "minecraft:chest" | "minecraft:trapped_chest" | "minecraft:barrel"
            ) {
                continue;
            }
            let seed = random.next_i64();
            view.world.record_block_entity(
                x,
                y,
                z,
                rustmc_worldgen::block_entity::Record {
                    nbt: BTreeMap::from([(
                        "LootTable".to_string(),
                        rustmc_world::nbt::Nbt::String("minecraft:chests/end_city_treasure".into()),
                    )]),
                    loot_seed: Some(seed),
                },
            );
        }
        if rustmc_worldgen::canvas::tracing_writes() {
            rustmc_worldgen::canvas::set_writer("");
        }
    }
}

/// A named processor list, read once and kept.
///
/// `village/savanna` alone reaches `street_savanna`, `zombie_savanna` and
/// `farm_savanna`, and a savanna village places 181 pieces, so this is read
/// three times instead of a hundred and eighty-one.
pub struct ProcessorLists {
    cache: BTreeMap<String, Vec<rustmc_worldgen::structure::place::Processor>>,
}

impl ProcessorLists {
    #[must_use]
    pub const fn new() -> Self {
        Self {
            cache: BTreeMap::new(),
        }
    }

    /// The element's list, resolved. `Err` names an unported processor rather
    /// than silently placing the piece without it.
    ///
    /// # Errors
    /// If the list names a processor or a rule test this port does not have.
    pub fn resolve(
        &mut self,
        processors: Option<&rustmc_worldgen::structure::template_pool::Processors>,
    ) -> Result<Vec<rustmc_worldgen::structure::place::Processor>, String> {
        use rustmc_worldgen::structure::place::Processor;
        use rustmc_worldgen::structure::template_pool::Processors;
        match processors {
            None => Ok(Vec::new()),
            Some(Processors::Inline(value)) => {
                Processor::parse_list(value).map_err(|e| format!("inline processor list: {}", e.0))
            }
            Some(Processors::Named(name)) => {
                if let Some(hit) = self.cache.get(name) {
                    return Ok(hit.clone());
                }
                let rel = name.strip_prefix("minecraft:").unwrap_or(name);
                let path = crate::data_path(&format!("worldgen/processor_list/{rel}.json"));
                let text = std::fs::read_to_string(&path)
                    .map_err(|e| format!("{}: {e}", path.display()))?;
                let value: serde_json::Value =
                    serde_json::from_str(&text).map_err(|e| format!("{}: {e}", path.display()))?;
                let list = Processor::parse_list(&value)
                    .map_err(|e| format!("{}: {}", path.display(), e.0))?;
                self.cache.insert(name.clone(), list.clone());
                Ok(list)
            }
        }
    }
}

impl Default for ProcessorLists {
    fn default() -> Self {
        Self::new()
    }
}

/// How much of vanilla's piece-stream threading is turned on.
///
/// **`RUSTMC_JIGSAW_STREAM` is unset by default and that is deliberate.**
/// Threading a stream into `place_piece` adds draws, and draws are draw order;
/// this project's rule is that new behaviour lands opt-in until it has been
/// measured, and the measurement this knob exists for is
/// `docs/DETERMINISM.md` §44. The three settings are a decomposition, not a
/// preference:
///
/// * **`Off`** — exactly the code that shipped before this knob. `place_piece`
///   gets `None`, no jigsaw container spends a `nextLong`, and the starts are
///   walked in whatever order the start list holds them.
/// * **`Stream`** (`1`) — the stream is threaded and nothing else moves. One
///   `WorldgenRandom` per structure id, `setFeatureSeed(population, index,
///   step)`, shared by every start of that structure the way
///   `startsForStructure(..).forEach(..)` shares one. **The start walk order is
///   left exactly as `Off` had it**, so a diff between `Off` and `Stream`
///   isolates the draws and nothing else.
/// * **`Faithful`** (`2`) — `Stream`, plus the two orders vanilla actually
///   imposes: structures visited in ascending step index, and the starts of one
///   structure walked in `LongOpenHashSet` iteration order, which is what
///   `StructureManager.startsForStructure` yields. This is the one that could
///   move a block by deciding which of two overlapping starts writes last, and
///   it is separated from `Stream` for exactly that reason.
#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
enum JigsawStream {
    Off,
    Stream,
    Faithful,
}

impl JigsawStream {
    fn from_env() -> Self {
        match std::env::var("RUSTMC_JIGSAW_STREAM")
            .unwrap_or_default()
            .trim()
        {
            "1" => Self::Stream,
            "2" => Self::Faithful,
            // Anything else, the empty string included, is off. An
            // unrecognised value is **not** silently promoted to on: ORACLE
            // rule 30 — an unrecognised knob is not a turned one, and the
            // decorate-order ladder has paid for that once already.
            _ => Self::Off,
        }
    }
}

/// Write every start of a jigsaw structure that reaches this chunk.
///
/// `starts` may hold more than one structure id — the five village variants
/// arrive interleaved — and vanilla treats each id as its own group with its
/// own stream, because `applyBiomeDecoration` reseeds per structure before
/// handing that structure's starts to `placeInChunk`.
#[expect(
    clippy::too_many_arguments,
    reason = "the seeding needs the population seed, the step and the derived \
              index table, and hiding them in a struct would put the stream's \
              three inputs one indirection away from the call that spends them"
)]
fn place_jigsaw_starts(
    world: &mut rustmc_worldgen::stage::decorate::Decoration<'_>,
    starts: &[Village],
    lists: &std::sync::Mutex<ProcessorLists>,
    clip: rustmc_worldgen::structure::pieces::BoundingBox,
    unplaceable: &std::sync::Mutex<Vec<String>>,
    population: i64,
    step_index_table: &std::collections::BTreeMap<
        String,
        rustmc_worldgen::structure::step_index::StepIndex,
    >,
    step: i32,
) {
    place_jigsaw_starts_with(
        world,
        starts,
        lists,
        clip,
        unplaceable,
        population,
        step_index_table,
        step,
        None,
    );
}

/// What a start needs to run its `feature_pool_element`s: the configured
/// features and the block tags they read.
///
/// Handing this to [`place_jigsaw_starts_with`] also forces the piece stream
/// to `Faithful` for those starts, because `FeaturePoolElement.place` draws
/// from the same `RandomSource` every container's `LootTableSeed` comes from:
/// a feature element run without the stream has no draws to spend, and the
/// stream run without the feature elements is desynced at the first one. The
/// villages and bastions pass `None` and keep the shipped default
/// (`RUSTMC_JIGSAW_STREAM`, unset = `Off`); the ancient city is the first
/// structure that passes `Some`, and it had no shipped output to preserve.
#[derive(Clone, Copy)]
struct FeatureElements<'a> {
    configured: &'a std::collections::BTreeMap<
        String,
        rustmc_worldgen::feature::configured::ConfiguredFeature,
    >,
    tags: &'a rustmc_worldgen::tags::BlockTags,
}

#[expect(
    clippy::too_many_arguments,
    reason = "place_jigsaw_starts's arguments plus the feature elements"
)]
fn place_jigsaw_starts_with(
    world: &mut rustmc_worldgen::stage::decorate::Decoration<'_>,
    starts: &[Village],
    lists: &std::sync::Mutex<ProcessorLists>,
    clip: rustmc_worldgen::structure::pieces::BoundingBox,
    unplaceable: &std::sync::Mutex<Vec<String>>,
    population: i64,
    step_index_table: &std::collections::BTreeMap<
        String,
        rustmc_worldgen::structure::step_index::StepIndex,
    >,
    step: i32,
    features: Option<FeatureElements<'_>>,
) {
    let mode = if features.is_some() {
        JigsawStream::Faithful
    } else {
        JigsawStream::from_env()
    };
    let trace = std::env::var("RUSTMC_JIGSAW_TRACE").is_ok_and(|v| v.trim() == "1");
    let index_of = |id: &str| -> i32 {
        step_index_table
            .get(&format!("minecraft:{id}"))
            .and_then(|s| i32::try_from(s.index).ok())
            .unwrap_or(0)
    };

    if mode == JigsawStream::Off {
        for start in starts {
            if !start.union_box.intersects(clip) {
                continue;
            }
            place_village_in_chunk(world, start, lists, clip, unplaceable, None, None, None);
        }
        return;
    }

    if mode == JigsawStream::Stream {
        // **THE VISIT ORDER HERE MUST BE BIT-FOR-BIT THE `Off` ONE, AND A
        // GROUPED LOOP IS NOT.** The first version of this function grouped by
        // structure id in both modes, which walks the five village variants one
        // variant at a time where `Off` walks them interleaved. `off` against
        // `stream` would then have measured a reorder and the draws together
        // and reported the sum as the cost of the draws — the whole point of
        // having three arms rather than two. Caught before it produced a
        // number. So the streams are created lazily and keyed by structure, and
        // the loop below is the `Off` loop with a stream handed to it.
        let mut streams: std::collections::BTreeMap<
            String,
            rustmc_worldgen::rng::worldgen_random::WorldgenRandom<
                rustmc_worldgen::rng::xoroshiro::XoroshiroRandomSource,
            >,
        > = std::collections::BTreeMap::new();
        let mut draws: std::collections::BTreeMap<String, u64> = std::collections::BTreeMap::new();
        // The audit's counters are pre-created per structure id rather than
        // lazily like the streams, because a `StreamAudit` borrows its tally:
        // growing the tally map while an audit holds a reference into it is
        // the one thing this shape must not do. The id set is known from
        // `starts` before the walk, so there is nothing lazy to gain.
        let audit_ids: std::collections::BTreeSet<String> = if trace {
            starts
                .iter()
                .filter(|s| s.union_box.intersects(clip))
                .map(|s| s.structure.clone())
                .collect()
        } else {
            std::collections::BTreeSet::new()
        };
        let tallies: std::collections::BTreeMap<String, std::cell::Cell<u64>> = audit_ids
            .iter()
            .map(|id| (id.clone(), std::cell::Cell::new(0u64)))
            .collect();
        let mut audits: std::collections::BTreeMap<String, StreamAudit<'_>> = audit_ids
            .iter()
            .map(|id| {
                (
                    id.clone(),
                    StreamAudit {
                        tally: &tallies[id],
                        refusals: 0,
                        first_refusal_at: None,
                    },
                )
            })
            .collect();
        for start in starts {
            if !start.union_box.intersects(clip) {
                continue;
            }
            let random = streams.entry(start.structure.clone()).or_insert_with(|| {
                let mut r = rustmc_worldgen::rng::worldgen_random::WorldgenRandom::new(
                    rustmc_worldgen::rng::xoroshiro::XoroshiroRandomSource::from_seed(0),
                );
                r.set_feature_seed(population, index_of(&start.structure), step);
                r
            });
            let mut counted = DrawCounter {
                inner: random,
                draws: 0,
                tally: tallies.get(&start.structure),
            };
            place_village_in_chunk(
                world,
                start,
                lists,
                clip,
                unplaceable,
                Some(&mut counted),
                audits.get_mut(&start.structure),
                features,
            );
            *draws.entry(start.structure.clone()).or_insert(0) += counted.draws;
        }
        if trace {
            for (id, spent) in &draws {
                println!(
                    "JIGSAW-STREAM structure={id} step={step} index={} starts={} chunk=({},{}) \
                     draws={spent} refusals={} downstream_draws={}",
                    index_of(id),
                    starts
                        .iter()
                        .filter(|s| &s.structure == id && s.union_box.intersects(clip))
                        .count(),
                    clip.min_x >> 4,
                    clip.min_z >> 4,
                    audits.get(id).map_or(0, |a| a.refusals),
                    audits.get(id).map_or(0, |a| a.downstream_draws()),
                );
            }
        }
        return;
    }

    // `Faithful`: the two orders vanilla imposes, as well as the draws.
    // Structures in ascending step index, because `applyBiomeDecoration` walks
    // the registry grouped by step and counts within the group; then the starts
    // of one structure in the order `StructureManager.startsForStructure`
    // yields them. This is the arm that can move a block without any draw
    // being involved, by deciding which of two overlapping starts writes last.
    let mut groups: Vec<(&str, Vec<&Village>)> = Vec::new();
    for start in starts {
        if !start.union_box.intersects(clip) {
            continue;
        }
        if let Some(slot) = groups.iter_mut().find(|(id, _)| *id == start.structure) {
            slot.1.push(start);
        } else {
            groups.push((start.structure.as_str(), vec![start]));
        }
    }
    groups.sort_by_key(|(id, _)| index_of(id));
    for (_, group) in &mut groups {
        // The chunk's reference set is a fastutil `LongOpenHashSet` keyed on
        // the start's chunk — neither insertion nor sorted order. The mineshaft
        // path above models the same set for the same reason.
        let mut refs = rustmc_worldgen::fastutil_long_set::LongOpenHashSet::new();
        for start in group.iter() {
            let (sx, sz) = start.start_chunk;
            if let Err(e) = refs.add(rustmc_worldgen::fastutil_long_set::chunk_pos_as_long(
                sx, sz,
            )) {
                unplaceable.lock().expect("the refusal lock").push(e);
            }
        }
        let mut ordered: Vec<&Village> = Vec::new();
        for packed in refs.iter_order() {
            ordered.extend(group.iter().copied().filter(|s| {
                rustmc_worldgen::fastutil_long_set::chunk_pos_as_long(
                    s.start_chunk.0,
                    s.start_chunk.1,
                ) == packed
            }));
        }
        *group = ordered;
    }

    for (id, group) in &groups {
        let mut random = rustmc_worldgen::rng::worldgen_random::WorldgenRandom::new(
            rustmc_worldgen::rng::xoroshiro::XoroshiroRandomSource::from_seed(0),
        );
        random.set_feature_seed(population, index_of(id), step);
        let tally = std::cell::Cell::new(0u64);
        let mut audit = StreamAudit {
            tally: &tally,
            refusals: 0,
            first_refusal_at: None,
        };
        let mut counted = DrawCounter {
            inner: &mut random,
            draws: 0,
            tally: if trace { Some(&tally) } else { None },
        };
        for start in group {
            place_village_in_chunk(
                world,
                start,
                lists,
                clip,
                unplaceable,
                Some(&mut counted),
                if trace { Some(&mut audit) } else { None },
                features,
            );
        }
        if trace {
            println!(
                "JIGSAW-STREAM structure={id} step={step} index={} starts={} chunk=({},{}) \
                 draws={} refusals={} downstream_draws={}",
                index_of(id),
                group.len(),
                clip.min_x >> 4,
                clip.min_z >> 4,
                counted.draws,
                audit.refusals,
                audit.downstream_draws(),
            );
        }
    }
}

/// Write the pieces of one village that fall inside this chunk.
///
/// `StructureStart.placeInChunk` walks the piece list **in order** and calls
/// `postProcess` on every piece whose box intersects the chunk box, so a later
/// piece overwrites an earlier one where they touch. That order is the order
/// `addPieces` built, which is the order the region file records — the same
/// list the 181-piece gate compares index for index.
#[expect(
    clippy::too_many_arguments,
    reason = "the start, its clip and stream, and the feature elements it may run"
)]
fn place_village_in_chunk(
    world: &mut rustmc_worldgen::stage::decorate::Decoration<'_>,
    village: &Village,
    lists: &std::sync::Mutex<ProcessorLists>,
    clip: rustmc_worldgen::structure::pieces::BoundingBox,
    unplaceable: &std::sync::Mutex<Vec<String>>,
    // See `place_piece`'s own parameter: the trait object needs a lifetime of
    // its own or a per-piece reborrow demands the stream outlive this call.
    mut random: Option<&mut (dyn rustmc_worldgen::rng::RandomSource + '_)>,
    // Assembled only under `RUSTMC_JIGSAW_TRACE=1`; `None` everywhere else, so
    // a traced run and an untraced one spend exactly the same draws.
    mut audit: Option<&mut StreamAudit<'_>>,
    features: Option<FeatureElements<'_>>,
) {
    use rustmc_worldgen::structure::jigsaw::ElementKind;
    use rustmc_worldgen::structure::place::{
        place_piece, settings_processors, start_reference_pos, PieceOrigin, PieceWorld,
    };

    // `StructureStart.placeInChunk` computes this **once for the whole
    // start**, before the piece loop, from piece zero's bounding box — so
    // every piece of this village or bastion is processed against the same
    // position, including the ones a hundred blocks away from it.
    //
    // Computed here rather than carried on the start because this is where
    // vanilla computes it: it is a property of the placement pass, not of the
    // assembled layout, and putting it on the struct would invite a second
    // caller to recompute it from a different piece.
    let Some(first) = village.pieces.first() else {
        return;
    };
    let reference = start_reference_pos(first.bbox);

    struct Piece<'w, 'a> {
        world: &'w mut rustmc_worldgen::stage::decorate::Decoration<'a>,
    }
    // `Decoration` already implements the recorder; this view exists only to
    // narrow what a piece may touch, so it forwards rather than deciding.
    impl rustmc_worldgen::block_entity::BlockEntityRecorder for Piece<'_, '_> {
        fn record_block_entity(
            &mut self,
            x: i32,
            y: i32,
            z: i32,
            record: rustmc_worldgen::block_entity::Record,
        ) {
            self.world.record_block_entity(x, y, z, record);
        }
    }
    impl PieceWorld for Piece<'_, '_> {
        fn block_at(&mut self, x: i32, y: i32, z: i32) -> String {
            use rustmc_worldgen::structure::writer::StructureWorld;
            self.world.block_at(x, y, z)
        }
        fn set_block(&mut self, x: i32, y: i32, z: i32, state: &str) {
            use rustmc_worldgen::structure::writer::StructureWorld;
            self.world.set_block(x, y, z, state);
        }
        fn world_surface_wg(&mut self, x: i32, z: i32) -> i32 {
            self.world.world_surface_wg(x, z)
        }
        fn block_in_tag(&self, tag: &str, block: &str) -> bool {
            self.world.block_tags().contains(tag, block)
        }
        // `BlockStateParser.parseForBlock` needs the block's default state.
        // Without it the jigsaw replacement writes `final_state` verbatim and
        // loses every property the string does not name.
        fn default_state(&self, block: &str) -> Option<String> {
            self.world.default_state(block)
        }
        // `CappedProcessor` forks off the world seed (the trail ruins'
        // archaeology lists).
        fn world_seed(&self) -> Option<i64> {
            Some(self.world.world_seed())
        }
    }

    for piece in &village.pieces {
        if !piece.bbox.intersects(clip) {
            continue;
        }
        // `ListPoolElement.place` places each element in order, at the
        // piece's own position and rotation, and every one of them carries
        // the list's projection already. One piece, several templates.
        let parts: Vec<&rustmc_worldgen::structure::jigsaw::Element> = match &piece.element.kind {
            ElementKind::List { elements } => elements.iter().collect(),
            _ => vec![&*piece.element],
        };
        for part in parts {
            let ElementKind::Single {
                template,
                processors,
                legacy,
                ..
            } = &part.kind
            else {
                // **A feature pool element writes blocks, and for a long time
                // this comment said it did not.** `FeaturePoolElement.place` is
                // one call — `this.feature.value().place(level, generator,
                // random, pos)`, bytecode offsets 0..22 — and it runs a whole
                // placed feature. The savanna villages' 22 of them are
                // `minecraft:pile_hay`, `minecraft:pile_melon` and
                // `minecraft:acacia`.
                //
                // The blocker used to be recorded here as a stream position. It
                // is not one any more and had already stopped being one when this
                // was written: `structure_step_indices()` derives the index from
                // the datapack, the caller seeds `setFeatureSeed(population,
                // index, 4)` off it exactly as the ruined portals do, and
                // `place_piece` now advances that stream by the `nextLong()` each
                // `RandomizableContainer` costs. The comment outlived its own
                // fix, which is the failure mode AGENT-BRIEF calls a stale caveat
                // reading as authoritative.
                //
                // The name resolves through `Registries.PLACED_FEATURE` — the
                // codec is `PlacedFeature.CODEC.fieldOf("feature")` — so it is
                // `worldgen/placed_feature/<name>.json` and not the configured
                // feature of the same name. `acacia`'s placement chain carries a
                // `would_survive(acacia_sapling)` filter that can decline the
                // whole feature; `pile_hay`'s is empty.
                //
                // A feature this port cannot place is still refused out loud
                // rather than skipped, and the refusal names the feature. An
                // empty element really does write nothing and is not refused.
                if let ElementKind::Feature { feature } = &part.kind {
                    if let (Some(ctx), Some(r)) = (features, random.as_deref_mut()) {
                        match place_feature_element(world, ctx, feature, piece.pos, r) {
                            Ok(()) => continue,
                            Err(e) => unplaceable.lock().expect("the refusal lock").push(e),
                        }
                        if let Some(a) = audit.as_deref_mut() {
                            a.note_refusal();
                        }
                        continue;
                    }
                    // **And it desyncs the piece stream from this point on.**
                    // `FeaturePoolElement.place` spends the whole placed feature's
                    // draws on the *same* `RandomSource` the containers take their
                    // `LootTableSeed` from, so once `random` is threaded (below), a
                    // refused feature element leaves every later container in this
                    // start reading a stream vanilla has moved further along. That
                    // is why the seed is only quotable for a structure whose pools
                    // hold no feature element at all: `trial_chambers` holds none,
                    // and 13 of vanilla's 188 template pools — every one of them a
                    // village `decor` or `trees` pool — hold one.
                    unplaceable.lock().expect("the refusal lock").push(format!(
                        "a `{feature}` feature pool element: the placed feature is \
                     unported (its stream index is known — step 4, index 23), \
                     and its unspent draws desync this start's piece stream"
                    ));
                    // The count is taken HERE, before any later piece of this
                    // start draws, because "later" is the whole distinction the
                    // audit exists to make.
                    if let Some(a) = audit.as_deref_mut() {
                        a.note_refusal();
                    }
                }
                continue;
            };
            let element = match lists
                .lock()
                .expect("the processor-list lock")
                .resolve(processors.as_ref())
            {
                Ok(list) => list,
                Err(e) => {
                    unplaceable.lock().expect("the refusal lock").push(e);
                    continue;
                }
            };
            let chain = settings_processors(*legacy, false, &element, part.projection);
            if rustmc_worldgen::canvas::tracing_writes() {
                rustmc_worldgen::canvas::set_writer(&format!(
                    "{} into chunk ({}, {})",
                    village.structure,
                    clip.min_x >> 4,
                    clip.min_z >> 4
                ));
            }
            let mut view = Piece { world };
            place_piece(
                &mut view,
                template,
                PieceOrigin::new(piece.pos, reference),
                rustmc_worldgen::structure::place::PlaceSettings::new(piece.rotation),
                &chain,
                clip,
                // `StructureStart.placeInChunk` hands **one** `RandomSource` to
                // every piece of the start in turn, so this is the same borrow
                // reissued per piece rather than a stream per piece.
                random.as_deref_mut(),
            );
            if rustmc_worldgen::canvas::tracing_writes() {
                rustmc_worldgen::canvas::set_writer("");
            }
        }
    }
}

/// `FeaturePoolElement.place` — `this.feature.value().place(level,
/// generator, random, pos)`: the placed feature the element names, at the
/// piece's own position, on the start's piece stream.
///
/// The name resolves through `Registries.PLACED_FEATURE`. A placed feature
/// with a non-empty placement chain is refused rather than run: the one
/// structure that passes features here (`ancient_city`, whose only element
/// is `sculk_patch_ancient_city`, `"placement": []`) needs none, and the
/// villages' `acacia` carries a `would_survive` filter this call site has not
/// been measured with.
fn place_feature_element(
    world: &mut rustmc_worldgen::stage::decorate::Decoration<'_>,
    ctx: FeatureElements<'_>,
    feature: &str,
    pos: (i32, i32, i32),
    mut random: &mut dyn rustmc_worldgen::rng::RandomSource,
) -> Result<(), String> {
    let stem = feature.strip_prefix("minecraft:").unwrap_or(feature);
    let path = crate::data_path(&format!("worldgen/placed_feature/{stem}.json"));
    let text = std::fs::read_to_string(&path)
        .map_err(|e| format!("feature pool element `{feature}`: {}: {e}", path.display()))?;
    let json: serde_json::Value = serde_json::from_str(&text)
        .map_err(|e| format!("feature pool element `{feature}`: {e}"))?;
    let placed = rustmc_worldgen::feature::decorate::PlacedFeature::parse(&json)?;
    if !placed.placement.is_empty() {
        return Err(format!(
            "feature pool element `{feature}`: its placed feature has a placement \
             chain, which this call site does not run"
        ));
    }
    let configured = ctx.configured.get(&placed.feature).ok_or_else(|| {
        format!(
            "feature pool element `{feature}`: configured feature `{}` is absent or unparsed",
            placed.feature
        )
    })?;
    let world: &mut dyn rustmc_worldgen::feature::configured::FeatureWorld = world;
    configured
        .place(world, ctx.tags, &mut random, pos)
        .map(|_| ())
        .map_err(|e| format!("feature pool element `{feature}`: {}", e.0))
}

/// One warm ocean ruin, chosen but not yet placed.
///
/// The template is loaded once per start rather than per chunk: a ruin spans
/// two chunks often enough that re-reading a gzipped NBT file per chunk pass
/// would be pure waste, and the choice is fixed by the seed anyway.
pub struct OceanRuin {
    pub plan: rustmc_worldgen::structure::ocean_ruin::Plan,
    pub template: rustmc_worldgen::structure::template::Template,
    /// `OceanRuinStructure.biomeTemp == COLD`: gravel rather than sand for
    /// the capped suspicious-block rule.
    pub cold: bool,
}

/// A ruin and, when it clustered, its placed satellites.
///
/// Satellites are ordinary small ruins with their own origin and rotation, so
/// they reuse `OceanRuin` wholesale rather than being a second kind of thing.
pub struct OceanRuinCluster {
    pub main: OceanRuin,
    pub satellites: Vec<OceanRuin>,
}

/// Every warm ocean ruin whose footprint can reach `area`.
///
/// A small warm ruin is 7 blocks across, so a start one chunk outside the area
/// can still write into it. The margin is 2 chunks — generous relative to the
/// footprint, and cheap, because the placement test rejects almost every chunk
/// before any template is read.
///
/// Only `ocean_ruin_warm` is generated. `ocean_ruins.json` is a two-entry
/// structure set and this port does not yet make the weighted choice between
/// warm and cold, which is recorded in `caveats()` rather than papered over.
///
/// # The biome gate, and what it was worth
///
/// `Structure.generate` does not call `findGenerationPoint`, it calls
/// `findValidGenerationPoint`, which is
/// `findGenerationPoint(ctx).filter(stub -> isValidBiome(stub, ctx))`. The
/// predicate is built one frame up, in `ChunkGenerator.tryGenerateStructure`:
/// `structure.biomes()::contains`, i.e. the structure's own biome `HolderSet`.
/// `isValidBiome` samples **once**, at the stub position, in quart
/// coordinates:
///
/// ```text
///   validBiome.test(biomeSource.getNoiseBiome(
///       QuartPos.fromBlock(pos.getX()),
///       QuartPos.fromBlock(pos.getY()),
///       QuartPos.fromBlock(pos.getZ()),
///       randomState.sampler()))
/// ```
///
/// and for a ruin `pos` comes from `onTopOfChunkCenter(ctx, OCEAN_FLOOR_WG,
/// ...)`: `(chunkPos.getMiddleBlockX(), getFirstOccupiedHeight(mx, mz,
/// OCEAN_FLOOR_WG, ...), chunkPos.getMiddleBlockZ())`, and
/// `getFirstOccupiedHeight` is `getBaseHeight - 1`.
///
/// This port never resolved the structure's own biome tag at all, so every
/// placement chunk got a ruin regardless of what was there. Measured
/// on the r7 window (seed 20260722, 156 chunks): one warm ocean ruin at
/// x 1098..1103, y 72..76, z 1120..1125, on dry grass, worth 43 genuine
/// mismatches, against **zero** `cut_sandstone` and **zero** `suspicious_sand`
/// anywhere in either vanilla reference.
///
/// The gate is applied before `plan`, which is where vanilla applies it: the
/// stub is filtered before `getPiecesBuilder()` runs the consumer. Nothing
/// downstream moves, because the random is per-chunk (`setLargeFeatureSeed`)
/// and a rejected chunk's draws were never shared with anyone.
///
/// `height_at` answers `None` outside the generated area, and there the gate
/// is **skipped rather than guessed** — refusing would delete real ruins whose
/// start sits outside the dump, and inventing a height would be worse than
/// either. Those starts are up to `reach` chunks out; the effect is recorded
/// in `caveats()`.
/// One buried treasure start: the chunk it belongs to, and nothing else.
///
/// The piece is a pure function of the chunk (`getBlockX(9)`, `getBlockZ(9)`)
/// and its y is found at write time from the canvas heightmap, so there is
/// nothing else worth carrying.
#[derive(Debug, Clone, Copy)]
pub struct BuriedTreasure {
    pub start_chunk: (i32, i32),
}

/// `BuriedTreasureStructure` over `area` and one chunk of margin.
///
/// # The two gates, and the one that does not exist
///
/// `findGenerationPoint` is `onTopOfChunkCenter(context, OCEAN_FLOOR_WG, ..)`
/// and it is `Optional.of(..)` unconditionally — it cannot refuse. So the
/// placement chunk test and the biome filter are the whole of the selection,
/// and the height it computes is used for **nothing but** the biome sample.
/// A port that treated the stub as a rejection point would place fewer
/// treasures than vanilla and have no way to notice.
///
/// The margin is one chunk and that is not a guess: the piece writes at
/// `chunk * 16 + 9` and its six neighbours, none of which can leave the start
/// chunk, so a start outside `area` cannot write into it. The ring is kept
/// anyway so the set of starts does not depend on the size of the square being
/// generated — the mistake `overworld_first_free_height`'s own notes record
/// costing two village_savanna starts and 13,659 blocks.
///
/// # Errors
/// If the extract is present but malformed.
pub fn buried_treasure_starts<B, H>(
    seed: i64,
    area: Area,
    biome_at: &mut B,
    height_at: H,
) -> Result<Vec<BuriedTreasure>, String>
where
    B: FnMut(i32, i32, i32) -> String,
    H: Fn(i32, i32) -> Option<i32>,
{
    use rustmc_worldgen::structure::placement::StructurePlacement;

    let set_path = format!(
        "{}/worldgen/structure_set/buried_treasures.json",
        crate::DATA
    );
    let Ok(text) = std::fs::read_to_string(&set_path) else {
        // No extract, no treasure. Silent rather than fatal, matching how the
        // rest of this file treats a missing datapack.
        return Ok(Vec::new());
    };
    let json: serde_json::Value =
        serde_json::from_str(&text).map_err(|e| format!("{set_path}: {e}"))?;
    let placement = StructurePlacement::parse(&json["placement"])?;
    let valid_biomes = crate::facts::resolve_biome_tag("has_structure/buried_treasure")?;

    let reach = 1;
    let mut out = Vec::new();
    for cx in (area.min_chunk_x - reach)..=(area.max_chunk_x + reach) {
        for cz in (area.min_chunk_z - reach)..=(area.max_chunk_z + reach) {
            // `isStructureChunk`, NOT `isPlacementChunk` — and the
            // difference is the whole structure here. `buried_treasures.json`
            // is `spacing: 1, separation: 0`, so the spread grid accepts
            // EVERY chunk and the frequency coin does all the work:
            // `legacy_type_2` at frequency 0.01 with salt 0. Written against
            // the grid alone this placed 68 spurious chests in the r=16
            // window where vanilla places none, and every box-scoped row in
            // `served_vs_vanilla` stayed green through it, because they only
            // look inside boxes vanilla itself recorded. The sweep that
            // caught it is in that file and was added in the same commit.
            //
            // `is_structure_chunk_ignoring_exclusion` is the right one rather
            // than the full `is_structure_chunk` for the reason its own doc
            // gives: this set has no exclusion zone, and the full test would
            // demand a registry resolver it would never call.
            if !placement
                .is_structure_chunk_ignoring_exclusion(seed, cx, cz)
                .map_err(|e| format!("{e:?}"))?
            {
                continue;
            }
            // `getMiddleBlockX/Z` is `chunk * 16 + 8`, not the piece's + 9.
            let (mx, mz) = (cx * 16 + 8, cz * 16 + 8);
            if let Some(y) = height_at(mx, mz) {
                let biome = biome_at(mx >> 2, y >> 2, mz >> 2);
                if !valid_biomes.contains(&biome) {
                    continue;
                }
            }
            out.push(BuriedTreasure {
                start_chunk: (cx, cz),
            });
        }
    }
    Ok(out)
}

/// The three `ScatteredFeaturePiece` sets — `desert_pyramids`,
/// `jungle_temples`, `swamp_huts` — over `area` and two chunks of margin.
///
/// # The gates, in vanilla's order
///
/// `isStructureChunk` (each set is a one-entry `random_spread` with no
/// frequency and no exclusion zone, so the grid decides alone), then the
/// structure's `findGenerationPoint`, then `isValidBiome` at the stub:
///
/// * the pyramid and the temple are `SinglePieceStructure`s, which first ask
///   `getLowestY(context, width, depth)` — the minimum of
///   `getFirstOccupiedHeight(.., WORLD_SURFACE_WG)` over the four corners
///   `(minX, minZ)`, `(minX, minZ + d)`, `(minX + w, minZ)`, `(minX + w,
///   minZ + d)` — and refuse below the sea level;
/// * all three then stand the stub on `onTopOfChunkCenter(WORLD_SURFACE_WG)`
///   and the biome is read there.
///
/// Every height is the pure beardless noise column, for the reason
/// [`overworld_first_free_height`] gives: vanilla lays starts out before any
/// neighbour chunk exists. `first_occupied` is `getBaseHeight - 1`.
///
/// The only draw is the piece's facing, on the structure's own
/// `setLargeFeatureSeed` random.
pub fn scattered_starts<B, H>(
    seed: i64,
    area: Area,
    biome_at: &mut B,
    first_occupied: H,
) -> Result<Vec<rustmc_worldgen::structure::scattered::ScatteredStart>, String>
where
    B: FnMut(i32, i32, i32) -> String,
    H: Fn(i32, i32) -> i32,
{
    use rustmc_worldgen::rng::legacy::LegacyRandomSource;
    use rustmc_worldgen::rng::worldgen_random::WorldgenRandom;
    use rustmc_worldgen::structure::placement::StructurePlacement;
    use rustmc_worldgen::structure::scattered::{Kind, ScatteredStart};

    let mut out = Vec::new();
    for (kind, set, structure, single) in [
        (
            Kind::DesertPyramid,
            "structure_set/desert_pyramids.json",
            "desert_pyramid",
            Some((21, 21)),
        ),
        (
            Kind::JungleTemple,
            "structure_set/jungle_temples.json",
            "jungle_pyramid",
            Some((12, 15)),
        ),
        (
            Kind::SwampHut,
            "structure_set/swamp_huts.json",
            "swamp_hut",
            None,
        ),
    ] {
        // Spelled whole, `structure_set/<name>.json`, because that literal is
        // what `ci/structure-surface.py --dispatch` counts as a set read here.
        let set_path = format!("{}/worldgen/{set}", crate::DATA);
        let Ok(text) = std::fs::read_to_string(&set_path) else {
            return Ok(Vec::new());
        };
        let json: serde_json::Value =
            serde_json::from_str(&text).map_err(|e| format!("{set_path}: {e}"))?;
        let placement = StructurePlacement::parse(&json["placement"])?;
        let def_path = format!("{}/worldgen/structure/{structure}.json", crate::DATA);
        let def: serde_json::Value = serde_json::from_str(
            &std::fs::read_to_string(&def_path).map_err(|e| format!("{def_path}: {e}"))?,
        )
        .map_err(|e| format!("{def_path}: {e}"))?;
        let biomes = crate::facts::resolve_structure_biomes(&def, &def_path)?;
        let reach = 2;
        for cx in (area.min_chunk_x - reach)..=(area.max_chunk_x + reach) {
            for cz in (area.min_chunk_z - reach)..=(area.max_chunk_z + reach) {
                if !placement
                    .is_structure_chunk_ignoring_exclusion(seed, cx, cz)
                    .map_err(|e| format!("{e:?}"))?
                {
                    continue;
                }
                let (min_x, min_z) = (cx * 16, cz * 16);
                if let Some((w, d)) = single {
                    let lowest = first_occupied(min_x, min_z)
                        .min(first_occupied(min_x, min_z + d))
                        .min(
                            first_occupied(min_x + w, min_z)
                                .min(first_occupied(min_x + w, min_z + d)),
                        );
                    if lowest < SEA_LEVEL {
                        continue;
                    }
                }
                let (mx, mz) = (min_x + 8, min_z + 8);
                let y = first_occupied(mx, mz);
                if !biomes.contains(&biome_at(mx >> 2, y >> 2, mz >> 2)) {
                    continue;
                }
                let mut random = WorldgenRandom::new(LegacyRandomSource::new(0));
                random.set_large_feature_seed(seed, cx, cz);
                out.push(ScatteredStart::new(kind, (cx, cz), &mut random));
            }
        }
    }
    Ok(out)
}

/// `placeInChunk` for every scattered start of `kind` that reaches this chunk,
/// on one `setFeatureSeed(population, index, 4)` stream shared by all of
/// them — vanilla seeds once per *structure*, not per start.
#[expect(
    clippy::too_many_arguments,
    reason = "the hook's own state, passed through"
)]
fn place_scattered_in_chunk(
    world: &mut rustmc_worldgen::stage::decorate::Decoration<'_>,
    starts: &[rustmc_worldgen::structure::scattered::ScatteredStart],
    kind: rustmc_worldgen::structure::scattered::Kind,
    population: i64,
    index: i32,
    seed: i64,
    chunk_x: i32,
    chunk_z: i32,
    s: &dyn Fn(&str) -> String,
) {
    use rustmc_worldgen::structure::scattered::{desert_pyramid, jungle_temple, swamp_hut, Kind};
    let clip = rustmc_worldgen::structure::pieces::BoundingBox::new(
        chunk_x * 16,
        MIN_Y + 1,
        chunk_z * 16,
        chunk_x * 16 + 15,
        MIN_Y + HEIGHT - 1,
        chunk_z * 16 + 15,
    );
    let mut random = rustmc_worldgen::rng::worldgen_random::WorldgenRandom::new(
        rustmc_worldgen::rng::xoroshiro::XoroshiroRandomSource::from_seed(0),
    );
    random.set_feature_seed(population, index, 4);
    for start in starts.iter().filter(|start| start.kind == kind) {
        // `StructureStart.placeInChunk` tests the piece's box (its current,
        // possibly re-seated one) against the chunk before `postProcess`.
        let mut state = start.state.lock().expect("the scattered start lock");
        if !state.piece.bounding_box.intersects(clip) {
            continue;
        }
        if rustmc_worldgen::canvas::tracing_writes() {
            rustmc_worldgen::canvas::set_writer(&format!(
                "{kind:?} {:?} into chunk ({chunk_x}, {chunk_z})",
                start.start_chunk
            ));
        }
        match kind {
            Kind::SwampHut => swamp_hut(world, &mut state, clip, s),
            Kind::JungleTemple => jungle_temple(world, &mut state, clip, &mut random, s),
            Kind::DesertPyramid => desert_pyramid(world, &mut state, clip, &mut random, seed, s),
        }
        if rustmc_worldgen::canvas::tracing_writes() {
            rustmc_worldgen::canvas::set_writer("");
        }
    }
}

/// One `IglooPieces.IglooPiece`: which template, where `addPieces` put it,
/// and the `PIVOTS`/`OFFSETS` entry for that template.
#[derive(Debug, Clone)]
pub struct IglooPiece {
    pub name: &'static str,
    pub template: std::sync::Arc<rustmc_worldgen::structure::template::Template>,
    /// `makePosition` — the start offset by `OFFSETS[name]` and lowered by
    /// the depth offset. The y is relative to the 90 every start is built at;
    /// `postProcess` re-seats it per pass and puts it back.
    pub pos: (i32, i32, i32),
    pub pivot: (i32, i32),
    pub offset: (i32, i32, i32),
}

/// An igloo start: a rotation and one, or `3 + n` with a basement, pieces —
/// laboratory first, then the ladders, then the dome, in `addPiece` order.
#[derive(Debug, Clone)]
pub struct Igloo {
    pub start_chunk: (i32, i32),
    pub rotation: rustmc_worldgen::structure::template::Rotation,
    pub pieces: Vec<IglooPiece>,
}

/// `IglooStructure` over `area` and one chunk of margin.
///
/// `onTopOfChunkCenter(WORLD_SURFACE_WG)` and the biome there, then on the
/// structure's `setLargeFeatureSeed` random: `Rotation.getRandom`, then
/// `addPieces`' `nextDouble() < 0.5` for a basement and, if so,
/// `nextInt(8) + 4` for its depth.
pub fn igloo_starts<B, H>(
    seed: i64,
    area: Area,
    biome_at: &mut B,
    first_occupied: H,
) -> Result<Vec<Igloo>, String>
where
    B: FnMut(i32, i32, i32) -> String,
    H: Fn(i32, i32) -> i32,
{
    use rustmc_worldgen::rng::legacy::LegacyRandomSource;
    use rustmc_worldgen::rng::worldgen_random::WorldgenRandom;
    use rustmc_worldgen::rng::RandomSource;
    use rustmc_worldgen::structure::placement::StructurePlacement;
    use rustmc_worldgen::structure::template::{Rotation, Template};

    let set_path = format!("{}/worldgen/structure_set/igloos.json", crate::DATA);
    let Ok(text) = std::fs::read_to_string(&set_path) else {
        return Ok(Vec::new());
    };
    let json: serde_json::Value =
        serde_json::from_str(&text).map_err(|e| format!("{set_path}: {e}"))?;
    let placement = StructurePlacement::parse(&json["placement"])?;
    let def_path = format!("{}/worldgen/structure/igloo.json", crate::DATA);
    let def: serde_json::Value = serde_json::from_str(
        &std::fs::read_to_string(&def_path).map_err(|e| format!("{def_path}: {e}"))?,
    )
    .map_err(|e| format!("{def_path}: {e}"))?;
    let biomes = crate::facts::resolve_structure_biomes(&def, &def_path)?;
    let load = |name: &str| -> Result<std::sync::Arc<Template>, String> {
        let path = format!("{}/structure/{name}.nbt", crate::DATA);
        let file = std::fs::File::open(&path).map_err(|e| format!("{path}: {e}"))?;
        let mut reader = flate2::read::GzDecoder::new(file);
        let (_n, root) =
            rustmc_world::nbt::read_named_root(&mut reader).map_err(|e| e.to_string())?;
        Ok(std::sync::Arc::new(
            Template::from_nbt(&root).map_err(|e| format!("{path}: {}", e.0))?,
        ))
    };
    let (top, middle, bottom) = (
        load("igloo/top")?,
        load("igloo/middle")?,
        load("igloo/bottom")?,
    );
    const ROTATIONS: [Rotation; 4] = [
        Rotation::None,
        Rotation::Clockwise90,
        Rotation::Clockwise180,
        Rotation::Counterclockwise90,
    ];
    let reach = 1;
    let mut out = Vec::new();
    for cx in (area.min_chunk_x - reach)..=(area.max_chunk_x + reach) {
        for cz in (area.min_chunk_z - reach)..=(area.max_chunk_z + reach) {
            if !placement
                .is_structure_chunk_ignoring_exclusion(seed, cx, cz)
                .map_err(|e| format!("{e:?}"))?
            {
                continue;
            }
            let (mx, mz) = (cx * 16 + 8, cz * 16 + 8);
            let y = first_occupied(mx, mz);
            if !biomes.contains(&biome_at(mx >> 2, y >> 2, mz >> 2)) {
                continue;
            }
            let mut random = WorldgenRandom::new(LegacyRandomSource::new(0));
            random.set_large_feature_seed(seed, cx, cz);
            let rotation =
                ROTATIONS[usize::try_from(random.next_i32_bound(4)).expect("0..4 is a usize")];
            let start = (cx * 16, 90, cz * 16);
            let piece = |name: &'static str,
                         template: &std::sync::Arc<Template>,
                         depth: i32|
             -> IglooPiece {
                // `PIVOTS` and `OFFSETS`, `<clinit>` offsets 24..109.
                let (pivot, offset) = match name {
                    "igloo/top" => ((3, 5), (0, 0, 0)),
                    "igloo/middle" => ((1, 1), (2, -3, 4)),
                    _ => ((3, 7), (0, -3, -2)),
                };
                IglooPiece {
                    name,
                    template: std::sync::Arc::clone(template),
                    pos: (
                        start.0 + offset.0,
                        start.1 + offset.1 - depth,
                        start.2 + offset.2,
                    ),
                    pivot,
                    offset,
                }
            };
            let mut pieces = Vec::new();
            if random.next_f64() < 0.5 {
                let depth = random.next_i32_bound(8) + 4;
                pieces.push(piece("igloo/bottom", &bottom, depth * 3));
                for i in 0..depth - 1 {
                    pieces.push(piece("igloo/middle", &middle, i * 3));
                }
            }
            pieces.push(piece("igloo/top", &top, 0));
            out.push(Igloo {
                start_chunk: (cx, cz),
                rotation,
                pieces,
            });
        }
    }
    Ok(out)
}

/// One placed `WoodlandMansionPiece`: the walk's piece, its template and the
/// box `StructureTemplate.getBoundingBox` gives it.
#[derive(Debug, Clone)]
pub struct MansionPlaced {
    pub piece: rustmc_worldgen::structure::mansion::MansionPiece,
    pub template: std::sync::Arc<rustmc_worldgen::structure::template::Template>,
    pub bbox: rustmc_worldgen::structure::pieces::BoundingBox,
}

/// `OceanMonumentStructure` over `area` and three chunks of margin — the
/// building starts 29 blocks before its chunk and its outer water skirt
/// reaches 63 blocks past that.
///
/// `findGenerationPoint` draws nothing. It refuses the chunk unless every
/// biome `getBiomesWithin(getBlockX(9), seaLevel, getBlockZ(9), 29)` returns
/// is in `#required_ocean_monument_surrounding`, then seats the stub with
/// `onTopOfChunkCenter(OCEAN_FLOOR_WG)`, whose biome must be in the
/// structure's own `#has_structure/ocean_monument`. Only then does
/// `createTopPiece` spend the start's `setLargeFeatureSeed` random.
///
/// # Errors
/// If the extract is present but malformed.
pub fn monument_starts<B, H>(
    seed: i64,
    area: Area,
    biome_at: &mut B,
    first_occupied: H,
) -> Result<Vec<rustmc_worldgen::structure::ocean_monument::Monument>, String>
where
    B: FnMut(i32, i32, i32) -> String,
    H: Fn(i32, i32) -> i32,
{
    use rustmc_worldgen::rng::legacy::LegacyRandomSource;
    use rustmc_worldgen::rng::worldgen_random::WorldgenRandom;
    use rustmc_worldgen::structure::placement::StructurePlacement;

    let set_path = format!(
        "{}/worldgen/structure_set/ocean_monuments.json",
        crate::DATA
    );
    let Ok(text) = std::fs::read_to_string(&set_path) else {
        return Ok(Vec::new());
    };
    let json: serde_json::Value =
        serde_json::from_str(&text).map_err(|e| format!("{set_path}: {e}"))?;
    let placement = StructurePlacement::parse(&json["placement"])?;
    let def_path = format!("{}/worldgen/structure/monument.json", crate::DATA);
    let def: serde_json::Value = serde_json::from_str(
        &std::fs::read_to_string(&def_path).map_err(|e| format!("{def_path}: {e}"))?,
    )
    .map_err(|e| format!("{def_path}: {e}"))?;
    let biomes = crate::facts::resolve_structure_biomes(&def, &def_path)?;
    let surrounding = crate::facts::resolve_biome_tag("required_ocean_monument_surrounding")?;

    let reach = 3;
    let mut out = Vec::new();
    for cx in (area.min_chunk_x - reach)..=(area.max_chunk_x + reach) {
        for cz in (area.min_chunk_z - reach)..=(area.max_chunk_z + reach) {
            if !placement
                .is_structure_chunk_ignoring_exclusion(seed, cx, cz)
                .map_err(|e| format!("{e:?}"))?
            {
                continue;
            }
            // `BiomeSource.getBiomesWithin(x, y, z, 29)`: every quart cell
            // from `fromBlock(p - 29)` to `fromBlock(p + 29)` on each axis.
            let (x, y, z) = (cx * 16 + 9, SEA_LEVEL, cz * 16 + 9);
            let r = 29;
            let mut ok = true;
            'scan: for qz in ((z - r) >> 2)..=((z + r) >> 2) {
                for qx in ((x - r) >> 2)..=((x + r) >> 2) {
                    for qy in ((y - r) >> 2)..=((y + r) >> 2) {
                        if !surrounding.contains(&biome_at(qx, qy, qz)) {
                            ok = false;
                            break 'scan;
                        }
                    }
                }
            }
            if !ok {
                continue;
            }
            let (mx, mz) = (cx * 16 + 8, cz * 16 + 8);
            let my = first_occupied(mx, mz);
            if !biomes.contains(&biome_at(mx >> 2, my >> 2, mz >> 2)) {
                continue;
            }
            let mut random = WorldgenRandom::new(LegacyRandomSource::new(0));
            random.set_large_feature_seed(seed, cx, cz);
            out.push(rustmc_worldgen::structure::ocean_monument::Monument::new(
                (cx, cz),
                &mut random,
            ));
        }
    }
    Ok(out)
}

/// Every ocean monument start for a window, wired as `generate_resuming`
/// wires them — for `worldgen-dump monument-starts`.
///
/// # Errors
/// If the extract is missing or malformed.
pub fn monument_report(
    seed: i64,
    area: Area,
) -> Result<Vec<rustmc_worldgen::structure::ocean_monument::Monument>, String> {
    let params = noise_parameters();
    let noises = crate::overworld_noises(&params);
    let router = OverworldRouter::new(seed, &noises, false);
    let seeding = NoiseSeeding::new(seed);
    let settings = FillSettings::overworld();
    let sampler = ClimateSampler::from_router(&router);
    let biomes = std::sync::Mutex::new(ParameterList::new(biome_table()));
    let mut biome_at = |qx: i32, qy: i32, qz: i32| {
        biomes
            .lock()
            .expect("the climate list lock")
            .find_value(sampler.sample(qx, qy, qz))
            .clone()
    };
    monument_starts(seed, area, &mut biome_at, |x, z| {
        rustmc_worldgen::stage::noise::base_height(
            &router,
            &seeding,
            settings,
            x,
            z,
            rustmc_worldgen::chunk_gen::Wg::OceanFloor,
        ) - 1
    })
}

/// `StructureStart.placeInChunk` for every monument reaching this chunk, on
/// one `setFeatureSeed(population, index, 4)` stream: the building's
/// `postProcess`, which writes its own shell and then each child room whose
/// box meets the chunk.
fn place_monuments_in_chunk(
    world: &mut rustmc_worldgen::stage::decorate::Decoration<'_>,
    monuments: &[rustmc_worldgen::structure::ocean_monument::Monument],
    population: i64,
    index: i32,
    chunk_x: i32,
    chunk_z: i32,
    s: &dyn Fn(&str) -> String,
) {
    let clip = rustmc_worldgen::structure::pieces::BoundingBox::new(
        chunk_x * 16,
        MIN_Y + 1,
        chunk_z * 16,
        chunk_x * 16 + 15,
        MIN_Y + HEIGHT - 1,
        chunk_z * 16 + 15,
    );
    if !monuments
        .iter()
        .any(|m| m.building.bounding_box.intersects(clip))
    {
        return;
    }
    let palette = rustmc_worldgen::structure::ocean_monument::Palette::new(s);
    let mut random = rustmc_worldgen::rng::worldgen_random::WorldgenRandom::new(
        rustmc_worldgen::rng::xoroshiro::XoroshiroRandomSource::from_seed(0),
    );
    random.set_feature_seed(population, index, 4);
    for monument in monuments
        .iter()
        .filter(|m| m.building.bounding_box.intersects(clip))
    {
        if rustmc_worldgen::canvas::tracing_writes() {
            rustmc_worldgen::canvas::set_writer(&format!(
                "monument {:?} into chunk ({chunk_x}, {chunk_z})",
                monument.start_chunk
            ));
        }
        rustmc_worldgen::structure::ocean_monument::place(
            world,
            monument,
            clip,
            &mut random,
            &palette,
            SEA_LEVEL,
        );
        spawn_monument_elders(world, monument, clip);
        if rustmc_worldgen::canvas::tracing_writes() {
            rustmc_worldgen::canvas::set_writer("");
        }
    }
}

/// A woodland mansion start: every piece in `createMansion`'s order, and the
/// union of their boxes (`PiecesContainer.calculateBoundingBox`).
/// `OceanMonumentPiece.spawnElder` for every room that calls it, in the
/// building's `childPieces` order: each wing room at `(11, 2, 16)` (design
/// 0) or `(11, 5, 13)` (design 1), the penthouse at `(6, 1, 6)`, and only
/// where that block is inside this chunk's box. `finalizeSpawn` draws from
/// the chunk's level random.
fn spawn_monument_elders(
    world: &mut rustmc_worldgen::stage::decorate::Decoration<'_>,
    monument: &rustmc_worldgen::structure::ocean_monument::Monument,
    clip: rustmc_worldgen::structure::pieces::BoundingBox,
) {
    use rustmc_worldgen::structure::ocean_monument::RoomKind;
    use rustmc_worldgen::structure::spawned::{finalize_spawn, mob_compound, uuid, Mob};
    for room in &monument.rooms {
        let local = match room.kind {
            RoomKind::Penthouse => (6, 1, 6),
            RoomKind::Wing { main_design: 0 } => (11, 2, 16),
            RoomKind::Wing { .. } => (11, 5, 13),
            _ => continue,
        };
        let at = room.piece.world_pos(local.0, local.1, local.2);
        if !clip.is_inside(at.0, at.1, at.2) {
            continue;
        }
        let Some(random) = world.level_random() else {
            continue;
        };
        let finalized = finalize_spawn(Mob::ElderGuardian, random);
        let id = uuid(Mob::ElderGuardian.id(), at, 0);
        world.record_entity(mob_compound(Mob::ElderGuardian, at, finalized, id));
    }
}

#[derive(Debug, Clone)]
pub struct Mansion {
    pub start_chunk: (i32, i32),
    pub pieces: Vec<MansionPlaced>,
    pub bbox: rustmc_worldgen::structure::pieces::BoundingBox,
}

/// `WoodlandMansionStructure` over `area` and seven chunks of margin — a
/// mansion's eleven-cell plan reaches about 88 blocks from its start.
///
/// On the start's `setLargeFeatureSeed` random: `Rotation.getRandom`, then
/// `getLowestYIn5by5BoxOffset7Blocks` (the minimum of four
/// `getFirstOccupiedHeight(WORLD_SURFACE_WG)` samples, no draw) and its
/// `y < 60` refusal, then the biome at the stub, then
/// `WoodlandMansionPieces.generateMansion` on the same random.
pub fn mansion_starts<B, H>(
    seed: i64,
    area: Area,
    biome_at: &mut B,
    first_occupied: H,
) -> Result<Vec<Mansion>, String>
where
    B: FnMut(i32, i32, i32) -> String,
    H: Fn(i32, i32) -> i32,
{
    use rustmc_worldgen::rng::legacy::LegacyRandomSource;
    use rustmc_worldgen::rng::worldgen_random::WorldgenRandom;
    use rustmc_worldgen::structure::placement::StructurePlacement;
    use rustmc_worldgen::structure::template::Template;

    let set_path = format!(
        "{}/worldgen/structure_set/woodland_mansions.json",
        crate::DATA
    );
    let Ok(text) = std::fs::read_to_string(&set_path) else {
        return Ok(Vec::new());
    };
    let json: serde_json::Value =
        serde_json::from_str(&text).map_err(|e| format!("{set_path}: {e}"))?;
    let placement = StructurePlacement::parse(&json["placement"])?;
    let def_path = format!("{}/worldgen/structure/mansion.json", crate::DATA);
    let def: serde_json::Value = serde_json::from_str(
        &std::fs::read_to_string(&def_path).map_err(|e| format!("{def_path}: {e}"))?,
    )
    .map_err(|e| format!("{def_path}: {e}"))?;
    let biomes = crate::facts::resolve_structure_biomes(&def, &def_path)?;
    let mut cache: std::collections::BTreeMap<String, std::sync::Arc<Template>> =
        std::collections::BTreeMap::new();
    let mut load = |name: &str| -> Result<std::sync::Arc<Template>, String> {
        if let Some(hit) = cache.get(name) {
            return Ok(std::sync::Arc::clone(hit));
        }
        let path = format!("{}/structure/woodland_mansion/{name}.nbt", crate::DATA);
        let file = std::fs::File::open(&path).map_err(|e| format!("{path}: {e}"))?;
        let mut reader = flate2::read::GzDecoder::new(file);
        let (_n, root) =
            rustmc_world::nbt::read_named_root(&mut reader).map_err(|e| e.to_string())?;
        let t =
            std::sync::Arc::new(Template::from_nbt(&root).map_err(|e| format!("{path}: {}", e.0))?);
        cache.insert(name.to_string(), std::sync::Arc::clone(&t));
        Ok(t)
    };
    let reach = 7;
    let mut out = Vec::new();
    for cx in (area.min_chunk_x - reach)..=(area.max_chunk_x + reach) {
        for cz in (area.min_chunk_z - reach)..=(area.max_chunk_z + reach) {
            if !placement
                .is_structure_chunk_ignoring_exclusion(seed, cx, cz)
                .map_err(|e| format!("{e:?}"))?
            {
                continue;
            }
            let mut random = WorldgenRandom::new(LegacyRandomSource::new(0));
            random.set_large_feature_seed(seed, cx, cz);
            let rotation = rustmc_worldgen::structure::jigsaw::random_rotation(&mut random);
            let Some(pos) =
                rustmc_worldgen::structure::end_city::generation_point(cx, cz, rotation, |x, z| {
                    Some(first_occupied(x, z))
                })
            else {
                continue;
            };
            if !biomes.contains(&biome_at(pos.0 >> 2, pos.1 >> 2, pos.2 >> 2)) {
                continue;
            }
            let walk =
                rustmc_worldgen::structure::mansion::generate_mansion(pos, rotation, &mut random);
            let mut pieces = Vec::with_capacity(walk.len());
            for piece in walk {
                let template = load(&piece.name)?;
                let bbox =
                    template.bounding_box_mirrored(piece.pos, piece.rotation, (0, 0), piece.mirror);
                pieces.push(MansionPlaced {
                    piece,
                    template,
                    bbox,
                });
            }
            let Some(first) = pieces.first() else {
                continue;
            };
            let mut bbox = first.bbox;
            for p in &pieces {
                bbox = rustmc_worldgen::structure::pieces::BoundingBox::new(
                    bbox.min_x.min(p.bbox.min_x),
                    bbox.min_y.min(p.bbox.min_y),
                    bbox.min_z.min(p.bbox.min_z),
                    bbox.max_x.max(p.bbox.max_x),
                    bbox.max_y.max(p.bbox.max_y),
                    bbox.max_z.max(p.bbox.max_z),
                );
            }
            out.push(Mansion {
                start_chunk: (cx, cz),
                pieces,
                bbox,
            });
        }
    }
    Ok(out)
}

/// `StructureStart.placeInChunk` for every mansion reaching this chunk, on one
/// `setFeatureSeed(population, index, 4)` stream: each intersecting piece's
/// template (`BlockIgnoreProcessor.STRUCTURE_BLOCK`, rotation and mirror, pivot
/// at the origin), its data markers, then `WoodlandMansionStructure
/// .afterPlace`'s cobblestone foundation.
#[expect(
    clippy::too_many_arguments,
    reason = "the hook's own state, passed through"
)]
fn place_mansions_in_chunk(
    world: &mut rustmc_worldgen::stage::decorate::Decoration<'_>,
    mansions: &[Mansion],
    population: i64,
    index: i32,
    chunk_x: i32,
    chunk_z: i32,
    props: &rustmc_behavior::block_props::BlockPropsTable,
    s: &dyn Fn(&str) -> String,
) {
    use rustmc_worldgen::block_entity::BlockEntityRecorder;
    use rustmc_worldgen::rng::RandomSource;
    use rustmc_worldgen::structure::place::{
        place_piece, structure_block, PieceWorld, PlaceSettings,
    };
    use rustmc_worldgen::structure::template::{transform, Facing};
    use rustmc_worldgen::structure::writer::StructureWorld;

    struct View<'w, 'a, 'p> {
        world: &'w mut rustmc_worldgen::stage::decorate::Decoration<'a>,
        props: &'p rustmc_behavior::block_props::BlockPropsTable,
    }
    impl rustmc_worldgen::block_entity::BlockEntityRecorder for View<'_, '_, '_> {
        fn record_block_entity(
            &mut self,
            x: i32,
            y: i32,
            z: i32,
            record: rustmc_worldgen::block_entity::Record,
        ) {
            self.world.record_block_entity(x, y, z, record);
        }
    }
    impl PieceWorld for View<'_, '_, '_> {
        fn block_at(&mut self, x: i32, y: i32, z: i32) -> String {
            self.world.block_at(x, y, z)
        }
        fn set_block(&mut self, x: i32, y: i32, z: i32, state: &str) {
            self.world.set_block(x, y, z, state);
        }
        fn world_surface_wg(&mut self, x: i32, z: i32) -> i32 {
            self.world.world_surface_wg(x, z)
        }
        fn block_in_tag(&self, tag: &str, block: &str) -> bool {
            self.world.block_tags().contains(tag, block)
        }
        fn default_state(&self, block: &str) -> Option<String> {
            self.world.default_state(block)
        }
        fn face_is_sturdy(&self, state: &str, direction: usize) -> Option<bool> {
            self.props
                .get(state)
                .and_then(|p| p.sturdy_faces.get(direction).copied())
        }
        fn face_is_collision_full(&self, state: &str, direction: usize) -> Option<bool> {
            self.props
                .get(state)
                .and_then(|p| p.collision_full_faces.get(direction).copied())
        }
    }

    let clip = rustmc_worldgen::structure::pieces::BoundingBox::new(
        chunk_x * 16,
        MIN_Y + 1,
        chunk_z * 16,
        chunk_x * 16 + 15,
        MIN_Y + HEIGHT - 1,
        chunk_z * 16 + 15,
    );
    if !mansions.iter().any(|m| m.bbox.intersects(clip)) {
        return;
    }
    let mut random = rustmc_worldgen::rng::worldgen_random::WorldgenRandom::new(
        rustmc_worldgen::rng::xoroshiro::XoroshiroRandomSource::from_seed(0),
    );
    random.set_feature_seed(population, index, 4);
    let air = s("minecraft:air");
    let chest = s("minecraft:chest");
    let cobblestone = s("minecraft:cobblestone");
    let plain = |state: &str| state.split('[').next().unwrap_or("").to_string();
    let is_air = |state: &str| {
        matches!(
            plain(state).as_str(),
            "minecraft:air" | "minecraft:cave_air" | "minecraft:void_air"
        )
    };
    for mansion in mansions.iter().filter(|m| m.bbox.intersects(clip)) {
        if rustmc_worldgen::canvas::tracing_writes() {
            rustmc_worldgen::canvas::set_writer(&format!(
                "mansion {:?} into chunk ({chunk_x}, {chunk_z})",
                mansion.start_chunk
            ));
        }
        for placed in &mansion.pieces {
            if !placed.bbox.intersects(clip) {
                continue;
            }
            let piece = &placed.piece;
            {
                let mut view = View {
                    world: &mut *world,
                    props,
                };
                place_piece(
                    &mut view,
                    &placed.template,
                    rustmc_worldgen::structure::place::PieceOrigin::unthreaded(piece.pos),
                    PlaceSettings::new(piece.rotation)
                        .with_mirror(piece.mirror)
                        .with_shape_update()
                        .with_waterlogging(),
                    &[structure_block()],
                    clip,
                    // `placeInWorld` spends a `nextLong` on every template
                    // container carrying a tag — the mansion's chests of
                    // alliums and saplings — on this same stream, before the
                    // piece's own markers draw their chests' seeds.
                    Some(&mut random),
                );
            }
            // `filterBlocks(templatePosition, placeSettings, STRUCTURE_BLOCK)`
            // then `handleDataMarker` for each one inside the chunk.
            for block in &placed.template.blocks {
                let Some(marker) = block.marker.as_deref() else {
                    continue;
                };
                let r = transform(block.pos, piece.mirror, piece.rotation, (0, 0));
                let (x, y, z) = (piece.pos.0 + r.0, piece.pos.1 + r.1, piece.pos.2 + r.2);
                if !clip.is_inside(x, y, z) {
                    continue;
                }
                if marker.starts_with("Chest") {
                    let facing = match marker {
                        "ChestWest" => Some(Facing::West),
                        "ChestEast" => Some(Facing::East),
                        "ChestSouth" => Some(Facing::South),
                        "ChestNorth" => Some(Facing::North),
                        _ => None,
                    };
                    let state = match facing {
                        Some(f) => rustmc_worldgen::structure::scattered::with_prop(
                            &chest,
                            "facing",
                            f.rotated(piece.rotation).name(),
                        ),
                        None => chest.clone(),
                    };
                    // `createChest`: inside the box, and not already a chest;
                    // then `setLootTable(WOODLAND_MANSION, random.nextLong())`
                    // on the chest that just appeared.
                    if plain(&world.block_at(x, y, z)) != "minecraft:chest" {
                        world.set_block(x, y, z, &state);
                        let seed = random.next_i64();
                        world.record_block_entity(
                            x,
                            y,
                            z,
                            rustmc_worldgen::block_entity::Record {
                                nbt: BTreeMap::from([(
                                    "LootTable".to_string(),
                                    rustmc_world::nbt::Nbt::String(
                                        "minecraft:chests/woodland_mansion".into(),
                                    ),
                                )]),
                                loot_seed: Some(seed),
                            },
                        );
                    }
                } else if matches!(marker, "Mage" | "Warrior" | "Group of Allays") {
                    // `handleDataMarker`: the mobs are made (a group of allays
                    // draws its size first, `nextInt(3) + 1` on the level
                    // random), then each one in turn is made persistent,
                    // snapped to the marker, `finalizeSpawn`ed (more level
                    // random) and added; the marker goes to air after each.
                    use rustmc_worldgen::structure::spawned::{
                        finalize_spawn, mob_compound, uuid, Mob,
                    };
                    if let Some(level) = world.level_random() {
                        use rustmc_worldgen::rng::RandomSource;
                        let (mob, count) = match marker {
                            "Mage" => (Mob::Evoker, 1),
                            "Warrior" => (Mob::Vindicator, 1),
                            _ => (Mob::Allay, level.next_i32_bound(3) + 1),
                        };
                        for ordinal in 0..count {
                            let level = world.level_random().expect("checked above");
                            let finalized = finalize_spawn(mob, level);
                            let id = uuid(mob.id(), (x, y, z), ordinal.unsigned_abs());
                            world.record_entity(mob_compound(mob, (x, y, z), finalized, id));
                        }
                    }
                    world.set_block(x, y, z, &air);
                }
            }
        }
        // `afterPlace`: a cobblestone column under every column of the
        // chunk whose bottom-layer block is inside a piece and not air, down
        // to the first block that is neither air nor a liquid.
        let bottom = mansion.bbox.min_y;
        for x in clip.min_x..=clip.max_x {
            for z in clip.min_z..=clip.max_z {
                if is_air(&world.block_at(x, bottom, z))
                    || !mansion.bbox.is_inside(x, bottom, z)
                    || !mansion
                        .pieces
                        .iter()
                        .any(|p| p.bbox.is_inside(x, bottom, z))
                {
                    continue;
                }
                let mut y = bottom - 1;
                while y > MIN_Y {
                    let here = world.block_at(x, y, z);
                    let name = plain(&here);
                    if !is_air(&here) && name != "minecraft:water" && name != "minecraft:lava" {
                        break;
                    }
                    world.set_block(x, y, z, &cobblestone);
                    y -= 1;
                }
            }
        }
        if rustmc_worldgen::canvas::tracing_writes() {
            rustmc_worldgen::canvas::set_writer("");
        }
    }
}

/// `IglooPiece.postProcess` for every piece of every igloo reaching this
/// chunk, in piece order.
#[allow(clippy::too_many_arguments)]
fn place_igloos_in_chunk(
    world: &mut rustmc_worldgen::stage::decorate::Decoration<'_>,
    igloos: &[Igloo],
    population: i64,
    index: i32,
    chunk_x: i32,
    chunk_z: i32,
    props: &rustmc_behavior::block_props::BlockPropsTable,
    s: &dyn Fn(&str) -> String,
) {
    use rustmc_worldgen::block_entity::BlockEntityRecorder;
    use rustmc_worldgen::rng::RandomSource;
    use rustmc_worldgen::structure::place::{
        place_piece, structure_block, PieceWorld, PlaceSettings,
    };
    use rustmc_worldgen::structure::template::{transform, Mirror};

    struct View<'w, 'a, 'p> {
        world: &'w mut rustmc_worldgen::stage::decorate::Decoration<'a>,
        props: &'p rustmc_behavior::block_props::BlockPropsTable,
    }
    impl rustmc_worldgen::block_entity::BlockEntityRecorder for View<'_, '_, '_> {
        fn record_block_entity(
            &mut self,
            x: i32,
            y: i32,
            z: i32,
            record: rustmc_worldgen::block_entity::Record,
        ) {
            self.world.record_block_entity(x, y, z, record);
        }
    }
    impl PieceWorld for View<'_, '_, '_> {
        fn block_at(&mut self, x: i32, y: i32, z: i32) -> String {
            use rustmc_worldgen::structure::writer::StructureWorld;
            self.world.block_at(x, y, z)
        }
        fn set_block(&mut self, x: i32, y: i32, z: i32, state: &str) {
            use rustmc_worldgen::structure::writer::StructureWorld;
            self.world.set_block(x, y, z, state);
        }
        fn world_surface_wg(&mut self, x: i32, z: i32) -> i32 {
            self.world.world_surface_wg(x, z)
        }
        fn block_in_tag(&self, tag: &str, block: &str) -> bool {
            self.world.block_tags().contains(tag, block)
        }
        fn default_state(&self, block: &str) -> Option<String> {
            self.world.default_state(block)
        }
        fn face_is_sturdy(&self, state: &str, direction: usize) -> Option<bool> {
            self.props
                .get(state)
                .and_then(|p| p.sturdy_faces.get(direction).copied())
        }
    }

    let clip = rustmc_worldgen::structure::pieces::BoundingBox::new(
        chunk_x * 16,
        MIN_Y + 1,
        chunk_z * 16,
        chunk_x * 16 + 15,
        MIN_Y + HEIGHT - 1,
        chunk_z * 16 + 15,
    );
    let air = s("minecraft:air");
    let snow = s("minecraft:snow_block");
    // `applyBiomeDecoration`'s stream for the igloo in this chunk.
    let mut random = rustmc_worldgen::rng::worldgen_random::WorldgenRandom::new(
        rustmc_worldgen::rng::xoroshiro::XoroshiroRandomSource::from_seed(0),
    );
    random.set_feature_seed(population, index, 4);
    for igloo in igloos {
        for piece in &igloo.pieces {
            // The box's x and z do not depend on the seating, so the
            // `intersects` `placeInChunk` makes before `postProcess` can be
            // taken at the constructor's y.
            let probe =
                piece
                    .template
                    .bounding_box_with_pivot(piece.pos, igloo.rotation, piece.pivot);
            if probe.max_x < clip.min_x
                || probe.min_x > clip.max_x
                || probe.max_z < clip.min_z
                || probe.min_z > clip.max_z
            {
                continue;
            }
            let rel = transform(
                (3 - piece.offset.0, 0, -piece.offset.2),
                Mirror::None,
                igloo.rotation,
                piece.pivot,
            );
            let probe_x = piece.pos.0 + rel.0;
            let probe_z = piece.pos.2 + rel.2;
            let h = world.world_surface_wg(probe_x, probe_z);
            let pos = (piece.pos.0, piece.pos.1 + h - 90 - 1, piece.pos.2);
            if rustmc_worldgen::canvas::tracing_writes() {
                rustmc_worldgen::canvas::set_writer(&format!(
                    "igloo {} {:?} into chunk ({chunk_x}, {chunk_z})",
                    piece.name, igloo.start_chunk
                ));
            }
            {
                let mut view = View {
                    world: &mut *world,
                    props,
                };
                place_piece(
                    &mut view,
                    &piece.template,
                    rustmc_worldgen::structure::place::PieceOrigin::unthreaded(pos),
                    PlaceSettings::new(igloo.rotation)
                        .with_pivot(piece.pivot)
                        .with_shape_update(),
                    &[structure_block()],
                    clip,
                    Some(&mut random),
                );
            }
            // `handleDataMarker("chest")`: the marker's own position goes to
            // air (`setBlock(pos, AIR, 3)`). Written only inside this chunk's
            // box — the marker's own chunk always runs this piece too. Then
            // `getBlockEntity(pos.below())`, and if that is a chest,
            // `setLootTable(IGLOO_CHEST, random.nextLong())`. `filterBlocks`
            // keeps only markers inside the chunk's box, so only the marker's
            // own chunk draws.
            {
                use rustmc_worldgen::structure::writer::StructureWorld;
                for block in &piece.template.blocks {
                    if block.marker.as_deref() != Some("chest") {
                        continue;
                    }
                    let r = transform(block.pos, Mirror::None, igloo.rotation, piece.pivot);
                    let (x, y, z) = (pos.0 + r.0, pos.1 + r.1, pos.2 + r.2);
                    if !clip.is_inside(x, y, z) {
                        continue;
                    }
                    world.set_block(x, y, z, &air);
                    let below = world.block_at(x, y - 1, z);
                    if below.split('[').next() == Some("minecraft:chest") {
                        let seed = random.next_i64();
                        world.record_block_entity(
                            x,
                            y - 1,
                            z,
                            rustmc_worldgen::block_entity::Record {
                                nbt: BTreeMap::from([(
                                    "LootTable".to_string(),
                                    rustmc_world::nbt::Nbt::String(
                                        "minecraft:chests/igloo_chest".into(),
                                    ),
                                )]),
                                loot_seed: Some(seed),
                            },
                        );
                    }
                }
                if piece.name == "igloo/top" {
                    let r = transform((3, 0, 5), Mirror::None, igloo.rotation, piece.pivot);
                    let (x, y, z) = (pos.0 + r.0, pos.1 + r.1, pos.2 + r.2);
                    let below = world.block_at(x, y - 1, z);
                    let name = below.split('[').next().unwrap_or("");
                    if !matches!(
                        name,
                        "minecraft:air"
                            | "minecraft:cave_air"
                            | "minecraft:void_air"
                            | "minecraft:ladder"
                    ) {
                        world.set_block(x, y, z, &snow);
                    }
                }
            }
            if rustmc_worldgen::canvas::tracing_writes() {
                rustmc_worldgen::canvas::set_writer("");
            }
        }
    }
}

/// Write one buried treasure, if this is its own chunk.
///
/// `placeInChunk` runs the piece once per chunk its box reaches, and the box
/// is a single block, so only the start chunk ever calls this. The guard is
/// explicit rather than implied because the box is *reassigned* by
/// `postProcess` — vanilla's saved `Children[0].BB` is at y 90 and the chest
/// is nowhere near it.
fn place_buried_treasure_in_chunk(
    world: &mut rustmc_worldgen::stage::decorate::Decoration<'_>,
    treasure: &BuriedTreasure,
    chunk_x: i32,
    chunk_z: i32,
    props: &rustmc_behavior::block_props::BlockPropsTable,
    population: i64,
    index: i32,
) {
    use rustmc_worldgen::structure::buried_treasure::{post_process, Piece as TreasurePiece};
    use rustmc_worldgen::structure::place::PieceWorld;

    if treasure.start_chunk != (chunk_x, chunk_z) {
        return;
    }

    struct View<'w, 'a> {
        world: &'w mut rustmc_worldgen::stage::decorate::Decoration<'a>,
    }
    impl rustmc_worldgen::block_entity::BlockEntityRecorder for View<'_, '_> {
        fn record_block_entity(
            &mut self,
            x: i32,
            y: i32,
            z: i32,
            record: rustmc_worldgen::block_entity::Record,
        ) {
            self.world.record_block_entity(x, y, z, record);
        }
    }
    impl PieceWorld for View<'_, '_> {
        fn block_at(&mut self, x: i32, y: i32, z: i32) -> String {
            use rustmc_worldgen::structure::writer::StructureWorld;
            self.world.block_at(x, y, z)
        }
        fn set_block(&mut self, x: i32, y: i32, z: i32, state: &str) {
            use rustmc_worldgen::structure::writer::StructureWorld;
            self.world.set_block(x, y, z, state);
        }
        fn world_surface_wg(&mut self, x: i32, z: i32) -> i32 {
            self.world.world_surface_wg(x, z)
        }
        fn block_in_tag(&self, tag: &str, block: &str) -> bool {
            self.world.block_tags().contains(tag, block)
        }
        fn default_state(&self, block: &str) -> Option<String> {
            self.world.default_state(block)
        }
    }

    let piece = TreasurePiece::for_chunk(chunk_x, chunk_z);
    // `level.getHeight(OCEAN_FLOOR_WG, bb.minX, bb.minZ)` — the piece's own
    // column at +9, not the chunk centre the placement stub used.
    let top_y = {
        use rustmc_worldgen::structure::writer::StructureWorld;
        world.ocean_floor_wg(piece.x, piece.z)
    };
    // `ChunkGenerator.getWritableArea`, whose low corner is `getMinY() + 1`.
    let writable = rustmc_worldgen::structure::pieces::BoundingBox::new(
        chunk_x * 16,
        MIN_Y + 1,
        chunk_z * 16,
        chunk_x * 16 + 15,
        MIN_Y + HEIGHT - 1,
        chunk_z * 16 + 15,
    );
    if rustmc_worldgen::canvas::tracing_writes() {
        rustmc_worldgen::canvas::set_writer(&format!(
            "buried treasure into chunk ({chunk_x}, {chunk_z})"
        ));
    }
    let solid_render = |state: &str| props.get(state).is_some_and(|p| p.solid_render);
    let mut view = View { world };
    let placed = post_process(&mut view, &piece, top_y, MIN_Y, writable, &solid_render);
    // `createChest(level, box, random, pos, BURIED_TREASURE, null)`: the seed
    // is the first `nextLong` of `applyBiomeDecoration`'s stream for
    // `buried_treasure` in step 3, and nothing else of this structure draws
    // on it — one start per chunk at most.
    if let rustmc_worldgen::structure::buried_treasure::Placed::Chest(x, y, z) = placed {
        use rustmc_worldgen::block_entity::BlockEntityRecorder;
        use rustmc_worldgen::rng::RandomSource;
        let mut random = rustmc_worldgen::rng::worldgen_random::WorldgenRandom::new(
            rustmc_worldgen::rng::xoroshiro::XoroshiroRandomSource::from_seed(0),
        );
        random.set_feature_seed(population, index, 3);
        view.world.record_block_entity(
            x,
            y,
            z,
            rustmc_worldgen::block_entity::Record {
                nbt: BTreeMap::from([(
                    "LootTable".to_string(),
                    rustmc_world::nbt::Nbt::String("minecraft:chests/buried_treasure".into()),
                )]),
                loot_seed: Some(random.next_i64()),
            },
        );
    }
    if rustmc_worldgen::canvas::tracing_writes() {
        rustmc_worldgen::canvas::set_writer("");
    }
}

pub fn ocean_ruin_starts<B, H>(
    seed: i64,
    area: Area,
    biome_at: &mut B,
    height_at: H,
) -> Result<Vec<OceanRuinCluster>, String>
where
    B: FnMut(i32, i32, i32) -> String,
    H: Fn(i32, i32) -> Option<i32>,
{
    use rustmc_worldgen::rng::legacy::LegacyRandomSource;
    use rustmc_worldgen::rng::worldgen_random::WorldgenRandom;
    use rustmc_worldgen::structure::ocean_ruin::{cold_pieces, plan, Plan};
    use rustmc_worldgen::structure::placement::StructurePlacement;
    use rustmc_worldgen::structure::template::Template;

    let set_path = format!("{}/worldgen/structure_set/ocean_ruins.json", crate::DATA);
    let Ok(text) = std::fs::read_to_string(&set_path) else {
        return Ok(Vec::new());
    };
    let json: serde_json::Value =
        serde_json::from_str(&text).map_err(|e| format!("{set_path}: {e}"))?;
    let placement = StructurePlacement::parse(&json["placement"])?;

    // Both entries of the set. They are equally weighted and their biome tags
    // are disjoint, and both stand their stub on the same `OCEAN_FLOOR_WG`
    // column, so whichever order `tryGenerateStructure` tries them in at most
    // one can pass — the weighted draw (on its own `setLargeFeatureSeed`
    // random, not the structure's) cannot change the outcome and is not
    // spent here. `large_probability` and `cluster_probability` are read
    // per structure; in 26.2 both are 0.3 and 0.9 for both temperatures.
    struct Temp {
        cold: bool,
        large_probability: f32,
        cluster_probability: f32,
        biomes: std::collections::BTreeSet<String>,
    }
    let mut temps = Vec::new();
    for (name, cold) in [("ocean_ruin_cold", true), ("ocean_ruin_warm", false)] {
        let structure_path = format!("{}/worldgen/structure/{name}.json", crate::DATA);
        let structure: serde_json::Value = serde_json::from_str(
            &std::fs::read_to_string(&structure_path).map_err(|e| e.to_string())?,
        )
        .map_err(|e| format!("{structure_path}: {e}"))?;
        temps.push(Temp {
            cold,
            large_probability: structure["large_probability"].as_f64().unwrap_or(0.3) as f32,
            cluster_probability: structure["cluster_probability"].as_f64().unwrap_or(0.9) as f32,
            biomes: crate::facts::resolve_structure_biomes(&structure, &structure_path)?,
        });
    }

    let templates = format!("{}/structure/underwater_ruin", crate::DATA);
    let load = |name: &str| -> Result<Template, String> {
        let path = format!("{templates}/{name}.nbt");
        let Ok(file) = std::fs::File::open(&path) else {
            return Err(format!("{path}: the extract has no such template"));
        };
        let mut reader = flate2::read::GzDecoder::new(file);
        let (_n, root) =
            rustmc_world::nbt::read_named_root(&mut reader).map_err(|e| e.to_string())?;
        Template::from_nbt(&root).map_err(|e| format!("{path}: {}", e.0))
    };
    // A warm plan becomes its cold pieces by index: `addPiece`'s one draw is
    // the same `nextInt` over an array of the same length.
    let pieces_for = |plan: &Plan, cold: bool| -> Result<Vec<OceanRuin>, String> {
        if !cold {
            return Ok(vec![OceanRuin {
                plan: plan.clone(),
                template: load(plan.template)?,
                cold,
            }]);
        }
        let names = cold_pieces(plan.template, plan.integrity)
            .ok_or_else(|| format!("{} has no cold counterpart", plan.template))?;
        names
            .iter()
            .map(|(name, integrity)| {
                let mut p = plan.clone();
                p.template = name;
                p.integrity = *integrity;
                Ok(OceanRuin {
                    template: load(name)?,
                    plan: p,
                    cold,
                })
            })
            .collect()
    };
    let reach = 4;
    let mut out = Vec::new();
    for cx in (area.min_chunk_x - reach)..=(area.max_chunk_x + reach) {
        for cz in (area.min_chunk_z - reach)..=(area.max_chunk_z + reach) {
            if !placement
                .is_placement_chunk(seed, cx, cz)
                .map_err(|e| format!("{e:?}"))?
            {
                continue;
            }
            let (mx, mz) = (cx * 16 + 8, cz * 16 + 8);
            let Some(y) = height_at(mx, mz) else {
                continue;
            };
            let biome = biome_at(mx >> 2, y >> 2, mz >> 2);
            let Some(temp) = temps.iter().find(|t| t.biomes.contains(&biome)) else {
                continue;
            };
            let mut random = WorldgenRandom::new(LegacyRandomSource::new(0));
            random.set_large_feature_seed(seed, cx, cz);
            let main_plan = plan(
                &mut random,
                cx,
                cz,
                temp.large_probability,
                temp.cluster_probability,
            );
            let mut main = pieces_for(&main_plan, temp.cold)?;
            let first = main.remove(0);
            // `addPiece` adds brick, cracked, mossy in that order, and only
            // then does `addClusterRuins` add the satellites — so the main
            // ruin's two companions lead the satellite list.
            let mut satellites = main;
            if main_plan.clustered {
                for s in rustmc_worldgen::structure::ocean_ruin::cluster(&mut random, &main_plan) {
                    if !s.placed {
                        continue;
                    }
                    satellites.extend(pieces_for(&s.plan, temp.cold)?);
                }
            }
            out.push(OceanRuinCluster {
                main: first,
                satellites,
            });
        }
    }
    Ok(out)
}

fn place_ocean_ruin_in_chunk(
    world: &mut rustmc_worldgen::stage::decorate::Decoration<'_>,
    ruin: &OceanRuin,
    seed: i64,
    chunk_x: i32,
    chunk_z: i32,
    random: &mut dyn rustmc_worldgen::rng::RandomSource,
) {
    use rustmc_worldgen::block_entity::BlockEntityRecorder;
    use rustmc_worldgen::structure::ocean_ruin::{marker_blocks, place_blocks_for};
    use rustmc_worldgen::structure::writer::StructureWorld;

    let (ox, _, oz) = ruin.plan.origin;

    // `postProcess` sets the y twice: from OCEAN_FLOOR_WG, then from
    // `getHeight`, which walks the footprint and lowers the piece when the
    // ground under most of it sits more than two blocks below.
    //
    // The second half was left out until there was something to gate it on.
    // There is now: the cluster satellites at (-57,42) sit at y 45..49 here
    // and y 37..41 in a server — a consistent ~8-block sink that only
    // `getHeight` explains.
    let far = rustmc_worldgen::structure::template::transform(
        (ruin.template.size.0 - 1, 0, ruin.template.size.2 - 1),
        rustmc_worldgen::structure::template::Mirror::None,
        ruin.plan.rotation,
        (0, 0),
    );

    // **The footprint test comes before the first heightmap read**, for the
    // same reason it does in the shipwreck: `StructureStart.placeInChunk`
    // tests `piece.getBoundingBox().intersects(box)` at bytecode offset 105
    // and only calls `piece.postProcess(..)` at 124, and every heightmap read
    // here is inside `postProcess`.
    //
    // This one was doing more than an early read — it built the whole block
    // list and *then* dropped every position outside the chunk, so a ruin
    // 36 chunks away was fully placed and fully discarded, once per chunk.
    // `RUSTMC_READ_REACH_TRAP=30` at r=16 caught it: decorating chunk (46,46)
    // reading block (1312,1088) in chunk (82,68).
    //
    // The bound is the rotated footprint, which is exactly the x/z range the
    // per-block filter below already applies, so nothing placed changes.
    let (x0, x1) = (ox.min(ox + far.0), ox.max(ox + far.0));
    let (z0, z1) = (oz.min(oz + far.2), oz.max(oz + far.2));
    if x1 < chunk_x * 16 || x0 > chunk_x * 16 + 15 || z1 < chunk_z * 16 || z0 > chunk_z * 16 + 15 {
        return;
    }

    let heightmap_y = world.ocean_floor_wg(ox, oz);
    let corner = (ox + far.0, heightmap_y, oz + far.2);
    let y = {
        struct Column<'w, 'a> {
            world: &'w mut rustmc_worldgen::stage::decorate::Decoration<'a>,
        }
        impl rustmc_worldgen::structure::ocean_ruin::ColumnReader for Column<'_, '_> {
            fn block_at(&mut self, x: i32, y: i32, z: i32) -> String {
                use rustmc_worldgen::structure::writer::StructureWorld;
                self.world.block_at(x, y, z)
            }
            fn min_y(&self) -> i32 {
                MIN_Y
            }
        }
        let mut column = Column { world };
        rustmc_worldgen::structure::ocean_ruin::settle_height(
            &mut column,
            (ox, heightmap_y, oz),
            corner,
        )
    };
    let mut blocks = place_blocks_for(&ruin.template, &ruin.plan, y, seed, ruin.cold);
    // The chest's `waterlogged` comes from the fluid already at that position.
    // Collected before the writes below so a block this ruin places cannot
    // answer the question about itself.
    let markers: Vec<_> = marker_blocks(&ruin.template, &ruin.plan, y, |pos| {
        world
            .block_at(pos.0, pos.1, pos.2)
            .starts_with("minecraft:water")
    });
    let chests: Vec<(i32, i32, i32)> = markers.iter().map(|(pos, _)| *pos).collect();
    blocks.extend(markers);

    let (lo_x, hi_x) = (chunk_x * 16, chunk_x * 16 + 15);
    let (lo_z, hi_z) = (chunk_z * 16, chunk_z * 16 + 15);
    blocks.retain(|((x, _, z), _)| *x >= lo_x && *x <= hi_x && *z >= lo_z && *z <= hi_z);

    // The capped archaeology rule is `RuleProcessor` + `AppendLoot`: each
    // suspicious block's `LootTableSeed` is the first `nextLong` of its own
    // positional stream (`RandomSource.create(Mth.getSeed(pos))`; a
    // `BlockMatchTest` and `AlwaysTrueTest` draw nothing before it).
    let archaeology = if ruin.cold {
        "minecraft:archaeology/ocean_ruin_cold"
    } else {
        "minecraft:archaeology/ocean_ruin_warm"
    };
    for ((x, y, z), state) in &blocks {
        if !state.starts_with("minecraft:suspicious_") {
            continue;
        }
        use rustmc_worldgen::rng::RandomSource;
        let mut positional = rustmc_worldgen::rng::legacy::LegacyRandomSource::new(
            rustmc_worldgen::structure::template::position_seed(*x, *y, *z),
        );
        world.record_block_entity(
            *x,
            *y,
            *z,
            rustmc_worldgen::block_entity::Record {
                nbt: BTreeMap::from([
                    (
                        "LootTable".to_string(),
                        rustmc_world::nbt::Nbt::String(archaeology.into()),
                    ),
                    (
                        "LootTableSeed".to_string(),
                        rustmc_world::nbt::Nbt::Long(positional.next_i64()),
                    ),
                ]),
                loot_seed: None,
            },
        );
    }
    // `handleDataMarker("chest")`: `setLootTable(isLarge ? UNDERWATER_RUIN_BIG
    // : UNDERWATER_RUIN_SMALL, random.nextLong())` on the postProcess stream,
    // for each marker `filterBlocks` returns — and `filterBlocks` keeps only
    // positions inside `placeSettings.getBoundingBox()`, which `postProcess`
    // has just set to the chunk's box. Measured: seed 12345's cold ruin at
    // (65,67) spans four chunks, and its chest's seed is draw 2 of the
    // chest's own chunk (64,66); drawing in all four put draw 2 of (65,67)
    // there instead.
    let table = if ruin.plan.large {
        "minecraft:chests/underwater_ruin_big"
    } else {
        "minecraft:chests/underwater_ruin_small"
    };
    // `handleDataMarker("drowned")`: a persistent drowned at the marker,
    // finalized from the level random, then the marker becomes water at or
    // below sea level and air above it. Only markers in this chunk's box.
    for block in &ruin.template.blocks {
        if block.marker.as_deref() != Some("drowned") {
            continue;
        }
        let r = rustmc_worldgen::structure::template::transform(
            block.pos,
            rustmc_worldgen::structure::template::Mirror::None,
            ruin.plan.rotation,
            (0, 0),
        );
        let at = (ox + r.0, y + r.1, oz + r.2);
        if at.0 < lo_x || at.0 > hi_x || at.2 < lo_z || at.2 > hi_z {
            continue;
        }
        use rustmc_worldgen::structure::spawned::{finalize_spawn, mob_compound, uuid, Mob};
        if let Some(level) = world.level_random() {
            let finalized = finalize_spawn(Mob::Drowned, level);
            world.record_entity(mob_compound(
                Mob::Drowned,
                at,
                finalized,
                uuid(Mob::Drowned.id(), at, 0),
            ));
        }
        let fill = if at.1 <= SEA_LEVEL {
            "minecraft:water[level=0]"
        } else {
            "minecraft:air"
        };
        world.set_block(at.0, at.1, at.2, fill);
    }
    for (x, y, z) in chests {
        if x < lo_x || x > hi_x || z < lo_z || z > hi_z {
            continue;
        }
        let seed = random.next_i64();
        world.record_block_entity(
            x,
            y,
            z,
            rustmc_worldgen::block_entity::Record {
                nbt: BTreeMap::from([(
                    "LootTable".to_string(),
                    rustmc_world::nbt::Nbt::String(table.into()),
                )]),
                loot_seed: Some(seed),
            },
        );
    }

    struct View<'w, 'a> {
        world: &'w mut rustmc_worldgen::stage::decorate::Decoration<'a>,
    }
    impl rustmc_worldgen::block_entity::BlockEntityRecorder for View<'_, '_> {
        fn record_block_entity(
            &mut self,
            x: i32,
            y: i32,
            z: i32,
            record: rustmc_worldgen::block_entity::Record,
        ) {
            self.world.record_block_entity(x, y, z, record);
        }
    }
    impl rustmc_worldgen::structure::place::PieceWorld for View<'_, '_> {
        fn block_at(&mut self, x: i32, y: i32, z: i32) -> String {
            self.world.block_at(x, y, z)
        }
        fn set_block(&mut self, x: i32, y: i32, z: i32, state: &str) {
            self.world.set_block(x, y, z, state);
        }
        fn world_surface_wg(&mut self, x: i32, z: i32) -> i32 {
            self.world.world_surface_wg(x, z)
        }
        fn block_in_tag(&self, tag: &str, block: &str) -> bool {
            self.world.block_tags().contains(tag, block)
        }
        fn default_state(&self, block: &str) -> Option<String> {
            self.world.default_state(block)
        }
    }
    // `OceanRuinPiece.makeSettings` sets no liquid settings, so the template
    // places with the default APPLY_WATERLOGGING.
    rustmc_worldgen::structure::place::write_with_waterlogging(&mut View { world }, &blocks);
}

/// One ocean shipwreck, chosen but not yet placed.
///
/// A shipwreck is a single piece, so there is no piece list: the plan and the
/// template are the whole start. The y is deliberately **not** stored — it is
/// recomputed from the heightmap fossil on every chunk pass, which is what
/// `postProcess` does, and storing it would hide a divergence between the two
/// passes rather than reproduce one.
pub struct Shipwreck {
    pub start_chunk: (i32, i32),
    pub plan: rustmc_worldgen::structure::shipwreck::Plan,
    pub template: rustmc_worldgen::structure::template::Template,
    /// A beached wreck's `heightAdjusted` latch: the y the first pass to
    /// reach it settled on, drawn once on that pass's stream and kept for
    /// every later chunk. An ocean wreck never reads it — its mean is a pure
    /// function of the frozen `OCEAN_FLOOR_WG` fossil, so recomputing it per
    /// pass is the same as latching it.
    pub beached_y: std::sync::Mutex<Option<i32>>,
}

/// Every ocean shipwreck whose footprint can reach `area`.
///
/// `shipwrecks.json` is a two-entry set — `shipwreck` and
/// `shipwreck_beached` — so unlike the End city there **is** a weighted
/// attempt order to make, and unlike the ocean ruin set it is read rather
/// than ignored. The biome gate decides which attempt wins: the two structures
/// have disjoint biome sets (nine oceans against two beaches), so at most one
/// of them can ever succeed in a given chunk.
///
/// # Why a beached wreck is counted and not placed
///
/// Its y is `lowest - size.y/2 - random.nextInt(3)`, and that draw is on
/// One ruined portal, planned but not yet written.
///
/// The plan is made once for the whole generated area rather than per chunk,
/// like a village's: the piece writes across chunk borders in a single pass
/// and every chunk it touches has to agree on where it is.
pub struct RuinedPortal {
    pub start_chunk: (i32, i32),
    /// Which of the seven variants won the weighted attempt — `ruined_portal`,
    /// `ruined_portal_desert`, and so on.
    pub structure: String,
    /// The template the plan drew — `ruined_portal/portal_3`. Carried so the
    /// start can be printed in the shape vanilla's own saved `Children[]` is
    /// printed in; [`Piece`](rustmc_worldgen::structure::ruined_portal::Piece)
    /// itself does not hold it.
    pub template_name: String,
    pub piece: rustmc_worldgen::structure::ruined_portal::Piece,
    pub template: rustmc_worldgen::structure::template::Template,
}

/// `RuinedPortalStructure.findGenerationPoint` for every variant in
/// `ruined_portals.json`, over the area and its margin.
///
/// # Why all seven variants and not just the overworld one
///
/// They share **one** structure set, so `tryGenerateStructure` walks them in
/// `weighted_attempt_order` and takes the first whose biome accepts the stub.
/// Porting only `ruined_portal` would not place fewer portals — it would place
/// the *wrong* portal in every chunk where a desert or jungle variant is the
/// one that wins, because our attempt loop would fall through to the standard
/// one that vanilla never reached. All seven have weight 1.
///
/// Each attempt gets a **fresh** random at the same
/// `setLargeFeatureSeed(seed, cx, cz)`: `Structure.generate` builds its own,
/// so a variant rejected on biome costs the next variant nothing. What does
/// differ between them is the draw *sequence* — `ruined_portal.json` has two
/// setups and so spends a `nextFloat` choosing one, while the other six have a
/// single setup and spend nothing, and their `air_pocket_probability` values
/// of 0.0 and 1.0 short-circuit [`sample`] where 0.5 does not.
///
/// # Errors
/// If the extract is present but malformed, or names a template it lacks.
pub fn ruined_portal_starts<B, H, C, K>(
    seed: i64,
    area: Area,
    biome_at: &mut B,
    height_at: H,
    column_at: C,
    cold_at: &mut K,
    min_y: i32,
) -> Result<Vec<RuinedPortal>, String>
where
    B: FnMut(i32, i32, i32) -> String,
    H: Fn(i32, i32, bool) -> i32,
    C: Fn(i32, i32) -> Vec<rustmc_worldgen::density::fill::Substance>,
    K: FnMut(&str, i32, i32, i32) -> bool,
{
    use rustmc_worldgen::rng::legacy::LegacyRandomSource;
    use rustmc_worldgen::rng::worldgen_random::WorldgenRandom;
    use rustmc_worldgen::structure::placement::StructurePlacement;
    use rustmc_worldgen::structure::processor::weighted_attempt_order;
    use rustmc_worldgen::structure::ruined_portal::{
        find_suitable_y, plan, properties, Piece, Setup, Site,
    };
    use rustmc_worldgen::structure::template::Template;

    let set_path = format!("{}/worldgen/structure_set/ruined_portals.json", crate::DATA);
    let Ok(text) = std::fs::read_to_string(&set_path) else {
        return Ok(Vec::new());
    };
    let json: serde_json::Value =
        serde_json::from_str(&text).map_err(|e| format!("{set_path}: {e}"))?;
    let placement = StructurePlacement::parse(&json["placement"])?;

    let entries: Vec<(String, i32)> = json["structures"]
        .as_array()
        .ok_or_else(|| format!("{set_path}: no `structures`"))?
        .iter()
        .map(|e| {
            (
                e["structure"]
                    .as_str()
                    .unwrap_or_default()
                    .strip_prefix("minecraft:")
                    .unwrap_or_default()
                    .to_string(),
                e["weight"].as_i64().unwrap_or(1) as i32,
            )
        })
        .collect();
    let weights: Vec<i32> = entries.iter().map(|(_, w)| *w).collect();

    // Each variant's setups and its biome set, read once.
    let mut defs: Vec<(Vec<Setup>, std::collections::BTreeSet<String>)> = Vec::new();
    for (name, _) in &entries {
        let path = format!("{}/worldgen/structure/{name}.json", crate::DATA);
        let value: serde_json::Value =
            serde_json::from_str(&std::fs::read_to_string(&path).map_err(|e| e.to_string())?)
                .map_err(|e| format!("{path}: {e}"))?;
        let setups = value["setups"]
            .as_array()
            .ok_or_else(|| format!("{path}: no `setups`"))?
            .iter()
            .map(Setup::parse)
            .collect::<Result<Vec<_>, _>>()?;
        // The biome set comes out of the object already open above, not out of
        // the structure's id. `ruined_portal.json` declares
        // `#minecraft:has_structure/ruined_portal_standard`, and there is no
        // `has_structure/ruined_portal.json` for a derived name to find.
        defs.push((
            setups,
            crate::facts::resolve_structure_biomes(&value, &path)?,
        ));
    }

    // A portal's box centre is inside its start chunk, the box reaches at most
    // a template's width from there, and `spreadNetherrack` reaches 14 blocks
    // past the centre on top of that. Four chunks is comfortably more than
    // that sum and the spacing is 40, so the extra attempts cost almost
    // nothing. Chosen wide on purpose: this project has twice measured a
    // window that was really measuring its own margin.
    let reach = 4;
    let mut out = Vec::new();
    for cx in (area.min_chunk_x - reach)..=(area.max_chunk_x + reach) {
        for cz in (area.min_chunk_z - reach)..=(area.max_chunk_z + reach) {
            if !placement
                .is_placement_chunk(seed, cx, cz)
                .map_err(|e| format!("{e:?}"))?
            {
                continue;
            }
            for entry in weighted_attempt_order(seed, cx, cz, &weights) {
                let (setups, biomes) = &defs[entry];
                let name = &entries[entry].0;

                let mut random = WorldgenRandom::new(LegacyRandomSource::new(0));
                random.set_large_feature_seed(seed, cx, cz);
                let plan = plan(&mut random, setups);
                let setup = setups[plan.setup_index];

                let path = format!("{}/structure/{}.nbt", crate::DATA, plan.template);
                let Ok(file) = std::fs::File::open(&path) else {
                    return Err(format!("{path}: the extract has no such template"));
                };
                let mut reader = flate2::read::GzDecoder::new(file);
                let (_n, root) =
                    rustmc_world::nbt::read_named_root(&mut reader).map_err(|e| e.to_string())?;
                let template = Template::from_nbt(&root).map_err(|e| format!("{path}: {}", e.0))?;

                // `new BlockPos(size.getX() / 2, 0, size.getZ() / 2)`, and the
                // box is taken at the **chunk origin** — not at the chunk
                // centre, which is what every other surface structure here
                // uses.
                let pivot = Piece::pivot_for(template.size);
                let chunk_origin = (cx * 16, 0, cz * 16);
                let bbox =
                    template.bounding_box_mirrored(chunk_origin, plan.rotation, pivot, plan.mirror);
                let centre = rustmc_worldgen::structure::ruined_portal::box_center(bbox);
                let ocean_floor = plan.placement.uses_ocean_floor_heightmap();
                let base_y = height_at(centre.0, centre.2, ocean_floor) - 1;

                // The four corner columns, in `ImmutableList.of`'s order —
                // the same order `find_suitable_y` scans them in, and the
                // order matters through its early exit at the third opaque.
                let corners = [
                    (bbox.min_x, bbox.min_z),
                    (bbox.max_x, bbox.min_z),
                    (bbox.min_x, bbox.max_z),
                    (bbox.max_x, bbox.max_z),
                ];
                let columns: Vec<Vec<rustmc_worldgen::density::fill::Substance>> =
                    corners.iter().map(|(x, z)| column_at(*x, *z)).collect();
                let site = Site {
                    placement: plan.placement,
                    air_pocket: plan.air_pocket,
                    base_y,
                    y_span: bbox.max_y - bbox.min_y + 1,
                    box_min_x: bbox.min_x,
                    box_min_z: bbox.min_z,
                    box_max_x: bbox.max_x,
                    box_max_z: bbox.max_z,
                    min_level_y: min_y,
                };
                let y = find_suitable_y(&mut random, &site, |x, y, z| {
                    let Some(i) = corners.iter().position(|c| *c == (x, z)) else {
                        return false;
                    };
                    let column = &columns[i];
                    let Ok(idx) = usize::try_from(y - min_y) else {
                        return false;
                    };
                    column.get(idx).is_some_and(|s| {
                        if ocean_floor {
                            s.blocks_motion()
                        } else {
                            !s.is_air()
                        }
                    })
                });

                // THE STUB IS THE CHUNK ORIGIN, NOT THE BOX CENTRE, and the
                // difference is 12 blocks of z for the measured portal.
                //
                // `RuinedPortalStructure.findGenerationPoint` computes the box
                // centre (offset 343 `BoundingBox.getCenter`) and spends it on
                // exactly one thing: `getBaseHeight(centre.x, centre.z, …)` at
                // 350..377. The stub it then returns is built at 409..428 out
                // of `blockpos14` — `ctx.chunkPos().getWorldPosition()`, the
                // chunk origin — with only `findSuitableY`'s y between them:
                //
                //     new BlockPos(blockpos14.getX(), i1, blockpos14.getZ())
                //
                // and that same `BlockPos` is what the lambda hands the
                // `RuinedPortalPiece` constructor as its `templatePosition`
                // (offset 100, `aload_1`), what `isCold` is sampled at
                // (11..52), and what `findValidGenerationPoint` filters the
                // biome on. Vanilla's own saved `TPX/TPY/TPZ` for the measured
                // portal is `768,42,1024` — chunk (48,64)'s origin exactly,
                // while its box is `[768 42 1032 .. 776 50 1039]`, whose centre
                // is (772, ·, 1036).
                //
                // Using the centre put every block of the portal 4 east and 12
                // south of vanilla's: measured 2026-08-09, 531 of our 552
                // netherrack landed in chunk (48,**65**) and 5 in (48,64), the
                // per-piece residual stayed at 553 of 554 and the r=16 window
                // went **worse** by 991. `the_four_saved_portals_reproduce_
                // field_for_field` could not see it — it gates the plan
                // (template, rotation, mirror, placement), never the position.
                let stub = (chunk_origin.0, y, chunk_origin.2);
                let biome = biome_at(stub.0 >> 2, stub.1 >> 2, stub.2 >> 2);
                if !biomes.contains(&biome) {
                    continue;
                }
                let cold = setup.can_be_cold && cold_at(&biome, stub.0, stub.1, stub.2);
                out.push(RuinedPortal {
                    start_chunk: (cx, cz),
                    structure: name.clone(),
                    template_name: plan.template.clone(),
                    piece: Piece {
                        template_position: stub,
                        placement: plan.placement,
                        properties: properties(&setup, plan.air_pocket, cold),
                        rotation: plan.rotation,
                        mirror: plan.mirror,
                        pivot,
                    },
                    template,
                });
                break;
            }
        }
    }
    // `applyBiomeDecoration` walks the step's structures in registry index
    // order, so the seven variants are written in the order their identifiers
    // sort — `ruined_portal` (index 10) through `ruined_portal_swamp` (16).
    // Two portals cannot share a placement chunk, but their netherrack aprons
    // can overlap, so the order is observable.
    out.sort_by(|a, b| {
        a.structure
            .cmp(&b.structure)
            .then(a.start_chunk.cmp(&b.start_chunk))
    });
    Ok(out)
}

/// Every ruined portal this port lays out for `area` in the **nether**: the
/// same attempt `generate_nether` makes, extracted so a gate can compare the
/// plan and the position against vanilla's saved start without generating
/// any terrain.
///
/// # Errors
/// If the extract is missing or malformed.
pub fn nether_ruined_portal_report(seed: i64, area: Area) -> Result<Vec<RuinedPortal>, String> {
    let noises = crate::nether_noises()?;
    let router = rustmc_worldgen::density::router::OverworldRouter::nether(seed, &noises);
    let seeding = NoiseSeeding::new(seed);
    let settings = FillSettings::nether();
    let sampler = ClimateSampler::from_router(&router);
    let biomes = std::sync::Mutex::new(ParameterList::new(crate::nether_biome_table()?));
    ruined_portal_starts(
        seed,
        area,
        &mut |qx, qy, qz| {
            biomes
                .lock()
                .expect("the climate list lock")
                .find_value(sampler.sample(qx, qy, qz))
                .clone()
        },
        |x, z, ocean_floor| {
            rustmc_worldgen::stage::noise::base_height(
                &router,
                &seeding,
                settings,
                x,
                z,
                if ocean_floor {
                    rustmc_worldgen::chunk_gen::Wg::OceanFloor
                } else {
                    rustmc_worldgen::chunk_gen::Wg::WorldSurface
                },
            )
        },
        |x, z| rustmc_worldgen::stage::noise::base_column(&router, &seeding, settings, x, z),
        &mut |_: &str, _: i32, _: i32, _: i32| false,
        NETHER_MIN_Y,
    )
}

/// Every ruined-portal start for a window, wired exactly as
/// `generate_decorating` wires it, for the `worldgen-dump ruined-portal-starts`
/// oracle command.
///
/// **This exists because the position was the one field nothing gated.**
/// `the_four_saved_portals_reproduce_field_for_field` pins the template, the
/// rotation, the mirror and the vertical placement out of vanilla's own saved
/// `Children[]`, and passed while every block of the measured portal was 4 east
/// and 12 south of where vanilla put it — because the stub was taken at the
/// box centre rather than at the chunk origin. A block diff cannot separate a
/// wrong position from a wrong template from a wrong stream, and it cost this
/// branch a whole measurement to find out which. This prints our starts in
/// exactly the format `worldgen-dump jigsaw-starts <ref> ruined_portal` prints
/// vanilla's, so `TPX/TPY/TPZ` and the box can be diffed line for line with no
/// generated world at all.
///
/// # Errors
/// If the extract is missing or malformed.
pub fn ruined_portal_report(seed: i64, area: Area) -> Result<Vec<RuinedPortal>, String> {
    let params = noise_parameters();
    let noises = crate::overworld_noises(&params);
    let router = OverworldRouter::new(seed, &noises, false);
    let seeding = NoiseSeeding::new(seed);
    let settings = FillSettings::overworld();
    let sampler = ClimateSampler::from_router(&router);
    let biomes = std::sync::Mutex::new(ParameterList::new(biome_table()));
    let biome_data = crate::biome_data();
    let info_noise = rustmc_worldgen::biome::temperature::TemperatureNoises::new();

    let mut biome_at = |qx: i32, qy: i32, qz: i32| {
        biomes
            .lock()
            .expect("the climate list lock")
            .find_value(sampler.sample(qx, qy, qz))
            .clone()
    };
    let height_at = |x: i32, z: i32, ocean_floor: bool| {
        rustmc_worldgen::stage::noise::base_height(
            &router,
            &seeding,
            settings,
            x,
            z,
            if ocean_floor {
                rustmc_worldgen::chunk_gen::Wg::OceanFloor
            } else {
                rustmc_worldgen::chunk_gen::Wg::WorldSurface
            },
        )
    };
    let column_at = |x: i32, z: i32| {
        rustmc_worldgen::stage::noise::base_column(&router, &seeding, settings, x, z)
    };
    let mut cold_at = |biome: &str, x: i32, y: i32, z: i32| {
        biome_data.get(biome).is_some_and(|entry| {
            info_noise.cold_enough_to_snow(entry.climate, x, y, z, crate::SEA_LEVEL)
        })
    };

    ruined_portal_starts(
        seed,
        area,
        &mut biome_at,
        height_at,
        column_at,
        &mut cold_at,
        settings.min_y,
    )
}

/// Write one ruined portal, if this chunk is the one that owns its centre.
///
/// **Unlike every other structure here, this is not a per-chunk clip.**
/// `RuinedPortalPiece.postProcess` returns immediately unless the box centre
/// lies in the chunk's writable area and then *widens* that area to the whole
/// template, so the portal is written once, entirely, from one chunk's pass —
/// and its netherrack apron reaches out of that chunk under the same
/// one-chunk write mask a feature has.
#[expect(clippy::too_many_arguments, reason = "the level's bounds ride along")]
fn place_ruined_portal_in_chunk<R: rustmc_worldgen::rng::RandomSource>(
    world: &mut rustmc_worldgen::stage::decorate::Decoration<'_>,
    portal: &RuinedPortal,
    random: &mut R,
    chunk_x: i32,
    chunk_z: i32,
    props: &rustmc_behavior::block_props::BlockPropsTable,
    level_min_y: i32,
    level_height: i32,
) {
    use rustmc_worldgen::structure::place::PieceWorld;
    use rustmc_worldgen::structure::ruined_portal::{post_process, PortalWorld};

    struct Piece<'w, 'a, 'p> {
        world: &'w mut rustmc_worldgen::stage::decorate::Decoration<'a>,
        props: &'p rustmc_behavior::block_props::BlockPropsTable,
    }
    // `Decoration` already implements the recorder; this view exists only to
    // narrow what a piece may touch, so it forwards rather than deciding.
    impl rustmc_worldgen::block_entity::BlockEntityRecorder for Piece<'_, '_, '_> {
        fn record_block_entity(
            &mut self,
            x: i32,
            y: i32,
            z: i32,
            record: rustmc_worldgen::block_entity::Record,
        ) {
            self.world.record_block_entity(x, y, z, record);
        }
    }
    impl PieceWorld for Piece<'_, '_, '_> {
        fn block_at(&mut self, x: i32, y: i32, z: i32) -> String {
            use rustmc_worldgen::structure::writer::StructureWorld;
            self.world.block_at(x, y, z)
        }
        fn set_block(&mut self, x: i32, y: i32, z: i32, state: &str) {
            use rustmc_worldgen::structure::writer::StructureWorld;
            self.world.set_block(x, y, z, state);
        }
        fn world_surface_wg(&mut self, x: i32, z: i32) -> i32 {
            self.world.world_surface_wg(x, z)
        }
        fn block_in_tag(&self, tag: &str, block: &str) -> bool {
            self.world.block_tags().contains(tag, block)
        }
        fn default_state(&self, block: &str) -> Option<String> {
            self.world.default_state(block)
        }
        fn face_is_sturdy(&self, state: &str, direction: usize) -> Option<bool> {
            self.props
                .get(state)
                .and_then(|p| p.sturdy_faces.get(direction).copied())
        }
        fn face_is_collision_full(&self, state: &str, direction: usize) -> Option<bool> {
            self.props
                .get(state)
                .and_then(|p| p.collision_full_faces.get(direction).copied())
        }
        /// See `Processor::LavaSubmerged` for why this is the collision shape
        /// and what it costs.
        fn shape_is_full_block(&self, state: &str) -> Option<bool> {
            self.props
                .get(state)
                .map(|p| p.collision_full_faces.iter().all(|f| *f))
        }
    }
    impl PortalWorld for Piece<'_, '_, '_> {
        fn height(&mut self, ocean_floor: bool, x: i32, z: i32) -> i32 {
            use rustmc_worldgen::structure::writer::StructureWorld;
            if ocean_floor {
                self.world.ocean_floor_wg(x, z)
            } else {
                self.world.world_surface_wg(x, z)
            }
        }
    }

    // `ChunkGenerator.getWritableArea`, whose low corner is `getMinY() + 1`
    // — the LEVEL's: -63..319 in the overworld, 1..255 in the nether.
    let writable = rustmc_worldgen::structure::pieces::BoundingBox::new(
        chunk_x * 16,
        level_min_y + 1,
        chunk_z * 16,
        chunk_x * 16 + 15,
        level_min_y + level_height - 1,
        chunk_z * 16 + 15,
    );
    // The centre test is cheap and rejects every chunk but one, so it is worth
    // doing before the view struct and the trace are built.
    let bbox = portal.piece.bounding_box(&portal.template);
    if !rustmc_worldgen::structure::ruined_portal::box_contains(
        writable,
        rustmc_worldgen::structure::ruined_portal::box_center(bbox),
    ) {
        return;
    }
    if rustmc_worldgen::canvas::tracing_writes() {
        rustmc_worldgen::canvas::set_writer(&format!(
            "ruined portal into chunk ({chunk_x}, {chunk_z})"
        ));
    }
    // `postProcess`'s random is the decoration stream the caller seeded with
    // `setFeatureSeed(decorationSeed, index, step)` for this variant's own
    // structure index — **not** a fresh one. Every draw `spreadNetherrack`
    // and the drip columns spend comes out of it.
    let mut view = Piece { world, props };
    let _ = post_process(&mut view, random, &portal.template, &portal.piece, writable);
    if rustmc_worldgen::canvas::tracing_writes() {
        rustmc_worldgen::canvas::set_writer("");
    }
}

/// `postProcess`'s random — the decoration stream at the `SURFACE_STRUCTURES`
/// structure index, which this port cannot read (ORACLE fault 9). Guessing it
/// would put a wreck at a y that is almost right, which is the most expensive
/// kind of wrong. The count is returned so `caveats()` can say how many were
/// skipped instead of implying there were none.
///
/// # Errors
/// If the extract is present but malformed, or names a template it does not
/// contain.
pub fn shipwreck_starts<B, O, S>(
    seed: i64,
    area: Area,
    biome_at: &mut B,
    ocean_floor_at: O,
    surface_at: S,
) -> Result<Vec<Shipwreck>, String>
where
    B: FnMut(i32, i32, i32) -> String,
    O: Fn(i32, i32) -> Option<i32>,
    S: Fn(i32, i32) -> Option<i32>,
{
    use rustmc_worldgen::rng::legacy::LegacyRandomSource;
    use rustmc_worldgen::rng::worldgen_random::WorldgenRandom;
    use rustmc_worldgen::structure::placement::StructurePlacement;
    use rustmc_worldgen::structure::processor::weighted_attempt_order;
    use rustmc_worldgen::structure::shipwreck::plan;
    use rustmc_worldgen::structure::template::Template;

    let set_path = format!("{}/worldgen/structure_set/shipwrecks.json", crate::DATA);
    let Ok(text) = std::fs::read_to_string(&set_path) else {
        return Ok(Vec::new());
    };
    let json: serde_json::Value =
        serde_json::from_str(&text).map_err(|e| format!("{set_path}: {e}"))?;
    let placement = StructurePlacement::parse(&json["placement"])?;

    // The two entries in file order, with their weights and their biome sets.
    let entries: Vec<(String, i32)> = json["structures"]
        .as_array()
        .ok_or_else(|| format!("{set_path}: no `structures`"))?
        .iter()
        .map(|e| {
            (
                e["structure"]
                    .as_str()
                    .unwrap_or_default()
                    .strip_prefix("minecraft:")
                    .unwrap_or_default()
                    .to_string(),
                e["weight"].as_i64().unwrap_or(1) as i32,
            )
        })
        .collect();
    let weights: Vec<i32> = entries.iter().map(|(_, w)| *w).collect();

    let mut defs: Vec<(bool, std::collections::BTreeSet<String>)> = Vec::new();
    for (name, _) in &entries {
        let path = format!("{}/worldgen/structure/{name}.json", crate::DATA);
        let value: serde_json::Value =
            serde_json::from_str(&std::fs::read_to_string(&path).map_err(|e| e.to_string())?)
                .map_err(|e| format!("{path}: {e}"))?;
        let beached = value["is_beached"].as_bool().unwrap_or(false);
        // Read rather than derived, for the reason written on
        // `resolve_structure_biomes`. **The derived name was correct here** —
        // `shipwreck.json` declares `#minecraft:has_structure/shipwreck` and
        // `shipwreck_beached.json` declares `…/shipwreck_beached`, so the two
        // sets are unchanged to the biome, which
        // `golden_biome_tags::mains_derived_name_was_right_for_shipwreck` pins.
        // What changes is that the next structure read through here is not
        // relying on a convention five of the extract's 34 structures break.
        defs.push((
            beached,
            crate::facts::resolve_structure_biomes(&value, &path)?,
        ));
    }

    // The longest template is 28 blocks and a wreck starts at its chunk's
    // minimum corner, so a start two chunks outside the area can write into
    // it. Three, because the placement test rejects almost every chunk before
    // a template is read and a margin that is measured to be enough is worth
    // more than one that is exactly enough.
    let reach = 3;
    let mut out = Vec::new();
    for cx in (area.min_chunk_x - reach)..=(area.max_chunk_x + reach) {
        for cz in (area.min_chunk_z - reach)..=(area.max_chunk_z + reach) {
            if !placement
                .is_placement_chunk(seed, cx, cz)
                .map_err(|e| format!("{e:?}"))?
            {
                continue;
            }
            for entry in weighted_attempt_order(seed, cx, cz, &weights) {
                let (beached, biomes) = &defs[entry];
                // `Structure.findValidGenerationPoint` =
                // `findGenerationPoint(ctx).filter(isValidBiome)`, and
                // `onTopOfChunkCenter` puts the stub at the chunk's **middle**
                // block — which is not where the piece is built. The heightmap
                // it reads is the variant's own.
                let (mx, mz) = (cx * 16 + 8, cz * 16 + 8);
                let stub_y = if *beached {
                    surface_at(mx, mz)
                } else {
                    ocean_floor_at(mx, mz)
                };
                // Outside the generated area the fossil was never written, so
                // this chunk cannot be decided. Skipping is the honest answer.
                let Some(stub_y) = stub_y else { continue };
                if !biomes.contains(&biome_at(mx >> 2, stub_y >> 2, mz >> 2)) {
                    continue;
                }
                let mut random = WorldgenRandom::new(LegacyRandomSource::new(0));
                random.set_large_feature_seed(seed, cx, cz);
                let plan = plan(&mut random, *beached);
                let path = format!("{}/structure/{}.nbt", crate::DATA, plan.template);
                let Ok(file) = std::fs::File::open(&path) else {
                    return Err(format!("{path}: the extract has no such template"));
                };
                let mut reader = flate2::read::GzDecoder::new(file);
                let (_n, root) =
                    rustmc_world::nbt::read_named_root(&mut reader).map_err(|e| e.to_string())?;
                let template = Template::from_nbt(&root).map_err(|e| format!("{path}: {}", e.0))?;
                out.push(Shipwreck {
                    start_chunk: (cx, cz),
                    plan,
                    template,
                    beached_y: std::sync::Mutex::new(None),
                });
                break;
            }
        }
    }
    Ok(out)
}

/// Write one wreck's blocks that fall inside this chunk.
///
/// The height walk is redone per chunk rather than cached, for the reason
/// `place_ocean_ruin_in_chunk` gives: `postProcess` runs once per chunk the
/// piece reaches and derives the same y from the same frozen fossil each time.
/// Vanilla latches it in `heightAdjusted` after the first pass.
///
/// **That latch is not known to be a pure optimisation, and this comment used
/// to claim it was.** `postProcess` opens `if (this.heightAdjusted || …)` and
/// skips the walk entirely on every later pass, and the walk reads
/// `OCEAN_FLOOR_WG` — which the wreck's *own* blocks, written during the first
/// chunk's pass, raise. So vanilla keeps the pre-wreck mean and this recomputes
/// a possibly post-wreck one. Measured not to bite on seed 20260722 at
/// (57,65)..(57,66), where every block lands at vanilla's y; a wreck straddling
/// more chunks could differ, and logging the mean per pass would settle it.
fn place_shipwreck_in_chunk(
    world: &mut rustmc_worldgen::stage::decorate::Decoration<'_>,
    wreck: &Shipwreck,
    chunk_x: i32,
    chunk_z: i32,
    props: &rustmc_behavior::block_props::BlockPropsTable,
    random: &mut dyn rustmc_worldgen::rng::RandomSource,
) {
    use rustmc_worldgen::structure::place::{place_piece, PieceWorld, PlaceSettings};
    use rustmc_worldgen::structure::shipwreck::{ground_height, PIVOT};
    use rustmc_worldgen::structure::writer::StructureWorld;

    struct Piece<'w, 'a, 'p> {
        world: &'w mut rustmc_worldgen::stage::decorate::Decoration<'a>,
        props: &'p rustmc_behavior::block_props::BlockPropsTable,
    }
    // `Decoration` already implements the recorder; this view exists only to
    // narrow what a piece may touch, so it forwards rather than deciding.
    impl rustmc_worldgen::block_entity::BlockEntityRecorder for Piece<'_, '_, '_> {
        fn record_block_entity(
            &mut self,
            x: i32,
            y: i32,
            z: i32,
            record: rustmc_worldgen::block_entity::Record,
        ) {
            self.world.record_block_entity(x, y, z, record);
        }
    }
    impl PieceWorld for Piece<'_, '_, '_> {
        fn block_at(&mut self, x: i32, y: i32, z: i32) -> String {
            use rustmc_worldgen::structure::writer::StructureWorld;
            self.world.block_at(x, y, z)
        }
        fn set_block(&mut self, x: i32, y: i32, z: i32, state: &str) {
            use rustmc_worldgen::structure::writer::StructureWorld;
            self.world.set_block(x, y, z, state);
        }
        fn world_surface_wg(&mut self, x: i32, z: i32) -> i32 {
            self.world.world_surface_wg(x, z)
        }
        fn block_in_tag(&self, tag: &str, block: &str) -> bool {
            self.world.block_tags().contains(tag, block)
        }
        // `BlockStateParser.parseForBlock` needs the block's default state.
        // Without it the jigsaw replacement writes `final_state` verbatim and
        // loses every property the string does not name.
        fn default_state(&self, block: &str) -> Option<String> {
            self.world.default_state(block)
        }
        fn face_is_sturdy(&self, state: &str, direction: usize) -> Option<bool> {
            self.props
                .get(state)
                .and_then(|p| p.sturdy_faces.get(direction).copied())
        }
    }

    // `generatePieces` builds at the chunk's minimum corner and a hardcoded
    // y=90; only the y moves.
    let origin_xz = (wreck.start_chunk.0 * 16, wreck.start_chunk.1 * 16);
    let size = wreck.template.size;
    // **The intersection test comes before the height walk, because that is
    // the order `StructureStart.placeInChunk` uses.** Its bytecode tests
    // `piece.getBoundingBox().intersects(box)` at offset 105 and only calls
    // `piece.postProcess(..)` at 124, so a chunk the piece does not reach
    // never touches the piece at all — and `adjustPositionHeight`'s walk over
    // `OCEAN_FLOOR_WG` lives inside `postProcess`.
    //
    // Running the walk first, as this did, made every chunk on the canvas
    // sample this wreck's footprint wherever it was. `RUSTMC_READ_REACH_TRAP`
    // caught it: at r=7 the three deepest reads came from decorating chunks
    // (55,55), (70,55) and (73,55) and were all the *same* block, (912,1040)
    // in chunk (57,65). That is why the reported read reach scaled with the
    // square — 16 at r=7, 39 at r=16 — instead of being a property of the
    // features.
    //
    // The early-out is the **horizontal** half of the test the full
    // `intersects` below still performs. A rotated box's x and z do not
    // depend on its y, so this can only skip cases the full test would also
    // skip, and the placed blocks are identical by construction.
    let probe = wreck.template.bounding_box_with_pivot(
        (
            origin_xz.0,
            rustmc_worldgen::structure::shipwreck::START_Y,
            origin_xz.1,
        ),
        wreck.plan.rotation,
        PIVOT,
    );
    if probe.max_x < chunk_x * 16
        || probe.min_x > chunk_x * 16 + 15
        || probe.max_z < chunk_z * 16
        || probe.min_z > chunk_z * 16 + 15
    {
        return;
    }

    // The constructor's y (`shipwreck::START_Y`, 90) never survives: an ocean
    // wreck's `postProcess` overwrites it with the walk's mean on the first
    // pass and latches it, so it is never a position anything is placed at.
    //
    // A beached wreck walks WORLD_SURFACE_WG instead and takes the lowest
    // column, sunk by `calculateBeachedPosition`'s `nextInt(3)` — drawn on
    // `random`, the `shipwreck_beached` stream, and only on the pass that
    // first sets `heightAdjusted`.
    let y = if wreck.plan.beached {
        let mut latch = wreck.beached_y.lock().expect("the beached wreck lock");
        if let Some(y) = *latch {
            y
        } else {
            let (_mean, lowest) =
                ground_height(origin_xz, size, |x, z| world.world_surface_wg(x, z));
            let y = rustmc_worldgen::structure::shipwreck::beached_position(lowest, size.1, random);
            *latch = Some(y);
            y
        }
    } else {
        ground_height(origin_xz, size, |x, z| world.ocean_floor_wg(x, z)).0
    };
    let pos = (origin_xz.0, y, origin_xz.1);

    // `TemplateStructurePiece.postProcess` reassigns the box from the
    // *adjusted* position on every pass, which is why vanilla's saved
    // `BB.minY` equals the adjusted `TP.y` even though `adjustPositionHeight`
    // never touches the box itself.
    let bbox = wreck
        .template
        .bounding_box_with_pivot(pos, wreck.plan.rotation, PIVOT);
    let clip = rustmc_worldgen::structure::pieces::BoundingBox::new(
        chunk_x * 16,
        MIN_Y + 1,
        chunk_z * 16,
        chunk_x * 16 + 15,
        MIN_Y + HEIGHT - 1,
        chunk_z * 16 + 15,
    );
    if !bbox.intersects(clip) {
        return;
    }
    if rustmc_worldgen::canvas::tracing_writes() {
        rustmc_worldgen::canvas::set_writer(&format!(
            "shipwreck into chunk ({chunk_x}, {chunk_z})"
        ));
    }
    let mut view = Piece { world, props };
    place_piece(
        &mut view,
        &wreck.template,
        rustmc_worldgen::structure::place::PieceOrigin::unthreaded(pos),
        PlaceSettings::new(wreck.plan.rotation)
            .with_pivot(PIVOT)
            .with_waterlogging()
            .with_shape_update(),
        &[rustmc_worldgen::structure::place::structure_and_air()],
        clip,
        // `placeInWorld`'s `nextLong` per tagged template container, on the
        // same stream the markers below draw from.
        Some(&mut *random),
    );
    // `ShipwreckPiece.handleDataMarker`: `MARKERS_TO_LOOT.get(marker)`, then
    // `setBlockEntityLootTable(level, random, pos.below(), table)` — a draw
    // only where a container stands below. `filterBlocks` keeps only markers
    // inside the chunk's box.
    {
        use rustmc_worldgen::block_entity::BlockEntityRecorder;
        for block in &wreck.template.blocks {
            let table = match block.marker.as_deref() {
                Some("map_chest") => "minecraft:chests/shipwreck_map",
                Some("treasure_chest") => "minecraft:chests/shipwreck_treasure",
                Some("supply_chest") => "minecraft:chests/shipwreck_supply",
                _ => continue,
            };
            let r = rustmc_worldgen::structure::template::transform(
                block.pos,
                rustmc_worldgen::structure::template::Mirror::None,
                wreck.plan.rotation,
                PIVOT,
            );
            let (x, y, z) = (pos.0 + r.0, pos.1 + r.1, pos.2 + r.2);
            if !clip.is_inside(x, y, z) {
                continue;
            }
            let below = view.world.block_at(x, y - 1, z);
            if !matches!(
                below.split('[').next().unwrap_or(""),
                "minecraft:chest" | "minecraft:trapped_chest" | "minecraft:barrel"
            ) {
                continue;
            }
            let seed = random.next_i64();
            view.world.record_block_entity(
                x,
                y - 1,
                z,
                rustmc_worldgen::block_entity::Record {
                    nbt: BTreeMap::from([(
                        "LootTable".to_string(),
                        rustmc_world::nbt::Nbt::String(table.into()),
                    )]),
                    loot_seed: Some(seed),
                },
            );
        }
    }
    if rustmc_worldgen::canvas::tracing_writes() {
        rustmc_worldgen::canvas::set_writer("");
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// The entities three structures spawn, against vanilla's own saved
    /// `entities/` region files: the world directories behind the clamped
    /// harvests `sl2-om1-a` (seed 42, monument at (49,-11)), `sl2-ec1-a`
    /// (seed 20260722, the ship city at (81,3)) and `sl2-wm1-a` (seed 8,
    /// mansion at (32,16)), r=4, `tick freeze`, so every saved position is the
    /// spawn position. Mobs are keyed by the block of their `Pos`, the item
    /// frame by its `block_pos` and `Facing`; an allay group's count is the
    /// level random's and is checked against 1..3 by the comparer, not here.
    /// All eight harvest windows this lane holds read 117 of 117
    /// (`worldgen-dump structure-spawns` against them).
    #[test]
    fn structure_spawns_are_where_vanilla_saved_them() {
        if !crate::have_extract() {
            return;
        }
        let keys = |v: Vec<StructureSpawn>| -> Vec<(String, (i32, i32, i32), String)> {
            let mut k: Vec<_> = v
                .into_iter()
                .map(|s| {
                    (
                        s.id.to_string(),
                        s.block,
                        s.facing.unwrap_or("-").to_string(),
                    )
                })
                .collect();
            k.sort();
            k
        };
        let m = |id: &str, b: (i32, i32, i32)| (format!("minecraft:{id}"), b, "-".to_string());

        let elders = keys(structure_spawns(42, Area::square(49, -11, 4), false).expect("om1"));
        assert_eq!(
            elders,
            vec![
                m("elder_guardian", (769, 45, -193)),
                m("elder_guardian", (772, 42, -160)),
                m("elder_guardian", (783, 53, -177)),
            ]
        );

        let city = keys(structure_spawns(20_260_722, Area::square(82, 0, 4), true).expect("ec1"));
        let mut want = vec![(
            "minecraft:item_frame".to_string(),
            (1306, 119, -28),
            "south".to_string(),
        )];
        for b in [
            (1303, 105, 51),
            (1303, 113, 51),
            (1304, 125, -8),
            (1306, 118, -27),
            (1307, 101, 47),
            (1307, 101, 55),
            (1307, 109, 47),
            (1307, 109, 55),
            (1308, 120, -8),
            (1311, 105, 51),
            (1311, 113, 51),
            (1312, 65, 49),
            (1312, 65, 52),
        ] {
            want.push(m("shulker", b));
        }
        want.sort();
        assert_eq!(city, want);

        let mansion = keys(structure_spawns(8, Area::square(34, 15, 4), false).expect("wm1"));
        let mut want: Vec<_> = [
            (571, 64, 251),
            (577, 64, 253),
            (581, 64, 243),
            (581, 64, 250),
        ]
        .into_iter()
        .map(|b| m("allay", b))
        .chain(
            [(536, 71, 251), (575, 82, 260)]
                .into_iter()
                .map(|b| m("evoker", b)),
        )
        .chain(
            [
                (515, 71, 229),
                (518, 71, 229),
                (519, 64, 228),
                (521, 71, 229),
                (531, 71, 262),
                (533, 63, 260),
                (537, 64, 252),
                (537, 71, 258),
                (541, 82, 251),
                (541, 82, 254),
                (541, 82, 257),
                (551, 71, 229),
                (554, 71, 229),
                (556, 63, 228),
                (556, 63, 270),
                (557, 71, 229),
                (563, 71, 267),
                (566, 71, 267),
                (569, 71, 267),
                (572, 63, 243),
                (572, 82, 259),
                (580, 82, 260),
            ]
            .into_iter()
            .map(|b| m("vindicator", b)),
        )
        .collect();
        want.sort();
        assert_eq!(mansion, want);
    }

    /// A real world: stone below, air above, a surface that is not stone, and
    /// biome cells that are not all the same.
    #[test]
    fn a_generated_chunk_looks_like_a_world() {
        if !crate::have_extract() {
            return;
        }
        let world =
            generate(20_260_725, Area::square(0, 0, 0), Through::Surface).expect("generates");
        let canvas = &world.canvas;

        // Bedrock, not stone: the surface rule's `vertical_gradient` lays
        // the world floor, so this doubles as proof the rules ran at all.
        assert_eq!(canvas.block_at(0, -64, 0), "minecraft:bedrock");
        assert_eq!(canvas.block_at(0, 319, 0), "minecraft:air");

        // The surface stage ran: the block at the top of the column is not
        // the generator's default.
        let mut replaced = 0;
        for z in 0..16 {
            for x in 0..16 {
                let top = canvas.world_surface_wg(x, z) - 1;
                if top > canvas.min_y() && canvas.block_at(x, top, z) != "minecraft:stone" {
                    replaced += 1;
                }
            }
        }
        assert!(
            replaced > 100,
            "only {replaced} of 256 columns have a surface block"
        );

        // Biomes were resolved rather than left at the fill.
        let (palette, _) = canvas.chunk_biomes(0, 0).expect("chunk");
        assert!(!palette.is_empty());
    }

    /// The carvers ran: some stone that the surface stage left is now air.
    #[test]
    fn the_carvers_cut_holes() {
        if !crate::have_extract() {
            return;
        }
        let before =
            generate(20_260_725, Area::square(0, 0, 0), Through::Surface).expect("generates");
        let after =
            generate(20_260_725, Area::square(0, 0, 0), Through::Carvers).expect("generates");

        let mut carved = 0;
        for y in -60..60 {
            for z in 0..16 {
                for x in 0..16 {
                    if before.canvas.block_at(x, y, z) != after.canvas.block_at(x, y, z) {
                        carved += 1;
                    }
                }
            }
        }
        assert!(carved > 0, "the carvers changed nothing in this chunk");
        // The aquifer is no longer stubbed, so it is no longer a caveat — and
        // this asserting its *absence* is what stops the caveat list rotting
        // into a list of things that used to be true.
        assert!(
            !after
                .caveats()
                .iter()
                .any(|c| c.contains("aquifers are stubbed")),
            "the aquifer stub is fixed and should not still be reported: {:?}",
            after.caveats()
        );
        // Same for `topMaterial`, fixed 2026-08-09. It had been the one
        // still-stubbed carver input and this assertion used to demand it be
        // present; leaving it that way would have made the caveat list claim
        // cave mouths have no surface in a world where they do.
        assert!(
            !after
                .caveats()
                .iter()
                .any(|c| c.contains("top-material is stubbed")),
            "the top-material stub is fixed and should not still be reported: {:?}",
            after.caveats()
        );
    }

    /// The whole pipeline: decoration writes blocks the carvers did not.
    #[test]
    fn the_full_pipeline_decorates() {
        if !crate::have_extract() || !crate::have_block_props() {
            return;
        }
        let carved =
            generate(20_260_725, Area::square(0, 0, 0), Through::Carvers).expect("generates");
        let full =
            generate(20_260_725, Area::square(0, 0, 0), Through::Decoration).expect("generates");

        let mut changed = 0;
        let mut states = std::collections::BTreeSet::new();
        for y in -64..200 {
            for z in 0..16 {
                for x in 0..16 {
                    let before = carved.canvas.block_at(x, y, z);
                    let after = full.canvas.block_at(x, y, z);
                    if before != after {
                        changed += 1;
                        states.insert(after.to_string());
                    }
                }
            }
        }
        assert!(
            changed > 0,
            "decoration wrote nothing — the biome set or the feature order is empty"
        );
        println!(
            "FULL PIPELINE: decoration changed {changed} blocks in one chunk, \
             {} distinct states",
            states.len()
        );
        println!("  caveats: {:?}", full.caveats());
        let mut refusals: Vec<_> = full.refused.iter().collect();
        refusals.sort_by_key(|(_, n)| std::cmp::Reverse(**n));
        println!("  refused: {:?}", &refusals[..refusals.len().min(6)]);
    }

    /// The caveats are a value, so a report cannot quote a number without
    /// them.
    #[test]
    fn the_caveats_name_what_is_missing() {
        if !crate::have_extract() {
            return;
        }
        let world = generate(1, Area::square(0, 0, 0), Through::Noise).expect("generates");
        let caveats = world.caveats();
        // Matched loosely on purpose. This assertion was written against
        // "structures are not generated", the wording changed when mineshafts
        // landed, and the test went red and stayed red — behind the known
        // carver failure, which `cargo test --workspace` fail-fasts on before
        // it ever reaches this crate. A caveat is prose; assert that the
        // subject is named, not how.
        assert!(
            caveats.iter().any(|c| c.contains("structure")),
            "no caveat mentions structures: {caveats:?}"
        );
        assert!(caveats.contains(&"surface rules did not run"));
        assert!(caveats.contains(&"decoration did not run"));
    }

    /// Two runs of one seed agree, block for block. The determinism contract
    /// over the *composed* pipeline, not one stage of it.
    #[test]
    fn two_runs_of_a_seed_agree_through_the_surface() {
        if !crate::have_extract() {
            return;
        }
        let run = || {
            let world =
                generate(4242, Area::square(1, -1, 0), Through::Surface).expect("generates");
            let (palette, ids) = world.canvas.chunk_data(1, -1).expect("chunk");
            (palette.to_vec(), ids.to_vec())
        };
        assert_eq!(run(), run());
    }

    /// One corridor's `hasPlacedSpider`, decorated in isolation, must not
    /// reach the next chunk.
    ///
    /// This is the whole of `docs/DETERMINISM.md` §33 at the seam where it
    /// lives. `spider && !placed_spider` gates a `nextInt(3)`, so a chunk
    /// that inherits the flag spends one draw fewer than a chunk that does
    /// not and every later value in its mineshaft pass lands one place
    /// early. Under `RUSTMC_DECORATE_ISOLATED=1` chunks decorate with no
    /// order between them at all, so "who got there first" is thread
    /// scheduling — and one binary produced three different worlds from one
    /// seed and one window before this.
    ///
    /// The injection that witnesses it: make [`SpiderMemory::for_chunk`]
    /// hand back a `Pass` over a shared set and the third assertion goes
    /// red, which is exactly the pre-fix code.
    #[test]
    fn an_isolated_chunk_does_not_inherit_a_neighbours_spider_corridor() {
        let key: SpiderKey = (7, -3, 4);
        let first = SpiderMemory::for_chunk();
        let second = SpiderMemory::for_chunk();

        assert!(
            !first.contains(key),
            "a fresh chunk memory remembers nothing"
        );
        first.insert(key);
        assert!(
            first.contains(key),
            "within one chunk the flag still carries between the corridor's \
             own sections, which is what suppresses the redraw vanilla \
             suppresses"
        );
        assert!(
            !second.contains(key),
            "the next chunk of the same corridor must not see it: under \
             isolation a chunk's writes are a pure function of the seed and \
             its position, and a flag another chunk set is another chunk's \
             write by a different name"
        );
    }

    /// And the shared-canvas arms keep vanilla's carry, which is the control
    /// that stops the test above from being satisfied by forgetting always.
    #[test]
    fn the_shared_canvas_models_carry_the_flag_between_chunks() {
        let key: SpiderKey = (7, -3, 4);
        let shared = std::sync::Mutex::new(std::collections::BTreeSet::new());
        let first = SpiderMemory::Pass(&shared);
        let second = SpiderMemory::Pass(&shared);

        assert!(!first.contains(key));
        first.insert(key);
        assert!(
            second.contains(key),
            "a corridor is post-processed once per chunk it overlaps and \
             vanilla saves the flag as `hps`, so under the shared-canvas \
             models the second chunk must not redraw the spawner"
        );
    }
}
